(window.SB_FULLC=window.SB_FULLC||{}).und={c:`[{"w":"unkempt","d":"is disheveled or messy","s":"After hiking for three days through the muddy forest trail without a mirror or comb, the explorer arrived at camp looking completely unkempt, with tangled hair and dirt-streaked clothes.","p":"uh-n-k-EH-m-p-t","o":"English","y":4,"bp":62,"m":"unkept","nt":"Advanced","ps":"adjective","t":[]},{"w":"understand","d":"know and comprehend the nature or meaning of","s":"Once the teacher used a diagram, the whole class began to understand how the water cycle works.","p":"uh-nder-STAND","o":"Old English","y":1,"bp":38,"m":"undrestand","sy":"un.der.stand","nt":"Primary","ps":"verb","t":["ooldeng"]},{"w":"univocal","d":"admitting of no doubt or misunderstanding; having only one meaning or interpretation and leading to only one conclusion","s":"The scientist's univocal data left no room for debate—the experiment had clearly succeeded.","p":"yoo-NIV-uh-kul","o":"Latin","y":6,"bp":33,"m":"univocle","sy":"u.ni.vo.cal","nt":"Open","ps":"adjective","t":["logic","olatin"]},{"w":"undergird","d":"lend moral support to","s":"Her parents' encouragement undergirded her confidence as she stepped onto the stage for the spelling bee finals.","p":"un-dur-GURD","o":"Old English","y":6,"bp":29,"sy":"un.der.gird","nt":"Open","ps":"verb","t":["logic","ooldeng"]},{"w":"university","d":"an institution of higher learning that grants degrees in various fields of study","s":"My cousin was thrilled to receive an acceptance letter from the university where she planned to study marine biology.","p":"yoo-nuh-VUR-suh-tee","o":"Latin","y":1,"bp":37,"m":"univeristy","sy":"u.ni.ver.si.ty","nt":"Open","ps":"noun","t":["olatin"]},{"w":"unilaterally","d":"in a unilateral manner; by means of one part or party","s":"The principal acted unilaterally to cancel the field trip without consulting the teachers or parents.","p":"yoo-nuh-LA-ter-uh-lee","o":"Latin","y":6,"bp":40,"m":"unilateraly","sy":"u.ni.lat.er.al.ly","nt":"Open","ps":"adverb","t":["olatin"]},{"w":"unfurl","d":"unroll, unfold, or spread out or be unrolled, unfolded, or spread out from a furled state","s":"As the parade began, the color guard would unfurl the enormous flag in one dramatic sweep, letting it billow proudly in the crisp autumn breeze above the cheering crowd.","p":"uh-NFURL","o":"Dutch","y":5,"bp":25,"m":"unfurle","sy":"ah.nfer.l","nt":"Open","ps":"verb","t":["odutch"]},{"w":"undulating","d":"moving with a smooth wavelike motion","s":"The undulating hills of the countryside looked like a green ocean frozen in gentle waves.","p":"UH-njuh-lay-tihng","o":"Latin","y":5,"bp":35,"m":"undualting","sy":"un.du.la.ting","nt":"Open","ps":"verb","t":["olatin"]},{"w":"unguiculate","d":"a mammal having nails or claws","s":"The biology teacher explained that humans, unlike hoofed animals, are unguiculates because we have nails instead of hooves.","p":"ung-GWIK-yuh-lit","o":"Latin","y":9,"bp":70,"m":"unguiculat","sy":"un.guic.u.late","nt":"Senior","ps":"noun","t":["animals","olatin"]},{"w":"undermine","d":"destroy property or hinder normal operations","p":"UH-nder-meyen","o":"Old English","y":4,"bp":29,"m":"undermyne","sy":"ah.nder.may.n","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"under","d":"located below or beneath something else","s":"The frightened kitten squeezed under the bed and refused to come out, no matter how many treats were placed just beyond the edge of the dust ruffle.","p":"UH-nder","o":"Old English","y":1,"bp":24,"m":"undar","sy":"ah.nder","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"undid","d":"cancel, annul, or reverse an action or its effect","p":"uh-NDIHD","o":"Old English","y":4,"bp":24,"m":"undied","sy":"ah.ndih.d","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"undine","d":"any of various female water spirits","s":"The legend described an undine rising from the misty lake to lure travelers to the water's edge.","p":"UH-ndeen","o":"German","y":6,"bp":25,"m":"undeen","sy":"ah.ndiy.n","nt":"Open","ps":"noun","t":["myth","onordic"]},{"w":"undo","d":"cancel, annul, or reverse an action or its effect","s":"I wish I could undo my actions.","p":"uh-NDOO","o":"Italian","y":4,"bp":23,"m":"unndo","sy":"ah.nduw","nt":"Open","ps":"verb","t":["oiberian"]},{"w":"undock","d":"move out of a dock","s":"Mission control gave the order to undock the supply capsule from the space station, and the crew watched through the porthole as it slowly drifted away into the blackness beyond.","p":"uh-NDAHK","o":"Latin","y":6,"bp":29,"m":"undoc","sy":"ah.ndaa.k","nt":"Open","ps":"verb","t":["seafaring","olatin"]},{"w":"undone","d":"cancel, annul, or reverse an action or its effect","p":"uh-NDUHN","o":"Old English","y":4,"bp":25,"m":"undun","sy":"ah.ndah.n","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"undue","d":"not yet payable","s":"The judge warned the lawyers that placing undue pressure on a witness was completely unacceptable and could result in the entire case being thrown out of court.","p":"uh-NDOO","o":"Latin","y":4,"bp":28,"m":"undew","sy":"ah.nduw","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unduly","d":"to an undue degree","s":"She was unduly pessimistic about her future.","p":"uh-NDOO-lee","o":"Latin","y":3,"bp":30,"m":"unduely","sy":"ah.nduw.liy","nt":"Open","ps":"adverb","t":["olatin"]},{"w":"unease","d":"physical discomfort (as mild sickness or depression)","s":"A feeling of unease crept over Maya as she walked alone through the dark and empty hallway.","p":"uh-NEEZ","o":"Old English","y":5,"bp":25,"m":"uneese","sy":"ah.niy.z","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"uneasy","d":"lacking a sense of security or affording no ease or reassurance","s":"Farmers were uneasy until rain finally came.","p":"uh-NEE-zee","o":"Old English","y":2,"bp":26,"sy":"ah.niy.ziy","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unesco","d":"an agency of the United Nations that promotes education and communication and the arts","s":"UNESCO declared the ancient ruins a World Heritage Site to protect them for future generations.","p":"yoo-NEH-skoh","y":5,"bp":26,"m":"Unesko","sy":"yuw.neh.skow","nt":"Open","ps":"noun","t":["politics","education"]},{"w":"uneven","d":"not even or uniform as e.g. in shape or texture","s":"The old cobblestone path was so uneven that visitors had to watch every step carefully to avoid catching their feet on the jagged, mismatched stones jutting up from the ground.","p":"uh-NEE-vuhn","o":"Old English","y":2,"bp":26,"m":"uneaven","sy":"ah.niy.vah.n","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unfair","d":"not fair; marked by injustice or partiality or deception","s":"The students thought it was deeply unfair that one class was allowed to use calculators on the test while every other class in the same grade had to solve the problems by hand.","p":"uh-NFEHR","o":"Latin","y":2,"bp":29,"m":"unfaire","sy":"ah.nfeh.r","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unfit","d":"not suitable, healthy, or good enough for something","p":"uh-NFIHT","o":"Latin","y":2,"bp":28,"m":"unfiit","sy":"ah.nfih.t","nt":"Open","ps":"verb","t":["olatin"]},{"w":"unfold","d":"develop or come to a promising stage","p":"uh-NFOHLD","o":"Old English","y":2,"bp":25,"m":"unfoldd","sy":"ah.nfow.ld","nt":"Open","ps":"verb","t":["stage","ooldeng"]},{"w":"unholy","d":"not hallowed or consecrated","p":"uh-NHOH-lee","o":"Old English","y":3,"bp":26,"m":"unholey","sy":"ah.nhhow.liy","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unhook","d":"take off a hook","s":"She carefully tried to unhook her backpack strap from the sharp nail sticking out of the fence.","p":"uh-NHUUK","o":"Old English","y":5,"bp":25,"m":"unhooke","sy":"ah.nhhuh.k","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"unhurt","d":"Not injured or harmed in any way; having come through a dangerous or difficult situation without any physical damage.","p":"uh-NHURT","o":"Old English","y":4,"bp":25,"m":"unhert","sy":"ah.nhher.t","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unicef","d":"an agency of the United Nations responsible for programs to aid education and the health of children and mothers in developing countries","s":"UNICEF delivered emergency food and medicine to children affected by the devastating flood.","p":"YOO-nuh-sehf","y":3,"bp":26,"m":"UNICEFF","sy":"yuw.nah.seh.f","nt":"Open","ps":"noun","t":["kinship"]},{"w":"unify","d":"To bring together separate parts, people, or groups into a single, united whole so that they function or act as one.","p":"YOO-nuh-feye","o":"Latin","y":3,"bp":30,"m":"unifiy","sy":"yuw.nah.fay","nt":"Open","ps":"verb","t":["olatin"]},{"w":"union","d":"an organization of employees formed to bargain with the employer","s":"You have to join the union in order to get a job.","p":"YOO-nyuhn","o":"French","y":1,"bp":28,"m":"uniion","sy":"yuw.nyah.n","nt":"Open","ps":"noun","t":["economy","ofrench"]},{"w":"unions","d":"an organization of employees formed to bargain with the employer","p":"YOO-nyuhnz","o":"Latin","y":1,"bp":29,"m":"unnions","sy":"yuw.nyah.nz","nt":"Open","ps":"noun","t":["economy","olatin"]},{"w":"unique","d":"radically distinctive and without equal","p":"yoo-NEEK","o":"French","y":3,"bp":70,"m":"uniqe","sy":"yuw.niy.k","nt":"Open | North South Finals","ps":"adjective","t":["ofrench"]},{"w":"unisex","d":"not distinguished on the basis of sex","s":"The school decided to install unisex restrooms to make all students feel welcome and included.","p":"YOO-nih-sehks","o":"Latin","y":3,"bp":30,"m":"uniseks","sy":"yuw.nih.seh.ks","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unison","d":"corresponding exactly","s":"The entire choir took a deep breath and then sang the opening note in perfect unison, filling the cathedral with a single, powerful sound that made the audience fall completely silent.","p":"YOO-nuh-suhn","o":"Latin","y":3,"bp":30,"m":"unisson","sy":"yuw.nah.sah.n","nt":"Open","ps":"noun","t":["olatin"]},{"w":"unit","d":"any division of quantity accepted as a standard of measurement or exchange","s":"The dollar is the United States unit of currency.","p":"YOO-nuht","o":"Latin","y":1,"bp":27,"m":"unnit","sy":"yuw.nah.t","nt":"Open","ps":"noun","t":["numbers","olatin"]},{"w":"unite","d":"to join together and act as one group","p":"YOO-neyet","o":"Latin","y":3,"bp":28,"m":"unnite","sy":"yuw.nay.t","nt":"Open","ps":"verb","t":["logic","olatin"]},{"w":"united","d":"act in concert or unite in a common purpose or belief","p":"yoo-NEYE-tihd","o":"Latin","y":1,"bp":30,"m":"unnited","sy":"yuw.nay.tah.d","nt":"Open","ps":"verb","t":["logic","olatin"]},{"w":"unites","d":"act in concert or unite in a common purpose or belief","p":"yoo-NEYETS","o":"Latin","y":3,"bp":29,"m":"unnites","sy":"yuw.nay.ts","nt":"Open","ps":"verb","t":["logic","olatin"]},{"w":"units","d":"any division of quantity accepted as a standard of measurement or exchange","p":"YOO-nuhts","o":"Latin","y":1,"bp":28,"m":"unnits","sy":"yuw.nah.ts","nt":"Open","ps":"noun","t":["numbers","olatin"]},{"w":"unity","d":"an undivided or unbroken completeness or totality with nothing wanting","p":"YOO-nuh-tee","o":"Anglo-Norman","y":1,"bp":67,"m":"unitty","sy":"yuw.nah.tiy","nt":"Open | North South Finals","ps":"noun","t":["ofrench"]},{"w":"unix","d":"trademark for a powerful operating system","s":"The computer science teacher showed students how to run basic commands using the UNIX operating system.","p":"YOO-nihks","y":2,"bp":23,"sy":"yuw.nih.ks","nt":"Open","ps":"noun","t":[]},{"w":"unjust","d":"not fair; marked by injustice or partiality or deception","s":"The students protested loudly because they believed the new school rule was completely unjust and unfairly targeted only certain groups of kids.","p":"uh-NJUHST","o":"Latin","y":2,"bp":29,"m":"injust","sy":"ah.njhah.st","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unkind","d":"lacking kindness","s":"A thoughtless and unkind remark.","p":"uh-NKEYEND","o":"Latin","y":3,"bp":29,"m":"unkinde","sy":"ah.nkay.nd","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unlike","d":"marked by dissimilarity","s":"For twins they are very unlike.","p":"uh-NLEYEK","o":"Latin","y":2,"bp":29,"m":"unlikly","sy":"ah.nlay.k","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unload","d":"to take goods or cargo off a truck, ship, or car","s":"After the long camping trip, the exhausted family worked together to unload all the heavy gear from the back of the van before dinner.","p":"uh-NLOHD","o":"Latin","y":3,"bp":29,"m":"unloade","sy":"ah.nlow.d","nt":"Open","ps":"verb","t":["seafaring","vehicles","olatin"]},{"w":"unlock","d":"open the lock of","s":"Maya fumbled nervously with her keys, desperate to unlock the door before the sudden rainstorm completely soaked her new jacket and backpack.","p":"uh-NLAHK","o":"Old English","y":2,"bp":25,"m":"unnlock","sy":"ah.nlaa.k","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"undamaged","d":"not harmed or spoiled; sound","s":"Remarkably, the ancient vase was found undamaged despite being buried for over two thousand years.","p":"uh-NDA-muhjd","o":"French","y":4,"bp":33,"m":"undammaged","sy":"ah.ndae.mah.jhd","nt":"Open","ps":"adjective","t":["ofrench"]},{"w":"undated","d":"not bearing a date","s":"The historian found an undated letter tucked inside the old journal, and without knowing when it was written, she could not be certain which war, which leader, or even which century it described.","p":"uh-NDAY-tihd","o":"Latin","y":3,"bp":31,"m":"undatted","sy":"ah.ndey.tih.d","nt":"Open","ps":"adjective","t":["maps","olatin"]},{"w":"undaunted","d":"unshaken in purpose","p":"uh-NDAW-ntihd","o":"French","y":5,"bp":33,"m":"undanted","sy":"ah.ndao.ntih.d","nt":"Open","ps":"adjective","t":["ofrench"]},{"w":"undecided","d":"not brought to a conclusion; subject to further thought","s":"Leo stood in front of the ice cream case for a full ten minutes, completely undecided between the salted caramel and the dark chocolate flavors, unable to choose even as the line grew longer behind him.","p":"uh-ndih-SEYE-dihd","o":"Latin","y":4,"bp":34,"m":"undecied","sy":"ah.ndih.say.dih.d","nt":"Open","ps":"adjective","t":["logic","olatin"]},{"w":"undefined","d":"not precisely limited, determined, or distinguished","s":"The boundary between the two neighboring properties was undefined, and without a clear survey or legal document, neither family could agree on exactly where one yard ended and the other rightfully began.","p":"uh-ndih-FEYEND","o":"Latin","y":4,"bp":33,"m":"undifined","sy":"ah.ndih.fay.nd","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"underage","d":"not of legal age","s":"The event coordinator checked every ticket carefully at the entrance because underage guests were not permitted inside the venue after nine o'clock, in strict compliance with the city's regulations for late-night public events.","p":"UH-nder-ihj","o":"French","y":5,"bp":32,"sy":"ah.nder.ih.jh","nt":"Open","ps":"adjective","t":["law","ofrench"]},{"w":"underarm","d":"with hand brought forward and up from below shoulder level","s":"The softball coach taught the beginners to throw underarm first, demonstrating how bringing the hand forward and upward from below the shoulder produces a smooth, accurate toss that younger players find much easier to control.","p":"uh-nder-AHRM","o":"Old English","y":5,"bp":28,"sy":"ah.nder.aa.rm","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"underbid","d":"bid (a hand of cards) at less than the strength of the hand warrants","s":"He chose to underbid his hand in the card game, hoping to trick his opponents into a false sense of security.","p":"UH-nder-bihd","o":"Old English","y":6,"bp":28,"sy":"ah.nder.bih.d","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"undercoat","d":"seal consisting of a coating of a tar or rubberlike material on the underside of a motor vehicle to retard corrosion","s":"The mechanic recommended applying an undercoat to protect the car's frame from rust during the harsh winter months.","p":"UH-nder-koht","o":"Old English","y":6,"bp":29,"sy":"ah.nder.kow.t","nt":"Open","ps":"noun","t":["vehicles","tools","ooldeng"]},{"w":"undercut","d":"the material removed by a cut made underneath","p":"UH-nder-kuht","o":"Old English","y":3,"bp":28,"sy":"ah.nder.kah.t","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"undercuts","d":"the material removed by a cut made underneath","p":"UH-nder-kuhts","o":"Old English","y":5,"bp":29,"sy":"ah.nder.kah.ts","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"underdog","d":"one at a disadvantage and expected to lose","s":"The crowd cheered loudly for the underdog, who had never won a single match against such a skilled opponent.","p":"UH-nder-dawg","o":"Old English","y":3,"bp":28,"sy":"ah.nder.dao.g","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"underdogs","d":"one at a disadvantage and expected to lose","s":"History is full of stories about underdogs who defied the odds and rose to become champions.","p":"UH-nder-dawgz","o":"Old English","y":4,"bp":29,"sy":"ah.nder.dao.gz","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"underfoot","d":"under the feet","s":"Trampled the beans underfoot.","p":"uh-nder-FUUT","o":"Old English","y":5,"bp":29,"sy":"ah.nder.fuh.t","nt":"Open","ps":"adverb","t":["ooldeng"]},{"w":"undergo","d":"pass through","s":"The chemical undergoes a sudden change.","p":"uh-nder-GOH","o":"Old English","y":5,"bp":27,"m":"undergoe","sy":"ah.nder.gow","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"undergoes","d":"pass through","s":"The chemical undergoes a sudden change.","p":"UH-nder-gohz","o":"Old English","y":4,"bp":29,"m":"undergos","sy":"ah.nder.gow.z","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"undergone","d":"pass through","p":"uh-nder-GAWN","o":"Old English","y":5,"bp":29,"m":"undergon","sy":"ah.nder.gao.n","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"undergrad","d":"a university student who has not yet received a first degree","s":"As an undergrad, she worked part-time at the campus library to help pay for her tuition.","p":"UH-nder-grad","o":"Latin","y":4,"bp":33,"m":"undergard","sy":"ah.nder.grae.d","nt":"Open","ps":"noun","t":["olatin"]},{"w":"underlie","d":"be or form the base for","s":"A desire for justice seems to underlie all of her decisions.","p":"uh-nder-LEYE","o":"Old English","y":6,"bp":28,"m":"underly","sy":"ah.nder.lay","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underlies","d":"be or form the base for","s":"A strong work ethic underlies her success in every subject.","p":"uh-nder-LEYEZ","o":"Old English","y":5,"bp":29,"m":"underlys","sy":"ah.nder.lay.z","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underline","d":"a line drawn underneath (especially under written matter)","p":"UH-nder-leyen","o":"Old English","y":6,"bp":29,"m":"underlyne","sy":"ah.nder.lay.n","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"underling","d":"an assistant subject to the authority or control of another","s":"The villain sent his underling to deliver the threatening message.","p":"UH-nder-lihng","o":"Old English","y":5,"bp":29,"m":"underlung","sy":"ah.nder.lih.ng","nt":"Open","ps":"noun","t":["jobs","ooldeng"]},{"w":"underpaid","d":"pay too little","s":"Many nurses feel underpaid despite the critical work they do every day.","p":"uh-nder-PAYD","o":"Old English","y":5,"bp":29,"m":"underpayd","sy":"ah.nder.pey.d","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underpass","d":"an underground tunnel or passage enabling pedestrians to cross a road or railway","s":"The cyclists used the underpass to safely cross beneath the busy highway.","p":"UH-nder-pas","o":"Old English","y":5,"bp":29,"m":"underpas","sy":"ah.nder.pae.s","nt":"Open","ps":"noun","t":["vehicles","ooldeng"]},{"w":"underpay","d":"pay too little","s":"It is unfair to underpay workers who contribute so much to a company's success.","p":"uh-nder-PAY","o":"Old English","y":6,"bp":28,"m":"underpai","sy":"ah.nder.pey","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underpin","d":"support from beneath","p":"UH-nder-pihn","o":"French","y":4,"bp":32,"m":"underpinn","sy":"ah.nder.pih.n","nt":"Open","ps":"verb","t":["ofrench"]},{"w":"underplay","d":"act (a role) with great restraint","s":"The actor chose to underplay the emotional scene, making it all the more powerful.","p":"uh-nder-PLAY","o":"Old English","y":6,"bp":29,"m":"underplai","sy":"ah.nder.pley","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underrate","d":"make too low an estimate of","p":"uh-nder-RAYT","o":"Norse","y":7,"bp":29,"m":"underrait","sy":"ah.nder.rey.t","nt":"Open","ps":"verb","t":["onordic"]},{"w":"undersea","d":"beneath the surface of the sea","s":"The documentary revealed a breathtaking undersea world full of glowing creatures.","p":"uh-nder-SEE","o":"Old English","y":6,"bp":28,"m":"undersee","sy":"ah.nder.siy","nt":"Open","ps":"adjective","t":["waterways","ooldeng"]},{"w":"undersell","d":"sell cheaper than one's competition","s":"The new store tried to undersell its competitors by offering deep discounts.","p":"UH-nder-sehl","o":"Old English","y":7,"bp":29,"m":"undersele","sy":"ah.nder.seh.l","nt":"Open","ps":"verb","t":["economy","trade","ooldeng"]},{"w":"underside","d":"the lower side of anything","s":"She turned over the leaf and found a cluster of tiny eggs on its underside.","p":"UH-nder-seyed","o":"Old English","y":5,"bp":29,"m":"undersied","sy":"ah.nder.say.d","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"undersold","d":"sell cheaper than one's competition","s":"The boutique undersold the big-box store by offering the same jacket at half the price.","p":"uh-nder-SOHLD","o":"Old English","y":6,"bp":29,"m":"undersolled","sy":"ah.nder.sow.ld","nt":"Open","ps":"verb","t":["sports","ooldeng"]},{"w":"undertake","d":"enter upon an activity or enterprise","p":"UH-nder-tayk","o":"Old English","y":4,"bp":29,"m":"undertaik","sy":"ah.nder.tey.k","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"undertone","d":"a quiet or hushed tone of voice","s":"There was a quiet undertone of sadness in the teacher's voice as she announced that the beloved school librarian was retiring, even though she smiled warmly and spoke enthusiastically about the celebration planned for Friday afternoon.","p":"UH-nder-tohn","o":"Old English","y":6,"bp":29,"m":"undertoan","sy":"ah.nder.tow.n","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"undertook","d":"enter upon an activity or enterprise","p":"uh-nder-TUUK","o":"Old English","y":3,"bp":29,"m":"undertuk","sy":"ah.nder.tuh.k","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"undertow","d":"an inclination contrary to the strongest or prevailing feeling","s":"His account had a poignant undertow of regret.","p":"UH-nder-toh","o":"Old English","y":5,"bp":69,"m":"undertoe","sy":"ah.nder.tow","nt":"Open | North South Finals","ps":"noun","t":["ooldeng"]},{"w":"undertows","d":"an inclination contrary to the strongest or prevailing feeling","p":"UH-nder-tohz","o":"Old English","y":8,"bp":29,"m":"undertoes","sy":"ah.nder.tow.z","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"underway","d":"currently in progress","p":"uh-nder-WAY","o":"Old English","y":2,"bp":28,"m":"under way","sy":"ah.nder.wey","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"underwear","d":"undergarment worn next to the skin and under the outer garments","s":"He remembered everything for the camping trip except an extra pair of underwear.","p":"UH-nder-wehr","o":"Old English","y":2,"bp":29,"m":"underwere","sy":"ah.nder.weh.r","nt":"Open","ps":"noun","t":["body","fabrics","ooldeng"]},{"w":"underwent","d":"pass through","p":"uh-nder-WEHNT","o":"Old English","y":3,"bp":29,"m":"underwant","sy":"ah.nder.weh.nt","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underwood","d":"the brush (small trees and bushes and ferns etc.) growing beneath taller trees in a wood or forest","s":"The fox darted through the underwood, disappearing beneath the thick ferns.","p":"UH-nder-wuud","o":"Old English","y":3,"bp":29,"m":"underwould","sy":"ah.nder.wuh.d","nt":"Open","ps":"noun","t":["botany","ooldeng"]},{"w":"undiluted","d":"Not weakened or thinned by mixing with another substance; at full strength and concentration.","s":"The scientist carefully handled the undiluted chemical solution, knowing that even a small drop of the pure substance could cause a dangerous reaction in the laboratory.","p":"uh-nduh-LOO-tihd","o":"Latin","y":5,"bp":34,"m":"undilluted","sy":"ah.ndah.luw.tih.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"undivided","d":"not parted by conflict of opinion","s":"Presented an undivided front.","p":"uh-nduh-VEYE-dihd","o":"Latin","y":4,"bp":34,"m":"undiveded","sy":"ah.ndah.vay.dih.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"undocking","d":"move out of a dock","s":"As the astronauts began undocking their spacecraft from the international space station, mission control carefully monitored every system to ensure a safe and smooth separation.","p":"uh-NDAH-kihng","o":"Dutch","y":6,"bp":29,"m":"undoking","sy":"ah.ndaa.kih.ng","nt":"Open","ps":"verb","t":["seafaring","odutch"]},{"w":"undoing","d":"an act that makes a previous act of no effect (as if not done)","p":"uh-NDOO-ihng","o":"Old English","y":5,"bp":27,"m":"undoeing","sy":"ah.nduw.ih.ng","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"undreamed","d":"not imagined even in a dream","s":"The invention brought undreamed riches to the young scientist who created it.","p":"uh-NDREEMD","o":"Old English","y":6,"bp":27,"m":"undreamt","sy":"ah.ndriy.md","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"undress","d":"to take off one's clothes","s":"After returning from a long day hiking through muddy trails, Marcus went straight to his room to undress and change into clean, comfortable clothes before dinner.","p":"uh-NDREHS","o":"Latin","y":4,"bp":30,"m":"undres","sy":"ah.ndreh.s","nt":"Open","ps":"noun","t":["olatin"]},{"w":"undressed","d":"Removed the clothing from your body.","p":"uh-NDREHST","o":"French","y":5,"bp":31,"m":"undrest","sy":"ah.ndreh.st","nt":"Open","ps":"verb","t":["ofrench"]},{"w":"undulate","d":"stir up (water) so as to form ripples","p":"UH-njuh-layt","o":"Latin","y":7,"bp":32,"m":"undualte","sy":"ah.njhah.ley.t","nt":"Open","ps":"verb","t":["olatin"]},{"w":"undulated","d":"stir up (water) so as to form ripples","p":"UH-njuh-lay-tuhd","o":"Latin","y":6,"bp":34,"m":"undualted","sy":"ah.njhah.ley.tah.d","nt":"Open","ps":"verb","t":["olatin"]},{"w":"undulates","d":"stir up (water) so as to form ripples","p":"UH-njuh-layts","o":"Latin","y":7,"bp":33,"m":"undulaits","sy":"ah.njhah.ley.ts","nt":"Open","ps":"verb","t":["olatin"]},{"w":"undying","d":"Lasting forever; never fading or coming to an end, especially referring to strong emotions or loyalty.","s":"The loyal knight pledged his undying devotion to the queen, promising that no force on earth could ever weaken his commitment to protecting her kingdom.","p":"uh-NDEYE-ihng","o":"Latin","y":4,"bp":31,"m":"undieing","sy":"ah.nday.ih.ng","nt":"Open","ps":"adjective","t":["emotions","olatin"]},{"w":"unearned","d":"not gained by merit or labor or service","s":"Accepted the unearned rewards that came his ways as well as the unearned criticism.","p":"uh-NURND","o":"Old English","y":4,"bp":26,"m":"unearnned","sy":"ah.ner.nd","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unearth","d":"bring to light","s":"The archaeologists hoped to unearth ancient pottery buried beneath the field.","p":"uh-NURTH","o":"Old English","y":4,"bp":26,"m":"unerath","sy":"ah.ner.th","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"unearthed","d":"bring to light","s":"The CIA unearthed a plot to kill the President.","p":"uh-NURTHT","o":"Old English","y":4,"bp":27,"sy":"ah.ner.tht","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"unearthly","d":"concerned with or affecting the spirit or soul","p":"uh-NUR-thlee","o":"Latin","y":5,"bp":33,"m":"unearthley","sy":"ah.ner.thliy","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"uneasily","d":"with anxiety or apprehension","p":"uh-NEE-zuh-lee","o":"Old English","y":5,"bp":29,"m":"uneasaly","sy":"ah.niy.zah.liy","nt":"Open","ps":"adverb","t":["emotions","ooldeng"]},{"w":"unedited","d":"not changed by editing","s":"The director released an unedited version of the film for true fans to enjoy.","p":"uh-NEH-duh-tihd","o":"Latin","y":4,"bp":33,"m":"uneditied","sy":"ah.neh.dah.tih.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unending","d":"continuing forever or indefinitely","p":"uh-NEH-ndihng","o":"Old English","y":4,"bp":28,"m":"unennding","sy":"ah.neh.ndih.ng","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unequal","d":"poorly balanced or matched in quantity or value or measure","s":"The two wrestlers were clearly unequal in strength, as the smaller competitor struggled to hold his ground against the much larger and more experienced opponent on the mat.","p":"uh-NEE-kwuhl","o":"Latin","y":4,"bp":31,"m":"unequil","sy":"ah.niy.kwah.l","nt":"Open","ps":"adjective","t":["numbers","olatin"]},{"w":"unequaled","d":"radically distinctive and without equal","p":"uh-NEE-kwuhld","o":"Latin","y":7,"bp":33,"m":"unequalted","sy":"ah.niy.kwah.ld","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unethical","d":"not conforming to approved standards of social or professional behavior","p":"uh-NEH-thih-kuhl","o":"Greek","y":3,"bp":34,"m":"unethicle","sy":"ah.neh.thih.kah.l","nt":"Open","ps":"adjective","t":["ogreek"]},{"w":"unevenly","d":"in an uneven and irregular way","p":"uh-NEE-vuh-nlee","o":"Old English","y":4,"bp":29,"m":"unevenley","sy":"ah.niy.vah.nliy","nt":"Open","ps":"adverb","t":["ooldeng"]},{"w":"unexpired","d":"not having come to an end or been terminated by passage of time","s":"Elected to fill the senator's unexpired term.","p":"uh-nih-KSPEYE-erd","o":"Latin","y":5,"bp":34,"m":"unexpiried","sy":"ah.nih.kspay.er.d","nt":"Open","ps":"adjective","t":["time","olatin"]},{"w":"unfailing","d":"not liable to failure","p":"uh-NFAY-lihng","o":"Old English","y":6,"bp":29,"m":"unfailling","sy":"ah.nfey.lih.ng","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unfairly","d":"in an unfair manner","s":"They dealt with him unfairly.","p":"uh-NFEH-rlee","o":"Latin","y":4,"bp":32,"m":"unfairley","sy":"ah.nfeh.rliy","nt":"Open","ps":"adverb","t":["olatin"]},{"w":"unfeeling","d":"devoid of feeling for others","s":"The unfeeling landlord ignored his tenants' desperate pleas for heat during the freezing winter, refusing to make repairs even when small children were shivering in their apartments.","p":"uh-NFEE-lihng","o":"Latin","y":5,"bp":33,"m":"unfealling","sy":"ah.nfiy.lih.ng","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unfenced","d":"not enclosed by a fence","s":"The unfenced meadow allowed the horses to roam freely across the rolling hills.","p":"uh-NFEHNST","o":"Old English","y":6,"bp":26,"m":"unfensed","sy":"ah.nfeh.nst","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unfilled","d":"of purchase orders that have not been filled","s":"The restaurant had several unfilled positions because few people had applied.","p":"uh-NFIHLD","o":"Old English","y":6,"bp":26,"m":"unfilld","sy":"ah.nfih.ld","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unfocused","d":"(of an image) not being in or brought into focus","p":"uh-NFOH-kuhst","o":"Latin","y":5,"bp":33,"m":"unfoccused","sy":"ah.nfow.kah.st","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unfolded","d":"develop or come to a promising stage","p":"uh-NFOH-ldihd","o":"Old English","y":3,"bp":28,"m":"unfoleded","sy":"ah.nfow.ldah.d","nt":"Open","ps":"verb","t":["stage","ooldeng"]},{"w":"unfolding","d":"a developmental process","p":"uh-NFOH-ldihng","o":"Old English","y":3,"bp":29,"m":"unfoldding","sy":"ah.nfow.ldih.ng","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"unfolds","d":"develop or come to a promising stage","p":"uh-NFOHLDZ","o":"Old English","y":3,"bp":26,"m":"unfoldes","sy":"ah.nfow.ldz","nt":"Open","ps":"verb","t":["growth","ooldeng"]},{"w":"unformed","d":"not having form or shape","s":"The sculptor stared at the unformed lump of clay sitting on her worktable, trying to imagine what magnificent shape would eventually emerge from its rough and shapeless mass.","p":"uh-NFAWRMD","o":"Latin","y":5,"bp":30,"m":"unformd","sy":"ah.nfao.rmd","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unfounded","d":"without a basis in reason or fact","s":"The rumors that the school was going to cancel the spring talent show turned out to be completely unfounded, as the principal confirmed the event would proceed as planned.","p":"uh-NFOW-ndihd","o":"Old English","y":5,"bp":29,"m":"unfownded","sy":"ah.nfaw.ndih.d","nt":"Open","ps":"adjective","t":["logic","ooldeng"]},{"w":"unfrozen","d":"become or cause to become soft or liquid","p":"uh-NFROH-zihn","o":"Old English","y":5,"bp":28,"m":"unfrozzen","sy":"ah.nfrow.zih.n","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"unfunded","d":"not furnished with funds","s":"The after-school art program was left unfunded when the district budget was cut, leaving dozens of students without supplies or a teacher to guide their creative projects.","p":"uh-NFUH-ndihd","o":"Latin","y":4,"bp":32,"m":"unfunnded","sy":"ah.nfah.ndih.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unfurled","d":"unroll, unfold, or spread out or be unrolled, unfolded, or spread out from a furled state","s":"The enormous banner unfurled dramatically from the stadium rafters, revealing a colorful message of congratulations that stretched nearly the entire length of the championship basketball court below.","p":"uh-NFURLD","o":"Dutch","y":5,"bp":26,"m":"unfurrled","sy":"ah.nfer.ld","nt":"Open","ps":"verb","t":["odutch"]},{"w":"unfurling","d":"unroll, unfold, or spread out or be unrolled, unfolded, or spread out from a furled state","s":"The young sailor watched in awe as the massive sails began unfurling in the ocean breeze, snapping open one by one and filling with wind to propel the ship forward.","p":"uh-NFUR-lihng","o":"Dutch","y":6,"bp":29,"m":"unfurrling","sy":"ah.nfer.lih.ng","nt":"Open","ps":"verb","t":["odutch"]},{"w":"ungainly","d":"lacking grace in movement or posture","s":"A gawky lad with long ungainly legs.","p":"uh-NGAY-nlee","o":"Norse","y":6,"bp":28,"m":"ungainely","sy":"ah.ngey.nliy","nt":"Open","ps":"adjective","t":["onordic"]},{"w":"ungodly","d":"characterized by iniquity; wicked because it is believed to be a sin","s":"My alarm went off at an ungodly hour of four in the morning, and I groaned into my pillow, wondering why I had ever agreed to run in a sunrise marathon.","p":"uh-NGAW-dlee","o":"Old English","y":4,"bp":27,"m":"ungodley","sy":"ah.ngao.dliy","nt":"Open","ps":"adjective","t":["character","ooldeng"]},{"w":"unguarded","d":"lacking protection or a guard","s":"The treasure room was left completely unguarded during the festival, giving the clever thief the perfect opportunity to slip inside without anyone noticing his suspicious movements.","p":"uh-NGAH-rdihd","o":"French","y":6,"bp":33,"m":"ungarded","sy":"ah.ngaa.rdih.d","nt":"Open","ps":"adjective","t":["ofrench"]},{"w":"unhappily","d":"in an unpleasant way","s":"They were unhappily married.","p":"uh-NHA-puh-lee","o":"Old English","y":5,"bp":30,"sy":"ah.nhhae.pah.liy","nt":"Open","ps":"adverb","t":["ooldeng"]},{"w":"unhappy","d":"experiencing or marked by or causing sadness or sorrow or discontent","s":"Unhappy over her departure.","p":"uh-NHA-pee","o":"Old English","y":2,"bp":27,"m":"unhappi","sy":"ah.nhhae.piy","nt":"Open","ps":"adjective","t":["emotions","ooldeng"]},{"w":"unharmed","d":"Free from injury or damage; not hurt or harmed in any way despite facing danger or difficulty.","s":"Remarkably, all the passengers walked away from the crash completely unharmed.","p":"uh-NHAHRMD","o":"Old English","y":3,"bp":26,"m":"unhamed","sy":"ah.nhhaa.rmd","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unhealthy","d":"not in or exhibiting good health in body or mind","s":"Eating fast food every single day is considered unhealthy because it can lead to serious problems like high blood pressure, weight gain, and a weakened immune system over time.","p":"uh-NHEH-lthee","o":"Old English","y":3,"bp":29,"m":"unheathly","sy":"ah.nhheh.lthiy","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unheard","d":"not necessarily inaudible but not heard","s":"Her quiet voice was unheard over the noise of the crowded gymnasium.","p":"uh-NHURD","o":"Old English","y":3,"bp":26,"m":"unherd","sy":"ah.nhher.d","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unheeded","d":"Not paid attention to or taken notice of; ignored despite being given as a warning or piece of advice.","s":"His cries were unheeded.","p":"uh-NHEE-dihd","o":"Old English","y":5,"bp":28,"m":"unheded","sy":"ah.nhhiy.dih.d","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unhelpful","d":"providing no assistance","s":"The vague directions were unhelpful, leaving the tourists more confused than before.","p":"uh-NHEH-lpfuhl","o":"Latin","y":4,"bp":33,"m":"unhelpfull","sy":"ah.nhheh.lpfah.l","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unhinge","d":"disturb in mind or make uneasy or cause to be worried or alarmed","p":"uh-NHIHNJ","o":"Dutch","y":7,"bp":26,"m":"unhinje","sy":"ah.nhhih.njh","nt":"Open","ps":"verb","t":["odutch"]},{"w":"unhinged","d":"disturb in mind or make uneasy or cause to be worried or alarmed","p":"uh-NHIHNJD","o":"Dutch","y":4,"bp":26,"m":"unhinjed","sy":"ah.nhhih.njhd","nt":"Open","ps":"verb","t":["odutch"]},{"w":"unhitch","d":"unfasten or release from or as if from a hitch","s":"The farmer stopped to unhitch the wagon from the tired old horse.","p":"uh-NHIHCH","o":"Old English","y":7,"bp":26,"m":"unhich","sy":"ah.nhhih.ch","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"unhorsed","d":"alight from (a horse)","s":"The knight was unhorsed during the jousting tournament and landed in the mud.","p":"uh-NHAWRST","o":"Old English","y":6,"bp":26,"m":"unhorst","sy":"ah.nhhao.rst","nt":"Open","ps":"verb","t":["animals","ooldeng"]},{"w":"unhurried","d":"relaxed and leisurely; without hurry or haste","s":"People strolling about in an unhurried way.","p":"uh-NHUR-eed","o":"Old English","y":6,"bp":29,"m":"unhuryed","sy":"ah.nhher.iy.d","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unicorn","d":"an imaginary creature represented as a white horse with a long horn growing from its forehead","s":"The little girl drew a glittery unicorn with a silver horn on her birthday card.","p":"YOO-nih-kawrn","o":"Latin","y":2,"bp":31,"m":"unikorn","sy":"yuw.nih.kao.rn","nt":"Open","ps":"noun","t":["animals","olatin"]},{"w":"unicycle","d":"a vehicle with a single wheel that is driven by pedals","s":"The circus performer balanced perfectly on his unicycle while juggling three oranges.","p":"YOO-nuh-seye-kuhl","o":"Latin","y":7,"bp":33,"m":"unicicle","sy":"yuw.nah.say.kah.l","nt":"Open","ps":"noun","t":["vehicles","olatin"]},{"w":"unicycles","d":"a vehicle with a single wheel that is driven by pedals","s":"The gymnasium stored several unicycles that students could borrow for the talent show.","p":"YOO-nuh-seye-kuhlz","o":"Latin","y":8,"bp":34,"m":"unicicles","sy":"yuw.nah.say.kah.lz","nt":"Open","ps":"noun","t":["vehicles","olatin"]},{"w":"unified","d":"Joined together as a single whole; combined so that separate parts work or act as one unit.","s":"Germany unified officially in 1990.","p":"YOO-nuh-feyed","o":"Latin","y":2,"bp":31,"m":"unifyed","sy":"yuw.nah.fay.d","nt":"Open","ps":"verb","t":["olatin"]},{"w":"uniform","d":"clothing of distinctive design worn by members of a particular group as a means of identification","s":"The guards were uniformed.","p":"YOO-nuh-fawrm","o":"Latin","y":1,"bp":31,"m":"unifrom","sy":"yuw.nah.fao.rm","nt":"Open","ps":"noun","t":["olatin"]},{"w":"uniformed","d":"provide with uniforms","s":"The guards were uniformed.","p":"YOO-nuh-fawrmd","o":"Latin","y":4,"bp":33,"m":"uniforemed","sy":"yuw.nah.fao.rmd","nt":"Open","ps":"verb","t":["olatin"]},{"w":"uniformly","d":"in a uniform manner","s":"A uniformly bright surface.","p":"YOO-nuh-faw-rmlee","o":"Latin","y":4,"bp":34,"m":"uniformley","sy":"yuw.nah.fao.rmliy","nt":"Open","ps":"adverb","t":["olatin"]},{"w":"uniforms","d":"clothing of distinctive design worn by members of a particular group as a means of identification","p":"YOO-nuh-fawrmz","o":"Latin","y":2,"bp":32,"m":"unifroms","sy":"yuw.nah.fao.rmz","nt":"Open","ps":"noun","t":["olatin"]},{"w":"unifying","d":"Bringing or joining separate things or people together so that they become a single, coherent whole.","p":"YOO-nuh-feye-ihng","o":"Latin","y":3,"bp":33,"m":"unifiyng","sy":"yuw.nah.fay.ih.ng","nt":"Open","ps":"verb","t":["olatin"]},{"w":"unimpeded","d":"not slowed or prevented","s":"A time of unimpeded growth.","p":"uh-nih-MPEE-dihd","o":"Latin","y":5,"bp":34,"sy":"ah.nih.mpiy.dih.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"uninjured","d":"not injured physically or mentally","s":"Both drivers were uninjured after the fender-bender at the intersection.","p":"uh-NIH-njerd","o":"Latin","y":5,"bp":33,"m":"uninjurred","sy":"ah.nih.njher.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"uninsured","d":"not covered by insurance","p":"uh-nih-NSHUURD","o":"French","y":4,"bp":33,"m":"uninsurred","sy":"ah.nih.nshuh.rd","nt":"Open","ps":"adjective","t":["ofrench"]},{"w":"uninvited","d":"unwelcome and unwanted","s":"The uninvited raccoon waddled into our campsite and helped himself to an entire bag of trail mix before we could shoo him back into the surrounding forest underbrush.","p":"uh-nih-NVEYE-tihd","o":"Latin","y":4,"bp":34,"m":"uninvitted","sy":"ah.nih.nvay.tih.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unionism","d":"the system or principles and theory of labor unions","s":"The professor lectured on unionism and how labor unions changed working conditions in factories.","p":"YOO-nyuh-nih-zuhm","o":"Latin","y":4,"bp":33,"m":"unionisim","sy":"yuw.nyah.nih.zah.m","nt":"Open","ps":"noun","t":["logic","olatin"]},{"w":"unionist","d":"a worker who belongs to a trade union","s":"As a proud unionist, she fought for better wages and safer conditions at the plant.","p":"YOO-nyuh-nuhst","o":"Latin","y":3,"bp":32,"m":"unionnist","sy":"yuw.nyah.nah.st","nt":"Open","ps":"noun","t":["economy","olatin"]},{"w":"unionists","d":"a worker who belongs to a trade union","s":"The unionists gathered outside city hall to demand fair treatment for all workers.","p":"YOO-nyuh-nihsts","o":"Latin","y":4,"bp":33,"m":"unionissts","sy":"yuw.nyah.nih.sts","nt":"Open","ps":"noun","t":["economy","olatin"]},{"w":"unionize","d":"recruit for a union or organize into a union","s":"We don't allow people to come into our plant and try to unionize the workers.","p":"YOO-nyuh-neyez","o":"Latin","y":6,"bp":32,"m":"unionise","sy":"yuw.nyah.nay.z","nt":"Open","ps":"verb","t":["olatin"]},{"w":"unionized","d":"recruit for a union or organize into a union","p":"YOO-nyuh-neyezd","o":"Latin","y":5,"bp":33,"m":"unionised","sy":"yuw.nyah.nay.zd","nt":"Open","ps":"verb","t":["olatin"]},{"w":"uniquely","d":"so as to be unique","s":"He could determine uniquely the properties of the compound.","p":"yoo-NEE-klee","o":"French","y":4,"bp":32,"m":"uniquly","sy":"yuw.niy.kliy","nt":"Open","ps":"adverb","t":["ofrench"]},{"w":"unisons","d":"musical notes or parts sounded together at exactly the same pitch","s":"The choir director asked the students to practice their unisons carefully, making sure every voice matched the exact same pitch so the harmonies would blend perfectly during the concert.","p":"YOO-nuh-suhnz","o":"Latin","y":8,"bp":31,"m":"unissons","sy":"yuw.nah.sah.nz","nt":"Open","ps":"noun","t":["olatin"]},{"w":"unitarian","d":"adherent of Unitarianism","s":"The Unitarian congregation welcomed people of many different faiths and backgrounds.","p":"yoo-nuh-TEH-ree-uhn","o":"Latin","y":4,"bp":36,"m":"uniterian","sy":"yuw.nah.teh.riy.ah.n","nt":"Open","ps":"noun","t":["olatin"]},{"w":"unitary","d":"relating to or characterized by or aiming toward unity","s":"The unitary principles of nationalism.","p":"YOO-nih-teh-ree","o":"Latin","y":3,"bp":33,"m":"unitery","sy":"yuw.nih.teh.riy","nt":"Open","ps":"adjective","t":["character","olatin"]},{"w":"uniting","d":"joining together to act as one","p":"yoo-NEYE-tihng","o":"Latin","y":3,"bp":31,"m":"unniting","sy":"yuw.nay.tih.ng","nt":"Open","ps":"noun","t":["economy","olatin"]},{"w":"universal","d":"(linguistics) a grammatical rule (or other linguistic feature) that is found in all languages","s":"Some form of religion seems to be a human universal.","p":"yoo-nuh-VUR-suhl","o":"Latin","y":2,"bp":34,"m":"universel","sy":"yuw.nah.ver.sah.l","nt":"Open","ps":"noun","t":["wordwords","olatin"]},{"w":"universe","d":"everything that exists anywhere","s":"They study the evolution of the universe.","p":"YOO-nuh-vurs","o":"French","y":2,"bp":73,"m":"univerce","sy":"yuw.nah.ver.s","nt":"Open | North South Finals","ps":"noun","t":["ofrench"]},{"w":"universes","d":"everything that exists anywhere","p":"YOO-nuh-vur-sihz","o":"Latin","y":4,"bp":34,"m":"univerces","sy":"yuw.nah.ver.sih.z","nt":"Open","ps":"noun","t":["olatin"]},{"w":"unjustly","d":"in an unjust manner","s":"He was unjustly singled out for punishment.","p":"uh-NJUH-stlee","o":"Latin","y":4,"bp":32,"m":"unjustley","sy":"ah.njhah.stliy","nt":"Open","ps":"adverb","t":["olatin"]},{"w":"unkindest","d":"lacking kindness","p":"uh-NKEYE-ndihst","o":"Old English","y":7,"bp":29,"m":"unkindist","sy":"ah.nkay.ndih.st","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unknowing","d":"not aware of what is happening","p":"uh-NNOH-ihng","o":"Latin","y":5,"bp":33,"m":"unknoweing","sy":"ah.nnow.ih.ng","nt":"Open","ps":"noun","t":["logic","olatin"]},{"w":"unknown","d":"Not familiar, discovered, or understood; something nobody has learned about yet.","s":"They came like angels out the unknown.","p":"uh-NNOHN","o":"Latin","y":1,"bp":30,"m":"unkown","sy":"ah.nnow.n","nt":"Open","ps":"noun","t":["olatin"]},{"w":"unknowns","d":"an unknown and unexplored region","p":"uh-NOHNZ","o":"Old English","y":4,"bp":26,"m":"unkows","sy":"ah.now.nz","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"unlabeled","d":"lacking a label or tag","s":"Unlabeled luggage is liable to be lost.","p":"uh-NLAY-buhld","o":"Old English","y":5,"bp":29,"m":"unlabelled","sy":"ah.nley.bah.ld","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unlawful","d":"not conforming to legality, moral law, or social convention","p":"uh-NLAW-fuhl","o":"Old English","y":2,"bp":28,"m":"unlawfull","sy":"ah.nlao.fah.l","nt":"Open","ps":"adjective","t":["law","logic","ooldeng"]},{"w":"unleaded","d":"not treated with lead","s":"When filling up the car at the gas station, Dad always chose unleaded fuel because it was better for the engine and significantly cleaner for the surrounding environment.","p":"uh-NLEH-dihd","o":"Latin","y":5,"bp":32,"m":"unleeded","sy":"ah.nleh.dah.d","nt":"Open","ps":"adjective","t":["chemistry","olatin"]},{"w":"unleash","d":"release or vent","s":"The coach warned the team that if they worked together and played with confidence, they had the power to unleash an unstoppable offensive strategy that would catch their rivals completely off guard.","p":"uh-NLEESH","o":"Old English","y":3,"bp":26,"m":"unleesh","sy":"ah.nliy.sh","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"unleashed","d":"release or vent","s":"When the final bell rang on the last day of school, the students unleashed a thunderous cheer that echoed through every hallway and could be heard from the parking lot outside.","p":"uh-NLEESHT","o":"Old English","y":3,"bp":27,"m":"unleasht","sy":"ah.nliy.sht","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"unleashes","d":"release or vent","s":"Every time the thunderstorm rolls across the valley, it unleashes a spectacular display of lightning that illuminates the dark sky and sends the family dog sprinting under the bed in fright.","p":"uh-NLEE-shihz","o":"Old English","y":4,"bp":29,"m":"unleashs","sy":"ah.nliy.shih.z","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"unlikely","d":"not likely to be true or to occur or to have occurred","s":"Legislation on the question is highly unlikely.","p":"uh-NLEYE-klee","o":"Norse","y":2,"bp":28,"m":"unlikley","sy":"ah.nlay.kliy","nt":"Open","ps":"adjective","t":["onordic"]},{"w":"unlimited","d":"having no limits in range or scope","s":"To start with a theory of unlimited freedom is to end up with unlimited despotism.","p":"uh-NLIH-muh-tihd","o":"Latin","y":2,"bp":34,"m":"unlimmited","sy":"ah.nlih.mah.tah.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unlined","d":"not having a lining or liner","s":"A thin unlined jacket.","p":"uh-NLEYEND","o":"Old English","y":5,"bp":26,"m":"unlinned","sy":"ah.nlay.nd","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unlisted","d":"not on a list","s":"An unlisted telephone number.","p":"uh-NLIH-stihd","o":"Old English","y":4,"bp":28,"m":"unlistted","sy":"ah.nlih.stih.d","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unlivable","d":"Not safe or fit for anyone to stay or dwell in.","p":"uh-NLIH-vuh-buhl","o":"Old English","y":7,"bp":30,"m":"unliveable","sy":"ah.nlih.vah.bah.l","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unloaded","d":"leave or unload","s":"The delivery crew unloaded box after box of new textbooks from the truck, stacking them carefully in the school hallway until every classroom had received its full supply for the semester.","p":"uh-NLOH-dihd","o":"Old English","y":3,"bp":28,"m":"unloeded","sy":"ah.nlow.dah.d","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"unloading","d":"the labor of taking a load of something off of or out of a vehicle or ship or container etc.","s":"The dock workers spent three hours unloading the massive cargo ship, carefully lifting heavy crates with a crane and placing them onto waiting forklifts on the busy waterfront.","p":"uh-NLOH-dihng","o":"Old English","y":4,"bp":29,"sy":"ah.nlow.dih.ng","nt":"Open","ps":"noun","t":["seafaring","vehicles","ooldeng"]},{"w":"unloads","d":"leave or unload","s":"Every morning before sunrise, the bakery driver unloads dozens of fresh bread trays at the back entrance of the grocery store so shelves are fully stocked when the doors open.","p":"uh-NLOHDZ","o":"Old English","y":5,"bp":26,"m":"unloades","sy":"ah.nlow.dz","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"unlocked","d":"open the lock of","s":"The detective unlocked the old wooden chest with a tiny brass key and discovered a bundle of letters that finally revealed the mystery everyone in the village had wondered about for decades.","p":"uh-NLAHKT","o":"Old English","y":2,"bp":26,"m":"unlockt","sy":"ah.nlaa.kt","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"unlocking","d":"open the lock of","s":"By studying ancient languages, the young archaeologist was slowly unlocking the secrets of a civilization that had been forgotten for over two thousand years beneath layers of desert sand.","p":"uh-NLAH-kihng","o":"Old English","y":3,"bp":29,"m":"unlockin","sy":"ah.nlaa.kih.ng","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"unloved","d":"Not receiving love or affection from others; feeling or being without the care and warmth that comes from loving relationships.","s":"The unloved puppy sat alone in the corner of the shelter, waiting for someone to notice him.","p":"uh-NLUHVD","o":"Latin","y":4,"bp":30,"m":"unlovved","sy":"ah.nlah.vd","nt":"Open","ps":"adjective","t":["emotions","olatin"]},{"w":"unlucky","d":"having or bringing misfortune","s":"Friday the 13th is an unlucky date.","p":"uh-NLUH-kee","o":"Old English","y":2,"bp":27,"m":"unluckey","sy":"ah.nlah.kiy","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"undeclared","d":"not announced or openly acknowledged","s":"Fighting an undeclared war.","p":"uh-ndih-KLEHRD","o":"French","y":5,"bp":34,"m":"undeclaired","sy":"ah.ndih.kleh.rd","nt":"Open","ps":"adjective","t":["ofrench"]},{"w":"undefeated","d":"Having never lost a competition or battle; remaining victorious throughout an entire season or series of contests without a single defeat.","p":"uh-ndih-FEE-tihd","o":"French","y":3,"bp":35,"m":"undefeeted","sy":"ah.ndih.fiy.tih.d","nt":"Open","ps":"adjective","t":["war","sports","time","ofrench"]},{"w":"undemocratic","d":"not in agreement with or according to democratic doctrine or practice or ideals","s":"The union broke with its past undemocratic procedures.","p":"uh-ndeh-muh-KRA-tihk","o":"Greek","y":5,"bp":38,"m":"undemocratick","sy":"ah.ndeh.mah.krae.tih.k","nt":"Open","ps":"adjective","t":["politics","logic","ogreek"]},{"w":"undeniable","d":"not possible to deny","s":"The scientist presented undeniable evidence that the ancient fossils were over three million years old.","p":"uh-ndih-NEYE-uh-buhl","o":"Latin","y":5,"bp":37,"m":"undenieable","sy":"ah.ndih.nay.ah.bah.l","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"undeniably","d":"to an undeniable degree or in an undeniable manner","s":"She is undeniably the most gifted student in the class.","p":"uh-ndih-NEYE-uh-blee","o":"Latin","y":4,"bp":37,"m":"undeniabley","sy":"ah.ndih.nay.ah.bliy","nt":"Open","ps":"adverb","t":["olatin"]},{"w":"underbelly","d":"The soft, vulnerable underside of an animal or, figuratively, the weakest or most unprotected part of something such as an organization or system.","p":"UH-nder-beh-lee","o":"Old English","y":6,"bp":31,"m":"underbely","sy":"ah.nder.beh.liy","nt":"Open","ps":"noun","t":["animals","ooldeng"]},{"w":"underbrush","d":"the brush (small trees and bushes and ferns etc.) growing beneath taller trees in a wood or forest","s":"The hikers struggled to push through the thick underbrush that tangled around their ankles with every step.","p":"UH-nder-bruhsh","o":"French","y":6,"bp":34,"sy":"ah.nder.brah.sh","nt":"Open","ps":"noun","t":["botany","ofrench"]},{"w":"underclass","d":"the social class lowest in the social hierarchy","s":"Underclass mothers and children.","p":"UH-nder-klas","o":"Old English","y":6,"bp":71,"sy":"ah.nder.klae.s","nt":"Open | North South Finals","ps":"noun","t":["ooldeng"]},{"w":"undercover","d":"conducted with or marked by hidden aims or methods","p":"uh-nder-KUH-ver","o":"Old English","y":3,"bp":31,"sy":"ah.nder.kah.ver","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"undercurrent","d":"a subdued emotional quality underlying an utterance; implicit meaning","s":"There was an undercurrent of tension at the dinner table even though everyone was smiling and speaking politely.","p":"UH-nder-kur-uhnt","o":"Old English","y":6,"bp":33,"m":"undercurrant","sy":"ah.nder.ker.ah.nt","nt":"Open","ps":"noun","t":["emotions","ooldeng"]},{"w":"undercutting","d":"sell cheaper than one's competition","p":"UH-nder-kuh-tihng","o":"Old English","y":7,"bp":33,"m":"undercuting","sy":"ah.nder.kah.tih.ng","nt":"Open","ps":"verb","t":["sports","ooldeng"]},{"w":"underdevelop","d":"process (a film or photographic plate) less than the required time or in an ineffective solution or at an insufficiently high temperature","s":"These photos are underdeveloped.","p":"uh-nder-dih-VEH-luhp","o":"Old English","y":8,"bp":34,"sy":"ah.nder.dih.veh.lah.p","nt":"Open","ps":"verb","t":["time","ooldeng"]},{"w":"undergarment","d":"a garment worn under other garments","s":"In medieval times, a linen undergarment called a chemise was worn beneath heavy woolen robes for comfort.","p":"UH-nder-gah-rmuhnt","o":"French","y":6,"bp":37,"m":"undergament","sy":"ah.nder.gaa.rmah.nt","nt":"Open","ps":"noun","t":["fabrics","ofrench"]},{"w":"undergoing","d":"pass through","p":"uh-nder-GOH-ihng","o":"Old English","y":4,"bp":31,"m":"undergowing","sy":"ah.nder.gow.ih.ng","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underground","d":"below the surface of the earth, or a railway that runs beneath a city","s":"In Paris the subway system is called the \`metro' and in London it is called the \`tube' or the \`underground'.","p":"UH-nder-grownd","o":"Old English","y":3,"bp":30,"m":"undreground","sy":"ah.nder.graw.nd","nt":"Open","ps":"noun","t":["physics","politics","jobs","ooldeng"]},{"w":"undergrowth","d":"the brush (small trees and bushes and ferns etc.) growing beneath taller trees in a wood or forest","s":"The fox disappeared silently into the undergrowth before the hunters could spot exactly which direction it went.","p":"UH-nder-grohth","o":"Old English","y":5,"bp":30,"m":"undergrowt","sy":"ah.nder.grow.th","nt":"Open","ps":"noun","t":["botany","ooldeng"]},{"w":"underhanded","d":"marked by deception","p":"uh-nder-HA-ndihd","o":"Old English","y":5,"bp":32,"m":"underhandid","sy":"ah.nder.hhae.ndih.d","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"underlined","d":"give extra weight to (a communication)","p":"UH-nder-leyend","o":"Old English","y":4,"bp":30,"m":"underlyned","sy":"ah.nder.lay.nd","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underlines","d":"a line drawn underneath (especially under written matter)","p":"UH-nder-leyenz","o":"Old English","y":5,"bp":30,"m":"underlynes","sy":"ah.nder.lay.nz","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"underlings","d":"an assistant subject to the authority or control of another","s":"The villain in the story barked orders at his underlings, who scrambled to carry them out without question.","p":"UH-nder-lihngz","o":"Old English","y":5,"bp":30,"m":"underlungs","sy":"ah.nder.lih.ngz","nt":"Open","ps":"noun","t":["jobs","ooldeng"]},{"w":"underlining","d":"give extra weight to (a communication)","p":"UH-nder-leye-nihng","o":"Old English","y":5,"bp":32,"m":"underlyning","sy":"ah.nder.lay.nih.ng","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underlying","d":"be or form the base for","p":"uh-nder-LEYE-ihng","o":"Old English","y":2,"bp":31,"m":"underlaying","sy":"ah.nder.lay.ih.ng","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"undermanned","d":"inadequate in number of workers or assistants etc.","p":"UH-nder-mand","o":"Old English","y":7,"bp":30,"m":"undermaned","sy":"ah.nder.mae.nd","nt":"Open","ps":"adjective","t":["numbers","ooldeng"]},{"w":"undermined","d":"destroy property or hinder normal operations","p":"uh-nder-MEYEND","o":"Old English","y":4,"bp":30,"m":"undermyned","sy":"ah.nder.may.nd","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"undermines","d":"destroy property or hinder normal operations","p":"uh-nder-MEYENZ","o":"Old English","y":4,"bp":30,"m":"undermynes","sy":"ah.nder.may.nz","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"undermining","d":"the act of gradually weakening something or someone","p":"UH-nder-meye-nihng","o":"Old English","y":4,"bp":32,"m":"undermyneing","sy":"ah.nder.may.nih.ng","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underneath","d":"on the lower or downward side; on the underside of","s":"A chest of drawers all scratched underneath.","p":"uh-nder-NEETH","o":"Old English","y":2,"bp":30,"m":"underneathe","sy":"ah.nder.niy.th","nt":"Open","ps":"adverb","t":["ooldeng"]},{"w":"undernourish","d":"provide with insufficient quality or quantity of nourishment","s":"The stunted growth of these children shows that they are undernourished.","p":"uh-nder-NUR-ihsh","o":"Latin","y":9,"bp":37,"m":"undernurrish","sy":"ah.nder.ner.ih.sh","nt":"Open","ps":"verb","t":["olatin"]},{"w":"underpants","d":"an undergarment that covers the body from the waist no further than to the thighs; usually worn next to the skin","s":"He was so rushed in the morning that he nearly left the house without remembering to pack a change of underpants.","p":"UH-nder-pants","o":"Old English","y":4,"bp":30,"m":"underpance","sy":"ah.nder.pae.nts","nt":"Open","ps":"noun","t":["body","ooldeng"]},{"w":"underpaying","d":"pay too little","s":"The workers organized a protest after discovering that the company had been underpaying them for nearly two years.","p":"UH-nder-pay-ihng","o":"Old English","y":6,"bp":32,"m":"underpaing","sy":"ah.nder.pey.ih.ng","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underpayment","d":"a payment smaller than needed or expected","s":"The accountant discovered an underpayment on last year's tax return and filed an amended form to correct it.","p":"UH-nder-pay-muhnt","o":"Old English","y":6,"bp":33,"m":"underpaymente","sy":"ah.nder.pey.mah.nt","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"underpinned","d":"support from beneath","p":"UH-nder-pihnd","o":"Old English","y":6,"bp":30,"m":"underpined","sy":"ah.nder.pih.nd","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underpinning","d":"support from beneath","p":"UH-nder-pih-nihng","o":"Old English","y":6,"bp":33,"m":"underpining","sy":"ah.nder.pih.nih.ng","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underplayed","d":"act (a role) with great restraint","s":"The veteran actor underplayed the villain so subtly that the audience barely noticed his menace until the final scene.","p":"uh-nder-PLAYD","o":"Old English","y":6,"bp":30,"m":"underplaid","sy":"ah.nder.pley.d","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underprice","d":"sell at artificially low prices","s":"The new bakery decided to underprice its muffins to attract customers away from the established shop down the street.","p":"UH-nder-preyes","o":"Old English","y":8,"bp":30,"m":"underprise","sy":"ah.nder.pray.s","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underpriced","d":"sell at artificially low prices","s":"The rare baseball card was severely underpriced at the garage sale, and a collector snapped it up immediately.","p":"UH-nder-preyest","o":"Old English","y":6,"bp":30,"m":"underprist","sy":"ah.nder.pray.st","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underpricing","d":"sell at artificially low prices","s":"By underpricing their concert tickets, the organizers hoped to fill every seat in the enormous arena.","p":"UH-nder-preye-sihng","o":"Old English","y":7,"bp":33,"m":"underpriseing","sy":"ah.nder.pray.sih.ng","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underrated","d":"make too low an estimate of","p":"uh-nder-RAY-tihd","o":"Old English","y":4,"bp":31,"m":"underraited","sy":"ah.nder.rey.tih.d","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underscore","d":"a line drawn underneath (especially under written matter)","p":"uh-nder-SKAWR","o":"Old English","y":6,"bp":30,"m":"underskor","sy":"ah.nder.skao.r","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"underscored","d":"give extra weight to (a communication)","p":"uh-nder-SKAWRD","o":"Old English","y":5,"bp":30,"m":"underscord","sy":"ah.nder.skao.rd","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underscores","d":"a line drawn underneath (especially under written matter)","p":"uh-nder-SKAWRZ","o":"Old English","y":5,"bp":30,"m":"underskorz","sy":"ah.nder.skao.rz","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"underscoring","d":"give extra weight to (a communication)","p":"uh-nder-SKAW-rihng","o":"Old English","y":6,"bp":33,"m":"underskoreing","sy":"ah.nder.skao.rih.ng","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underselling","d":"sell cheaper than one's competition","s":"The electronics chain boasted that it was underselling every rival store in the city by at least ten percent.","p":"UH-nder-seh-lihng","o":"Old English","y":8,"bp":33,"m":"underseleing","sy":"ah.nder.seh.lih.ng","nt":"Open","ps":"verb","t":["economy","trade","ooldeng"]},{"w":"undershirt","d":"a collarless men's undergarment for the upper part of the body","s":"On the coldest morning of the year, Marcus layered a thermal undershirt beneath his flannel shirt to stay warm.","p":"UH-nder-shurt","o":"Old English","y":6,"bp":30,"m":"undershert","sy":"ah.nder.sher.t","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"undershirts","d":"a collarless men's undergarment for the upper part of the body","s":"Dad packed five white undershirts for the camping trip, knowing he would need a clean one each day.","p":"UH-nder-shurts","o":"Old English","y":7,"bp":30,"m":"undersherts","sy":"ah.nder.sher.ts","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"undersized","d":"smaller than normal for its kind","s":"The undersized puppy was the runt of the litter, but it quickly became everyone's favorite because of its playful spirit.","p":"UH-nder-seyezd","o":"Old English","y":5,"bp":30,"m":"undersised","sy":"ah.nder.say.zd","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"understaffed","d":"inadequate in number of workers or assistants etc.","p":"UH-nder-staft","o":"Old English","y":6,"bp":31,"m":"understafed","sy":"ah.nder.stae.ft","nt":"Open","ps":"adjective","t":["numbers","ooldeng"]},{"w":"understands","d":"know and comprehend the nature or meaning of","p":"uh-nder-STANDZ","o":"Old English","y":2,"bp":30,"m":"undertsands","sy":"ah.nder.stae.ndz","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"understate","d":"represent as less significant or important","s":"It would be an understatement to understate how dangerous the storm was — it uprooted hundreds of ancient trees.","p":"UH-nder-stayt","o":"Latin","y":7,"bp":34,"m":"understait","sy":"ah.nder.stey.t","nt":"Open","ps":"verb","t":["olatin"]},{"w":"understated","d":"represent as less significant or important","s":"The room is pleasant and understated.","p":"UH-nder-stay-tihd","o":"Old English","y":4,"bp":32,"m":"understayted","sy":"ah.nder.stey.tih.d","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"understates","d":"represent as less significant or important","s":"The report understates the impact of the drought by focusing only on crop losses and ignoring the wildlife damage.","p":"UH-nder-stayts","o":"Old English","y":6,"bp":30,"m":"understaits","sy":"ah.nder.stey.ts","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"understating","d":"represent as less significant or important","s":"By understating the risks of the hike, the guide left the tourists completely unprepared for the steep rocky trail.","p":"UH-nder-stay-tihng","o":"Old English","y":6,"bp":33,"m":"understateing","sy":"ah.nder.stey.tih.ng","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"understood","d":"know and comprehend the nature or meaning of","p":"uh-nder-STUUD","o":"Old English","y":2,"bp":30,"m":"understoud","sy":"ah.nder.stuh.d","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"understudy","d":"an actor able to replace a regular performer when required","s":"When the lead actress twisted her ankle backstage, the understudy stepped into the spotlight and delivered a breathtaking performance.","p":"UH-nder-stuh-dee","o":"French","y":5,"bp":35,"m":"understuddy","sy":"ah.nder.stah.diy","nt":"Open","ps":"noun","t":["stage","ofrench"]},{"w":"undertaken","d":"enter upon an activity or enterprise","p":"UH-nder-tay-kuhn","o":"Old English","y":3,"bp":31,"m":"undertakken","sy":"ah.nder.tey.kah.n","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"undertaker","d":"one whose business is the management of funerals","s":"The soft-spoken undertaker arranged every detail of the service with such care that the grieving family felt truly comforted.","p":"UH-nder-tay-ker","o":"Old English","y":4,"bp":31,"m":"undertakker","sy":"ah.nder.tey.ker","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"undertakes","d":"enter upon an activity or enterprise","p":"UH-nder-tayks","o":"Old English","y":4,"bp":30,"m":"undertaiks","sy":"ah.nder.tey.ks","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"undertaking","d":"any piece of work that is undertaken or attempted","s":"He prepared for great undertakings.","p":"UH-nder-tay-kihng","o":"Old English","y":3,"bp":32,"m":"undertakeing","sy":"ah.nder.tey.kih.ng","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"undertakings","d":"any piece of work that is undertaken or attempted","s":"He prepared for great undertakings.","p":"UH-nder-tay-kihngz","o":"Old English","y":5,"bp":33,"sy":"ah.nder.tey.kih.ngz","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"undertones","d":"a quiet or hushed tone of voice","s":"The seemingly cheerful story carried dark undertones of loss and regret that older readers immediately recognized, even though younger children simply enjoyed it as a fun adventure tale.","p":"UH-nder-tohnz","o":"Old English","y":5,"bp":30,"m":"undertoans","sy":"ah.nder.tow.nz","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"undervalue","d":"assign too low a value to","p":"UH-nder-va-lyoo","o":"Latin","y":7,"bp":35,"m":"undervalu","sy":"ah.nder.vae.lyuw","nt":"Open","ps":"verb","t":["olatin"]},{"w":"undervalued","d":"assign too low a value to","p":"UH-nder-va-lyood","o":"Latin","y":5,"bp":36,"m":"undervalewed","sy":"ah.nder.vae.lyuw.d","nt":"Open","ps":"verb","t":["olatin"]},{"w":"undervalues","d":"assign too low a value to","p":"UH-nder-va-lyooz","o":"Latin","y":7,"bp":36,"m":"undervalus","sy":"ah.nder.vae.lyuw.z","nt":"Open","ps":"verb","t":["olatin"]},{"w":"undervaluing","d":"assign too low a value to","p":"uh-nder-VA-lyoo-ihng","o":"Latin","y":6,"bp":38,"m":"undervalueing","sy":"ah.nder.vae.lyuw.ih.ng","nt":"Open","ps":"verb","t":["olatin"]},{"w":"underwater","d":"beneath the surface of the water","s":"The marine biologist spent three hours underwater photographing the vibrant coral reef, marveling at the dazzling colors of the fish darting in and out of the delicate formations below.","p":"UH-nder-waw-ter","o":"Old English","y":3,"bp":31,"m":"underwaiter","sy":"ah.nder.wao.ter","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"underweight","d":"being very thin","p":"UH-nder-wayt","o":"Old English","y":5,"bp":30,"m":"underwaight","sy":"ah.nder.wey.t","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"underworld","d":"the criminal class","p":"UH-nder-wurld","o":"Old English","y":3,"bp":30,"m":"underworl","sy":"ah.nder.wer.ld","nt":"Open","ps":"noun","t":["law","ooldeng"]},{"w":"underwrite","d":"guarantee financial support of","p":"UH-nder-reyet","o":"Old English","y":7,"bp":30,"m":"underright","sy":"ah.nder.ray.t","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underwriter","d":"a banker who deals chiefly in underwriting new securities","s":"The underwriter reviewed every financial document before agreeing to back the startup company's bold expansion plan.","p":"UH-nder-reye-ter","o":"Old English","y":5,"bp":32,"m":"underrighter","sy":"ah.nder.ray.ter","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"underwriters","d":"a banker who deals chiefly in underwriting new securities","s":"A team of underwriters spent weeks analyzing the risk before approving the massive infrastructure bond issue.","p":"UH-nder-reye-terz","o":"Old English","y":5,"bp":33,"m":"underrighters","sy":"ah.nder.ray.ter.z","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"underwrites","d":"guarantee financial support of","p":"UH-nder-reyets","o":"Old English","y":6,"bp":30,"m":"underrights","sy":"ah.nder.ray.ts","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underwriting","d":"guarantee financial support of","p":"uh-nder-REYE-tihng","o":"Old English","y":5,"bp":33,"m":"underwritting","sy":"ah.nder.ray.tih.ng","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underwritten","d":"guarantee financial support of","p":"UH-nder-rih-tuhn","o":"Old English","y":7,"bp":33,"m":"underwriten","sy":"ah.nder.rih.tah.n","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underwrote","d":"guarantee financial support of","p":"uh-nder-ROHT","o":"Old English","y":7,"bp":30,"m":"underroat","sy":"ah.nder.row.t","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"undeserved","d":"not deserved or earned","s":"Has an undeserved reputation as a coward.","p":"uh-ndih-ZURVD","o":"Latin","y":5,"bp":34,"sy":"ah.ndih.zer.vd","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"undeserving","d":"not deserving","p":"uh-ndih-ZUR-vihng","o":"Latin","y":5,"bp":36,"sy":"ah.ndih.zer.vih.ng","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"undesirable","d":"a person who is not wanted, often because they cause trouble","s":"The committee decided that a longer school day would be an undesirable change.","p":"uh-ndih-ZEYE-ruh-buhl","o":"Latin","y":5,"bp":37,"m":"undesireable","sy":"ah.ndih.zay.rah.bah.l","nt":"Open","ps":"noun","t":["character","olatin"]},{"w":"undetectable","d":"not easily seen","p":"uh-ndih-TEH-ktuh-buhl","o":"Latin","y":7,"bp":38,"m":"undetectible","sy":"ah.ndih.teh.ktah.bah.l","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"undetected","d":"not perceived or discerned","s":"They feared some undetected trace of poison.","p":"uh-ndih-TEH-ktihd","o":"Latin","y":4,"bp":35,"m":"undeteccted","sy":"ah.ndih.teh.ktih.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"undetermined","d":"not yet having been ascertained or determined","p":"uh-ndih-TUR-mihnd","o":"Latin","y":5,"bp":37,"m":"undetermind","sy":"ah.ndih.ter.mih.nd","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"undeterred","d":"not deterred","s":"Pursued his own path...undeterred by lack of popular appreciation and understanding.","p":"uh-ndih-TURD","o":"Latin","y":6,"bp":34,"sy":"ah.ndih.ter.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"undeveloped","d":"not developed","s":"Courses in interior design were rare and undeveloped.","p":"uh-ndih-VEH-luhpt","o":"French","y":4,"bp":36,"sy":"ah.ndih.veh.lah.pt","nt":"Open","ps":"adjective","t":["ofrench"]},{"w":"undiagnosed","d":"eluding diagnosis","s":"The doctor was puzzled because the patient's strange symptoms remained undiagnosed for months, despite numerous tests and consultations with specialists across the country.","p":"uh-NDEYE-a-gnohst","o":"Greek","y":5,"bp":36,"m":"undiagnozed","sy":"ah.nday.ae.gnow.st","nt":"Open","ps":"adjective","t":["body","ogreek"]},{"w":"undignified","d":"lacking dignity","s":"The principal thought it was undignified to chase the escaped hamster around the classroom, but she did it anyway.","p":"uh-NDIH-gnih-feyed","o":"Latin","y":5,"bp":36,"m":"undignifyed","sy":"ah.ndih.gnih.fay.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"undiminished","d":"not lessened or diminished","p":"uh-nduh-MIH-nihsht","o":"Latin","y":6,"bp":37,"m":"undiminised","sy":"ah.ndah.mih.nih.sht","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"undiplomatic","d":"not skilled in dealing with others","s":"His undiplomatic comment about the chef's cooking caused an awkward silence that lasted the rest of the dinner party.","p":"uh-ndih-pluh-MA-tihk","o":"Greek","y":7,"bp":38,"m":"undiplomactic","sy":"ah.ndih.plah.mae.tih.k","nt":"Open","ps":"adjective","t":["ogreek"]},{"w":"undisclosed","d":"not made known","s":"The celebrity sold her mansion to an undisclosed buyer, and rumors about who purchased it spread all over town.","p":"uh-ndih-SKLOHZD","o":"Latin","y":4,"bp":34,"m":"undiscloased","sy":"ah.ndih.sklow.zd","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"undiscovered","d":"not discovered","s":"With earth-based telescopes many stars remain undiscovered.","p":"uh-ndih-SKUH-verd","o":"Latin","y":5,"bp":37,"m":"undiscoverd","sy":"ah.ndih.skah.ver.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"undisguised","d":"plain to see","p":"uh-ndih-SGEYEZD","o":"French","y":7,"bp":34,"m":"undisguized","sy":"ah.ndih.sgay.zd","nt":"Open","ps":"adjective","t":["landforms","ofrench"]},{"w":"undisputed","d":"generally agreed upon; not subject to dispute","s":"Serena Williams was considered the undisputed queen of tennis for many years, winning championship after championship with breathtaking skill and fierce determination.","p":"uh-ndih-SPYOO-tihd","o":"Latin","y":4,"bp":35,"m":"undispuded","sy":"ah.ndih.spyuw.tih.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"undisturbed","d":"untroubled by interference or disturbance","s":"He could pursue his studies undisturbed.","p":"uh-ndih-STURBD","o":"Latin","y":5,"bp":34,"m":"undisturb'd","sy":"ah.ndih.ster.bd","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"undocumented","d":"lacking necessary documents (as for e.g. permission to live or work in a country)","s":"The undocumented workers lived in constant fear of deportation, even though they had spent years contributing to their communities and building meaningful lives there.","p":"uh-NDAH-kyuh-meh-ntihd","o":"Latin","y":4,"bp":38,"m":"undocumente","sy":"ah.ndaa.kyah.meh.ntih.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"undoubtedly","d":"without doubt; certainly","s":"It's undoubtedly very beautiful.","p":"uh-NDOW-tih-dlee","o":"French","y":4,"bp":36,"m":"undoubtadly","sy":"ah.ndaw.tih.dliy","nt":"Open","ps":"adverb","t":["ofrench"]},{"w":"unearthing","d":"bring to light","p":"uh-NUR-thihng","o":"Old English","y":5,"bp":30,"sy":"ah.ner.thih.ng","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"uneasiness","d":"feelings of anxiety that make you tense and irritable","s":"A strange uneasiness crept over Sofia as she walked down the dim hallway and heard footsteps behind her.","p":"uh-NEE-zee-nuhs","o":"Old English","y":6,"bp":31,"m":"uneasnyess","sy":"ah.niy.ziy.nah.s","nt":"Open","ps":"noun","t":["emotions","ooldeng"]},{"w":"uneconomic","d":"wasteful of resources","s":"Running the old furnace through summer proved uneconomic, costing the school district thousands of dollars in unnecessary fuel.","p":"uh-neh-kuh-NAH-mihk","o":"Greek","y":5,"bp":37,"m":"uneconomick","sy":"ah.neh.kah.naa.mih.k","nt":"Open","ps":"adjective","t":["ogreek"]},{"w":"uneconomical","d":"inefficient in use of time and effort and materials","p":"uh-neh-kuh-NAH-mih-kuhl","o":"Greek","y":6,"bp":40,"m":"uneconomicle","sy":"ah.neh.kah.naa.mih.kah.l","nt":"Open","ps":"adjective","t":["time","ogreek"]},{"w":"uneducated","d":"not having a good education","s":"Despite being uneducated in a formal sense, the self-taught inventor held patents on dozens of remarkable devices.","p":"uh-NEH-juu-kay-tihd","o":"Latin","y":4,"bp":37,"m":"uneducatted","sy":"ah.neh.jhuh.key.tih.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unemotional","d":"unsusceptible to or destitute of or showing no emotion","s":"The detective's unemotional expression never revealed what he was thinking, even as the suspect broke down in tears.","p":"uh-nee-MOH-shuh-nuhl","o":"Latin","y":6,"bp":37,"m":"unemotionall","sy":"ah.niy.mow.shah.nah.l","nt":"Open","ps":"adjective","t":["emotions","olatin"]},{"w":"unemployable","d":"not acceptable for employment as a worker","s":"His illiteracy made him unemployable.","p":"uh-nih-MPLOY-uh-buhl","o":"Latin","y":7,"bp":38,"m":"unemployeable","sy":"ah.nih.mploy.ah.bah.l","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unemployed","d":"people who are involuntarily out of work (considered as a group)","s":"The long-term unemployed need assistance.","p":"uh-neh-MPLOYD","o":"Latin","y":3,"bp":34,"m":"unempolyed","sy":"ah.neh.mploy.d","nt":"Open","ps":"noun","t":["olatin"]},{"w":"unemployment","d":"the state of being unemployed or not having a job","s":"Unemployment is a serious social evil.","p":"uh-nih-MPLOY-muhnt","o":"French","y":3,"bp":37,"m":"unemplyoment","sy":"ah.nih.mploy.mah.nt","nt":"Open","ps":"noun","t":["ofrench"]},{"w":"unencumbered","d":"free of encumbrance","s":"Inherited an unencumbered estate.","p":"uh-neh-NKUH-mberd","o":"French","y":5,"bp":37,"m":"unencombered","sy":"ah.neh.nkah.mber.d","nt":"Open","ps":"adjective","t":["ofrench"]},{"w":"unenforced","d":"not enforced; not compelled especially by legal or police action","s":"Too many unenforced laws can breed contempt for law.","p":"uh-neh-NFAWRST","o":"French","y":6,"bp":34,"m":"unenforst","sy":"ah.neh.nfao.rst","nt":"Open","ps":"adjective","t":["law","ofrench"]},{"w":"unenviable","d":"hard to deal with; especially causing pain or embarrassment","p":"uh-NEH-nvee-uh-buhl","o":"Latin","y":7,"bp":37,"m":"unenvieable","sy":"ah.neh.nviy.ah.bah.l","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unequivocal","d":"admitting of no doubt or misunderstanding; having only one meaning or interpretation and leading to only one conclusion","p":"uh-nih-KWIH-vuh-kuhl","o":"Latin","y":6,"bp":37,"m":"unequivical","sy":"ah.nih.kwih.vah.kah.l","nt":"Open","ps":"adjective","t":["logic","olatin"]},{"w":"unethically","d":"in an unethical manner","p":"uh-NEH-thih-klee","o":"Greek","y":7,"bp":36,"m":"unethicaly","sy":"ah.neh.thih.kliy","nt":"Open","ps":"adverb","t":["ogreek"]},{"w":"uneventful","d":"marked by no noteworthy or significant events","s":"After weeks of drama and chaos at school, Maya was relieved to have a completely uneventful Saturday where nothing more exciting happened than finishing her favorite book.","p":"uh-nee-VEH-ntfuhl","o":"Latin","y":5,"bp":35,"m":"uneventfull","sy":"ah.niy.veh.ntfah.l","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unexciting","d":"not stimulating","s":"The substitute teacher's lesson was so unexciting that half the class struggled to stay awake, despite his attempts to make fractions sound adventurous and thrilling.","p":"uh-nih-KSEYE-tihng","o":"Old English","y":6,"bp":31,"m":"unexciteing","sy":"ah.nih.ksay.tih.ng","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unexpected","d":"not expected or anticipated","s":"The unexpected rainstorm during the outdoor graduation ceremony sent hundreds of parents scrambling for umbrellas and shelter beneath the nearby trees on the school lawn.","p":"uh-nih-KSPEH-ktihd","o":"Latin","y":2,"bp":35,"m":"unexpexted","sy":"ah.nih.kspeh.ktih.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unexpectedly","d":"in a way that was not expected","p":"uh-nih-KSPEH-ktih-dlee","o":"Latin","y":4,"bp":38,"m":"unexpectidly","sy":"ah.nih.kspeh.ktih.dliy","nt":"Open","ps":"adverb","t":["olatin"]},{"w":"unexplained","d":"not explained","s":"Accomplished by some unexplained process.","p":"uh-nih-KSPLAYND","o":"Latin","y":5,"bp":34,"m":"unexplaned","sy":"ah.nih.kspley.nd","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unexploded","d":"still capable of exploding or being fired","p":"uh-nih-KSPLOH-dihd","o":"Latin","y":5,"bp":35,"m":"unexplodded","sy":"ah.nih.ksplow.dih.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unexploited","d":"undeveloped or unused","s":"Vast unexploited (or undeveloped) natural resources.","p":"uh-nih-KSPLOY-tihd","o":"French","y":7,"bp":36,"m":"unexploighted","sy":"ah.nih.ksploy.tih.d","nt":"Open","ps":"adjective","t":["ofrench"]},{"w":"unexplored","d":"not yet discovered","p":"uh-nih-KSPLAWRD","o":"Latin","y":5,"bp":34,"m":"unexplord","sy":"ah.nih.ksplao.rd","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unfailingly","d":"without fail","s":"Mrs. Tanaka was unfailingly kind to every student who walked through her classroom door, no matter how difficult the day.","p":"uh-NFAY-lih-nglee","o":"Old English","y":7,"bp":32,"sy":"ah.nfey.lih.ngliy","nt":"Open","ps":"adverb","t":["ooldeng"]},{"w":"unfairness","d":"partiality that is not fair or equitable","s":"The team captain spoke up about the unfairness of the rule that only penalized younger players for the same mistake.","p":"uh-NFEH-rnuhs","o":"Latin","y":6,"bp":34,"m":"unfairnes","sy":"ah.nfeh.rnah.s","nt":"Open","ps":"noun","t":["olatin"]},{"w":"unfaithful","d":"not true to duty or obligation or promises","s":"The knight was exiled from the kingdom after being declared unfaithful to his oath, having secretly shared military plans with the rival king across the border.","p":"uh-NFAY-thfuhl","o":"Latin","y":5,"bp":34,"m":"unfaithfull","sy":"ah.nfey.thfah.l","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unfamiliar","d":"not known or well known","s":"A name unfamiliar to most.","p":"uh-nfuh-MIH-lyer","o":"Latin","y":3,"bp":35,"m":"unfamilliar","sy":"ah.nfah.mih.lyer","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unfathomable","d":"of depth; not capable of being sounded or measured","p":"uh-NFA-thuh-muh-buhl","o":"Latin","y":6,"bp":38,"m":"unfathomible","sy":"ah.nfae.dhah.mah.bah.l","nt":"Open","ps":"adjective","t":["numbers","olatin"]},{"w":"unfavorable","d":"not encouraging or approving or pleasing; ,","p":"uh-NFAY-ver-uh-buhl","o":"Latin","y":6,"bp":37,"m":"unfavourable","sy":"ah.nfey.ver.ah.bah.l","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unfavorably","d":"showing disapproval; in a disparaging way","s":"He reviewed the play unfavorably.","p":"uh-NFAY-ver-uh-blee","o":"Latin","y":5,"bp":37,"m":"unfavourably","sy":"ah.nfey.ver.ah.bliy","nt":"Open","ps":"adverb","t":["olatin"]},{"w":"unfeasible","d":"not capable of being carried out or put into practice","p":"uh-NFEE-zuh-buhl","o":"French","y":7,"bp":35,"m":"unfeasable","sy":"ah.nfiy.zah.bah.l","nt":"Open","ps":"adjective","t":["ofrench"]},{"w":"unfettered","d":"not bound by shackles and chains","s":"With summer stretching ahead of her, Priya felt unfettered and free to pursue every creative project she had been dreaming about.","p":"uh-NFEH-terd","o":"Old English","y":6,"bp":30,"sy":"ah.nfeh.ter.d","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unfinished","d":"not brought to the desired final state","s":"The unfinished mural on the gymnasium wall showed a half-painted mural of a soaring eagle, abandoned when the artist unexpectedly moved away before completing the project.","p":"uh-NFIH-nihsht","o":"Old English","y":3,"bp":30,"m":"unfinised","sy":"ah.nfih.nih.sht","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unflagging","d":"staying strong and energetic without ever tiring","p":"uh-NFLA-gihng","o":"Latin","y":7,"bp":34,"m":"unflaggin","sy":"ah.nflae.gih.ng","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unflappable","d":"not easily perturbed or excited or upset; marked by extreme calm and composure","p":"uh-NFLA-puh-buhl","o":"English","y":8,"bp":36,"m":"unflappible","sy":"ah.nflae.pah.bah.l","nt":"Open","ps":"adjective","t":[]},{"w":"unflattering","d":"showing or representing unfavorably","p":"uh-NFLA-ter-ihng","o":"Old English","y":7,"bp":33,"m":"unflatering","sy":"ah.nflae.ter.ih.ng","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unflinching","d":"not shrinking from danger","s":"The unflinching firefighter rushed back into the burning building a second time to rescue the family's terrified dog.","p":"uh-NFLIH-nchihng","o":"Old English","y":7,"bp":30,"m":"unflinshing","sy":"ah.nflih.nchih.ng","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unforeseen","d":"not anticipated","p":"uh-nfaw-RSEEN","o":"Old English","y":4,"bp":30,"m":"unforseen","sy":"ah.nfao.rsiy.n","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unforgivable","d":"not excusable","s":"Betraying a close friend's deepest secret for personal gain is, in most people's eyes, simply unforgivable.","p":"uh-nfaw-RGIH-vuh-buhl","o":"Old English","y":6,"bp":34,"m":"unforgiveable","sy":"ah.nfao.rgih.vah.bah.l","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unforgiving","d":"unwilling or unable to forgive or show mercy","s":"A surly unforgiving old woman.","p":"uh-nfer-GIH-vihng","o":"Latin","y":5,"bp":36,"m":"unforgivving","sy":"ah.nfer.gih.vih.ng","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unfortunate","d":"a person who suffers misfortune","s":"An unfortunate turn of events.","p":"uh-NFAW-rchuh-nuht","o":"Latin","y":4,"bp":36,"m":"unfortunete","sy":"ah.nfao.rchah.nah.t","nt":"Open","ps":"noun","t":["olatin"]},{"w":"unfortunates","d":"a person who suffers misfortune","s":"The charity worked tirelessly to provide warm meals and shelter to the unfortunates left homeless after the flood.","p":"uh-NFAW-rchuh-nuhts","o":"Latin","y":6,"bp":37,"m":"unfortunetes","sy":"ah.nfao.rchah.nah.ts","nt":"Open","ps":"noun","t":["olatin"]},{"w":"unfriendly","d":"not kind or welcoming toward other people","s":"The new student seemed unfriendly at first, but she was really just shy.","p":"uh-NFREH-ndlee","o":"Old English","y":4,"bp":30,"m":"unfreindly","sy":"ah.nfreh.ndliy","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unfulfilled","d":"of persons; marked by failure to realize full potentialities","s":"Unfulfilled and uneasy men.","p":"uh-nfuu-LFIHLD","o":"Old English","y":6,"bp":30,"m":"unfullfilled","sy":"ah.nfuh.lfih.ld","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unglamorous","d":"not challenging; dull and lacking excitement","s":"An unglamorous job greasing engines.","p":"uh-NGLA-mer-uhs","o":"Latin","y":8,"bp":36,"m":"unglamoreous","sy":"ah.nglae.mer.ah.s","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"ungovernable","d":"Impossible to control or manage; describing a person whose behavior or emotions are too wild or defiant to be directed by rules or authority.","p":"uh-NGUH-ver-nuh-buhl","o":"Latin","y":7,"bp":38,"m":"ungovernible","sy":"ah.ngah.ver.nah.bah.l","nt":"Open","ps":"adjective","t":["emotions","conduct","olatin"]},{"w":"ungrateful","d":"not feeling or showing gratitude","s":"It seemed ungrateful for the students to complain about the free pizza party the principal organized, especially after she had spent her own money to plan the celebration.","p":"uh-NGRAY-tfuhl","o":"French","y":4,"bp":34,"m":"ungratful","sy":"ah.ngrey.tfah.l","nt":"Open","ps":"adjective","t":["ofrench"]},{"w":"unhampered","d":"Free to move or act without being slowed, blocked, or held back.","s":"An outlet for healthy and unhampered action.","p":"uh-NHA-mperd","o":"Old English","y":6,"bp":30,"m":"unhamperd","sy":"ah.nhhae.mper.d","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unhappiness","d":"emotions experienced when not in a state of well-being","s":"The little boy tried to hide his unhappiness when his best friend moved to another city, but his eyes gave him away.","p":"uh-NHA-pee-nihs","o":"Latin","y":5,"bp":36,"m":"unhappyness","sy":"ah.nhhae.piy.nih.s","nt":"Open","ps":"noun","t":["emotions","olatin"]},{"w":"unhealthful","d":"not sanitary or healthful","p":"uh-NHEH-lthfuhl","o":"Latin","y":7,"bp":34,"m":"unhealthfull","sy":"ah.nhheh.lthfah.l","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unheralded","d":"without warning or announcement","p":"uh-NHEH-ruh-ldihd","o":"Latin","y":6,"bp":35,"m":"unheraled","sy":"ah.nhheh.rah.ldih.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unhindered","d":"able to move or progress freely without being blocked or slowed","p":"uh-NHIH-nderd","o":"Latin","y":5,"bp":34,"m":"unhinderd","sy":"ah.nhhih.nder.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unicellular","d":"having or consisting of a single cell","s":"Through her microscope, the biology student marveled at the tiny unicellular organisms darting through the drop of pond water.","p":"yoo-nih-SEH-lyuh-ler","o":"Latin","y":7,"bp":37,"m":"unicelular","sy":"yuw.nih.seh.lyah.ler","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unidentified","d":"not yet identified","p":"uh-neye-DEH-ntuh-feyed","o":"Latin","y":4,"bp":38,"m":"unindentified","sy":"ah.nay.deh.ntah.fay.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unification","d":"an occurrence that involves the production of a union","p":"yoo-nuh-fuh-KAY-shuhn","o":"Latin","y":4,"bp":37,"m":"unificaton","sy":"yuw.nah.fah.key.shah.n","nt":"Open","ps":"noun","t":["olatin"]},{"w":"uniformity","d":"a condition in which everything is regular and unvarying","s":"The uniformity of the soldiers' marching steps made the parade look flawless.","p":"yoo-nuh-FAW-rmuh-tee","o":"French","y":4,"bp":37,"m":"uniformaty","sy":"yuw.nah.fao.rmah.tiy","nt":"Open","ps":"noun","t":["ofrench"]},{"w":"unilateral","d":"involving only one part or side","p":"yoo-nuh-LA-ter-uhl","o":"Latin","y":4,"bp":37,"m":"unilatteral","sy":"yuw.nah.lae.ter.ah.l","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unimaginable","d":"totally unlikely","s":"The destruction left by the tornado was unimaginable to those who had never witnessed one.","p":"uh-nih-MA-jih-nuh-buhl","o":"French","y":6,"bp":40,"m":"unimagable","sy":"ah.nih.mae.jhih.nah.bah.l","nt":"Open","ps":"adjective","t":["ofrench"]},{"w":"unimagined","d":"not imagined even in a dream","s":"The new telescope revealed unimagined worlds far beyond our own galaxy.","p":"uh-nih-MA-juhnd","o":"Latin","y":6,"bp":35,"m":"unimagened","sy":"ah.nih.mae.jhah.nd","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unimpaired","d":"not damaged or diminished in any respect","s":"His speech remained unimpaired.","p":"uh-nih-MPEHRD","o":"French","y":7,"bp":34,"m":"unimpared","sy":"ah.nih.mpeh.rd","nt":"Open","ps":"adjective","t":["ofrench"]},{"w":"unimportant","d":"not important","s":"A relatively unimportant feature of the system.","p":"uh-nih-MPAW-rtuhnt","o":"Latin","y":4,"bp":36,"m":"unimportent","sy":"ah.nih.mpao.rtah.nt","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unimpressed","d":"not moved to serious regard","s":"Trying to appear unimpressed.","p":"uh-nih-MPREHST","o":"Latin","y":5,"bp":34,"m":"unimpresed","sy":"ah.nih.mpreh.st","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unimpressive","d":"not capable of impressing","s":"The magician's first trick was unimpressive, but his finale left the audience speechless.","p":"uh-nih-MPREH-sihv","o":"Latin","y":7,"bp":37,"m":"unimprssive","sy":"ah.nih.mpreh.sih.v","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unimproved","d":"not made more desirable or valuable or profitable; especially not made ready for use or marketing","s":"Taxes on unimproved land are low.","p":"uh-nih-MPROOVD","o":"French","y":6,"bp":34,"sy":"ah.nih.mpruw.vd","nt":"Open","ps":"adjective","t":["economy","ofrench"]},{"w":"uninfected","d":"free from sepsis or infection","s":"A clean (or uninfected) wound.","p":"uh-nih-NFEH-ktihd","o":"Latin","y":5,"bp":35,"m":"uninfeccted","sy":"ah.nih.nfeh.ktih.d","nt":"Open","ps":"adjective","t":["disease","olatin"]},{"w":"uninformed","d":"not informed; lacking in knowledge or information","p":"uh-nih-NFAWRMD","o":"Latin","y":4,"bp":34,"m":"uninfromed","sy":"ah.nih.nfao.rmd","nt":"Open","ps":"adjective","t":["logic","olatin"]},{"w":"uninhabited","d":"not having inhabitants; not lived in","p":"uh-nih-NHA-buh-tihd","o":"Latin","y":5,"bp":37,"m":"uninhabitted","sy":"ah.nih.nhhae.bah.tih.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"uninhibited","d":"not inhibited or restrained","p":"uh-nih-NHIH-bih-tihd","o":"Latin","y":5,"bp":37,"m":"uninhibitted","sy":"ah.nih.nhhih.bih.tih.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"uninitiated","d":"not initiated; deficient in relevant experience","s":"It seemed a bizarre ceremony to uninitiated western eyes.","p":"uh-nih-NIH-shee-ay-tihd","o":"Latin","y":5,"bp":39,"m":"uninisiated","sy":"ah.nih.nih.shiy.ey.tih.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"uninspired","d":"having no intellectual or emotional or spiritual excitement","s":"The production was professional but uninspired.","p":"uh-nih-NSPEYE-erd","o":"Latin","y":5,"bp":35,"m":"uninspirred","sy":"ah.nih.nspay.er.d","nt":"Open","ps":"adjective","t":["emotions","olatin"]},{"w":"uninspiring","d":"depressing to the spirit","s":"A villa of uninspiring design.","p":"uh-nih-NSPEYE-rihng","o":"Latin","y":5,"bp":36,"m":"uninspireing","sy":"ah.nih.nspay.rih.ng","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"uninsurable","d":"not capable of being insured or not eligible to be insured","s":"The crumbling old warehouse was deemed uninsurable because of its dangerous condition.","p":"uh-nih-NSHUU-ruh-buhl","o":"French","y":7,"bp":37,"m":"uninnsurable","sy":"ah.nih.nshuh.rah.bah.l","nt":"Open","ps":"adjective","t":["ofrench"]},{"w":"unintended","d":"not deliberate","s":"The spilled paint created an unintended masterpiece on the studio floor.","p":"uh-nih-NTEH-ndihd","o":"Latin","y":4,"bp":35,"m":"unintented","sy":"ah.nih.nteh.ndih.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"uninterested","d":"not having or showing interest","p":"uh-NIH-ntruh-stihd","o":"Latin","y":5,"bp":37,"m":"uninterrested","sy":"ah.nih.ntrah.stah.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"uninviting","d":"neither attractive nor tempting","s":"The dark, narrow alley looked so uninviting that we chose a different route home.","p":"uh-nih-NVEYE-tihng","o":"Latin","y":6,"bp":35,"m":"uninviteing","sy":"ah.nih.nvay.tih.ng","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"uninvolved","d":"not involved","s":"Being uninvolved he remained objective.","p":"uh-nih-NVAWLVD","o":"Latin","y":5,"bp":34,"m":"uninvovled","sy":"ah.nih.nvao.lvd","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unionization","d":"act of forming labor unions","s":"The issue underlying the strike was unionization.","p":"yoo-nyuh-nuh-ZAY-shuhn","o":"Latin","y":5,"bp":38,"m":"unionisation","sy":"yuw.nyah.nah.zey.shah.n","nt":"Open","ps":"noun","t":["olatin"]},{"w":"unionizing","d":"recruit for a union or organize into a union","p":"YOO-nyuh-neye-zihng","o":"Latin","y":6,"bp":35,"m":"unionising","sy":"yuw.nyah.nay.zih.ng","nt":"Open","ps":"verb","t":["olatin"]},{"w":"uniqueness","d":"the quality of being one of a kind","p":"yoo-NEE-knuhs","o":"French","y":6,"bp":34,"m":"uniquness","sy":"yuw.niy.knah.s","nt":"Open","ps":"noun","t":["ofrench"]},{"w":"universality","d":"the quality of being universal; existing everywhere","s":"The universality of music means that a melody can move people no matter what language they speak.","p":"yoo-nuh-ver-SA-luh-tee","o":"Latin","y":5,"bp":40,"m":"universallity","sy":"yuw.nah.ver.sae.lah.tiy","nt":"Open","ps":"noun","t":["olatin"]},{"w":"universally","d":"In a way that applies to or is shared by all people, places, or things everywhere without exception.","s":"People universally agree on this.","p":"yoo-nuh-VUR-suh-lee","o":"Latin","y":5,"bp":37,"m":"universaly","sy":"yuw.nah.ver.sah.liy","nt":"Open","ps":"adverb","t":["olatin"]},{"w":"universities","d":"the body of faculty and students at a university","s":"Many universities around the world offer scholarships to talented students who cannot afford tuition.","p":"yoo-nuh-VUR-suh-teez","o":"Latin","y":2,"bp":38,"m":"universites","sy":"yuw.nah.ver.sah.tiy.z","nt":"Open","ps":"noun","t":["olatin"]},{"w":"unjustified","d":"lacking justification or authorization","p":"uh-NJUH-stuh-feyed","o":"Latin","y":5,"bp":36,"m":"unjustifyed","sy":"ah.njhah.stah.fay.d","nt":"Open","ps":"adjective","t":["logic","olatin"]},{"w":"unknowable","d":"not knowable","s":"The unknowable mysteries of life.","p":"uh-NNOH-uh-buhl","o":"Latin","y":6,"bp":35,"m":"unknoweable","sy":"ah.nnow.ah.bah.l","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unknowingly","d":"without knowledge or intention","p":"uh-NNOH-ih-nglee","o":"Old English","y":4,"bp":32,"sy":"ah.nnow.ih.ngliy","nt":"Open","ps":"adverb","t":["logic","ooldeng"]},{"w":"unlawfully","d":"not conforming to the law","s":"They were unlawfully married.","p":"uh-NLAW-fuh-lee","o":"Old English","y":6,"bp":31,"m":"unlawfuly","sy":"ah.nlao.fah.liy","nt":"Open","ps":"adverb","t":["law","ooldeng"]},{"w":"unleashing","d":"release or vent","s":"The scientists worried that drilling too deeply into the ancient glacier could risk unleashing deadly microbes that had been frozen and dormant for thousands of years beneath the ice.","p":"uh-NLEE-shihng","o":"Old English","y":5,"bp":30,"m":"unleeashing","sy":"ah.nliy.shih.ng","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"unlicensed","d":"lacking official approval","s":"The city shut down the unlicensed food cart because it had never passed a health inspection.","p":"uh-NLEYE-suhnst","o":"Latin","y":4,"bp":34,"m":"unlicenced","sy":"ah.nlay.sah.nst","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"underachiever","d":"a student who does not perform as well as expected or as well as the IQ indicates","s":"The counselor encouraged the underachiever by showing him that his test scores proved he was capable of far more than his grades suggested.","p":"UH-nder-uh-chee-ver","o":"Old English","y":8,"bp":35,"m":"underacheiver","sy":"ah.nder.ah.chiy.ver","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"underachievers","d":"a student who does not perform as well as expected or as well as the IQ indicates","s":"The teacher created special projects to motivate the underachievers in her class to reach their full potential.","p":"UH-nder-uh-chee-verz","o":"Old English","y":8,"bp":36,"m":"underacheivers","sy":"ah.nder.ah.chiy.ver.z","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"undercarriage","d":"framework that serves as a support for the body of a vehicle","s":"The mechanic inspected the undercarriage of the car for rust and damage after the long road trip.","p":"UH-nder-ka-rihj","o":"Old English","y":7,"bp":33,"m":"undercarage","sy":"ah.nder.kae.rih.jh","nt":"Open","ps":"noun","t":["vehicles","ooldeng"]},{"w":"underclassmen","d":"an undergraduate who is not yet a senior","s":"The upperclassmen volunteered to mentor the underclassmen during the first week of school.","p":"uh-nder-KLA-smehn","o":"Old English","y":7,"bp":33,"m":"underclassman","sy":"ah.nder.klae.smeh.n","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"undercurrents","d":"a subdued emotional quality underlying an utterance; implicit meaning","s":"Despite their polite smiles, there were strong undercurrents of tension between the two rival teams.","p":"UH-nder-kur-uhnts","o":"Old English","y":7,"bp":33,"sy":"ah.nder.ker.ah.nts","nt":"Open","ps":"noun","t":["emotions","ooldeng"]},{"w":"underdeveloped","d":"process (a film or photographic plate) less than the required time or in an ineffective solution or at an insufficiently high temperature","s":"These photos are underdeveloped.","p":"uh-nder-dih-VEH-luhpt","o":"Old English","y":5,"bp":36,"sy":"ah.nder.dih.veh.lah.pt","nt":"Open","ps":"verb","t":["time","ooldeng"]},{"w":"underdevelopment","d":"state of inadequate development","s":"Much poverty can be traced to the underdevelopment of industry.","p":"uh-nder-duh-VEH-luh-pmuhnt","o":"Old English","y":7,"bp":39,"m":"underdevelopement","sy":"ah.nder.dah.veh.lah.pmah.nt","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"underemployed","d":"employed only part-time when one needs full-time employment or not making full use of your skills","s":"Migrants are likely to be poor and underemployed.","p":"uh-nder-ih-MPLOYD","o":"Old English","y":6,"bp":33,"m":"underemployeed","sy":"ah.nder.ih.mploy.d","nt":"Open","ps":"adjective","t":["time","ooldeng"]},{"w":"underestimate","d":"an estimation that is too low; an estimate that is less than the true or actual value","s":"Don't underestimate the value of this heirloom-you may sell it at a good price.","p":"uh-nder-EH-stuh-mayt","o":"Latin","y":5,"bp":39,"sy":"ah.nder.eh.stah.mey.t","nt":"Open","ps":"noun","t":["olatin"]},{"w":"underestimated","d":"assign too low a value to","p":"uh-nder-EH-stuh-may-tihd","o":"Old English","y":5,"bp":37,"sy":"ah.nder.eh.stah.mey.tih.d","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"underestimates","d":"an estimation that is too low; an estimate that is less than the true or actual value","p":"uh-nder-EH-stih-mihts","o":"Old English","y":6,"bp":36,"sy":"ah.nder.eh.stih.mih.ts","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"underestimating","d":"assign too low a value to","p":"uh-nder-EH-stih-may-tihng","o":"Old English","y":6,"bp":38,"sy":"ah.nder.eh.stih.mey.tih.ng","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"undergarments","d":"a garment worn under other garments","s":"Explorers in the Arctic wore special thermal undergarments to stay warm in the brutal cold.","p":"UH-nder-gah-rmuhnts","o":"French","y":6,"bp":37,"m":"undergaments","sy":"ah.nder.gaa.rmah.nts","nt":"Open","ps":"noun","t":["fabrics","ofrench"]},{"w":"undergraduate","d":"a university student who has not yet received a first degree","s":"As an undergraduate, she spent her summers doing research in the university laboratory.","p":"uh-nder-GRA-juh-wuht","o":"Latin","y":5,"bp":39,"m":"undergradute","sy":"ah.nder.grae.jhah.wah.t","nt":"Open","ps":"noun","t":["olatin"]},{"w":"undergraduates","d":"a university student who has not yet received a first degree","s":"The professor encouraged all undergraduates to attend the guest lecture on climate change.","p":"uh-nder-GRA-juh-wuhts","o":"Latin","y":5,"bp":40,"m":"undergradutes","sy":"ah.nder.grae.jhah.wah.ts","nt":"Open","ps":"noun","t":["olatin"]},{"w":"undernourished","d":"provide with insufficient quality or quantity of nourishment","s":"The stunted growth of these children shows that they are undernourished.","p":"uh-nder-NUR-ihsht","o":"Latin","y":7,"bp":38,"m":"undernurrished","sy":"ah.nder.ner.ih.sht","nt":"Open","ps":"verb","t":["olatin"]},{"w":"underprivileged","d":"lacking the rights and advantages of other members of society","s":"The charity raised funds to provide school supplies for underprivileged children in the city.","p":"uh-nder-PRIH-vluhjd","o":"Latin","y":6,"bp":39,"m":"underprivledged","sy":"un.der.priv.i.legd","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"undersecretary","d":"a secretary immediately subordinate to the head of a department of government","s":"The undersecretary handled the department's daily correspondence while the minister was overseas.","p":"uh-nder-SEH-krih-teh-ree","o":"Latin","y":6,"bp":41,"m":"undersecratary","sy":"ah.nder.seh.krih.teh.riy","nt":"Open","ps":"noun","t":["politics","olatin"]},{"w":"understandable","d":"capable of being apprehended or understood","s":"It is completely understandable that she felt nervous before her first public speaking performance.","p":"uh-nder-STA-nduh-buhl","o":"Old English","y":6,"bp":36,"m":"understandible","sy":"ah.nder.stae.ndah.bah.l","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"understandably","d":"in an intelligible manner","p":"uh-nder-STA-nduh-blee","o":"Old English","y":5,"bp":36,"m":"understandibly","sy":"ah.nder.stae.ndah.bliy","nt":"Open","ps":"adverb","t":["ooldeng"]},{"w":"understanding","d":"the cognitive condition of someone who understands","s":"He has virtually no understanding of social cause and effect.","p":"uh-nder-STA-ndihng","o":"Old English","y":2,"bp":33,"m":"understaning","sy":"ah.nder.stae.ndih.ng","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"understandings","d":"the cognitive condition of someone who understands","p":"uh-nder-STA-ndihngz","o":"Old English","y":5,"bp":34,"m":"understanidings","sy":"ah.nder.stae.ndih.ngz","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"understatement","d":"a statement that is restrained in ironic contrast to what might have been said","s":"Calling the Grand Canyon 'a nice hole in the ground' is quite the understatement.","p":"UH-nder-stay-tmuhnt","o":"Old English","y":5,"bp":34,"m":"understatment","sy":"ah.nder.stey.tmah.nt","nt":"Open","ps":"noun","t":["ooldeng"]},{"w":"undervaluation","d":"too low a value or price assigned to something","s":"The undervaluation of the rare painting meant the museum acquired it for a surprisingly low price.","p":"uh-nder-va-lyoo-AY-shuhn","o":"Latin","y":7,"bp":41,"m":"undervaulation","sy":"ah.nder.vae.lyuw.ey.shah.n","nt":"Open","ps":"noun","t":["olatin"]},{"w":"undifferentiated","d":"not differentiated","s":"The scientist studied undifferentiated stem cells because they have the ability to develop into any type of cell.","p":"uh-ndih-fer-EH-nshee-ay-tihd","o":"Latin","y":7,"bp":44,"m":"undifferenciated","sy":"ah.ndih.fer.eh.nshiy.ey.tih.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"undiplomatically","d":"without diplomacy; in an undiplomatic manner","s":"She declined the invitation undiplomatically.","p":"uh-ndih-pluh-MA-tih-klee","o":"Greek","y":9,"bp":43,"m":"undiplomaticlly","sy":"ah.ndih.plah.mae.tih.kliy","nt":"Open","ps":"adverb","t":["ogreek"]},{"w":"undisciplined","d":"not subjected to discipline","p":"uh-NDIH-sih-plihnd","o":"Latin","y":6,"bp":37,"m":"undisciplinned","sy":"ah.ndih.sih.plih.nd","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"undistinguished","d":"not worthy of notice","s":"The critic described the film as undistinguished, noting that nothing about it stood out from other movies of that year.","p":"uh-ndih-STIH-nggwihsht","o":"Latin","y":8,"bp":39,"m":"undistingished","sy":"ah.ndih.stih.nggwih.sht","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"undistributed","d":"(of investments) not distributed among a variety of securities","s":"The financial advisor warned that undistributed investments carried a higher risk during market downturns.","p":"uh-ndih-STRIH-byoo-tihd","o":"Latin","y":7,"bp":39,"m":"undistibuted","sy":"ah.ndih.strih.byuw.tih.d","nt":"Open","ps":"adjective","t":["economy","olatin"]},{"w":"undiversified","d":"not diversified","s":"His undiversified portfolio suffered greatly when the single industry he had invested in collapsed.","p":"uh-ndih-VUR-sih-feyed","o":"Latin","y":8,"bp":39,"m":"undiversifyed","sy":"ah.ndih.ver.sih.fay.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unenforceable","d":"not enforceable; not capable of being brought about by compulsion","p":"uh-neh-NFAW-rsuh-buhl","o":"Latin","y":7,"bp":39,"m":"unenforciable","sy":"ah.neh.nfao.rsah.bah.l","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unenlightened","d":"not enlightened; ignorant","s":"The devices by which unenlightened men preserved the unjust social order.","p":"uh-neh-NLEYE-tuhnd","o":"Old English","y":7,"bp":33,"m":"unenlightend","sy":"ah.neh.nlay.tah.nd","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unenthusiastic","d":"not enthusiastic; lacking excitement or ardor","s":"An unenthusiastic performance by the orchestra.","p":"uh-nih-nthoo-zee-A-stihk","o":"Latin","y":7,"bp":41,"m":"unenthusiasic","sy":"ah.nih.nthuw.ziy.ae.stih.k","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unequivocally","d":"in an unambiguous manner","s":"She stated her intentions unequivocally.","p":"uh-nee-KWIH-vuh-kuh-lee","o":"Latin","y":7,"bp":40,"m":"unequivocaly","sy":"ah.niy.kwih.vah.kah.liy","nt":"Open","ps":"adverb","t":["olatin"]},{"w":"unexplainable","d":"not to be accounted for or explained","p":"uh-nih-KSPLAY-nuh-buhl","o":"Latin","y":8,"bp":39,"m":"unexplainible","sy":"ah.nih.kspley.nah.bah.l","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unfamiliarity","d":"unusualness as a consequence of not being well known","s":"Her unfamiliarity with the city's bus system made navigating to school on the first day quite stressful.","p":"uh-nfuh-mih-LYEH-ruh-tee","o":"Latin","y":6,"bp":40,"m":"unfamilliarity","sy":"ah.nfah.mih.lyeh.rah.tiy","nt":"Open","ps":"noun","t":["olatin"]},{"w":"unfashionable","d":"not in accord with or not following current fashion","p":"uh-NFA-shuh-nuh-buhl","o":"French","y":7,"bp":39,"sy":"ah.nfae.shah.nah.bah.l","nt":"Open","ps":"adjective","t":["fashion","ofrench"]},{"w":"unforeseeable","d":"incapable of being anticipated","p":"uh-nfaw-RSEE-uh-buhl","o":"Old English","y":8,"bp":35,"m":"unforseeable","sy":"ah.nfao.rsiy.ah.bah.l","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unforgettable","d":"impossible to forget","s":"Watching the northern lights dance across the midnight sky was an absolutely unforgettable experience.","p":"uh-nfer-GEH-tuh-buhl","o":"Old English","y":7,"bp":35,"m":"unforgetable","sy":"ah.nfer.geh.tah.bah.l","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unfortunately","d":"Used to express regret that something bad or unlucky has happened; by the misfortune of chance or circumstance.","s":"Unfortunately it rained all day.","p":"uh-NFAW-rchuh-nuh-tlee","o":"Latin","y":2,"bp":39,"m":"unfortunatly","sy":"ah.nfao.rchah.nah.tliy","nt":"Open","ps":"adverb","t":["olatin"]},{"w":"unhesitatingly","d":"without hesitation","s":"She said yes unhesitatingly.","p":"uh-NHEH-zih-tay-tih-nglee","o":"Latin","y":7,"bp":41,"m":"unhesitantingly","sy":"ah.nhheh.zih.tey.tih.ngliy","nt":"Open","ps":"adverb","t":["olatin"]},{"w":"unilateralism","d":"the doctrine that nations should conduct their foreign affairs individualistically without the advice or involvement of other nations","s":"Critics of unilateralism argued that global problems like climate change require cooperation among many nations.","p":"yoo-nih-LA-ter-uh-lih-zuhm","o":"Latin","y":7,"bp":42,"m":"unilateralizm","sy":"yuw.nih.lae.ter.ah.lih.zah.m","nt":"Open","ps":"noun","t":["logic","olatin"]},{"w":"unimaginative","d":"deficient in originality or creativity; lacking powers of invention","p":"uh-nih-MA-jih-nuh-tihv","o":"Latin","y":7,"bp":40,"m":"unimagintive","sy":"ah.nih.mae.jhih.nah.tih.v","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unimpeachable","d":"beyond doubt or reproach","p":"uh-nih-MPEE-chuh-buhl","o":"French","y":8,"bp":39,"m":"unimpeachible","sy":"ah.nih.mpiy.chah.bah.l","nt":"Open","ps":"adjective","t":["ofrench"]},{"w":"unincorporated","d":"not organized and maintained as a legal corporation","s":"The unincorporated town had no official mayor or city council to manage local services.","p":"uh-nih-NKAW-rper-ay-tihd","o":"Latin","y":5,"bp":41,"m":"unincorperated","sy":"ah.nih.nkao.rper.ey.tih.d","nt":"Open","ps":"adjective","t":["law","olatin"]},{"w":"uninformative","d":"lacking information","s":"The weather report was so uninformative that residents had no idea whether to expect rain or sunshine.","p":"uh-nih-NFAW-rmuh-tihv","o":"Latin","y":8,"bp":39,"m":"uninformitive","sy":"ah.nih.nfao.rmah.tih.v","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"uninhabitable","d":"not fit for habitation","s":"After the earthquake, inspectors declared many of the damaged buildings completely uninhabitable.","p":"uh-nih-NHA-buh-tuh-buhl","o":"Latin","y":7,"bp":40,"m":"uninhabitible","sy":"ah.nih.nhhae.bah.tah.bah.l","nt":"Open","ps":"adjective","t":["ecology","olatin"]},{"w":"unintelligible","d":"poorly articulated or enunciated, or drowned by noise","p":"uh-nih-NTEH-luh-juh-buhl","o":"Latin","y":8,"bp":41,"m":"unintelligable","sy":"ah.nih.nteh.lah.jhah.bah.l","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unintentional","d":"without deliberate intent","p":"uh-nih-NTEH-nshuh-nuhl","o":"Latin","y":5,"bp":39,"m":"unintentionel","sy":"ah.nih.nteh.nshah.nah.l","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unintentionally","d":"without intention; in an unintentional manner","s":"She hit him unintentionally.","p":"uh-nih-NTEH-nshuh-nuh-lee","o":"Latin","y":7,"bp":42,"m":"unintentionaly","sy":"ah.nih.nteh.nshah.nah.liy","nt":"Open","ps":"adverb","t":["olatin"]},{"w":"uninteresting","d":"arousing no interest or attention or curiosity or excitement","s":"A very uninteresting account of her trip.","p":"uh-NIH-ntruh-stihng","o":"Latin","y":5,"bp":37,"m":"uninterresting","sy":"ah.nih.ntrah.stih.ng","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"uninterrupted","d":"having undisturbed continuity","s":"A convalescent needs uninterrupted sleep.","p":"uh-nih-nter-UH-ptihd","o":"Latin","y":5,"bp":39,"m":"uninterupted","sy":"ah.nih.nter.ah.ptih.d","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unjustifiable","d":"incapable of being justified or explained","s":"The judge ruled that the use of force during the incident was unjustifiable given the circumstances.","p":"uh-njuh-stih-FEYE-uh-buhl","o":"French","y":7,"bp":40,"m":"unjustifyable","sy":"ah.njhah.stih.fay.ah.bah.l","nt":"Open","ps":"adjective","t":["ofrench"]},{"w":"unjustifiably","d":"without any excuse","s":"He is unjustifiably harsh on her.","p":"uh-njuh-stih-FEYE-uh-blee","o":"French","y":6,"bp":40,"m":"unjustifyably","sy":"ah.njhah.stih.fay.ah.bliy","nt":"Open","ps":"adverb","t":["ofrench"]},{"w":"undies","d":"women's underwear","s":"She packed her favorite pair of undies in her overnight bag before the school trip.","p":"UN-deez","o":"Old English","y":3,"bp":25,"m":"undys","sy":"un.dies","nt":"Open","ps":"noun","t":["clothing","ooldeng"]},{"w":"undoer","d":"a person or thing that cancels or reverses something already carried out","s":"The drawing program has an undoer that reverses your last change with a single click.","p":"un-DOO-ur","o":"Italian","y":8,"bp":26,"m":"undoeer","sy":"un.do.er","nt":"Open","ps":"noun","t":["ancient","oiberian"]},{"w":"undoes","d":"cancel, annul, or reverse an action or its effect","p":"un-DUZ","o":"Old English","y":5,"bp":25,"m":"undos","sy":"un.does","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"undyed","d":"not artificially colored or bleached","p":"un-DYD","o":"Latin","y":5,"bp":29,"m":"undied","sy":"un.dyed","nt":"Open","ps":"adjective","t":["colors","olatin"]},{"w":"unfed","d":"Not having been given food; having gone without a meal or nourishment; hungry due to a lack of feeding.","s":"A grudge that remained unfed.","p":"un-FED","o":"Old English","y":5,"bp":24,"m":"unfeud","sy":"un.fed","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unfirm","d":"not firmly or solidly positioned","s":"The hiker tested each step carefully on the unfirm ground near the edge of the cliff.","p":"un-FIRM","o":"German","y":8,"bp":25,"m":"unferm","sy":"un.firm","nt":"Open","ps":"adjective","t":["onordic"]},{"w":"unfits","d":"make unfit or unsuitable","s":"A serious knee injury unfits an athlete for competition faster than almost anything else.","p":"un-FITS","o":"Old English","y":8,"bp":25,"m":"unfiits","sy":"un.fits","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"unfree","d":"held in servitude","s":"The unfree laborers on the plantation longed desperately for the day they would gain their liberty.","p":"un-FREE","o":"Latin","y":6,"bp":29,"sy":"un.free","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"ungual","d":"of or relating to a nail or claw or hoof","s":"The veterinarian examined the ungual structure of the eagle's talon before treating the injured bird.","p":"UNG-gwul","o":"Latin","y":7,"bp":29,"m":"unguel","sy":"un.gual","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"unguis","d":"any rigid body structure composed primarily of keratin","s":"The scientist studied the unguis of the fossilized dinosaur to determine how it captured prey.","p":"UNG-gwis","o":"Latin","y":7,"bp":29,"m":"ungues","sy":"un.guis","nt":"Open","ps":"noun","t":["olatin"]},{"w":"unhand","d":"To release your grip on a person and set them free at once.","s":"The hero shouted at the villain to unhand the frightened captive immediately.","p":"un-HAND","o":"Old English","y":6,"bp":25,"sy":"un.hand","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"unhewn","d":"(of stone especially) not given a finished form by or as if by hewing","s":"A house of unhewn grey stone roughly cemented together.","p":"un-HYOON","o":"Latin","y":6,"bp":29,"m":"unhewned","sy":"un.hewn","nt":"Open","ps":"adjective","t":["minerals","olatin"]},{"w":"uniat","d":"A member of an Eastern Christian church that is joined with the Roman Catholic Church.","s":"The uniat priest followed Eastern liturgical traditions while remaining in communion with Rome.","p":"YOO-nee-at","o":"Latin","y":7,"bp":30,"m":"unniat","sy":"u.ni.at","nt":"Open","ps":"noun","t":["religion","ancient","olatin"]},{"w":"uniate","d":"a member of the Uniat Church","s":"The uniate congregation celebrated their ancient Byzantine rites with great reverence each Sunday.","p":"YOO-nee-it","o":"Latin","y":7,"bp":30,"m":"uniате","sy":"u.ni.ate","nt":"Open","ps":"noun","t":["religion","olatin"]},{"w":"unio","d":"type genus of the family Unionidae","s":"The biologist carefully lifted a unio from the riverbed to study its pearly inner shell.","p":"YOO-nee-oh","o":"Latin","y":7,"bp":29,"m":"uneo","sy":"u.ni.o","nt":"Open","ps":"noun","t":["kinship","olatin"]},{"w":"unkept","d":"(especially of promises or contracts) having been violated or disregarded","s":"Broken (or unkept) promises.","p":"un-KEPT","o":"Old English","y":5,"bp":25,"m":"unkeeped","sy":"un.kept","nt":"Open","ps":"adjective","t":["law","ooldeng"]},{"w":"unknot","d":"become or cause to become undone by separating the fibers or threads of","s":"She spent twenty minutes trying to unknot the tangled fishing line before giving up.","p":"un-NOT","o":"Old English","y":6,"bp":25,"m":"unnot","sy":"un.knot","nt":"Open","ps":"verb","t":["ooldeng"]},{"w":"unlace","d":"undo the ties of","s":"After the long hike, Marcus sat down and began to unlace his muddy boots with relief.","p":"un-LAYS","o":"French","y":7,"bp":29,"m":"unlaice","sy":"un.lace","nt":"Open","ps":"verb","t":["ofrench"]},{"w":"unlade","d":"take the load off (a container or vehicle)","s":"The dockworkers hurried to unlade the heavy cargo from the ship before the storm arrived.","p":"un-LAYD","o":"Old English","y":8,"bp":25,"m":"unlaid","sy":"un.lade","nt":"Open","ps":"verb","t":["vehicles","ooldeng"]},{"w":"unlash","d":"untie the lashing of","s":"The sailors had to quickly unlash the equipment on deck as the waves grew dangerously high.","p":"un-LASH","o":"French","y":8,"bp":29,"m":"unlach","sy":"un.lash","nt":"Open","ps":"verb","t":["ofrench"]},{"w":"unlax","d":"cause to feel relaxed","s":"Listening to soft music helped her unlax after the most stressful week of the entire school year.","p":"un-LAKS","o":"Latin","y":7,"bp":28,"m":"unrelax","sy":"un.lax","nt":"Open","ps":"verb","t":["olatin"]},{"w":"unlit","d":"not set afire or burning","s":"The children crept nervously through the unlit hallway, not daring to make a sound.","p":"un-LIT","o":"Old English","y":4,"bp":24,"m":"unlitt","sy":"un.lit","nt":"Open","ps":"adjective","t":["ooldeng"]},{"w":"unlive","d":"live so as to annul some previous behavior","s":"No matter how much he regretted his cruel words, he could not unlive the moment he had spoken them.","p":"un-LIV","o":"Latin","y":8,"bp":29,"m":"unliev","sy":"un.live","nt":"Open","ps":"verb","t":["olatin"]},{"w":"ungetatable","d":"difficult to reach or attain","s":"The championship tickets were completely ungetatable just two hours after going on sale.","p":"un-GET-at-uh-bul","o":"Latin","y":9,"bp":34,"m":"ungetable","sy":"unge.tat.able","nt":"Open","ps":"adjective","t":["olatin"]},{"w":"undecapeptide","d":"A peptide molecule composed of exactly eleven amino acid residues linked together in a chain, playing various roles in biological signaling and regulation.","s":"Substance P is an undecapeptide, a chain of exactly eleven amino acids that transmits pain signals in the nervous system.","p":"un-dek-uh-PEP-tyd","o":"Greek","y":9,"bp":26,"sy":"un.de.capep.tide","ps":"noun","t":["chemistry","ogreek"]},{"w":"understater","d":"A person who deliberately describes something as less significant, smaller, or less serious than it actually is, often for effect or out of modesty.","s":"He was a classic understater, describing the hurricane simply as 'a bit of wind and rain.'.","p":"UN-der-stay-ter","o":"Greek","y":8,"bp":35,"sy":"un.der.stater","ps":"noun","t":["ogreek"]},{"w":"undidactic","d":"Not didactic; free from a moralizing or preachy instructional tone, presenting ideas without lecturing the audience.","s":"The teacher's undidactic approach let students discover answers through exploration rather than direct instruction.","p":"un-dy-DAK-tik","o":"Greek","y":8,"bp":30,"sy":"un.di.dac.tic","ps":"adjective","t":["ogreek"]},{"w":"unenergetic","d":"not inclined to be enterprising","s":"On the rainy Saturday morning, the whole class felt unenergetic and could barely stay awake.","p":"un-en-er-JET-ik","o":"Greek","y":8,"bp":38,"sy":"un.en.er.get.ic","ps":"adjective","t":["character","ogreek"]},{"w":"unhorizoned","d":"Lacking a visible or conceptual horizon; having no clear boundary between sky and earth, or no defined limits or prospects.","s":"The poet described the foggy morning sea as unhorizoned, a vast blur with no visible edge.","p":"un-huh-RY-zund","o":"Greek","y":8,"bp":35,"sy":"un.hori.zoned","ps":"adjective","t":["maps","ogreek"]},{"w":"underbill","d":"To charge less than the correct or full amount for goods or services; to issue a bill that is lower than what is actually owed.","s":"The contractor accidentally underbilled the client by forgetting to charge for materials.","p":"UN-der-bil","o":"Anglo-Norman","y":9,"bp":24,"sy":"un.der.bill","ps":"verb","t":["ofrench"]},{"w":"undercount","d":"To count fewer of something than the actual total, resulting in a number that is lower than the true amount.","s":"Researchers warned that the survey would undercount homeless individuals who lacked permanent addresses.","p":"UH-nder-kow-nt","o":"Anglo-Norman","y":7,"bp":25,"sy":"ah.nder.kaw.nt","ps":"verb","t":["numbers","ofrench"]},{"w":"underfur","d":"thick soft fur lying beneath the longer and coarser guard hair","s":"The Arctic fox's dense underfur keeps it warm even when temperatures plunge far below freezing.","p":"UHN-der-fur","o":"Anglo-Norman","y":8,"bp":17,"sy":"un.der.fur","ps":"noun","t":["ofrench"]},{"w":"undermaintain","d":"To maintain something at a level that is less than what is necessary or adequate, leading to deterioration or poor performance.","s":"City officials were criticized for choosing to undermaintain the aging bridges to save money.","p":"uhn-der-mayn-TAYN","o":"Anglo-Norman","y":9,"bp":34,"sy":"un.der.main.tain","ps":"verb","t":["ofrench"]},{"w":"underofficer","d":"A lower-ranking officer who serves in a subordinate position beneath a senior officer.","s":"The underofficer relayed the captain's orders to the troops assembled on the field.","p":"UHN-der-aw-fih-ser","o":"Anglo-Norman","y":9,"bp":35,"sy":"un.der.of.fi.cer","ps":"noun","t":["ofrench"]},{"w":"underreport","d":"To report or present information about something in a way that makes the actual amount, number, or severity seem less than it truly is.","s":"Scientists believe many minor earthquakes go undetected and are therefore underreported in official records.","p":"uh-nder-rih-PAW-rt","o":"Anglo-Norman","y":7,"bp":33,"sy":"ah.nder.rih.pao.rt","ps":"verb","t":["numbers","ofrench"]},{"w":"undertreasurer","d":"A deputy or assistant treasurer who works under the authority of the chief treasurer in managing finances.","s":"The undertreasurer managed daily financial records while the head treasurer handled major investments.","p":"uhn-der-TREZH-er-er","o":"Anglo-Norman","y":9,"bp":25,"sy":"un.der.trea.sur.er","ps":"noun","t":["poetry","economy","ofrench"]},{"w":"undertreat","d":"To provide medical or therapeutic treatment that is insufficient or inadequate for the condition being addressed.","s":"Doctors warned that to undertreat a serious infection could allow it to become life-threatening.","p":"uhn-der-TREET","o":"Anglo-Norman","y":8,"bp":25,"sy":"un.der.treat","ps":"verb","t":["body","ofrench"]},{"w":"unfamous","d":"Not well known or celebrated; lacking fame or public recognition.","s":"He remained happily unfamous, preferring quiet village life over any spotlight.","p":"uhn-FAY-mus","o":"Anglo-Norman","y":9,"bp":17,"sy":"un.fa.mous","ps":"adjective","t":["ofrench"]},{"w":"ungarble","d":"To restore a garbled or distorted message to its original clear and correct form; to make sense of something that was scrambled or confused.","s":"The technician worked for hours to ungarble the scrambled radio transmission.","p":"uhn-GAR-bul","o":"Anglo-Norman","y":9,"bp":17,"sy":"un.gar.ble","ps":"verb","t":["ofrench"]},{"w":"unharness","d":"To take off the straps and gear used to attach an animal to a plow, cart, or wagon.","s":"After a long day of plowing the fields under the hot summer sun, the tired farmer gently began to unharness the two brown horses from their heavy wooden yoke.","p":"uhn-HAR-nes","o":"Anglo-Norman","y":8,"bp":24,"sy":"un.har.ness","ps":"verb","t":["animals","tools","farming","vehicles","ofrench"]},{"w":"uniporter","d":"A transport protein in a cell membrane that carries only one specific type of molecule or ion across the membrane in a single direction.","s":"The biology textbook explained that a uniporter carries only one type of molecule across a cell membrane.","p":"YOO-nih-por-ter","o":"Anglo-Norman","y":8,"bp":22,"sy":"uni.porter","ps":"noun","t":["chemistry","ofrench"]},{"w":"underboss","d":"an assistant or second-in-command to a chief (especially in a crime syndicate)","s":"The underboss ran the daily operations of the crime family while the top leader stayed hidden.","p":"UN-dur-baws","o":"Dutch","y":6,"bp":24,"sy":"un.der.boss","ps":"noun","t":["law","odutch"]},{"w":"undeclare","d":"To officially withdraw, cancel, or take back a declaration or formal announcement that was previously made, reversing its stated intent or effect.","s":"The country chose to undeclare its previous stance on the treaty after new leadership took over.","p":"un-dih-KLAIR","o":"French","y":9,"bp":28,"sy":"un.de.clare","ps":"verb","t":["ofrench"]},{"w":"undecylic","d":"Relating to or derived from undecyl, a chemical group or compound containing eleven carbon atoms, often used in descriptions of fatty acids or organic chemistry.","s":"The chemist noted that undecylic acid contains an eleven-carbon chain in its structure.","p":"un-deh-SIL-ik","o":"French","y":9,"bp":28,"sy":"un.de.cylic","ps":"adjective","t":["chemistry","ofrench"]},{"w":"undefiant","d":"Not showing open resistance, boldness, or defiance; lacking the rebellious or challenging attitude associated with standing up against authority or opposition.","s":"The usually bold student was surprisingly undefiant when the principal spoke to her.","p":"un-dih-FY-unt","o":"French","y":8,"bp":29,"sy":"un.de.fi.ant","ps":"adjective","t":["poetry","ofrench"]},{"w":"undeify","d":"To remove the divine status or godlike reverence from someone or something; to strip away the worship or extreme admiration that has been bestowed upon a person or idea.","s":"The philosopher argued that modern culture needed to undeify celebrities and see them as ordinary people.","p":"un-DEE-ih-fy","o":"French","y":8,"bp":20,"sy":"un.de.ify","ps":"verb","t":["religion","ofrench"]},{"w":"undemocratization","d":"The process of reversing or dismantling democratic systems, institutions, or principles within a government or organization, moving away from democratic rule toward more authoritarian control.","s":"Scholars warned that the new laws represented a dangerous undemocratization of the country's government.","p":"un-deh-mok-ruh-tih-ZAY-shun","o":"French","y":9,"bp":33,"sy":"un.de.moc.ra.ti.za.tion","ps":"noun","t":["poetry","politics","logic","ofrench"]},{"w":"undemocratize","d":"To reverse the process of democratization by removing or weakening democratic rights, institutions, or practices within a society or governing body.","s":"Critics feared the dictator's actions would undemocratize institutions that took generations to build.","p":"un-deh-MOK-ruh-tyz","o":"French","y":9,"bp":40,"sy":"un.de.moc.ra.tize","ps":"verb","t":["politics","ofrench"]},{"w":"underassistant","d":"A person who serves in an assistant role at a level below that of a standard assistant, occupying one of the lowest rungs in a hierarchical support structure.","s":"As the underassistant on the project, she handled small tasks while the senior staff made decisions.","p":"un-dur-uh-SIS-tunt","o":"French","y":9,"bp":29,"sy":"un.der.as.sis.tant","ps":"noun","t":["ofrench"]},{"w":"underbust","d":"Referring to the measurement or area of the body directly beneath the bust or chest; often used in clothing and corsetry to describe a style or measurement taken just below the breasts.","s":"The costume designer measured the underbust to ensure the corset would fit properly.","p":"UN-dur-bust","o":"French","y":7,"bp":28,"sy":"un.der.bust","ps":"noun","t":["numbers","ofrench"]},{"w":"underdose","d":"To administer or take a smaller amount of a medication or substance than the recommended or effective therapeutic amount, potentially reducing its intended benefit.","s":"The nurse was careful not to underdose the patient, as too little medication would be ineffective.","p":"UN-dur-dohs","o":"French","y":9,"bp":28,"sy":"un.der.dose","ps":"verb","t":["body","ofrench"]},{"w":"underemotional","d":"Displaying or expressing less emotion than would be considered typical or appropriate for a given situation; seeming emotionally detached or insufficiently responsive.","s":"The underemotional actor delivered his lines so flatly that the audience felt nothing.","p":"un-dur-ih-MOH-shun-ul","o":"French","y":9,"bp":30,"sy":"un.der.e.mo.tion.al","ps":"adjective","t":["emotions","ofrench"]},{"w":"underhydration","d":"A condition in which the body or a substance does not contain enough water or fluids to function optimally, falling below the necessary level of hydration.","s":"The coach warned the team that underhydration during summer practice could cause serious health problems.","p":"un-dur-hy-DRAY-shun","o":"French","y":9,"bp":29,"sy":"un.der.hy.dra.tion","ps":"noun","t":["ofrench"]},{"w":"underinvest","d":"To commit less money, resources, or effort to something than is needed or advisable, resulting in inadequate support for growth, maintenance, or development.","s":"The city continued to underinvest in its public schools, leading to crumbling buildings and outdated textbooks.","p":"un-dur-in-VEST","o":"French","y":8,"bp":37,"sy":"un.der.in.vest","ps":"verb","t":["economy","ofrench"]},{"w":"underpromotion","d":"The act of providing insufficient promotion, publicity, or advancement for a product, person, or idea; in chess, the promotion of a pawn to a piece other than a queen.","s":"The talented employee quit after years of underpromotion while less qualified colleagues advanced.","p":"un-dur-pruh-MOH-shun","o":"French","y":9,"bp":29,"sy":"un.der.pro.mo.tion","ps":"noun","t":["royalty","sports","ofrench"]},{"w":"underrecruit","d":"To recruit an insufficient number of people for a position, organization, or study, resulting in a shortage of participants or members.","s":"The army began to underrecruit during peacetime, leaving gaps when conflict suddenly broke out.","p":"un-der-reh-KROOT","o":"French","y":9,"bp":36,"sy":"un.der.recruit","ps":"verb","t":["numbers","ofrench"]},{"w":"understructure","d":"lowest support of a structure","p":"un-der-STRUK-cher","o":"French","y":9,"bp":27,"sy":"un.der.struc.ture","ps":"noun","t":["ofrench"]},{"w":"undiscoverability","d":"The quality or state of being impossible or extremely difficult to find, detect, or uncover, especially in a search or investigation.","s":"The spy was proud of the undiscoverability of her secret hideout, buried deep in the forest.","p":"un-dis-kuv-er-uh-BIL-ih-tee","o":"French","y":9,"bp":32,"sy":"undis.cov.er.abil.i.ty","ps":"noun","t":["economy","ofrench"]},{"w":"undiversion","d":"The absence or reversal of a diversion; the state of not being turned aside from a direct path or purpose, or the act of restoring a diverted flow or course.","s":"The coach worried that the team's undiversion from its rigid routine made games feel boring.","p":"un-dih-VER-zhun","o":"French","y":8,"bp":37,"sy":"un.di.ver.sion","ps":"noun","t":["ofrench"]},{"w":"undynamic","d":"characterized by an absence of force or forcefulness","s":"The undynamic speaker droned on in a flat voice, and half the audience fell asleep.","p":"un-dy-NAM-ik","o":"French","y":9,"bp":29,"sy":"un.dy.nam.ic","ps":"adjective","t":["physics","character","ofrench"]},{"w":"unemployability","d":"The condition or quality of being unfit or unable to obtain or hold employment, often due to lack of skills, health issues, or other barriers.","s":"Refusing to learn any new skills contributed to his unemployability in the changing job market.","p":"un-em-ploy-uh-BIL-ih-tee","o":"French","y":8,"bp":33,"sy":"un.em.ploy.a.bil.i.ty","ps":"noun","t":["ofrench"]},{"w":"unemployee","d":"A person who is not currently employed; someone who lacks the status of an employee, especially one who has lost or never held a job.","s":"The company referred to the laid-off worker humorously as an unemployee until he found a new job.","p":"un-em-ploy-EE","o":"French","y":9,"bp":30,"sy":"un.em.ploy.ee","ps":"noun","t":["character","ofrench"]},{"w":"unequip","d":"To remove equipment, gear, or supplies from someone or something; to strip away the tools or provisions previously provided.","s":"Before returning the camping gear, you must unequip all the accessories from the backpack frame.","p":"un-ih-KWIP","o":"French","y":9,"bp":19,"sy":"un.equip","ps":"verb","t":["tools","ofrench"]},{"w":"unfacetious","d":"Not joking or playful; characterized by seriousness and sincerity rather than humor or lighthearted wit.","s":"Her unfacetious tone made it clear she was completely serious about the new classroom rules.","p":"un-fuh-SEE-shus","o":"French","y":9,"bp":35,"sy":"un.face.tious","ps":"adjective","t":["character","ofrench"]},{"w":"unfacetiously","d":"In a manner that is not joking or playful; speaking or acting with complete seriousness and without any attempt at humor.","s":"He stated unfacetiously that the project would take three years, and everyone finally believed him.","p":"un-fuh-SEE-shus-lee","o":"French","y":9,"bp":38,"sy":"un.face.tious.ly","ps":"adverb","t":["ofrench"]},{"w":"unfalsifiability","d":"The property of a claim or theory that makes it impossible to prove false through any conceivable observation or experiment, often considered a weakness in scientific reasoning.","s":"The philosopher argued that the unfalsifiability of the theory made it impossible to test scientifically.","p":"un-fawl-sih-fy-uh-BIL-ih-tee","o":"French","y":9,"bp":35,"sy":"un.fal.si.fi.a.bil.i.ty","ps":"noun","t":["logic","ofrench"]},{"w":"unfile","d":"To remove a document or record from a file or filing system; to reverse the act of filing something away for storage or reference.","s":"She had to unfile the documents and reorganize them into the correct folders after the mix-up.","p":"un-FYL","o":"French","y":8,"bp":18,"sy":"un.file","ps":"verb","t":["ofrench"]},{"w":"unflamboyant","d":"Not showy, flashy, or attention-seeking; characterized by quiet restraint and a lack of dramatic flair or ostentatious display.","s":"The unflamboyant architect preferred clean, simple lines over flashy decorations.","p":"un-flam-BOY-unt","o":"French","y":8,"bp":38,"sy":"un.flam.boy.ant","ps":"adjective","t":["stage","character","ofrench"]},{"w":"unflamboyantly","d":"In a manner that is not showy or dramatic; behaving or presenting oneself with quiet restraint and without flashy or ostentatious display.","s":"She dressed unflamboyantly for the gala, choosing a simple navy dress over sequins.","p":"un-flam-BOY-unt-lee","o":"French","y":9,"bp":29,"sy":"un.flam.boy.ant.ly","ps":"adverb","t":["stage","ofrench"]},{"w":"unformation","d":"The process or act of breaking up or dissolving a formation; the reversal of an organized arrangement or structured grouping.","s":"The general ordered the unformation of the troops so they could rest in small informal groups.","p":"un-for-MAY-shun","o":"French","y":8,"bp":37,"sy":"un.for.ma.tion","ps":"noun","t":["ofrench"]},{"w":"ungenteel","d":"Not refined, polite, or socially elegant; lacking the graceful manners and cultivated behavior associated with genteel society.","s":"His ungenteel habit of talking with his mouth full embarrassed his hosts at the dinner party.","p":"un-jen-TEEL","o":"French","y":8,"bp":28,"sy":"un.gen.teel","ps":"adjective","t":["farming","ofrench"]},{"w":"ungrammaticality","d":"The quality or state of violating the rules of grammar; the property of a sentence or expression that makes it incorrect according to grammatical standards.","s":"The teacher underlined each example of ungrammaticality in the essay with a red pen.","p":"un-gruh-mat-ih-KAL-ih-tee","o":"French","y":9,"bp":33,"sy":"un.gram.mat.i.cal.i.ty","ps":"noun","t":["wordwords","ofrench"]},{"w":"ungrandiose","d":"Not grand, pompous, or exaggeratedly impressive; modest and free from the inflated scale or dramatic excess typical of grandiose things.","s":"His ungrandiose lifestyle was surprising given how wealthy his family was.","p":"un-GRAN-dee-ohs","o":"French","y":9,"bp":34,"sy":"un.grandiose","ps":"adjective","t":["stage","ofrench"]},{"w":"ungraspability","d":"The quality of being impossible to grasp, understand, or hold onto, either physically or mentally; the state of eluding comprehension or capture.","s":"The ungraspability of quantum physics frustrated many students in the advanced science class.","p":"un-grasp-uh-BIL-ih-tee","o":"French","y":9,"bp":30,"sy":"un.gras.pa.bil.i.ty","ps":"noun","t":["ofrench"]},{"w":"ungrave","d":"To remove from a grave; to exhume or dig up something that has been buried, reversing the act of interment.","s":"The archaeologists had to ungrave the ancient artifacts carefully to avoid damaging them.","p":"un-GRAYV","o":"French","y":9,"bp":19,"sy":"un.grave","ps":"verb","t":["ofrench"]},{"w":"ungroup","d":"To separate members of a group back into individual units; to undo the act of grouping things or people together.","s":"The teacher asked students to ungroup their desks and sit individually for the test.","p":"un-GROOP","o":"French","y":8,"bp":19,"sy":"un.group","ps":"verb","t":["ofrench"]},{"w":"unhash","d":"To reverse a hashing process; to decode or untangle something that has been mixed, scrambled, or converted into a hash format.","s":"The programmer wrote a function to unhash the encoded data back into readable text.","p":"un-HASH","o":"French","y":8,"bp":18,"sy":"un.hash","ps":"verb","t":["ofrench"]},{"w":"unhypnotic","d":"Not having the quality of inducing hypnosis or a trance-like state; failing to captivate, mesmerize, or hold the attention in a compelling way.","s":"The speaker's unhypnotic, choppy delivery failed to keep the audience's attention.","p":"un-hip-NOT-ik","o":"French","y":8,"bp":30,"sy":"un.hyp.not.ic","ps":"adjective","t":["ofrench"]},{"w":"unicodification","d":"The process of converting text or characters into the Unicode standard, a universal encoding system that represents characters from virtually all writing systems in the world.","s":"The unicodification of the website's text allowed users from every country to read it in their own language.","p":"yoo-nih-koh-dih-fih-KAY-shun","o":"French","y":9,"bp":31,"sy":"uni.cod.i.fi.ca.tion","ps":"noun","t":["ofrench"]},{"w":"unideal","d":"Not perfect or optimal; falling short of what would be considered the best or most desirable outcome or condition.","s":"Working without any light was unideal, but she finished the project anyway.","p":"un-eye-DEE-ul","o":"French","y":7,"bp":19,"sy":"unide.al","ps":"adjective","t":["ofrench"]},{"w":"unimpeachability","d":"The quality of being beyond reproach or question; the state of being so trustworthy and blameless that no charge or accusation can successfully be brought against someone or something.","s":"The judge's unimpeachability meant no one could question her honesty or fairness.","p":"un-im-pee-chuh-BIL-ih-tee","o":"French","y":9,"bp":32,"sy":"unim.peach.a.bil.i.ty","ps":"noun","t":["law","ofrench"]},{"w":"uninymic","d":"Relating to or characterized by having only one name, as in a person or entity known by a single name rather than a first and last name.","s":"The linguist noted that the tribe's uninymic naming system gave every person a single, unique name with no family surname.","p":"yoo-nih-NIM-ik","o":"French","y":9,"bp":18,"ps":"adjective","t":["character","ofrench"]},{"w":"uniquify","d":"To make something unique or distinct; to modify a set of items so that each one is different and no duplicates remain.","s":"The designer tried to uniquify each product so that no two items in the shop looked the same.","p":"yoo-NEEK-ih-fy","o":"French","y":9,"bp":18,"ps":"verb","t":["ofrench"]},{"w":"unisexuality","d":"The quality or state of being designed for, applicable to, or characteristic of only one sex, or alternatively of being common to and shared by all sexes without distinction.","s":"The fashion line celebrated unisexuality by designing clothes that anyone could wear comfortably.","p":"yoo-nih-sek-shoo-AL-ih-tee","o":"French","y":8,"bp":41,"sy":"uni.sex.u.al.i.ty","ps":"noun","t":["ofrench"]},{"w":"unitarity","d":"The mathematical property of a transformation or system in which the total probability is preserved and the process is fully reversible, especially important in quantum mechanics.","s":"The physics professor explained that unitarity ensures total probability never exceeds one in quantum mechanics.","p":"yoo-nih-TAIR-ih-tee","o":"French","y":7,"bp":29,"sy":"uni.tar.i.ty","ps":"noun","t":["physics","numbers","ofrench"]},{"w":"universalise","d":"make universal","p":"yoo-nih-VER-suh-lyz","o":"French","y":9,"bp":36,"sy":"uni.ver.salise","ps":"verb","t":["ofrench"]},{"w":"unliterary","d":"marked by lack of affectation or pedantry","s":"Her talk was very unliterary.","p":"un-LIT-er-air-ee","o":"French","y":8,"bp":30,"sy":"un.lit.er.ary","ps":"adjective","t":["ofrench"]},{"w":"unluxurious","d":"Not characterized by luxury, comfort, or indulgence; plain, simple, and lacking the rich or extravagant qualities associated with luxury.","s":"The cabin was unluxurious but perfectly cozy for a weekend of hiking and campfires.","p":"un-lug-ZHOOR-ee-us","o":"French","y":9,"bp":38,"sy":"un.lux.u.ri.ous","ps":"adjective","t":["landforms","character","ofrench"]},{"w":"unfirmness","d":"The quality or state of being unsteady, unstable, or lacking solidity; the condition of not being firm in structure or resolve.","s":"The unfirmness of the bridge's foundation made the engineers very nervous.","p":"un-FIRM-ness","o":"German","y":9,"bp":25,"sy":"un.firm.ness","ps":"noun","t":["onordic"]},{"w":"unke","d":"To croak or make a gloomy prediction; to speak pessimistically about the future, often used of a person who habitually foretells doom.","s":"The old man would unke about storms coming, always predicting the worst.","p":"OONK-eh","o":"German","y":8,"bp":6,"sy":"un.ke","ps":"verb","t":["emotions","onordic"]},{"w":"underbet","d":"To wager less money than the situation, odds, or strategy would call for, resulting in a bet that is smaller than optimal.","s":"The experienced poker player warned his student that it was just as dangerous to underbet a strong hand as to overbet a weak one, since both errors cost money.","p":"UN-der-bet","o":"Hebrew","y":8,"bp":23,"sy":"un.der.bet","ps":"verb","t":["economy","osemitic"]},{"w":"unget","d":"In Jewish law, to revoke or annul a get, which is a religious bill of divorce, thereby canceling the dissolution of a marriage under rabbinical authority.","s":"The rabbinical court carefully deliberated whether it was permissible to unget the document after new testimony raised serious questions about the original proceeding's validity.","p":"un-GET","o":"Hebrew","y":7,"bp":12,"ps":"verb","t":["poetry","religion","law","kinship","osemitic"]},{"w":"undamaging","d":"Not causing harm, injury, or destruction; having no negative effect on a person or thing.","s":"The light rain was undamaging to the crops, actually giving them a helpful drink of water.","p":"un-DAM-ij-ing","o":"Latin","y":8,"bp":30,"sy":"un.dam.ag.ing","ps":"adjective","t":["olatin"]},{"w":"undammable","d":"Impossible to block or restrain with a dam; incapable of being held back by any barrier.","s":"The undammable river flooded every attempt engineers made to block its powerful flow.","p":"un-DAM-uh-bul","o":"Latin","y":9,"bp":27,"sy":"un.dammable","ps":"adjective","t":["olatin"]},{"w":"undamned","d":"Not condemned or cursed; free from a sentence of damnation or strong condemnation.","s":"In the story, the ghost was finally undamned after completing his unfinished earthly task.","p":"un-DAMD","o":"Latin","y":8,"bp":25,"sy":"un.damned","ps":"adjective","t":["olatin"]},{"w":"undampened","d":"Not reduced in strength, enthusiasm, or intensity; remaining lively and undiminished despite potential obstacles.","s":"Her undampened excitement about the trip continued even after they missed their first flight.","p":"un-DAM-pund","o":"Latin","y":8,"bp":29,"sy":"un.damp.ened","ps":"adjective","t":["olatin"]},{"w":"undancerly","d":"Lacking the grace, poise, or skill expected of a dancer; behaving or moving in a way unbecoming of a trained dancer.","s":"His undancerly moves on the stage made the audience giggle instead of applaud.","p":"un-DAN-sur-lee","o":"Latin","y":8,"bp":29,"sy":"un.dancer.ly","ps":"adverb","t":["stage","olatin"]},{"w":"undappled","d":"Not marked with spots, patches, or flecks of color or light; presenting a plain, uniform surface without variation.","s":"The undappled grey sky stretched from horizon to horizon without a single patch of sunlight.","p":"un-DAP-uld","o":"Latin","y":8,"bp":28,"sy":"un.dap.pled","ps":"adjective","t":["landforms","colors","olatin"]},{"w":"undared","d":"Not attempted out of courage or boldness; describing an action or challenge that no one was willing to take on.","s":"The challenge remained undared, and no one in the group was brave enough to try it.","p":"un-DAIRD","o":"Latin","y":8,"bp":19,"sy":"un.dared","ps":"adjective","t":["olatin"]},{"w":"undarkened","d":"Not made dark or dim; remaining bright and unobscured by shadow or darkness.","s":"The undarkened sky at midnight during the summer solstice amazed the northern travelers.","p":"un-DAR-kund","o":"Latin","y":8,"bp":29,"sy":"un.dark.ened","ps":"adjective","t":["olatin"]},{"w":"undarned","d":"Not repaired by darning; describing a hole or worn area in fabric that has not been mended with thread.","s":"The undarned socks sat in a pile on the table, full of holes and waiting to be repaired.","p":"un-DARND","o":"Latin","y":8,"bp":25,"sy":"un.darned","ps":"adjective","t":["fabrics","olatin"]},{"w":"undashed","d":"Not discouraged, broken, or shattered; remaining intact and unbroken by force or disappointment.","s":"The undashed explorer pressed forward through the storm without a moment of hesitation.","p":"un-DASHT","o":"Latin","y":8,"bp":25,"sy":"un.dashed","ps":"adjective","t":["physics","olatin"]},{"w":"undatable","d":"not capable of being given a date","s":"The ancient pottery shard was undatable because it lacked any recognizable markings or style.","p":"un-DAY-tuh-bul","o":"Latin","y":8,"bp":28,"sy":"un.dat.able","ps":"adjective","t":["olatin"]},{"w":"undaughterly","d":"Not behaving in the manner expected of a dutiful or affectionate daughter; acting contrary to what a daughter is traditionally expected to do.","s":"Her refusal to visit her ailing mother was considered undaughterly by the whole family.","p":"un-DAW-tur-lee","o":"Latin","y":8,"bp":38,"sy":"un.daugh.ter.ly","ps":"adjective","t":["festivals","emotions","kinship","olatin"]},{"w":"undauntable","d":"Impossible to intimidate or discourage; describing a person or spirit that cannot be frightened or made to give up.","s":"The undauntable knight charged into battle no matter how many enemies stood against him.","p":"un-DAWN-tuh-bul","o":"Latin","y":9,"bp":35,"sy":"un.daunt.able","ps":"adjective","t":["olatin"]},{"w":"undaunting","d":"Not frightening or discouraging; describing a challenge or task that does not inspire fear or hesitation.","s":"The teacher's gentle smile made the difficult math problem feel undaunting to the nervous student.","p":"un-DAWN-ting","o":"Latin","y":8,"bp":29,"sy":"un.daunt.ing","ps":"adjective","t":["emotions","olatin"]},{"w":"undauntingly","d":"In a manner that is not intimidating or discouraging; without causing fear or a sense of being overwhelmed.","s":"She undauntingly climbed the steep mountain trail even as others turned back.","p":"un-DAWN-ting-lee","o":"Latin","y":8,"bp":38,"sy":"un.daunt.ing.ly","ps":"adverb","t":["emotions","olatin"]},{"w":"undazzled","d":"Not overwhelmed or blinded by brilliance, spectacle, or impressive display; remaining clear-headed and unimpressed.","s":"The critic remained undazzled by the flashy special effects and focused on the weak plot.","p":"un-DAZ-uld","o":"Latin","y":8,"bp":28,"sy":"un.daz.zled","ps":"adjective","t":["colors","olatin"]},{"w":"undazzling","d":"Failing to impress or dazzle; not brilliant, spectacular, or striking in any remarkable way.","s":"The undazzling gray walls of the waiting room made everyone feel sleepy and bored.","p":"un-DAZ-ling","o":"Latin","y":9,"bp":29,"sy":"un.daz.zling","ps":"adjective","t":["colors","olatin"]},{"w":"undead","d":"Describing a being that is neither fully alive nor completely dead, such as a vampire or zombie in folklore and fiction.","s":"In the horror story, the graveyard was filled with undead creatures that rose at midnight.","p":"un-DED","o":"Latin","y":3,"bp":18,"sy":"un.dead","ps":"adjective","t":["festivals","olatin"]},{"w":"undeadened","d":"Not dulled, numbed, or made insensitive; remaining fully alert and responsive to sensation or feeling.","s":"His undeadened senses allowed him to hear every whisper in the crowded hallway.","p":"un-DED-und","o":"Latin","y":8,"bp":29,"sy":"un.dead.ened","ps":"adjective","t":["olatin"]},{"w":"undeadly","d":"Not causing or capable of causing death; posing no lethal threat or danger.","s":"The harmless little spider was completely undeadly, despite its frightening appearance.","p":"un-DED-lee","o":"Latin","y":8,"bp":27,"sy":"un.dead.ly","ps":"adjective","t":["olatin"]},{"w":"undeafen","d":"To restore the ability to hear; to reverse a state of deafness so that sound can be perceived once again.","s":"The surgeon hoped the new procedure would undeafen patients who had lost their hearing.","p":"un-DEF-un","o":"Latin","y":8,"bp":27,"sy":"un.deaf.en","ps":"verb","t":["olatin"]},{"w":"undeafened","d":"Not made deaf; retaining full hearing ability without having experienced any loss or impairment of sound perception.","s":"The crowd was undeafened by the distant explosion because they wore protective earmuffs.","p":"un-DEF-und","o":"Latin","y":8,"bp":29,"sy":"un.deaf.ened","ps":"adjective","t":["olatin"]},{"w":"undealt","d":"Not yet distributed or handled; describing cards, problems, or matters that have not been given out or addressed.","s":"Half the cards remained undealt in the center of the table as the game was interrupted.","p":"un-DELT","o":"Latin","y":8,"bp":19,"sy":"un.dealt","ps":"adjective","t":["olatin"]},{"w":"undeath","d":"A state of existence that is neither true life nor true death, often associated in fiction with creatures such as vampires, ghosts, or zombies.","s":"The vampire lived in a state of undeath, forever trapped between the living and the dead.","p":"un-DETH","o":"Latin","y":6,"bp":19,"sy":"un.death","ps":"noun","t":["olatin"]},{"w":"undebased","d":"Not lowered in quality, value, or moral standing; remaining pure and uncorrupted in its original form.","s":"The undebased gold coin held its full value because it was never mixed with cheaper metals.","p":"un-dih-BAYST","o":"Latin","y":8,"bp":28,"sy":"un.de.based","ps":"adjective","t":["logic","olatin"]},{"w":"undebatably","d":"In a manner that cannot be argued or disputed; so clearly true or settled that no debate is possible.","s":"She was undebatably the fastest runner on the team, winning every single race by a wide margin.","p":"un-dih-BAY-tuh-blee","o":"Latin","y":8,"bp":37,"sy":"un.de.bat.ably","ps":"adverb","t":["olatin"]},{"w":"undebated","d":"Not discussed or argued about; referring to a topic or question that has never been the subject of formal debate.","s":"The rule was passed as undebated because every council member agreed without argument.","p":"un-dih-BAY-tid","o":"Latin","y":8,"bp":29,"sy":"un.de.bat.ed","ps":"adjective","t":["olatin"]},{"w":"undebuggable","d":"Impossible to identify and fix errors in, especially in computer code; describing software so flawed or complex that its bugs cannot be resolved.","s":"The programmer sighed, saying the ancient code was practically undebuggable after so many years.","p":"un-dih-BUG-uh-bul","o":"Latin","y":9,"bp":38,"sy":"un.de.bug.gable","ps":"adjective","t":["olatin"]},{"w":"undecadent","d":"Not characterized by moral or cultural decline; free from excessive indulgence, luxury, or decay of standards.","s":"The undecadent lifestyle of the monks included simple meals and long hours of quiet study.","p":"un-DEK-uh-dunt","o":"Latin","y":8,"bp":29,"sy":"un.deca.dent","ps":"adjective","t":["character","logic","olatin"]},{"w":"undeceive","d":"free from deception or illusion","s":"The kind teacher gently tried to undeceive her students who believed the myth about lightning.","p":"un-dih-SEEV","o":"Latin","y":9,"bp":28,"sy":"un.de.ceive","ps":"verb","t":["olatin"]},{"w":"undeception","d":"The act of freeing someone from a false belief or illusion; the process of revealing the truth after a person has been deceived.","s":"His honest confession was an act of undeception that finally cleared up years of misunderstanding.","p":"un-dih-SEP-shun","o":"Latin","y":8,"bp":37,"sy":"un.de.cep.tion","ps":"noun","t":["logic","olatin"]},{"w":"undecide","d":"To reverse or cancel a decision that has already been made; to return to a state of uncertainty after having chosen a course of action.","s":"She tried to undecide her choice of college after hearing about a better scholarship elsewhere.","p":"un-dih-SYD","o":"Latin","y":9,"bp":27,"sy":"un.de.cide","ps":"verb","t":["olatin"]},{"w":"undecimalized","d":"Not converted to a decimal system; remaining in a non-decimal format, such as fractions or traditional units of measurement.","s":"The undecimalized measurement system confused students who expected everything in units of ten.","p":"un-DES-ih-muh-lyzd","o":"Latin","y":9,"bp":28,"sy":"un.dec.i.mal.ized","ps":"adjective","t":["festivals","numbers","olatin"]},{"w":"undecimated","d":"Not destroyed, greatly reduced, or devastated; remaining whole and intact without having suffered massive losses.","s":"The undecimated forest stretched for miles, untouched and full of wildlife.","p":"un-DES-ih-may-tid","o":"Latin","y":8,"bp":38,"sy":"un.dec.i.mat.ed","ps":"adjective","t":["olatin"]},{"w":"undeciphered","d":"not deciphered","s":"Linear A is still undeciphered.","p":"un-dih-SY-furd","o":"Latin","y":7,"bp":38,"sy":"un.de.ci.phered","ps":"adjective","t":["olatin"]},{"w":"undecked","d":"Not decorated or adorned; lacking ornaments, trimmings, or embellishments of any kind.","s":"The plain, undecked hallway felt empty compared to the festively decorated gymnasium.","p":"un-DEKT","o":"Latin","y":8,"bp":25,"sy":"un.decked","ps":"adjective","t":["olatin"]},{"w":"undeclaration","d":"The absence or withdrawal of an official declaration; the act of reversing or nullifying something that was previously declared.","s":"The diplomat's undeclaration of war left both nations confused about their official relationship.","p":"un-dek-luh-RAY-shun","o":"Latin","y":9,"bp":28,"sy":"un.dec.la.ra.tion","ps":"noun","t":["olatin"]},{"w":"undeclinable","d":"Not capable of being declined, refused, or turned down; impossible to reject or grammatically inflect with different case endings.","s":"The invitation to the royal banquet seemed undeclinable, as refusing would cause great offense.","p":"un-dih-KLYN-uh-bul","o":"Latin","y":9,"bp":38,"sy":"un.de.clin.able","ps":"adjective","t":["wordwords","olatin"]},{"w":"undecomposable","d":"representing the furthest possible extent of analysis or division into parts","s":"A feeling is a simple and undecomposable mental state.","p":"un-dee-kum-POH-zuh-bul","o":"Latin","y":9,"bp":29,"sy":"un.de.com.pos.able","ps":"adjective","t":["numbers","olatin"]},{"w":"undecorate","d":"To remove decorations or ornaments from something, stripping it back to a plain or unadorned state.","s":"After the holidays, the family helped undecorate the house by taking down every ornament.","p":"un-DEK-uh-rayt","o":"Latin","y":9,"bp":30,"sy":"un.dec.o.rate","ps":"verb","t":["landforms","olatin"]},{"w":"undecorative","d":"Not serving a decorative purpose; lacking any ornamental or aesthetic quality; plain and purely functional.","s":"The undecorative concrete walls made the basement feel cold and unwelcoming.","p":"un-DEK-uh-ray-tiv","o":"Latin","y":9,"bp":39,"sy":"un.dec.o.ra.tive","ps":"adjective","t":["landforms","olatin"]},{"w":"undecreasing","d":"Not decreasing; remaining constant or continuing to grow without any reduction in size, amount, or intensity.","s":"The undecreasing noise from the construction site made it impossible to concentrate in class.","p":"un-dih-KREE-sing","o":"Latin","y":8,"bp":38,"sy":"un.de.creas.ing","ps":"adjective","t":["olatin"]},{"w":"undecreed","d":"Not established or commanded by an official decree; lacking the authority of a formal ruling or order.","s":"The rule remained undecreed because the council never reached a final vote.","p":"un-dih-KREED","o":"Latin","y":8,"bp":28,"sy":"un.de.creed","ps":"adjective","t":["poetry","law","olatin"]},{"w":"undecremented","d":"Not reduced or diminished; describing a value or quantity that has not been decreased by any amount.","s":"The undecremented counter kept rising because no one programmed it to subtract.","p":"un-DEK-ruh-ment-ed","o":"Latin","y":9,"bp":26,"sy":"un.decre.ment.ed","ps":"adjective","t":["olatin"]},{"w":"undeeded","d":"Not transferred or conveyed by means of a legal deed; describing property for which no official ownership document has been issued.","s":"The undeeded land had no legal owner on record, causing disputes among the neighbors.","p":"un-DEE-did","o":"Latin","y":8,"bp":27,"sy":"un.deed.ed","ps":"adjective","t":["law","olatin"]},{"w":"undefaced","d":"Not damaged, marked, or disfigured in any way; remaining in its original, unspoiled condition without any defacement.","s":"The undefaced statue in the park had been carefully protected from vandalism for over a century.","p":"un-dih-FAYST","o":"Latin","y":8,"bp":28,"sy":"un.de.faced","ps":"adjective","t":["olatin"]},{"w":"undefendable","d":"not defended or capable of being defended","s":"The lawyer admitted that the client's position was completely undefendable, since the evidence against him was so overwhelming that no argument could reasonably justify his actions in court.","p":"un-dih-FEN-duh-bul","o":"Latin","y":8,"bp":38,"sy":"un.de.fend.able","ps":"adjective","t":["olatin"]},{"w":"undefensive","d":"Not defensive in attitude or behavior; open, calm, and willing to accept criticism without putting up emotional or physical barriers.","s":"His undefensive response to criticism showed real maturity and willingness to improve.","p":"un-dih-FEN-siv","o":"Latin","y":9,"bp":37,"sy":"un.de.fen.sive","ps":"adjective","t":["emotions","olatin"]},{"w":"undeferrable","d":"Not capable of being postponed, delayed, or put off to a later time; requiring immediate attention or action.","s":"The undeferrable deadline meant every student had to submit their project by Friday no matter what.","p":"un-dih-FUR-uh-bul","o":"Latin","y":9,"bp":36,"sy":"un.de.ferrable","ps":"adjective","t":["time","olatin"]},{"w":"undeferred","d":"Not postponed or delayed; carried out or addressed immediately without being put off to a future time.","s":"The undeferred payment arrived exactly on the agreed date, surprising everyone at the office.","p":"un-dih-FURD","o":"Latin","y":9,"bp":29,"sy":"un.de.ferred","ps":"adjective","t":["time","olatin"]},{"w":"undefiable","d":"Not capable of being defied, challenged, or resisted; so powerful or absolute that no opposition against it is possible.","s":"The champion's record seemed undefiable, as no competitor came close to breaking it.","p":"un-dih-FY-uh-bul","o":"Latin","y":9,"bp":30,"sy":"un.de.fi.able","ps":"adjective","t":["olatin"]},{"w":"undefied","d":"Not challenged, opposed, or resisted; describing a rule, authority, or power that has never been openly confronted or disobeyed.","s":"For decades, the school's strict dress code went undefied by even the boldest students.","p":"un-dih-FYD","o":"Latin","y":8,"bp":27,"sy":"un.de.fied","ps":"adjective","t":["poetry","olatin"]},{"w":"undefine","d":"To take away a word's or term's fixed meaning, leaving it without a set explanation.","s":"The philosopher tried to undefine the word 'freedom,' arguing that no single meaning could capture it.","p":"un-dih-FYN","o":"Latin","y":9,"bp":27,"sy":"un.de.fine","ps":"verb","t":["wordwords","olatin"]},{"w":"undefinedly","d":"In a manner that is not clearly defined or precisely explained; vaguely or without clear boundaries or meaning.","s":"The artist spoke undefinedly about her inspiration, leaving the audience to interpret her words freely.","p":"un-dih-FYND-lee","o":"Latin","y":8,"bp":37,"sy":"un.de.fined.ly","ps":"adverb","t":["olatin"]},{"w":"undefinition","d":"The state or act of lacking a clear definition; the removal or absence of a precise meaning or explanation for a word or concept.","s":"The linguist called the removal of strict word meanings an act of undefinition in modern slang.","p":"un-def-ih-NIH-shun","o":"Latin","y":8,"bp":39,"sy":"un.def.i.ni.tion","ps":"noun","t":["wordwords","olatin"]},{"w":"undeflectable","d":"Not capable of being turned aside, redirected, or deflected from its course; impossible to divert from a straight path or purpose.","s":"The meteor's path was undeflectable by the time scientists detected it heading toward Earth.","p":"un-dih-FLEK-tuh-bul","o":"Latin","y":9,"bp":25,"sy":"un.de.flectable","ps":"adjective","t":["olatin"]},{"w":"undeflected","d":"Not turned aside or redirected; continuing in the original direction or purpose without having been diverted or bent away.","s":"The laser beam traveled undeflected through the vacuum chamber in a perfectly straight line.","p":"un-dih-FLEK-tid","o":"Latin","y":8,"bp":37,"sy":"un.de.flect.ed","ps":"adjective","t":["olatin"]},{"w":"undeformable","d":"Not capable of being bent, twisted, or altered in shape; able to maintain its original form under pressure or stress without distortion.","s":"The engineer chose an undeformable alloy so the bridge would hold its shape under heavy traffic.","p":"un-dih-FOR-muh-bul","o":"Latin","y":9,"bp":36,"sy":"un.de.formable","ps":"adjective","t":["olatin"]},{"w":"undefrauded","d":"Not cheated, deceived, or swindled; having successfully avoided or been protected from any act of fraud or deceit.","s":"Thanks to careful accounting, the charity remained undefrauded despite many attempts at scamming.","p":"un-dih-FRAWD-id","o":"Latin","y":8,"bp":37,"sy":"un.de.fraud.ed","ps":"adjective","t":["olatin"]},{"w":"undegassed","d":"Not having had dissolved gases removed; still containing its original gas content, as in a liquid or material from which gas has not been extracted.","s":"The scientist warned that the undegassed sample would release bubbles and ruin the experiment.","p":"un-dih-GAST","o":"Latin","y":9,"bp":29,"sy":"un.de.gassed","ps":"adjective","t":["olatin"]},{"w":"undegradable","d":"Not capable of being broken down, deteriorated, or reduced to a lower quality or simpler substances, especially through natural processes.","s":"Some plastics are virtually undegradable and will remain in landfills for thousands of years.","p":"un-dih-GRAY-duh-bul","o":"Latin","y":9,"bp":36,"sy":"un.degrad.able","ps":"adjective","t":["olatin"]},{"w":"undegrading","d":"Not causing degradation, humiliation, or a lowering of quality or character; maintaining dignity and value without any reduction.","s":"She appreciated the undegrading tone of the feedback, which corrected her work without any insults.","p":"un-dih-GRAY-ding","o":"Latin","y":8,"bp":37,"sy":"un.de.grad.ing","ps":"adjective","t":["olatin"]},{"w":"undejected","d":"Not downcast, discouraged, or low in spirits; remaining cheerful and optimistic rather than feeling sad or hopeless.","s":"Even after losing the match, the undejected player smiled and immediately started planning her comeback.","p":"un-dih-JEK-tid","o":"Latin","y":8,"bp":30,"sy":"un.de.ject.ed","ps":"adjective","t":["olatin"]},{"w":"undelayable","d":"Not capable of being postponed or put off; so urgent or immediate that any delay is impossible or unacceptable.","s":"The emergency surgery was undelayable, so the doctors rushed the patient straight into the operating room.","p":"un-dih-LAY-uh-bul","o":"Latin","y":9,"bp":35,"sy":"un.de.layable","ps":"adjective","t":["olatin"]},{"w":"undelayed","d":"Not held back or postponed; happening or arriving exactly on time without any delay or interruption to the schedule.","s":"The rescue team's undelayed response saved three hikers stranded on the icy mountain path.","p":"un-dih-LAYD","o":"Latin","y":8,"bp":28,"sy":"un.de.layed","ps":"adjective","t":["time","olatin"]},{"w":"undelayedly","d":"Without any delay or postponement; in a prompt and immediate manner without any pause or interruption in time.","s":"The principal undelayedly announced the school closing, giving families plenty of time to make plans.","p":"un-dih-LAYD-lee","o":"Latin","y":8,"bp":37,"sy":"un.de.layed.ly","ps":"adverb","t":["time","olatin"]},{"w":"undelaying","d":"Not causing or involving any delay; acting or proceeding promptly and without hesitation or postponement of any kind.","s":"The undelaying crew worked through the night to finish setting up the stage before dawn.","p":"un-dih-LAY-ing","o":"Latin","y":8,"bp":30,"sy":"un.de.lay.ing","ps":"adjective","t":["olatin"]},{"w":"undelegated","d":"Not assigned or handed over to another person or group; describing a task or authority that was never transferred or entrusted to someone else.","s":"The undelegated tasks piled up on the manager's desk because she refused to share the workload.","p":"un-DEL-ih-gay-tid","o":"Latin","y":8,"bp":38,"sy":"un.del.e.gat.ed","ps":"adjective","t":["poetry","olatin"]},{"w":"undelete","d":"To restore or recover something that was previously deleted, especially a computer file or piece of data, returning it to its prior state.","s":"Luckily, she was able to undelete the report from the recycling bin just minutes after erasing it.","p":"un-dih-LEET","o":"Latin","y":7,"bp":25,"sy":"un.delete","ps":"verb","t":["olatin"]},{"w":"undeletion","d":"The act or process of restoring something that was previously deleted; the recovery of erased data, text, or files back to their original state.","s":"The tech support team performed an undeletion to recover the accidentally erased project files.","p":"un-dih-LEE-shun","o":"Latin","y":8,"bp":29,"sy":"un.dele.tion","ps":"noun","t":["olatin"]},{"w":"undelight","d":"The absence of delight or pleasure; a state or feeling of disappointment, dissatisfaction, or the complete lack of joy.","s":"The stale sandwiches and broken chairs filled the guests with undelight at the so-called celebration.","p":"un-dih-LYT","o":"Latin","y":8,"bp":28,"sy":"un.de.light","ps":"noun","t":["emotions","olatin"]},{"w":"undelighted","d":"Not experiencing or expressing delight or joy; feeling no pleasure or enthusiasm in response to something that might otherwise be enjoyable.","s":"The critic was clearly undelighted by the film, giving it only one star in her review.","p":"un-dih-LYT-id","o":"Latin","y":8,"bp":37,"sy":"un.de.light.ed","ps":"adjective","t":["emotions","olatin"]},{"w":"undelightful","d":"Not pleasant, enjoyable, or charming; lacking the qualities that would make something delightful or a source of happiness.","s":"The rainy, muddy camping trip turned out to be completely undelightful for the frustrated group.","p":"un-dih-LYT-ful","o":"Latin","y":8,"bp":38,"sy":"un.de.light.ful","ps":"adjective","t":["emotions","olatin"]},{"w":"undelimitated","d":"Not marked off, bounded, or separated by clear limits or borders; lacking any defined boundaries or divisions between areas or concepts.","s":"The artist's creativity felt undelimitated, as though no boundary could contain her imagination.","p":"un-dih-LIM-ih-tay-tid","o":"Latin","y":9,"bp":29,"sy":"un.de.lim.i.tat.ed","ps":"adjective","t":["numbers","olatin"]},{"w":"undelimited","d":"Not restricted by or divided into clear boundaries or limits; describing a space, concept, or area that has no defined edges or borders.","s":"The undelimited territory on the old map confused explorers who couldn't tell where one region ended.","p":"un-dih-LIM-ih-tid","o":"Latin","y":8,"bp":38,"sy":"un.de.lim.it.ed","ps":"adjective","t":["numbers","olatin"]},{"w":"undelivered","d":"Not having been delivered or brought to the intended recipient; said of a message, package, or speech that was never received.","s":"The stack of undelivered packages sat in the warehouse because the driver's truck had broken down.","p":"uh-ndih-LIH-ver-d","o":"Latin","y":6,"bp":37,"sy":"ah.ndih.lih.ver.d","ps":"adjective","t":["olatin"]},{"w":"undemeaned","d":"Not having been humiliated, degraded, or treated in a way that lowers one's dignity or self-respect.","s":"The athlete left the competition undemeaned, carrying herself with dignity despite finishing last.","p":"un-dih-MEEND","o":"Latin","y":8,"bp":29,"sy":"un.de.meaned","ps":"adjective","t":["olatin"]},{"w":"undemeaning","d":"Not causing humiliation or loss of dignity; respectful and uplifting in tone or manner.","s":"Her undemeaning criticism helped the students improve their writing without damaging their confidence.","p":"un-dih-MEE-ning","o":"Latin","y":8,"bp":37,"sy":"un.de.mean.ing","ps":"adjective","t":["olatin"]},{"w":"undemented","d":"Not affected by dementia or extreme mental confusion; retaining a clear and sound mind.","s":"Despite the chaos around her, the elderly professor remained calm and completely undemented in her thinking.","p":"un-dih-MEN-tid","o":"Latin","y":8,"bp":30,"sy":"un.de.ment.ed","ps":"adjective","t":["disease","olatin"]},{"w":"undemocratisation","d":"The process or condition of reversing or eliminating democratic structures, rights, or practices within a government or organization.","s":"Scholars worried that the new laws represented an undemocratisation of the country's election process.","p":"un-dem-oh-krat-ih-ZAY-shun","o":"Latin","y":9,"bp":29,"sy":"un.democrati.sa.tion","ps":"noun","t":["politics","olatin"]},{"w":"undemocratise","d":"To reverse or remove democratic principles, processes, or institutions from a system or government.","s":"Critics feared that the new ruler's policies would undemocratise a nation that had voted freely for generations.","p":"un-dih-MOK-ruh-tize","o":"Latin","y":9,"bp":25,"sy":"un.democra.tise","ps":"verb","t":["politics","logic","olatin"]},{"w":"undemocratizable","d":"Impossible to make democratic; describing a system or society that cannot be converted to democratic governance.","s":"Some historians argue that certain ancient systems were so rigid they were essentially undemocratizable.","p":"un-dih-MOK-ruh-tye-zuh-bul","o":"Latin","y":9,"bp":33,"sy":"un.de.moc.ra.ti.z.able","ps":"adjective","t":["politics","olatin"]},{"w":"undemonic","d":"Not demonic, evil, or fiendish in nature; free from any association with malevolent or supernatural wickedness.","s":"The playful puppy had an undemonic energy that made every visitor instantly feel at ease.","p":"un-dih-MON-ik","o":"Latin","y":8,"bp":29,"sy":"un.de.mon.ic","ps":"adjective","t":["olatin"]},{"w":"undemoted","d":"Not having been reduced in rank, status, or position; remaining at one's current or original level.","s":"Despite the company's restructuring, the loyal supervisor remained undemoted and kept her original title.","p":"un-dih-MOH-tid","o":"Latin","y":8,"bp":29,"sy":"un.de.mot.ed","ps":"adjective","t":["olatin"]},{"w":"undeniableness","d":"The quality or state of being impossible to deny, dispute, or contradict; absolute certainty or obviousness.","s":"The undeniableness of the scientific evidence convinced even the most stubborn skeptics in the room.","p":"un-dih-NYE-uh-bul-nes","o":"Latin","y":9,"bp":29,"sy":"un.de.ni.able.ness","ps":"noun","t":["olatin"]},{"w":"undenominational","d":"not bound or devoted to the promotion of a particular denomination","p":"un-dih-nom-ih-NAY-shun-ul","o":"Latin","y":9,"bp":33,"sy":"un.de.nom.i.na.tion.al","ps":"adjective","t":["olatin"]},{"w":"undensitized","d":"Not subjected to a process that alters or measures density; lacking treatment designed to change material density.","s":"The undensitized film was still sensitive to light and had to be kept in a dark container.","p":"un-DEN-sih-tyzd","o":"Latin","y":8,"bp":38,"sy":"un.den.si.tized","ps":"adjective","t":["numbers","olatin"]},{"w":"undentable","d":"Impossible to dent or make an impression upon; so strong or resilient that no dent can be formed.","s":"The new car's undentable bumper held up perfectly after a minor collision in the parking lot.","p":"un-DENT-uh-bul","o":"Latin","y":9,"bp":27,"sy":"un.dentable","ps":"adjective","t":["olatin"]},{"w":"undented","d":"Not having been dented or marked with a depression; remaining smooth and undamaged in surface.","s":"After the crash, it was amazing that the car's door remained completely undented.","p":"un-DEN-tid","o":"Latin","y":8,"bp":27,"sy":"un.dent.ed","ps":"adjective","t":["olatin"]},{"w":"undeodorized","d":"Not treated with a deodorizing agent; retaining natural or original odors without chemical alteration.","s":"The undeodorized gym locker smelled strongly after a week of use.","p":"un-dee-OH-duh-ryzd","o":"Latin","y":8,"bp":36,"sy":"un.deodor.ized","ps":"adjective","t":["chemistry","olatin"]},{"w":"undepartmentalized","d":"Not divided or organized into separate departments; operating as a unified whole without distinct departmental divisions.","s":"The small startup remained undepartmentalized, with everyone pitching in on every task.","p":"un-dih-part-MEN-tuh-lyzd","o":"Latin","y":9,"bp":32,"sy":"un.de.part.men.tal.ized","ps":"adjective","t":["numbers","olatin"]},{"w":"undepictable","d":"Impossible to portray, illustrate, or represent in any visual or descriptive medium.","s":"The horror of the disaster was so extreme it seemed completely undepictable in words.","p":"un-dih-PIK-tuh-bul","o":"Latin","y":9,"bp":36,"sy":"un.de.pictable","ps":"adjective","t":["olatin"]},{"w":"undepicted","d":"not pictured","s":"Many everyday heroes of the war remained undepicted in paintings or photographs.","p":"un-dih-PIK-tid","o":"Latin","y":8,"bp":30,"sy":"un.de.pict.ed","ps":"adjective","t":["olatin"]},{"w":"undepletable","d":"Impossible to use up, exhaust, or reduce; describing a resource or supply that cannot be depleted.","s":"Scientists dream of finding an undepletable energy source that never runs out.","p":"un-dih-PLEE-tuh-bul","o":"Latin","y":9,"bp":36,"sy":"un.de.pletable","ps":"adjective","t":["olatin"]},{"w":"undeployable","d":"Not able to be sent out, positioned, or put into active use; describing personnel or equipment that cannot be deployed.","s":"The broken machinery was deemed undeployable until it could be fully repaired.","p":"un-dih-PLOY-uh-bul","o":"Latin","y":9,"bp":38,"sy":"un.de.ploy.able","ps":"adjective","t":["olatin"]},{"w":"undeployed","d":"Not yet sent out or put into active service; describing soldiers, resources, or equipment held back from use.","s":"Several rescue drones sat undeployed in storage throughout the quiet summer.","p":"un-dih-PLOID","o":"Latin","y":8,"bp":29,"sy":"un.de.ployed","ps":"adjective","t":["war","olatin"]},{"w":"undeposited","d":"Not having been placed into a bank account or other storage; describing a check, cash, or item that was never deposited.","s":"The undeposited checks piled up on the accountant's desk for weeks.","p":"un-dih-POZ-ih-tid","o":"Latin","y":8,"bp":37,"sy":"un.de.posit.ed","ps":"adjective","t":["economy","olatin"]},{"w":"underagent","d":"A subordinate agent who operates under the authority or supervision of a higher-ranking agent.","s":"The underagent relayed messages to the senior spy without ever meeting the target.","p":"UN-der-ay-jent","o":"Latin","y":8,"bp":30,"sy":"un.der.a.gent","ps":"noun","t":["poetry","olatin"]},{"w":"underanged","d":"Arranged or organized at a level below what is sufficient or appropriate; inadequately arranged or ordered.","s":"The underanged schedule left students confused, with too many overlapping classes and not enough time between sessions to prepare for the next activity.","p":"un-der-AYNJD","o":"Latin","y":8,"bp":26,"ps":"adjective","t":["olatin"]},{"w":"underapproximate","d":"To make an estimate or approximation that is lower than the actual or correct value.","s":"Scientists warned that their models might underapproximate the true scale of the storm.","p":"un-der-uh-PROK-sih-mayt","o":"Latin","y":9,"bp":32,"sy":"un.der.ap.prox.i.mate","ps":"verb","t":["olatin"]},{"w":"undercalculate","d":"To calculate a quantity or amount as less than it actually is; to underestimate through mathematical error or insufficient data.","s":"If you undercalculate the ingredients, your recipe will not turn out correctly.","p":"un-der-KAL-kyoo-layt","o":"Latin","y":9,"bp":29,"sy":"un.der.cal.cu.late","ps":"verb","t":["numbers","olatin"]},{"w":"undercapitalization","d":"The condition of having insufficient financial capital to operate or grow effectively; a lack of funding needed to sustain a business.","s":"The restaurant failed within a year due to severe undercapitalization and mounting debt.","p":"un-der-kap-ih-tul-ih-ZAY-shun","o":"Latin","y":9,"bp":33,"sy":"un.der.cap.i.tal.iza.tion","ps":"noun","t":["olatin"]},{"w":"undercapitalize","d":"To provide a business or project with less financial capital than is needed for successful operation or growth.","s":"Investors warned the founder not to undercapitalize the business at its launch.","p":"uh-nder-KA-puh-tuh-leye-z","o":"Latin","y":9,"bp":31,"sy":"ah.nder.kae.pah.tah.lay.z","ps":"verb","t":["olatin"]},{"w":"underconfidence","d":"A state of having less confidence than a situation warrants; insufficient belief in one's own abilities or judgment.","s":"Her underconfidence kept her from raising her hand even when she knew the right answer.","p":"un-der-KON-fih-dens","o":"Latin","y":9,"bp":30,"sy":"un.der.con.fi.dence","ps":"noun","t":["logic","olatin"]},{"w":"underconfident","d":"Lacking sufficient confidence in oneself or one's abilities; displaying less self-assurance than is appropriate or warranted.","s":"The underconfident player rarely took shots even when he had a clear opportunity.","p":"un-der-KON-fih-dent","o":"Latin","y":9,"bp":29,"sy":"un.der.con.fi.dent","ps":"adjective","t":["olatin"]},{"w":"undercoordination","d":"An insufficient level of coordination between people, departments, or systems, leading to inefficiency or confusion.","s":"The project failed because of undercoordination between the two teams working on it.","p":"un-der-koh-or-dih-NAY-shun","o":"Latin","y":9,"bp":33,"sy":"un.der.co.or.di.na.tion","ps":"noun","t":["olatin"]},{"w":"underdense","d":"Having a density lower than a standard, expected, or required level; less densely packed or concentrated than normal.","s":"The underdense fog near the coast allowed drivers to see just enough to drive safely.","p":"un-der-DENS","o":"Latin","y":9,"bp":29,"sy":"un.der.dense","ps":"adjective","t":["olatin"]},{"w":"underdiagnosis","d":"The condition of a disease or disorder being diagnosed less frequently than it actually occurs in a population.","s":"Experts believe the underdiagnosis of the illness left thousands without proper treatment.","p":"un-der-dye-ug-NOH-sis","o":"Latin","y":9,"bp":29,"sy":"un.der.diag.no.sis","ps":"noun","t":["body","disease","olatin"]},{"w":"underenforcement","d":"The failure to enforce laws, rules, or regulations as strictly or thoroughly as required or intended.","s":"Underenforcement of the speed limit led to dangerous driving on that busy street.","p":"un-der-en-FORS-ment","o":"Latin","y":9,"bp":30,"sy":"un.der.en.force.ment","ps":"noun","t":["law","olatin"]},{"w":"underexaggerate","d":"To describe or represent something as less significant or extreme than it actually is; to exaggerate in the direction of understatement.","s":"He tends to underexaggerate his achievements, making himself sound far less impressive than he is.","p":"un-der-eg-ZAJ-er-ayt","o":"Latin","y":9,"bp":31,"sy":"un.der.ex.ag.ger.ate","ps":"verb","t":["olatin"]},{"w":"underexercise","d":"To exercise less than the amount necessary for good health or proper physical development.","s":"Many teenagers underexercise because they spend most of their free time on screens.","p":"un-der-EK-ser-syz","o":"Latin","y":9,"bp":28,"sy":"un.der.ex.er.cise","ps":"verb","t":["olatin"]},{"w":"underided","d":"not mocked, teased, or laughed at","s":"Her unusual hobby went underided because her classmates were genuinely curious about it.","p":"un-der-EYE-did","o":"Latin","y":8,"bp":29,"sy":"un.der.id.ed","ps":"adjective","t":["olatin"]},{"w":"underinflate","d":"To inflate something, such as a tire or balloon, to a pressure lower than the recommended or required level.","s":"If you underinflate your bike tires, riding becomes much harder and less safe.","p":"un-der-in-FLAYT","o":"Latin","y":9,"bp":38,"sy":"un.der.in.flate","ps":"verb","t":["olatin"]},{"w":"underinformed","d":"Not having enough information or knowledge about a subject; lacking the full facts needed to make a good decision.","s":"Voters who are underinformed about candidates often make choices they later regret.","p":"un-der-in-FORMD","o":"Latin","y":9,"bp":26,"sy":"un.der.in.formed","ps":"adjective","t":["logic","olatin"]},{"w":"underinsulate","d":"To provide less insulation than is necessary to properly retain heat or prevent energy loss in a structure.","s":"If you underinsulate your attic, you will lose heat all winter long.","p":"un-der-IN-syoo-layt","o":"Latin","y":9,"bp":28,"sy":"un.der.in.su.late","ps":"verb","t":["physics","olatin"]},{"w":"underivative","d":"not derivative or imitative","s":"A natural underivative poet.","p":"un-deh-RIV-uh-tiv","o":"Latin","y":9,"bp":38,"sy":"un.der.iva.tive","ps":"adjective","t":["olatin"]},{"w":"underivatized","d":"Not having undergone a chemical derivatization process; remaining in its original, unmodified chemical form.","s":"The chemical compound remained underivatized, preserving its original molecular structure for study.","p":"un-deh-RIV-uh-tyzd","o":"Latin","y":9,"bp":26,"sy":"un.der.iva.tized","ps":"adjective","t":["chemistry","olatin"]},{"w":"underived","d":"not derived; primary or simple","s":"The linguist studied underived words that formed the roots of an entire language family.","p":"un-deh-RYVD","o":"Latin","y":8,"bp":28,"sy":"un.der.ived","ps":"adjective","t":["olatin"]},{"w":"underlayment","d":"a pad placed under a carpet","s":"The workers laid foam underlayment beneath the hardwood floor to reduce noise.","p":"un-der-LAY-ment","o":"Latin","y":7,"bp":38,"sy":"un.der.lay.ment","ps":"noun","t":["household","olatin"]},{"w":"underluminous","d":"Producing or emitting less light than is needed or expected for a given purpose or situation.","s":"The underluminous hallway made it difficult to read the room numbers on the doors.","p":"un-der-LOO-mih-nus","o":"Latin","y":9,"bp":28,"sy":"un.der.lu.mi.nous","ps":"adjective","t":["olatin"]},{"w":"underogatory","d":"Not derogatory or disrespectful; free from any language or tone that belittles or demeans others.","s":"His underogatory remarks were surprisingly kind, lacking the insults everyone had expected.","p":"un-deh-ROG-uh-tor-ee","o":"Latin","y":8,"bp":39,"sy":"un.der.oga.to.ry","ps":"adjective","t":["wordwords","olatin"]},{"w":"underplant","d":"To plant smaller or lower-growing plants beneath taller plants in a garden or landscape setting.","s":"Gardeners often underplant tall trees with shade-loving flowers like hostas and ferns.","p":"un-der-PLANT","o":"Latin","y":8,"bp":29,"sy":"un.der.plant","ps":"verb","t":["botany","olatin"]},{"w":"underpopulation","d":"A condition in which a region or area has too few people to sustain its economy, infrastructure, or social systems effectively.","s":"The remote island suffered from underpopulation, making it hard to keep the school open.","p":"un-der-pop-yoo-LAY-shun","o":"Latin","y":9,"bp":31,"sy":"un.der.pop.u.la.tion","ps":"noun","t":["economy","olatin"]},{"w":"underprescribe","d":"to prescribe a smaller dose or amount of a medicine than a patient actually needs","s":"Doctors are careful not to underprescribe a medicine, since too small a dose will not work.","p":"un-der-preh-SKRYB","o":"Latin","y":9,"bp":27,"sy":"un.der.pre.scribe","ps":"verb","t":["body","pharmacy","olatin"]},{"w":"underproduce","d":"produce below capacity or demand","p":"un-der-pruh-DOOS","o":"Latin","y":9,"bp":38,"sy":"un.der.pro.duce","ps":"verb","t":["olatin"]},{"w":"underpromote","d":"To advertise, publicize, or advance something or someone with less effort or resources than are needed to achieve adequate recognition or success.","s":"The studio chose to underpromote the film, and it barely made any money opening weekend.","p":"un-der-pruh-MOHT","o":"Latin","y":9,"bp":38,"sy":"un.der.pro.mote","ps":"verb","t":["olatin"]},{"w":"underrecognize","d":"To give insufficient acknowledgment or credit to a person, group, or achievement that deserves greater recognition.","s":"Teachers often underrecognize students who work hard quietly without seeking praise.","p":"un-der-REK-og-nyz","o":"Latin","y":9,"bp":29,"sy":"un.der.rec.og.nize","ps":"verb","t":["olatin"]},{"w":"underregulate","d":"To apply fewer rules, restrictions, or oversight to an industry or activity than is necessary to protect the public or ensure fair practices.","s":"Critics argued that the government chose to underregulate the food industry, risking public health.","p":"un-der-REG-yoo-layt","o":"Latin","y":9,"bp":28,"sy":"un.der.reg.u.late","ps":"verb","t":["olatin"]},{"w":"underrotate","d":"To fail to complete a full rotation or turn, especially in skating, gymnastics, or diving, stopping short of the required degree of spin.","s":"The gymnast would underrotate her back flip and land short of completing the full spin.","p":"un-der-ROH-tayt","o":"Latin","y":9,"bp":37,"sy":"un.der.ro.tate","ps":"verb","t":["sports","olatin"]},{"w":"undersee","d":"To perceive or understand less than the full scope of a situation; to fail to observe or grasp what is truly happening.","s":"A manager who undersees their team may miss important problems brewing beneath the surface.","p":"un-der-SEE","o":"Latin","y":9,"bp":27,"sy":"un.der.see","ps":"verb","t":["olatin"]},{"w":"understimulate","d":"To provide less stimulation, excitement, or challenge than is needed for proper development, engagement, or response.","s":"Teachers worry that easy worksheets will understimulate gifted students and cause them to lose interest.","p":"un-der-STIM-yoo-layt","o":"Latin","y":9,"bp":29,"sy":"un.der.stim.u.late","ps":"verb","t":["olatin"]},{"w":"understratum","d":"A layer of rock, soil, or other material that lies beneath the uppermost or most visible layer; a hidden underlying foundation.","s":"Geologists drilled through the topsoil to study the understratum of ancient rock below.","p":"un-der-STRAY-tum","o":"Latin","y":8,"bp":38,"sy":"un.der.stra.tum","ps":"noun","t":["minerals","olatin"]},{"w":"undertreatment","d":"The condition of receiving less medical care, therapy, or intervention than a patient's illness or condition actually requires.","s":"The doctor warned that undertreatment of the infection could allow bacteria to spread rapidly.","p":"un-der-TREET-ment","o":"Latin","y":9,"bp":27,"sy":"un.der.treat.ment","ps":"noun","t":["body","disease","olatin"]},{"w":"undervote","d":"To cast a ballot on which fewer choices are marked than are permitted, or to record fewer votes than the total number expected in an election.","s":"Researchers noticed an undervote on the ballot measure, meaning many voters skipped that question entirely.","p":"un-der-VOHT","o":"Latin","y":9,"bp":28,"sy":"un.der.vote","ps":"verb","t":["politics","numbers","olatin"]},{"w":"undescaled","d":"Not having had scales, mineral deposits, or encrusted buildup removed; still coated with its original layer of scale or crust.","s":"The undescaled kettle was coated inside with a thick crust of mineral deposits.","p":"un-deh-SKAYLD","o":"Latin","y":8,"bp":27,"sy":"un.descaled","ps":"adjective","t":["minerals","olatin"]},{"w":"undescried","d":"Not spotted, observed, or discovered; remaining unseen or unnoticed by anyone looking.","s":"The tiny island remained undescried by sailors for centuries because it lay hidden in thick fog.","p":"un-deh-SKRYD","o":"Latin","y":8,"bp":29,"sy":"un.de.scried","ps":"adjective","t":["olatin"]},{"w":"undesecrate","d":"To restore the sacred or respected status of something that had been profaned or violated; to reverse an act of desecration.","s":"The priest worked to undesecrate the old chapel by blessing its walls and restoring its sacred objects.","p":"un-DES-eh-krayt","o":"Latin","y":9,"bp":37,"sy":"un.des.e.crate","ps":"verb","t":["religion","olatin"]},{"w":"undesecrated","d":"Not having been defiled, violated, or treated with disrespect; remaining in a pure, sacred, or untouched condition.","s":"Remarkably, the ancient tomb was found undesecrated, its treasures completely untouched.","p":"un-DES-eh-krayt-ed","o":"Latin","y":8,"bp":39,"sy":"un.des.e.crat.ed","ps":"adjective","t":["religion","olatin"]},{"w":"undesigned","d":"not done or made or performed with purpose or intent","s":"The funny photo was completely undesigned — a happy accident captured at just the right moment.","p":"un-deh-ZYND","o":"Latin","y":7,"bp":29,"sy":"un.de.signed","ps":"adjective","t":["olatin"]},{"w":"undesignedly","d":"In a manner that is not intentional or planned; happening by accident or chance rather than by deliberate design.","s":"She undesignedly bumped into her old friend at the bookstore, and they ended up talking for hours.","p":"un-deh-ZYN-ed-lee","o":"Latin","y":8,"bp":38,"sy":"un.de.signed.ly","ps":"adverb","t":["olatin"]},{"w":"undesignedness","d":"The quality or state of being without intention, plan, or deliberate purpose; the condition of happening purely by chance.","s":"The painting's charm came from its undesignedness — every brushstroke looked free and spontaneous.","p":"un-deh-ZYN-ed-nes","o":"Latin","y":9,"bp":27,"sy":"un.de.signed.ness","ps":"noun","t":["olatin"]},{"w":"undesigning","d":"Not scheming, crafty, or deceptive; honest and straightforward in one's motives and actions without hidden agendas.","s":"Her undesigning nature meant she never tried to trick or manipulate anyone around her.","p":"un-deh-ZY-ning","o":"Latin","y":8,"bp":37,"sy":"un.de.sign.ing","ps":"adjective","t":["olatin"]},{"w":"undespairing","d":"Not giving in to despair or hopelessness; maintaining hope and a positive outlook even in difficult circumstances.","s":"Even after losing the championship, the team remained undespairing and vowed to train harder.","p":"un-deh-SPAIR-ing","o":"Latin","y":9,"bp":38,"sy":"un.de.spair.ing","ps":"adjective","t":["emotions","olatin"]},{"w":"undespairingly","d":"In a manner that shows no despair or loss of hope; continuing forward with confidence and optimism despite hardship.","s":"She undespairingly continued her research even after three experiments failed in a row.","p":"un-deh-SPAIR-ing-lee","o":"Latin","y":9,"bp":29,"sy":"un.de.spair.ing.ly","ps":"adverb","t":["emotions","olatin"]},{"w":"undesponding","d":"Not yielding to despondency or low spirits; remaining hopeful, cheerful, or determined in the face of difficulties.","s":"The undesponding explorer kept mapping the forest even when supplies ran low.","p":"un-deh-SPOND-ing","o":"Latin","y":8,"bp":38,"sy":"un.de.spond.ing","ps":"adjective","t":["olatin"]},{"w":"undespotic","d":"Not characteristic of a despot; not exercising absolute, harsh, or tyrannical power over others.","s":"The undespotic leader held open town meetings and always listened to citizens' concerns.","p":"un-deh-SPOT-ik","o":"Latin","y":8,"bp":29,"sy":"un.despot.ic","ps":"adjective","t":["olatin"]},{"w":"undestroyable","d":"impossible to wreck, ruin, or break apart","p":"un-deh-STROY-uh-bul","o":"Latin","y":9,"bp":26,"sy":"un.de.stroy.able","ps":"adjective","t":["olatin"]},{"w":"undestroyed","d":"Not having been ruined, demolished, or eliminated; remaining intact and whole despite forces or events that might have caused destruction.","s":"After the earthquake, only one bridge remained undestroyed and open for emergency vehicles.","p":"un-deh-STROYD","o":"Latin","y":8,"bp":35,"sy":"un.de.stroyed","ps":"adjective","t":["physics","olatin"]},{"w":"undetachable","d":"Impossible to separate, remove, or disconnect from something; permanently fixed or joined so that it cannot be taken apart.","s":"The safety latch was undetachable without a special key, keeping the cabinet locked tight.","p":"un-deh-TACH-uh-bul","o":"Latin","y":9,"bp":38,"sy":"un.de.tach.able","ps":"adjective","t":["olatin"]},{"w":"undetached","d":"Not separated or disconnected; still joined or connected to something else rather than standing apart on its own.","s":"The garage remained undetached from the house even after the renovation added a new wing.","p":"un-deh-TACHT","o":"Latin","y":9,"bp":29,"sy":"un.de.tached","ps":"adjective","t":["olatin"]},{"w":"undetailed","d":"Lacking specific details, particulars, or fine points; vague or general rather than thorough and precise.","s":"The student's essay was criticized for being undetailed and lacking specific examples to support its claims.","p":"un-deh-TAYLD","o":"Latin","y":9,"bp":29,"sy":"un.de.tailed","ps":"adjective","t":["olatin"]},{"w":"undetectably","d":"In a way that cannot be noticed, found, or identified by any means of observation or measurement.","s":"The spy moved undetectably through the shadows, leaving no trace of her presence.","p":"un-deh-TEK-tuh-blee","o":"Latin","y":8,"bp":36,"sy":"un.de.tectably","ps":"adverb","t":["numbers","olatin"]},{"w":"undeteriorated","d":"Not having declined in quality, condition, or value; remaining as good as its original state without any decay or worsening.","s":"Surprisingly, the ancient scroll was undeteriorated after two thousand years sealed in a clay jar.","p":"un-deh-teer-ee-OR-ay-ted","o":"Latin","y":9,"bp":32,"sy":"un.de.te.ri.o.rat.ed","ps":"adjective","t":["olatin"]},{"w":"undeterminacy","d":"The state or quality of being uncertain, indefinite, or without a fixed or clearly established outcome or answer.","s":"The scientist was troubled by the undeterminacy of her data, since the results could be interpreted in multiple ways.","p":"un-deh-TER-mih-nuh-see","o":"Latin","y":9,"bp":29,"sy":"un.de.ter.mi.na.cy","ps":"noun","t":["olatin"]},{"w":"undetested","d":"Not hated or strongly disliked; regarded without feelings of loathing or disgust.","s":"She was one of the few politicians in town who was genuinely undetested by people from both parties.","p":"un-deh-TES-ted","o":"Latin","y":8,"bp":30,"sy":"un.de.test.ed","ps":"adjective","t":["olatin"]},{"w":"undetonated","d":"Not yet exploded or set off; describes a device such as a bomb that has failed to or has not been triggered to detonate.","s":"The bomb squad carefully removed the undetonated device before it could cause any harm.","p":"un-DET-oh-nay-ted","o":"Latin","y":7,"bp":38,"sy":"un.det.o.nat.ed","ps":"adjective","t":["tools","olatin"]},{"w":"undevelopable","d":"Not capable of being developed, built upon, or improved; describes land or potential that cannot be turned into something more advanced or useful.","s":"The marshy land was declared undevelopable because buildings would sink into the soft, wet ground.","p":"un-deh-VEL-oh-puh-bul","o":"Latin","y":9,"bp":26,"sy":"un.de.vel.opable","ps":"adjective","t":["olatin"]},{"w":"undevil","d":"To free or remove from the influence or possession of a devil; to rid of evil or devilish qualities.","s":"The old story told of a ritual used to undevil a person who had been cursed by dark magic.","p":"un-DEV-ul","o":"Latin","y":8,"bp":20,"sy":"un.dev.il","ps":"verb","t":["olatin"]},{"w":"undevised","d":"Not planned, invented, or schemed; describes something that was never thought up or arranged through deliberate effort.","s":"The solution seemed undevised by any human mind, as if it had appeared out of thin air.","p":"un-deh-VYZD","o":"Latin","y":8,"bp":28,"sy":"un.de.vised","ps":"adjective","t":["olatin"]},{"w":"undevitrified","d":"Not converted from a glassy state back into a crystalline structure; still remaining in its original glass-like form without having undergone devitrification.","s":"The ancient glass remained undevitrified, keeping its smooth, clear glassy structure after centuries underground.","p":"un-deh-VIT-rih-fyde","o":"Latin","y":9,"bp":28,"sy":"un.de.vit.ri.fied","ps":"adjective","t":["chemistry","minerals","olatin"]},{"w":"undevolved","d":"Not transferred or passed down to a lower level of authority or to a successor; remaining with the original holder.","s":"The power remained undevolved from the central government, leaving local towns with little control.","p":"un-deh-VOLVD","o":"Latin","y":8,"bp":29,"sy":"un.de.volved","ps":"adjective","t":["poetry","olatin"]},{"w":"undevoted","d":"Lacking dedication, loyalty, or wholehearted commitment to a person, cause, or activity.","s":"An undevoted student rarely completes homework and shows little passion for learning.","p":"un-deh-VOH-ted","o":"Latin","y":8,"bp":29,"sy":"un.de.vot.ed","ps":"adjective","t":["olatin"]},{"w":"undevotion","d":"The absence of devotion, dedication, or religious reverence; a state of being without sincere commitment or piety.","s":"The coach was disappointed by the undevotion some players showed during early morning practices.","p":"un-deh-VOH-shun","o":"Latin","y":8,"bp":30,"sy":"un.de.vo.tion","ps":"noun","t":["religion","olatin"]},{"w":"undevoured","d":"Not eaten up or consumed; still intact and untouched by any creature or force that would devour it.","s":"The undevoured sandwich sat on the plate as the child insisted she wasn't hungry.","p":"un-deh-VOWRD","o":"Latin","y":9,"bp":29,"sy":"un.de.voured","ps":"adjective","t":["physics","olatin"]},{"w":"undevout","d":"Not devout; lacking sincerity or fervor in religious belief or spiritual practice.","s":"The undevout villager rarely visited the temple and spent his Sundays fishing instead.","p":"un-deh-VOWT","o":"Latin","y":9,"bp":27,"sy":"un.de.vout","ps":"adjective","t":["religion","logic","olatin"]},{"w":"undevoutness","d":"The quality or state of being undevout; a lack of religious sincerity, reverence, or spiritual dedication.","s":"Her undevoutness surprised the congregation, since her parents had been deeply religious their whole lives.","p":"un-deh-VOWT-nes","o":"Latin","y":9,"bp":38,"sy":"un.de.vout.ness","ps":"noun","t":["religion","olatin"]},{"w":"undialable","d":"Not capable of being dialed; describes a phone number or device that cannot be reached or activated by dialing.","s":"The old rotary phone became completely undialable once its dial mechanism jammed and refused to turn.","p":"un-DY-ul-uh-bul","o":"Latin","y":9,"bp":30,"sy":"un.di.al.able","ps":"adjective","t":["tools","numbers","olatin"]},{"w":"undialed","d":"Not having been dialed; describes a phone number or rotary mechanism that was never activated or called.","s":"The undialed phone sat on the desk, and no one had yet made a single call.","p":"un-DY-uld","o":"Latin","y":8,"bp":27,"sy":"un.di.aled","ps":"adjective","t":["tools","numbers","olatin"]},{"w":"undiapered","d":"Not wearing or fitted with a diaper; describes an infant or object without a diaper in place.","s":"The undiapered baby crawled across the changing mat while Mom grabbed a fresh one.","p":"un-DY-uh-perd","o":"Latin","y":8,"bp":30,"sy":"un.di.a.pered","ps":"adjective","t":["olatin"]},{"w":"undictatorial","d":"Not characteristic of a dictator; free from authoritarian control, domineering behavior, or absolute rule.","s":"The undictatorial coach let the players vote on strategy instead of ordering them around.","p":"un-dik-tuh-TOR-ee-ul","o":"Latin","y":9,"bp":29,"sy":"un.dic.ta.to.ri.al","ps":"adjective","t":["poetry","olatin"]},{"w":"undifferentiable","d":"Not capable of being distinguished or told apart from something else; so similar that no clear distinction can be drawn.","s":"The twins were so alike that their teachers found them completely undifferentiable.","p":"un-dif-uh-REN-shee-uh-bul","o":"Latin","y":9,"bp":30,"sy":"un.dif.fer.en.tiable","ps":"adjective","t":["olatin"]},{"w":"undifferentiating","d":"Not making or showing any distinction between things; treating all elements as though they are the same without recognizing differences.","s":"Her undifferentiating praise meant every student got the same compliment regardless of effort.","p":"un-dif-uh-REN-shee-ay-ting","o":"Latin","y":9,"bp":33,"sy":"un.dif.fer.en.ti.at.ing","ps":"adjective","t":["olatin"]},{"w":"undifferentiation","d":"The state or process of lacking differentiation; a condition in which cells, groups, or ideas have not developed distinct characteristics or specialized roles.","s":"The scientist noted the undifferentiation of the stem cells before they were exposed to the growth factor.","p":"un-dif-uh-ren-shee-AY-shun","o":"Latin","y":9,"bp":33,"sy":"un.dif.fer.en.ti.a.tion","ps":"noun","t":["olatin"]},{"w":"undigestible","d":"Impossible to digest; not capable of being broken down physically or understood mentally.","s":"Certain fibers are undigestible, passing through the body without being broken down.","p":"un-dih-JES-tih-bul","o":"Latin","y":9,"bp":35,"sy":"undi.gestible","ps":"adjective","t":["olatin"]},{"w":"undiggable","d":"Not able to be dug into or excavated; so hard, frozen, or unyielding that no digging is possible.","s":"The frozen ground in January was undiggable, forcing the crew to wait until spring.","p":"un-DIG-uh-bul","o":"Latin","y":9,"bp":27,"sy":"undig.gable","ps":"adjective","t":["olatin"]},{"w":"undight","d":"To undress or strip of equipment or adornment; an archaic term meaning to undo or remove clothing or armor.","s":"The knight returned from battle and began to undight his heavy armor piece by piece.","p":"un-DYT","o":"Latin","y":8,"bp":17,"ps":"verb","t":["war","olatin"]},{"w":"undigital","d":"Not involving or relating to digital technology; analog, non-electronic, or existing outside the realm of digital devices and data.","s":"She preferred the undigital experience of writing letters by hand rather than texting.","p":"un-DIJ-ih-tul","o":"Latin","y":8,"bp":28,"sy":"undig.i.tal","ps":"adjective","t":["physics","tools","olatin"]},{"w":"undignify","d":"To deprive of dignity or respect; to cause someone or something to appear less worthy or honorable.","s":"The comedian was careful never to undignify his guests with mean-spirited jokes.","p":"un-DIG-nih-fy","o":"Latin","y":8,"bp":28,"sy":"undig.ni.fy","ps":"verb","t":["olatin"]},{"w":"undignifying","d":"Causing a loss of dignity or respect; describing an action or situation that strips away honor or self-worth.","s":"Forcing the students to crawl through a mud pit was seen as undignifying by parents.","p":"un-DIG-nih-fy-ing","o":"Latin","y":8,"bp":38,"sy":"undig.ni.fy.ing","ps":"adjective","t":["olatin"]},{"w":"undilated","d":"Not widened or expanded; describes a pupil, opening, or vessel that has not enlarged or stretched beyond its normal size.","s":"The doctor noted that the patient's pupils were undilated even in the dim examination room.","p":"un-DY-lay-ted","o":"Latin","y":8,"bp":28,"sy":"undi.lat.ed","ps":"adjective","t":["seafaring","olatin"]},{"w":"undiligent","d":"Lacking diligence or careful effort; not hardworking or persistent in completing tasks or responsibilities.","s":"An undiligent student who never studies is likely to struggle at exam time.","p":"un-DIL-ih-jent","o":"Latin","y":8,"bp":27,"sy":"undili.gent","ps":"adjective","t":["olatin"]},{"w":"undimensioned","d":"Not given or marked with specific dimensions; lacking stated measurements such as height, width, or depth.","s":"The undimensioned sketch gave no measurements, making it impossible to build from.","p":"un-dih-MEN-shund","o":"Latin","y":9,"bp":25,"sy":"undi.men.sioned","ps":"adjective","t":["numbers","olatin"]},{"w":"undimerized","d":"Not combined or joined as a dimer; describes molecules or units that have remained separate rather than bonding in pairs.","s":"The chemist confirmed the protein remained undimerized after the experiment was complete.","p":"un-DY-mer-yzd","o":"Latin","y":8,"bp":34,"sy":"undimer.ized","ps":"adjective","t":["chemistry","olatin"]},{"w":"undiminishing","d":"Not becoming smaller, weaker, or less intense; remaining constant or full in strength, size, or quality over time.","s":"Her undiminishing enthusiasm for learning inspired everyone in the classroom.","p":"un-dih-MIN-ish-ing","o":"Latin","y":9,"bp":26,"sy":"undi.min.ish.ing","ps":"adjective","t":["time","olatin"]},{"w":"undimmable","d":"Not capable of being dimmed or made less bright; describes a light source whose intensity cannot be reduced.","s":"The LED was undimmable, blazing at full brightness no matter which switch was flipped.","p":"un-DIM-uh-bul","o":"Latin","y":9,"bp":26,"ps":"adjective","t":["olatin"]},{"w":"undimpled","d":"Not having dimples; smooth and without the small indentations that appear on cheeks or other surfaces.","s":"Her undimpled cheeks made her smile look entirely different from her dimpled sister's.","p":"un-DIM-puld","o":"Latin","y":8,"bp":26,"sy":"undim.pled","ps":"adjective","t":["olatin"]},{"w":"undirect","d":"Not direct or straightforward; indirect, roundabout, or lacking a clear and purposeful course.","s":"The coach's undirect approach confused players who needed clear instructions.","p":"un-dih-REKT","o":"Latin","y":8,"bp":25,"sy":"undi.rect","ps":"adjective","t":["olatin"]},{"w":"undirected","d":"aimlessly drifting","s":"The undirected students wandered the library without any research focus or goal.","p":"un-dih-REK-ted","o":"Latin","y":6,"bp":29,"sy":"undi.rect.ed","ps":"adjective","t":["olatin"]},{"w":"undirectedly","d":"In a manner that lacks direction, guidance, or purpose; wandering or proceeding without a clear goal or plan.","s":"He wandered undirectedly through the city streets, enjoying having nowhere to be.","p":"un-dih-REK-ted-lee","o":"Latin","y":8,"bp":38,"sy":"undi.rect.ed.ly","ps":"adverb","t":["sports","olatin"]},{"w":"undisabused","d":"Not corrected of a mistaken belief or false impression; still holding on to an error or misunderstanding that has not been cleared up.","s":"She remained undisabused of the notion that the Earth was flat because no one corrected her.","p":"un-dis-uh-BYOOZD","o":"Latin","y":8,"bp":34,"sy":"undis.abused","ps":"adjective","t":["logic","olatin"]},{"w":"undiscardable","d":"Not able to be thrown away, set aside, or gotten rid of; too essential or irreplaceable to discard.","s":"That family heirloom was undiscardable no matter how much clutter it created.","p":"un-dis-KAR-duh-bul","o":"Latin","y":9,"bp":25,"sy":"undis.card.able","ps":"adjective","t":["olatin"]},{"w":"undiscarded","d":"Not thrown away or set aside; still kept or retained rather than being discarded or disposed of.","s":"The undiscarded drafts piled up on her desk, each one too important to throw away.","p":"un-dis-KAR-ded","o":"Latin","y":8,"bp":35,"sy":"undis.card.ed","ps":"adjective","t":["olatin"]},{"w":"undiscerned","d":"Not noticed, recognized, or perceived; slipping past observation or awareness without being detected or understood.","s":"The tiny flaw in the diamond went undiscerned by all but the most expert jeweler.","p":"un-dis-ERND","o":"Latin","y":8,"bp":34,"sy":"undis.cerned","ps":"adjective","t":["olatin"]},{"w":"undischarged","d":"owed as a debt","s":"The court determined that the undischarged debt of several thousand dollars had been accumulating interest for years, making it nearly impossible for the struggling family to regain financial stability.","p":"un-dis-CHARJD","o":"Latin","y":9,"bp":35,"sy":"undis.charged","ps":"adjective","t":["economy","olatin"]},{"w":"undisclose","d":"To refrain from revealing or making known; to keep secret or hidden from others.","s":"The spy was trained to undisclose any sensitive information even under pressure.","p":"un-dis-KLOHZ","o":"Latin","y":9,"bp":27,"sy":"undis.close","ps":"verb","t":["olatin"]},{"w":"undisclosing","d":"Not revealing or sharing information; keeping details or facts secret and hidden from others.","s":"The undisclosing witness gave only yes or no answers to avoid revealing details.","p":"un-dis-KLOH-zing","o":"Latin","y":8,"bp":36,"sy":"undis.clos.ing","ps":"adjective","t":["olatin"]},{"w":"undiscordant","d":"Not discordant; harmonious, agreeable, or free from conflict or clashing elements.","s":"The choir's undiscordant harmony filled the hall with a beautifully unified sound.","p":"un-dis-KOR-dunt","o":"Latin","y":8,"bp":36,"sy":"undis.cor.dant","ps":"adjective","t":["olatin"]},{"w":"undiscounted","d":"Not reduced in price or value; sold or considered at full original price without any deduction.","s":"The undiscounted price was still on the tag, so she had to ask for the sale rate at the register.","p":"un-dis-KOWN-tid","o":"Latin","y":8,"bp":36,"sy":"undis.count.ed","ps":"adjective","t":["olatin"]},{"w":"undiscouraged","d":"not deterred","p":"un-dis-KUR-ijd","o":"Latin","y":9,"bp":25,"sy":"undis.cour.aged","ps":"adjective","t":["olatin"]},{"w":"undiscussable","d":"Not able to be discussed or talked about openly; too sensitive, forbidden, or awkward to bring up in conversation.","s":"In that household, money was an undiscussable topic that no one dared bring up at dinner.","p":"un-dis-KUS-uh-bul","o":"Latin","y":9,"bp":25,"sy":"undis.cuss.able","ps":"adjective","t":["olatin"]},{"w":"undiseased","d":"Free from disease; healthy and not affected by illness or any pathological condition.","s":"The veterinarian declared the herd completely undiseased after a thorough inspection.","p":"un-dih-ZEEZD","o":"Latin","y":8,"bp":27,"sy":"undis.eased","ps":"adjective","t":["disease","olatin"]},{"w":"undisfigured","d":"Not disfigured; retaining the original, unharmed appearance without damage, scarring, or deformity.","s":"The ancient statue stood undisfigured after centuries, its face still perfectly intact.","p":"un-dis-FIG-yurd","o":"Latin","y":9,"bp":38,"sy":"und.is.fig.ured","ps":"adjective","t":["olatin"]},{"w":"undisguisable","d":"Impossible to disguise, hide, or conceal; too obvious or apparent to be masked by any means.","s":"Her excitement was completely undisguisable; her grin gave her away instantly.","p":"un-dis-GY-zuh-bul","o":"Latin","y":9,"bp":25,"sy":"undis.guis.able","ps":"adjective","t":["olatin"]},{"w":"undislocate","d":"To restore a dislocated joint or part to its proper position; to undo or reverse a dislocation.","s":"The physical therapist worked carefully to undislocate the patient's shoulder joint.","p":"un-dis-LOH-kayt","o":"Latin","y":9,"bp":35,"sy":"undis.lo.cate","ps":"verb","t":["olatin"]},{"w":"undisparaged","d":"Not belittled, criticized, or spoken of disparagingly; regarded without contempt or dismissiveness.","s":"Her creative work went undisparaged by critics, who praised every piece she showed.","p":"un-dis-PAIR-ijd","o":"Latin","y":8,"bp":36,"sy":"undis.par.aged","ps":"adjective","t":["olatin"]},{"w":"undispellable","d":"Impossible to dispel or drive away; so persistent that no force or effort can remove or dissolve it.","s":"The gloom in the haunted house was undispellable, lingering no matter how many lights were turned on.","p":"un-dis-PEL-uh-bul","o":"Latin","y":9,"bp":23,"sy":"undis.pellable","ps":"adjective","t":["physics","olatin"]},{"w":"undispelled","d":"Not driven away or dissolved; still remaining in place and not cleared or removed by any means.","s":"The undispelled rumors about the haunted house continued to frighten the neighborhood children.","p":"un-dis-PELD","o":"Latin","y":9,"bp":34,"sy":"undis.pelled","ps":"adjective","t":["olatin"]},{"w":"undispensable","d":"Not capable of being dispensed, distributed, or done without; that which cannot be given out or excused.","s":"The medicine remained undispensable at the closed pharmacy, leaving patients frustrated.","p":"un-dis-PEN-suh-bul","o":"Latin","y":9,"bp":25,"sy":"undis.pens.able","ps":"adjective","t":["olatin"]},{"w":"undispensed","d":"Not distributed, given out, or administered; still held back and not yet released or issued to recipients.","s":"The undispensed prescriptions piled up on the counter when the pharmacist called in sick.","p":"un-dis-PENST","o":"Latin","y":8,"bp":34,"sy":"undis.pensed","ps":"adjective","t":["olatin"]},{"w":"undisplayable","d":"Not capable of being displayed or shown; impossible to exhibit or present to an audience or viewer.","s":"The damaged painting was undisplayable and had to be stored in the museum's basement.","p":"un-dis-PLAY-uh-bul","o":"Latin","y":9,"bp":23,"sy":"undis.playable","ps":"adjective","t":["olatin"]},{"w":"undisplayed","d":"Not shown, exhibited, or put on display; kept hidden or stored away rather than presented publicly.","s":"The undisplayed trophies sat in boxes in the school's storage room for years.","p":"un-dis-PLAYD","o":"Latin","y":8,"bp":34,"sy":"undis.played","ps":"adjective","t":["olatin"]},{"w":"undisposed","d":"Not dealt with, settled, or gotten rid of; remaining unresolved, unsold, or not assigned to any purpose.","s":"The undisposed waste sat in the lot until the city finally sent a cleanup crew.","p":"un-dis-POHZD","o":"Latin","y":8,"bp":27,"sy":"undis.posed","ps":"adjective","t":["olatin"]},{"w":"undisposedness","d":"The state or quality of being undisposed; the condition of remaining unsettled, undecided, or not inclined toward something.","s":"Her undisposedness to change careers surprised everyone who thought she was ready to move on.","p":"un-dis-POHZD-nes","o":"Latin","y":9,"bp":26,"sy":"undis.posed.ness","ps":"noun","t":["character","olatin"]},{"w":"undisprovable","d":"Impossible to disprove or refute; not capable of being shown to be false or incorrect by any evidence or argument.","s":"The ancient legend was undisprovable because no records from that era survived.","p":"un-dis-PROO-vuh-bul","o":"Latin","y":9,"bp":25,"sy":"undis.prov.able","ps":"adjective","t":["logic","olatin"]},{"w":"undisputable","d":"not open to question; obviously true","s":"The scientist's findings were undisputable, backed by decades of carefully collected data and confirmed by research teams across more than twenty countries around the world.","p":"un-dis-PYOO-tuh-bul","o":"Latin","y":8,"bp":35,"sy":"undis.putable","ps":"adjective","t":["olatin"]},{"w":"undisputatious","d":"Not argumentative or quarrelsome; having a calm, agreeable nature that avoids disputes and controversy.","s":"The undisputatious student accepted the teacher's correction with a quiet nod.","p":"un-dis-pyoo-TAY-shus","o":"Latin","y":9,"bp":27,"sy":"undis.pu.ta.tious","ps":"adjective","t":["logic","olatin"]},{"w":"undisputedly","d":"in an unarguable and undisputed manner","p":"un-dis-PYOO-tid-lee","o":"Latin","y":7,"bp":38,"sy":"undis.put.ed.ly","ps":"adverb","t":["olatin"]},{"w":"undisrupted","d":"Not interrupted, disturbed, or broken up; continuing smoothly and without any interference or disruption.","s":"The ceremony proceeded undisrupted despite the stormy weather outside.","p":"un-dis-RUP-tid","o":"Latin","y":8,"bp":35,"sy":"undis.rupt.ed","ps":"adjective","t":["olatin"]},{"w":"undissembled","d":"Not concealed or disguised; genuine, open, and honest without any pretense or hidden motive.","s":"His undissembled grief at the funeral moved everyone in the room.","p":"un-dih-SEM-buld","o":"Latin","y":9,"bp":36,"sy":"undis.sem.bled","ps":"adjective","t":["olatin"]},{"w":"undissimulated","d":"Not hidden through pretense or simulation; openly and genuinely expressed without any false appearance.","s":"Her undissimulated excitement about the trip made everyone around her smile.","p":"un-dih-SIM-yuh-lay-tid","o":"Latin","y":9,"bp":29,"sy":"undis.sim.u.lat.ed","ps":"adjective","t":["olatin"]},{"w":"undissipated","d":"Not scattered, wasted, or dispersed; remaining concentrated, intact, and not diminished through excess or carelessness.","s":"The undissipated fog clung to the valley all morning, refusing to lift.","p":"un-DIS-uh-pay-tid","o":"Latin","y":9,"bp":38,"sy":"undis.si.pat.ed","ps":"adjective","t":["olatin"]},{"w":"undissuadable","d":"Not capable of being persuaded to give up a plan or belief; impossible to talk out of a course of action.","s":"Once she made up her mind, she was undissuadable, even by her closest friends.","p":"un-dih-SWAY-duh-bul","o":"Latin","y":9,"bp":25,"sy":"undis.suad.able","ps":"adjective","t":["logic","olatin"]},{"w":"undissuaded","d":"Not talked out of a decision or course of action; remaining firm in one's intention despite attempts at persuasion.","s":"Undissuaded by the warnings, the young explorer set off into the dense jungle alone.","p":"un-dih-SWAY-did","o":"Latin","y":9,"bp":35,"sy":"undis.suad.ed","ps":"adjective","t":["olatin"]},{"w":"undistillability","d":"The quality or state of being impossible to purify or concentrate through the process of distillation.","s":"The undistillability of the compound made it impossible to purify using standard equipment.","p":"un-dis-til-uh-BIL-ih-tee","o":"Latin","y":9,"bp":33,"sy":"undis.til.l.a.bil.i.ty","ps":"noun","t":["chemistry","olatin"]},{"w":"undistillable","d":"Not capable of being purified or separated through distillation; impossible to process through heating and condensing.","s":"The mixture was undistillable because its components broke down before reaching boiling point.","p":"un-dis-TIL-uh-bul","o":"Latin","y":9,"bp":26,"sy":"undis.til.l.able","ps":"adjective","t":["chemistry","olatin"]},{"w":"undistinguishable","d":"not capable of being distinguished or differentiated","p":"un-dis-TING-gwish-uh-bul","o":"Latin","y":9,"bp":29,"sy":"undis.tin.guish.able","ps":"adjective","t":["olatin"]},{"w":"undistinguishably","d":"In a manner that cannot be distinguished or told apart; so similarly that no difference can be detected.","s":"The two paint colors blended undistinguishably on the wall, creating a seamless gradient.","p":"un-dis-TING-gwish-uh-blee","o":"Latin","y":9,"bp":29,"sy":"undis.tin.guish.ably","ps":"adverb","t":["olatin"]},{"w":"undistinguishing","d":"Not making or showing distinctions; treating all things or people as alike without noticing important differences.","s":"The undistinguishing crowd applauded every performer equally, regardless of talent.","p":"un-dis-TING-gwish-ing","o":"Latin","y":9,"bp":29,"sy":"undis.tin.guish.ing","ps":"adjective","t":["olatin"]},{"w":"undistractable","d":"Not capable of being distracted or having one's attention pulled away; able to maintain complete focus regardless of interruptions.","s":"The undistractable student kept studying even as her siblings played loudly nearby.","p":"un-dis-TRAK-tuh-bul","o":"Latin","y":9,"bp":24,"sy":"undis.tractable","ps":"adjective","t":["olatin"]},{"w":"undistractible","d":"Unable to be distracted; possessing such strong concentration that outside stimuli cannot break one's focus.","s":"The surgeon was completely undistractible once the operation began.","p":"un-dis-TRAK-tih-bul","o":"Latin","y":9,"bp":24,"sy":"undis.tractible","ps":"adjective","t":["olatin"]},{"w":"undistraught","d":"Not distraught or deeply distressed; calm and composed even in circumstances that would normally cause great anxiety.","s":"Surprisingly undistraught after the loss, the coach calmly planned the next game's strategy.","p":"un-dis-TRAWT","o":"Latin","y":8,"bp":35,"sy":"undis.traught","ps":"adjective","t":["emotions","olatin"]},{"w":"undistressed","d":"Not experiencing distress, anxiety, or suffering; remaining calm, comfortable, and free from worry or hardship.","s":"The undistressed sailor navigated the rough waves with a steady hand and calm expression.","p":"un-dis-TREST","o":"Latin","y":9,"bp":35,"sy":"undis.tressed","ps":"adjective","t":["emotions","olatin"]},{"w":"undivert","d":"To redirect back to the original course or purpose; to undo a diversion and return something to its intended path or function.","s":"The pilot had to undivert the flight back to its original path once the storm cleared.","p":"un-dih-VURT","o":"Latin","y":8,"bp":27,"sy":"un.di.vert","ps":"verb","t":["olatin"]},{"w":"undiverting","d":"Not entertaining or interesting; failing to divert or amuse the mind in any way.","s":"The long, undiverting lecture left most students struggling to stay awake.","p":"un-dih-VERT-ing","o":"Latin","y":8,"bp":37,"sy":"un.di.vert.ing","ps":"adjective","t":["olatin"]},{"w":"undividable","d":"cannot be divided without leaving a remainder","s":"The class argued whether the odd number was undividable into two perfectly equal groups.","p":"un-dih-VY-duh-bul","o":"Latin","y":9,"bp":37,"sy":"un.di.vid.able","ps":"adjective","t":["numbers","olatin"]},{"w":"undividedly","d":"In a complete and whole manner, without being split or divided in attention or loyalty.","s":"She gave her attention undividedly to the injured bird she was nursing back to health.","p":"un-dih-VY-ded-lee","o":"Latin","y":8,"bp":38,"sy":"un.di.vid.ed.ly","ps":"adverb","t":["numbers","olatin"]},{"w":"undividedness","d":"The state or quality of being whole and unified, without any division or separation.","s":"The team's undividedness in their goal was the key to their championship victory.","p":"un-dih-VY-ded-nes","o":"Latin","y":9,"bp":28,"sy":"un.di.vid.ed.ness","ps":"noun","t":["numbers","olatin"]},{"w":"undivined","d":"Not discovered, guessed, or revealed through intuition or supernatural insight.","s":"The undivined purpose of the ancient artifact puzzled archaeologists for decades.","p":"un-dih-VYND","o":"Latin","y":8,"bp":28,"sy":"un.di.vined","ps":"adjective","t":["olatin"]},{"w":"undizzied","d":"Not made dizzy or disoriented; remaining clear-headed and steady despite potential causes of dizziness.","s":"Somehow undizzied after ten spins, the gymnast landed her routine perfectly.","p":"un-DIZ-eed","o":"Latin","y":8,"bp":26,"sy":"un.dizzied","ps":"adjective","t":["olatin"]},{"w":"undoable","d":"impossible to achieve","p":"un-DOO-uh-bul","o":"Latin","y":7,"bp":25,"sy":"un.doable","ps":"adjective","t":["olatin"]},{"w":"undocketed","d":"Not recorded or entered into an official docket, register, or schedule of cases and documents.","s":"The undocketed complaints were lost in the system and never reached the judge.","p":"un-DOK-it-ed","o":"Latin","y":8,"bp":30,"sy":"un.dock.et.ed","ps":"adjective","t":["olatin"]},{"w":"undoctorly","d":"Not befitting or characteristic of a doctor; lacking the professionalism, knowledge, or conduct expected of a physician.","s":"The physician's undoctorly jokes during the checkup made some patients uncomfortable.","p":"un-DOK-ter-lee","o":"Latin","y":8,"bp":30,"sy":"un.doc.tor.ly","ps":"adjective","t":["body","logic","olatin"]},{"w":"undoctrinaire","d":"Not rigidly bound to a particular doctrine or ideology; open-minded and flexible in thinking rather than strictly dogmatic.","s":"The undoctrinaire teacher encouraged students to question every idea, including her own.","p":"un-dok-trih-NAIR","o":"Latin","y":9,"bp":26,"sy":"un.doc.tri.naire","ps":"adjective","t":["logic","olatin"]},{"w":"undodgeable","d":"Impossible to avoid or evade; something that must be faced no matter what action one takes.","s":"The penalty for breaking the rule was undodgeable, no matter how creative your excuse.","p":"un-DOJ-uh-bul","o":"Latin","y":9,"bp":35,"sy":"un.dodge.able","ps":"adjective","t":["olatin"]},{"w":"undoglike","d":"Not resembling or characteristic of a dog in behavior, appearance, or temperament.","s":"The cat's fierce loyalty to its owner was considered undoglike by everyone who witnessed it.","p":"un-DOG-lyk","o":"Latin","y":9,"bp":28,"sy":"un.dog.like","ps":"adjective","t":["character","olatin"]},{"w":"undomestic","d":"not domestic or related to home","s":"Had established herself in her career at the price of being so undomestic she didn't even know how to light the oven.","p":"un-duh-MES-tik","o":"Latin","y":8,"bp":30,"sy":"un.do.mes.tic","ps":"adjective","t":["olatin"]},{"w":"undomesticable","d":"Impossible to tame, domesticate, or adapt to a household or civilized setting; inherently wild.","s":"The wild lynx was truly undomesticable, refusing every attempt to make it a house pet.","p":"un-duh-MES-tih-kuh-bul","o":"Latin","y":9,"bp":30,"sy":"un.do.mes.ti.ca.ble","ps":"adjective","t":["household","olatin"]},{"w":"undomesticate","d":"To cause a tame animal to become wild again.","s":"Years in the wilderness seemed to undomesticate the once-tame horse.","p":"un-duh-MES-tih-kayt","o":"Latin","y":9,"bp":28,"sy":"un.do.mes.ti.cate","ps":"verb","t":["animals","olatin"]},{"w":"undominated","d":"Not controlled, ruled over, or subjected to the authority or power of another person or force.","s":"The undominated chess player won every tournament without a single loss.","p":"un-DOM-ih-nay-ted","o":"Latin","y":8,"bp":38,"sy":"un.dom.i.nat.ed","ps":"adjective","t":["physics","poetry","olatin"]},{"w":"undonated","d":"Not given as a gift or contribution; kept rather than transferred to another person or cause.","s":"The undonated supplies sat in the warehouse while the charity waited for contributions.","p":"un-DOH-nay-ted","o":"Latin","y":8,"bp":29,"sy":"un.do.nat.ed","ps":"adjective","t":["olatin"]},{"w":"undoomed","d":"Not condemned to a terrible fate; free from a sense of inevitable destruction or failure.","s":"Against all odds, the sailors felt undoomed when the storm finally passed.","p":"un-DOOMD","o":"Latin","y":8,"bp":25,"sy":"un.doomed","ps":"adjective","t":["olatin"]},{"w":"undouble","d":"To unfold or open something that has been doubled over; to reduce from a doubled state back to a single layer.","s":"She carefully pulled the fabric apart to undouble the folded cloth.","p":"un-DUB-ul","o":"Latin","y":9,"bp":27,"sy":"un.dou.ble","ps":"verb","t":["olatin"]},{"w":"undoubled","d":"Not folded over or doubled; existing in a single, unrepeated layer or form.","s":"The undoubled sheet lay flat and smooth across the table.","p":"un-DUB-uld","o":"Latin","y":9,"bp":28,"sy":"un.dou.bled","ps":"adjective","t":["olatin"]},{"w":"undoubtful","d":"Free from doubt or uncertainty; completely certain and confident in a belief or outcome.","s":"Her undoubtful confidence inspired every member of the team.","p":"un-DOWT-ful","o":"Latin","y":9,"bp":29,"sy":"un.doubt.ful","ps":"adjective","t":["logic","olatin"]},{"w":"undoubtfully","d":"In a manner free from doubt or uncertainty; with complete confidence and no hesitation.","s":"He undoubtfully accepted the challenge without a moment's hesitation.","p":"un-DOWT-ful-ee","o":"Latin","y":9,"bp":38,"sy":"un.doubt.ful.ly","ps":"adverb","t":["olatin"]},{"w":"undownable","d":"Impossible to bring down, defeat, or suppress; resilient enough to resist being overcome by any force.","s":"The spirited gymnast was undownable, bouncing back after every stumble.","p":"un-DOWN-uh-bul","o":"Latin","y":9,"bp":29,"sy":"un.down.able","ps":"adjective","t":["physics","olatin"]},{"w":"undragonlike","d":"Not resembling or characteristic of a dragon in behavior, appearance, or fearsome qualities.","s":"The tiny, friendly lizard was completely undragonlike despite its scaly skin.","p":"un-DRAG-un-lyk","o":"Latin","y":9,"bp":38,"sy":"un.drag.on.like","ps":"adjective","t":["myth","olatin"]},{"w":"undrainable","d":"Impossible to drain or empty of liquid; retaining its contents no matter what means are used.","s":"The enormous swamp seemed undrainable no matter how many pumps they used.","p":"un-DRAYN-uh-bul","o":"Latin","y":9,"bp":34,"sy":"undrain.able","ps":"adjective","t":["olatin"]},{"w":"undramatizable","d":"Not capable of being adapted into a dramatic form or presented effectively as a theatrical production.","s":"The critic argued that the dull legal document was completely undramatizable for the stage.","p":"un-druh-MAT-ih-zy-uh-bul","o":"Latin","y":9,"bp":29,"sy":"un.drama.ti.z.able","ps":"adjective","t":["stage","olatin"]},{"w":"undrape","d":"strip something of drapery","s":"The artist carefully moved to undrape the statue before the crowd.","p":"un-DRAYP","o":"Latin","y":9,"bp":19,"sy":"un.drape","ps":"verb","t":["olatin"]},{"w":"undraped","d":"strip something of drapery","s":"The museum curator carefully undraped the newly restored painting, revealing its rich colors to the crowd of eager visitors who had waited months to see it.","p":"un-DRAYPT","o":"Latin","y":8,"bp":25,"sy":"un.draped","ps":"verb","t":["olatin"]},{"w":"undraw","d":"To pull back or open something that has been drawn, such as a curtain or a bolt; to reverse the act of drawing.","s":"He reached up to undraw the heavy curtains and let in the morning light.","p":"un-DRAW","o":"Latin","y":8,"bp":18,"sy":"un.draw","ps":"verb","t":["household","painting","olatin"]},{"w":"undreaded","d":"Not feared or dreaded; no longer or never regarded with terror or anxious anticipation.","s":"The friendly dentist made each visit an undreaded event for her young patients.","p":"un-DRED-ed","o":"Latin","y":8,"bp":28,"sy":"un.dread.ed","ps":"adjective","t":["emotions","olatin"]},{"w":"undreading","d":"Not experiencing or showing dread or fear; approaching something without anxiety or apprehension.","s":"Undreading the long hike, Marcus packed his bag with excitement.","p":"un-DRED-ing","o":"Latin","y":8,"bp":29,"sy":"un.dread.ing","ps":"adjective","t":["emotions","olatin"]},{"w":"undream","d":"To reverse or undo a dream; to cause something imagined or dreamed to be forgotten or unmade.","s":"Try as he might, he could not undream the vivid nightmare that haunted him.","p":"un-DREEM","o":"Latin","y":8,"bp":19,"sy":"un.dream","ps":"verb","t":["olatin"]},{"w":"undreamable","d":"Impossible to conceive of even in a dream; so extraordinary or strange that the imagination cannot picture it.","s":"The scientist's discovery was undreamable even a century ago.","p":"un-DREEM-uh-bul","o":"Latin","y":9,"bp":35,"sy":"un.dream.able","ps":"adjective","t":["olatin"]},{"w":"undreamt","d":"not imagined even in a dream","s":"Traveling to the moon was an undreamt possibility for people living in the 1800s.","p":"un-DREMT","o":"Latin","y":7,"bp":25,"sy":"un.dreamt","ps":"adjective","t":["olatin"]},{"w":"undressable","d":"Not capable of being undressed or having clothing removed; impossible to take clothing off of.","s":"The tiny doll's outfit was so tangled it seemed completely undressable.","p":"un-DRES-uh-bul","o":"Latin","y":9,"bp":35,"sy":"un.dress.able","ps":"adjective","t":["olatin"]},{"w":"undrooping","d":"Not drooping or hanging downward; remaining upright, alert, and energetic without wilting or sagging.","s":"The undrooping sunflower stood tall even after days without rain.","p":"un-DROOP-ing","o":"Latin","y":8,"bp":29,"sy":"un.droop.ing","ps":"adjective","t":["olatin"]},{"w":"undrugged","d":"Not under the influence of any drug or sedative; in a natural, clear-headed, and unaltered state of consciousness.","s":"The undrugged patient was fully alert and able to answer all the doctor's questions.","p":"un-DRUGD","o":"Latin","y":8,"bp":26,"sy":"un.drugged","ps":"adjective","t":["pharmacy","olatin"]},{"w":"undrunken","d":"Not in a state of intoxication; completely sober and unaffected by alcohol or any intoxicating substance.","s":"He remained undrunken at the party, sipping only water all evening.","p":"un-DRUNK-en","o":"Latin","y":8,"bp":28,"sy":"un.drunk.en","ps":"adjective","t":["olatin"]},{"w":"undueness","d":"The quality or state of being undue; the condition of being excessive, improper, or not rightfully deserved.","s":"The judge noted the undueness of the harsh penalty for such a minor offense.","p":"un-DOO-nes","o":"Latin","y":8,"bp":28,"sy":"un.due.ness","ps":"noun","t":["olatin"]},{"w":"undug","d":"Not excavated or dug up; remaining in the ground untouched by any digging instrument or effort.","s":"The treasure remained undug in the yard because they lost the map.","p":"un-DUG","o":"Latin","y":7,"bp":17,"sy":"un.dug","ps":"adjective","t":["music","olatin"]},{"w":"undulation","d":"an undulating curve","s":"The undulation of the wheat field in the breeze looked like ocean waves.","p":"un-dyoo-LAY-shun","o":"Latin","y":6,"bp":30,"sy":"un.du.la.tion","ps":"noun","t":["olatin"]},{"w":"undulationist","d":"A person who believes in or advocates a theory based on wave-like or undulating motion, especially in scientific contexts.","s":"The undulationist argued that light traveled in waves, not particles.","p":"un-dyoo-LAY-shun-ist","o":"Latin","y":9,"bp":28,"sy":"un.du.la.tion.ist","ps":"noun","t":["logic","olatin"]},{"w":"undull","d":"To make less dull; to sharpen, brighten, or restore liveliness or keenness to something.","s":"A bright coat of paint was enough to undull the gray, lifeless room.","p":"un-DUL","o":"Latin","y":9,"bp":18,"sy":"un.dull","ps":"verb","t":["olatin"]},{"w":"undulled","d":"Not made dull; still sharp, bright, or lively, having retained its original keenness or vividness.","s":"Even after years of use, the chef's undulled knife cut cleanly through vegetables.","p":"un-DULD","o":"Latin","y":9,"bp":25,"sy":"un.dulled","ps":"adjective","t":["olatin"]},{"w":"unduped","d":"Not deceived or tricked; having seen through a deception and remained undeluded.","s":"The savvy shopper remained unduped by the store's fake 'sale' prices.","p":"un-DYOOPT","o":"Latin","y":8,"bp":17,"ps":"adjective","t":["olatin"]},{"w":"unduplicable","d":"Impossible to duplicate or copy; so unique that it cannot be reproduced in any form.","s":"The artist's style was so unique it was completely unduplicable by anyone else.","p":"un-DYOO-plih-kuh-bul","o":"Latin","y":9,"bp":38,"sy":"undu.pli.ca.ble","ps":"adjective","t":["olatin"]},{"w":"undust","d":"To remove dust from something; to clean by wiping or brushing away accumulated dust.","s":"She used a soft cloth to undust every shelf in the library.","p":"un-DUST","o":"Latin","y":8,"bp":18,"sy":"un.dust","ps":"verb","t":["olatin"]},{"w":"undwelt","d":"Never lived in or inhabited; describing a place where no one has ever taken up residence.","s":"The creepy undwelt mansion at the end of the road had been empty for decades.","p":"un-DWELT","o":"Latin","y":8,"bp":17,"ps":"adjective","t":["olatin"]},{"w":"undyingly","d":"In a manner that does not die or fade; with enduring, everlasting persistence.","s":"She undyingly supported her friend through every hardship imaginable.","p":"un-DY-ing-lee","o":"Latin","y":8,"bp":28,"sy":"undy.ing.ly","ps":"adverb","t":["time","olatin"]},{"w":"undyingness","d":"The quality or state of being undying; the condition of lasting or enduring forever without fading.","s":"The undyingness of his passion for music inspired everyone around him.","p":"un-DY-ing-nes","o":"Latin","y":9,"bp":35,"sy":"undy.ing.ness","ps":"noun","t":["olatin"]},{"w":"uneared","d":"Not having formed ears or grain heads; describing a plant, especially corn, that has not yet developed its ear.","s":"The uneared corn stalks wilted in the summer heat before producing any grain.","p":"un-EERD","o":"Latin","y":8,"bp":19,"sy":"un.eared","ps":"adjective","t":["botany","olatin"]},{"w":"unearnt","d":"Not earned or deserved; obtained without proper work, merit, or effort.","s":"He felt guilty spending money that seemed unearnt after so little effort.","p":"un-ERNT","o":"Latin","y":8,"bp":19,"sy":"un.earnt","ps":"adjective","t":["olatin"]},{"w":"uneating","d":"Not eating; refraining from or incapable of consuming food.","s":"The uneating cat worried its owner, since it had ignored its bowl for two days.","p":"un-EE-ting","o":"Latin","y":8,"bp":27,"sy":"un.eat.ing","ps":"adjective","t":["olatin"]},{"w":"unebbing","d":"Not receding or pulling back; describing a tide, flow, or feeling that never diminishes or withdraws.","s":"The unebbing tide of enthusiasm from the crowd kept the concert energy high all night.","p":"un-EB-ing","o":"Latin","y":8,"bp":25,"sy":"uneb.bing","ps":"adjective","t":["waterways","olatin"]},{"w":"uneccentric","d":"Not eccentric; conforming to the norm in behavior or appearance; conventional and predictable.","s":"Unlike his wildly creative siblings, Marcus was refreshingly uneccentric, preferring plain clothes and ordinary hobbies.","p":"un-ek-SEN-trik","o":"Latin","y":9,"bp":37,"sy":"un.ec.cen.tric","ps":"adjective","t":["olatin"]},{"w":"unechoed","d":"Not repeated or reflected back as an echo; describing a sound or statement that received no response or reverberation.","s":"Her plea for help went unechoed through the empty hallways of the abandoned school.","p":"un-EK-ode","o":"Latin","y":9,"bp":27,"sy":"un.e.choed","ps":"adjective","t":["olatin"]},{"w":"unechoing","d":"Not producing or sending back an echo; silent in response, absorbing sound without reflection.","s":"The padded walls of the recording studio were completely unechoing, making every sound flat and close.","p":"un-EK-oh-ing","o":"Latin","y":9,"bp":29,"sy":"un.e.cho.ing","ps":"adjective","t":["olatin"]},{"w":"uneclipsable","d":"Impossible to eclipse or overshadow; so brilliant or remarkable that nothing can dim or surpass it.","s":"Her talent was uneclipsable — no rival could ever overshadow her performances on stage.","p":"un-ih-KLIP-suh-bul","o":"Latin","y":9,"bp":35,"sy":"un.eclipsable","ps":"adjective","t":["astronomy","olatin"]},{"w":"uneclipsed","d":"Not overshadowed or blocked out; remaining fully visible, bright, or prominent without being diminished by anything else.","s":"The champion's record stood uneclipsed for over two decades.","p":"un-ih-KLIPST","o":"Latin","y":8,"bp":27,"sy":"un.eclipsed","ps":"adjective","t":["olatin"]},{"w":"unecstatic","d":"Not feeling or showing ecstasy; lacking enthusiasm, elation, or overwhelming joy.","s":"The audience was unecstatic after the poorly rehearsed play ended abruptly in the second act.","p":"un-ek-STAT-ik","o":"Latin","y":8,"bp":30,"sy":"un.ec.stat.ic","ps":"adjective","t":["emotions","olatin"]},{"w":"unecstatically","d":"In a manner that is without ecstasy or intense excitement; calmly and without enthusiastic emotion.","s":"She clapped unecstatically, barely lifting her hands above her lap.","p":"un-ek-STAT-ih-kul-ee","o":"Latin","y":9,"bp":30,"sy":"un.ec.stat.i.cal.ly","ps":"adverb","t":["emotions","olatin"]},{"w":"unedge","d":"To remove or blunt the edge of something; to take away sharpness from a blade or border.","s":"The carpenter used fine sandpaper to unedge the sharp corners of the wooden toy.","p":"un-EJ","o":"Latin","y":8,"bp":18,"sy":"un.edge","ps":"verb","t":["olatin"]},{"w":"uneducatedly","d":"In a manner that shows a lack of education or formal learning; behaving or speaking without the benefit of schooling.","s":"He spoke uneducatedly about the topic, mixing up basic facts that any textbook would clarify.","p":"un-EJ-oo-kay-ted-lee","o":"Latin","y":8,"bp":42,"sy":"un.e.d.u.cat.ed.ly","ps":"adverb","t":["olatin"]},{"w":"uneducatedness","d":"The state or quality of lacking education; the condition of being without formal learning or schooling.","s":"The committee was troubled by the uneducatedness evident in the candidate's answers.","p":"un-EJ-oo-kay-ted-nes","o":"Latin","y":9,"bp":32,"sy":"un.e.d.u.cat.ed.ness","ps":"noun","t":["olatin"]},{"w":"uneffaceable","d":"Impossible to erase, wipe out, or obliterate; leaving a permanent mark that cannot be removed.","s":"The memory of that joyful summer was uneffaceable, staying with her for the rest of her life.","p":"un-ih-FAY-suh-bul","o":"Latin","y":9,"bp":38,"sy":"un.ef.face.able","ps":"adjective","t":["olatin"]},{"w":"uneffaced","d":"Not erased, wiped out, or removed; still clearly visible or present despite the passage of time.","s":"The ancient carvings remained uneffaced despite centuries of wind and rain.","p":"un-ih-FAYST","o":"Latin","y":8,"bp":28,"sy":"un.ef.faced","ps":"adjective","t":["time","olatin"]},{"w":"uneffectual","d":"Not producing the desired effect; failing to achieve its intended purpose; ineffective or futile.","s":"The principal's uneffectual warnings failed to stop students from running in the halls.","p":"un-ih-FEK-choo-ul","o":"Latin","y":9,"bp":38,"sy":"un.ef.fec.tu.al","ps":"adjective","t":["olatin"]},{"w":"unejected","d":"Not thrown out, expelled, or forcibly removed from a place or position.","s":"The faulty cartridge remained unejected from the old printer no matter how many times he pressed the button.","p":"un-ih-JEK-ted","o":"Latin","y":8,"bp":29,"sy":"un.e.ject.ed","ps":"adjective","t":["olatin"]},{"w":"unelaborate","d":"not elaborate; lacking rich or complex detail","s":"The design was unelaborate but elegant, using just two colors and clean straight lines.","p":"un-ih-LAB-uh-rut","o":"Latin","y":9,"bp":37,"sy":"un.elab.o.rate","ps":"adjective","t":["olatin"]},{"w":"unelapsed","d":"Not yet passed or gone by; describing time that has not yet run its course or come to an end.","s":"With much of the unelapsed time still on the clock, the team had plenty of chances to score.","p":"un-ih-LAPST","o":"Latin","y":8,"bp":26,"sy":"un.elapsed","ps":"adjective","t":["time","olatin"]},{"w":"unelect","d":"To remove from elected office; to reverse or cancel the election of a person to a position.","s":"The angry citizens wanted to unelect their representative before his term was even half over.","p":"un-ih-LEKT","o":"Latin","y":8,"bp":19,"sy":"un.elect","ps":"verb","t":["politics","olatin"]},{"w":"unelectrified","d":"Not supplied with or converted to electricity; lacking electrical power or the excitement that electricity can bring.","s":"The remote village was still unelectrified, relying on candles and oil lamps after dark.","p":"un-ih-LEK-trih-fyd","o":"Latin","y":9,"bp":26,"sy":"un.elec.tri.fied","ps":"adjective","t":["physics","olatin"]},{"w":"unelicited","d":"Not drawn out or prompted by questioning or request; given or occurring spontaneously without being asked for.","s":"Her unelicited opinion surprised the teacher, who hadn't asked for any comments yet.","p":"un-ih-LIS-ih-ted","o":"Latin","y":8,"bp":29,"sy":"un.elicit.ed","ps":"adjective","t":["olatin"]},{"w":"unelongated","d":"Not stretched out or lengthened; remaining at its original length without having been extended.","s":"The unelongated shape of the seed made it look more like a tiny ball than a typical oval kernel.","p":"un-ih-LONG-gay-ted","o":"Latin","y":8,"bp":38,"sy":"un.e.lon.gat.ed","ps":"adjective","t":["olatin"]},{"w":"uneloquent","d":"Lacking eloquence; not able to express ideas clearly, fluently, or persuasively.","s":"His uneloquent speech was full of 'um's and 'uh's, failing to inspire the crowd.","p":"un-EL-uh-kwent","o":"Latin","y":9,"bp":29,"sy":"un.elo.quent","ps":"adjective","t":["olatin"]},{"w":"unemancipated","d":"Not freed from legal, social, or political restraint; still under the control or authority of another.","s":"The unemancipated workers were still bound by unfair contracts they had no power to break.","p":"un-ih-MAN-sih-pay-ted","o":"Latin","y":9,"bp":29,"sy":"un.e.man.ci.pat.ed","ps":"adjective","t":["poetry","law","politics","olatin"]},{"w":"unemarginated","d":"Not having a notched, indented, or distinct margin; lacking a clearly defined or emarginated edge, especially in biology.","s":"The unemarginated leaf had smooth edges with no notches or indentations along its border.","p":"un-ih-MAR-jih-nay-ted","o":"Latin","y":9,"bp":26,"sy":"un.e.marginat.ed","ps":"adjective","t":["olatin"]},{"w":"unembalmed","d":"Not treated with preservatives or embalming fluid after death; describing a body that has not undergone the embalming process.","s":"Because the body was unembalmed, the burial had to take place within a day.","p":"un-em-BAHMD","o":"Latin","y":8,"bp":29,"sy":"un.em.balmed","ps":"adjective","t":["olatin"]},{"w":"unembargoed","d":"Not subject to an embargo; free from trade restrictions or official bans on commerce.","s":"Once the trade route was deemed unembargoed, ships were finally free to carry goods into the port.","p":"un-em-BAR-gode","o":"Latin","y":8,"bp":37,"sy":"un.em.bar.goed","ps":"adjective","t":["economy","olatin"]},{"w":"unembarrassable","d":"Describing a person who cannot be made to feel embarrassed or self-conscious, no matter the situation or circumstances.","s":"My little brother is completely unembarrassable — he once sang off-key in front of the whole school without flinching.","p":"un-em-BAIR-uh-suh-bul","o":"Latin","y":9,"bp":30,"sy":"un.em.bar.rass.able","ps":"adjective","t":["olatin"]},{"w":"unembarrassing","d":"Not causing embarrassment or awkwardness; unlikely to make someone feel self-conscious or ashamed.","s":"The teacher's correction was gentle and unembarrassing, so nobody in class felt ashamed.","p":"un-em-BAIR-uh-sing","o":"Latin","y":9,"bp":29,"sy":"un.em.bar.rass.ing","ps":"adjective","t":["olatin"]},{"w":"unembarrassment","d":"The state or condition of being free from embarrassment; an absence of self-consciousness or shame.","s":"His unembarrassment at singing in public made everyone around him feel more relaxed about joining in.","p":"un-em-BAIR-us-munt","o":"Latin","y":9,"bp":30,"sy":"un.em.bar.rass.ment","ps":"noun","t":["olatin"]},{"w":"unembed","d":"To remove something from an embedded position; to extract or detach something that was fixed firmly within a surrounding material or context.","s":"The editor had to unembed the video file from the document before sending it by email.","p":"un-em-BED","o":"Latin","y":8,"bp":20,"sy":"un.em.bed","ps":"verb","t":["olatin"]},{"w":"unembittered","d":"Not made resentful, cynical, or bitter by hardship or disappointment; remaining free of bitterness despite difficult experiences.","s":"Despite losing the championship, she remained unembittered and congratulated the winner warmly.","p":"un-em-BIT-erd","o":"Latin","y":9,"bp":38,"sy":"un.em.bit.tered","ps":"adjective","t":["olatin"]},{"w":"unemblazoned","d":"Not decorated or marked with a bold design, coat of arms, or conspicuous insignia; left plain without any blazoned decoration.","s":"The plain, unemblazoned shield gave no hint of which family the knight belonged to.","p":"un-em-BLAY-zund","o":"Latin","y":8,"bp":38,"sy":"un.em.bla.zoned","ps":"adjective","t":["landforms","fabrics","royalty","olatin"]},{"w":"unembodied","d":"Not having a physical or material body; existing as a spirit, idea, or abstract form without a tangible physical presence.","s":"The philosopher argued that the soul is an unembodied essence, existing as pure thought and feeling long after the physical form has faded away completely.","p":"un-em-BOD-eed","o":"Latin","y":8,"bp":30,"sy":"un.em.bod.ied","ps":"adjective","t":["olatin"]},{"w":"unemboldened","d":"Not made braver or more confident; lacking the encouragement or inspiration needed to act with boldness or courage.","s":"Unemboldened by any encouragement, the shy student never raised her hand in class.","p":"un-em-BOHL-dund","o":"Latin","y":8,"bp":38,"sy":"un.em.bold.ened","ps":"adjective","t":["olatin"]},{"w":"unembraced","d":"Not accepted, welcomed, or held in affection; not adopted or taken up with enthusiasm by others.","s":"The new school policy was unembraced by most teachers, who preferred the old system.","p":"un-em-BRAYST","o":"Latin","y":8,"bp":29,"sy":"un.em.braced","ps":"adjective","t":["emotions","olatin"]},{"w":"unembroidered","d":"Not decorated with embroidery or ornamental stitching; also used figuratively to mean not embellished or exaggerated with extra details.","s":"The unembroidered cloth was simple and plain, waiting to be decorated with colorful thread.","p":"un-em-BROY-derd","o":"Latin","y":9,"bp":26,"sy":"un.em.broi.dered","ps":"adjective","t":["fabrics","olatin"]},{"w":"unempathetic","d":"Lacking empathy or the ability to understand and share the feelings of another person; showing no sensitivity to others' emotions.","s":"The unempathetic coach ignored the injured player's pain and told her to keep running.","p":"un-em-puh-THET-ik","o":"Latin","y":8,"bp":39,"sy":"un.em.pa.thet.ic","ps":"adjective","t":["emotions","olatin"]},{"w":"unemployableness","d":"The quality or state of being impossible or very difficult to employ; the condition of lacking the skills, traits, or qualifications needed to hold a job.","s":"His complete unemployableness was due to a refusal to learn any new skills despite many opportunities.","p":"un-em-PLOY-uh-bul-nus","o":"Latin","y":9,"bp":30,"sy":"un.em.ploy.able.ness","ps":"noun","t":["olatin"]},{"w":"unemployably","d":"In a manner that makes employment impossible or extremely unlikely; to a degree that prevents one from being hired or put to useful work.","s":"He was so rude at every job interview that he seemed almost unemployably arrogant.","p":"un-em-PLOY-uh-blee","o":"Latin","y":8,"bp":38,"sy":"un.em.ploy.ably","ps":"adverb","t":["olatin"]},{"w":"unempowered","d":"Not given authority, confidence, or the means to take action; lacking the power or resources needed to act effectively or independently.","s":"The students felt unempowered when their suggestions were ignored by the school board.","p":"un-em-POW-erd","o":"Latin","y":8,"bp":37,"sy":"un.em.pow.ered","ps":"adjective","t":["poetry","olatin"]},{"w":"unempowering","d":"Not giving strength, confidence, or authority to someone; tending to leave a person feeling helpless or without the ability to take meaningful action.","s":"Being told to sit quietly and never speak up is an unempowering experience for any student.","p":"un-em-POW-er-ing","o":"Latin","y":8,"bp":39,"sy":"un.em.pow.er.ing","ps":"adjective","t":["poetry","character","olatin"]},{"w":"unemptied","d":"Not having been emptied; still containing its contents because no one has removed or drained them.","s":"The unemptied trash cans overflowed by the end of the school week.","p":"un-EMP-teed","o":"Latin","y":8,"bp":28,"sy":"un.emp.tied","ps":"adjective","t":["olatin"]},{"w":"unemulated","d":"Not copied, imitated, or followed as a model by others; lacking admiration great enough to inspire imitation.","s":"The artist's unique style remained unemulated because no one could match her creativity.","p":"un-EM-yoo-lay-tid","o":"Latin","y":8,"bp":32,"sy":"un.em.u.lat.ed","ps":"adjective","t":["olatin"]},{"w":"unenabled","d":"Not given the ability, access, or means to do something; not activated or made functional.","s":"The feature remained unenabled on the device until the software update was installed.","p":"un-en-AY-buld","o":"Latin","y":8,"bp":28,"sy":"un.en.abled","ps":"adjective","t":["olatin"]},{"w":"unenactable","d":"Not capable of being officially passed into law or put into practice; impossible to enact or carry out through proper procedures.","s":"The committee declared the new rule unenactable because it violated existing law.","p":"un-en-AK-tuh-bul","o":"Latin","y":9,"bp":37,"sy":"un.e.n.actable","ps":"adjective","t":["law","olatin"]},{"w":"unenacted","d":"Not yet passed into law or officially put into effect; remaining as a proposal or idea without having been formally carried out.","s":"The proposed climate bill remained unenacted after years of debate in Congress.","p":"un-en-AK-tid","o":"Latin","y":8,"bp":31,"sy":"un.e.n.act.ed","ps":"adjective","t":["law","olatin"]},{"w":"unenamored","d":"Not charmed, fascinated, or deeply attracted to someone or something; feeling little or no admiration or love.","s":"She was clearly unenamored with the idea of spending her Saturday cleaning the garage.","p":"un-en-AM-erd","o":"Latin","y":8,"bp":30,"sy":"un.e.n.amored","ps":"adjective","t":["olatin"]},{"w":"unenamour'd","d":"An archaic or poetic contracted form of unenamoured, meaning not captivated or in love; not charmed by someone or something.","s":"The poet wrote that the knight rode away unenamour'd, his heart cold as stone.","p":"un-en-AM-erd","o":"Latin","y":9,"bp":37,"sy":"un.e.n.amour'd","ps":"adjective","t":["law","olatin"]},{"w":"unenamoured","d":"Not charmed, infatuated, or deeply attracted to a person or thing; feeling no strong love or admiration, especially in British spelling.","s":"He remained unenamoured of city life and longed to return to the countryside.","p":"un-en-AM-erd","o":"Latin","y":9,"bp":37,"sy":"un.e.n.amoured","ps":"adjective","t":["wordwords","olatin"]},{"w":"unencapsulated","d":"Not enclosed or contained within a capsule, protective layer, or summarizing wrapper; left without a surrounding covering or concise summary.","s":"The unencapsulated data was vulnerable because it lacked any protective coding layer.","p":"un-en-KAP-syoo-lay-tid","o":"Latin","y":8,"bp":30,"sy":"un.en.cap.su.lat.ed","ps":"adjective","t":["olatin"]},{"w":"unencased","d":"Not enclosed or covered in a protective case or outer shell; left exposed without a surrounding container or housing.","s":"The fragile instrument arrived unencased and was damaged during shipping.","p":"un-en-KAYST","o":"Latin","y":8,"bp":28,"sy":"un.en.cased","ps":"adjective","t":["olatin"]},{"w":"unenchanting","d":"Not charming, delightful, or magically appealing; failing to captivate or produce a sense of wonder in those who encounter it.","s":"The tour guide gave an unenchanting lecture that put half the group to sleep.","p":"un-en-CHANT-ing","o":"Latin","y":9,"bp":38,"sy":"un.en.chant.ing","ps":"adjective","t":["emotions","olatin"]},{"w":"unenciphered","d":"Not converted into a secret code or cipher; left in plain, readable form without encryption or encoding.","s":"The unenciphered message could be read by anyone who intercepted it.","p":"un-en-SY-ferd","o":"Latin","y":8,"bp":38,"sy":"un.en.ci.phered","ps":"adjective","t":["landforms","olatin"]},{"w":"unencode","d":"To reverse the encoding of data or a message; to convert something from a coded or transformed format back to its original readable form.","s":"The programmer needed to unencode the scrambled file before he could read it.","p":"un-en-KOHD","o":"Latin","y":9,"bp":27,"sy":"un.en.code","ps":"verb","t":["olatin"]},{"w":"unencoded","d":"Not converted into a coded or specially formatted form; remaining in its original, plain, or unprocessed state without any encoding applied.","s":"The unencoded signal was broadcast openly and could be picked up by any radio.","p":"un-en-KOH-did","o":"Latin","y":8,"bp":29,"sy":"un.en.cod.ed","ps":"adjective","t":["landforms","olatin"]},{"w":"unencountered","d":"Not yet met with, experienced, or come across; never having been faced or discovered before.","s":"The explorer documented several unencountered species deep in the rainforest.","p":"un-en-KOWN-terd","o":"Latin","y":9,"bp":26,"sy":"un.en.coun.tered","ps":"adjective","t":["olatin"]},{"w":"unencouraged","d":"Not supported, motivated, or given positive reinforcement; lacking the encouragement needed to pursue a goal or continue an effort.","s":"Left unencouraged by her teachers, she nearly gave up her dream of becoming a writer.","p":"un-en-KUR-ijd","o":"Latin","y":9,"bp":38,"sy":"un.en.cour.aged","ps":"adjective","t":["sports","olatin"]},{"w":"unencouraging","d":"not encouraging","s":"The coach's unencouraging tone made the players feel nervous before the big game.","p":"un-en-KUR-ij-ing","o":"Latin","y":9,"bp":28,"sy":"un.en.cour.ag.ing","ps":"adjective","t":["olatin"]},{"w":"unencouragingly","d":"In a manner that offers no encouragement or positive support; in a way that discourages effort or fails to inspire hope or confidence.","s":"She shrugged unencouragingly when her brother asked if his painting was any good.","p":"un-en-KUR-ij-ing-lee","o":"Latin","y":9,"bp":31,"sy":"un.en.cour.ag.ing.ly","ps":"adverb","t":["emotions","olatin"]},{"w":"unenculturated","d":"Not having been taught or absorbed into the customs, values, and social behaviors of a particular culture or society.","s":"The unenculturated child had never been exposed to the traditions of her heritage.","p":"un-en-KUL-chur-ay-tid","o":"Latin","y":9,"bp":30,"sy":"un.en.cul.tur.at.ed","ps":"adjective","t":["olatin"]},{"w":"unendangered","d":"Not threatened with harm, extinction, or serious risk; existing in a safe condition without danger or threat.","s":"Unlike the panda, the common pigeon is an unendangered species found worldwide.","p":"un-en-DAYN-jerd","o":"Latin","y":8,"bp":38,"sy":"un.en.dan.gered","ps":"adjective","t":["ecology","olatin"]},{"w":"unendearing","d":"Not winning affection or making a favorable impression; failing to inspire warmth, fondness, or liking in others.","s":"His habit of interrupting people was an unendearing quality that made friends uncomfortable.","p":"un-en-DEER-ing","o":"Latin","y":8,"bp":37,"sy":"un.en.dear.ing","ps":"adjective","t":["emotions","olatin"]},{"w":"unendearingly","d":"In a manner that fails to win affection or charm; in a way that does not make a person or thing more likable or beloved.","s":"He smiled unendearingly, more like a sneer, which made everyone back away.","p":"un-en-DEER-ing-lee","o":"Latin","y":9,"bp":28,"sy":"un.en.dear.ing.ly","ps":"adverb","t":["emotions","olatin"]},{"w":"unendly","d":"Without end; in an endless or limitless manner; a rare or archaic form expressing the quality of having no conclusion or termination.","s":"The road stretched on in an unendly fashion through the flat desert plains.","p":"un-END-lee","o":"Latin","y":8,"bp":20,"sy":"un.end.ly","ps":"adverb","t":["logic","olatin"]},{"w":"unendowed","d":"not equipped or provided","p":"un-en-DOWD","o":"Latin","y":8,"bp":28,"sy":"un.en.dowed","ps":"adjective","t":["olatin"]},{"w":"unendurable","d":"Describing something so painful, difficult, or unpleasant that it cannot be tolerated or endured by a person.","p":"un-en-DYOOR-uh-bul","o":"Latin","y":7,"bp":35,"sy":"un.en.durable","ps":"adjective","t":["olatin"]},{"w":"unendurableness","d":"The quality or state of being impossible to bear or tolerate; the condition of exceeding all limits of endurance.","s":"The unendurableness of the constant noise finally convinced her to move apartments.","p":"un-en-DYOOR-uh-bul-nes","o":"Latin","y":9,"bp":28,"sy":"un.en.durable.ness","ps":"noun","t":["animals","olatin"]},{"w":"unendurably","d":"In a manner that cannot be endured or tolerated; to an unbearable degree.","s":"The wait was unendurably long, and the children grew restless after the first hour.","p":"un-en-DYOOR-uh-blee","o":"Latin","y":8,"bp":35,"sy":"un.en.durably","ps":"adverb","t":["olatin"]},{"w":"unenergetically","d":"without energy; in a lethargic manner","p":"un-en-er-JET-ih-kuh-lee","o":"Latin","y":9,"bp":33,"sy":"un.en.er.get.i.cal.ly","ps":"adverb","t":["physics","olatin"]},{"w":"unenervated","d":"Not weakened or drained of energy or vitality; remaining strong and vigorous despite potential challenges.","s":"The marathon runner remained unenervated despite the heat because she had trained hard.","p":"un-EN-er-vay-tid","o":"Latin","y":8,"bp":38,"sy":"un.en.er.vat.ed","ps":"adjective","t":["physics","olatin"]},{"w":"unenfeebled","d":"Not made weak or feeble; remaining strong and without any loss of physical or mental strength.","s":"The elderly champion was unenfeebled in spirit even after a long illness.","p":"un-en-FEE-buld","o":"Latin","y":8,"bp":37,"sy":"un.en.fee.bled","ps":"adjective","t":["olatin"]},{"w":"unenforceability","d":"The quality or condition of being impossible to enforce or compel compliance with, especially referring to a law, rule, or contract.","s":"The lawyer argued the contract's unenforceability because it lacked proper signatures.","p":"un-en-FOR-suh-bil-ih-tee","o":"Latin","y":8,"bp":32,"sy":"un.en.force.abil.i.ty","ps":"noun","t":["law","olatin"]},{"w":"unenfranchised","d":"Not granted the right to vote or other civil rights and privileges; deprived of or never given full citizenship rights.","s":"Unenfranchised citizens had no say in the election and felt completely ignored.","p":"un-en-FRAN-chyzd","o":"Latin","y":9,"bp":27,"sy":"un.en.fran.chised","ps":"adjective","t":["politics","olatin"]},{"w":"unengaging","d":"Failing to capture interest or attention; dull and unable to involve or attract others.","s":"The documentary was so unengaging that half the class fell asleep within minutes.","p":"un-en-GAY-jing","o":"Latin","y":7,"bp":30,"sy":"un.en.gag.ing","ps":"adjective","t":["olatin"]},{"w":"unenhanced","d":"Not improved, intensified, or made better in any way; remaining in its original unaltered state.","s":"The photographer chose to display the unenhanced photo to show nature's true beauty.","p":"un-en-HANST","o":"Latin","y":7,"bp":29,"sy":"un.en.hanced","ps":"adjective","t":["olatin"]},{"w":"unenigmatic","d":"Not mysterious or puzzling; straightforward and easy to understand with no hidden meaning.","s":"His straightforward answer was refreshingly unenigmatic compared to the riddles he usually spoke.","p":"un-en-ig-MAT-ik","o":"Latin","y":8,"bp":37,"sy":"un.enig.mat.ic","ps":"adjective","t":["olatin"]},{"w":"unenjoyed","d":"Not experienced with pleasure or satisfaction; left without being appreciated or taken delight in.","s":"The birthday cake sat unenjoyed on the table because everyone was too full to eat.","p":"un-en-JOYD","o":"Latin","y":8,"bp":28,"sy":"un.en.joyed","ps":"adjective","t":["emotions","olatin"]},{"w":"unenlightenable","d":"Incapable of being enlightened, educated, or brought to greater understanding or awareness.","s":"The stubborn man seemed unenlightenable, refusing to accept any new information.","p":"un-en-LY-ten-uh-bul","o":"Latin","y":9,"bp":30,"sy":"un.en.light.en.able","ps":"adjective","t":["olatin"]},{"w":"unenlisted","d":"Not enrolled or signed up for military service; not having joined the armed forces as a volunteer or recruit.","s":"As an unenlisted civilian, she still volunteered to help at the military base.","p":"un-en-LIS-tid","o":"Latin","y":8,"bp":30,"sy":"un.en.list.ed","ps":"adjective","t":["physics","war","olatin"]},{"w":"unenlivening","d":"Failing to make something more lively, cheerful, or interesting; having no brightening or energizing effect.","s":"The substitute teacher's unenlivening lecture made the whole class stare at the clock.","p":"un-en-LY-ven-ing","o":"Latin","y":8,"bp":38,"sy":"un.en.liven.ing","ps":"adjective","t":["olatin"]},{"w":"unennobled","d":"Not elevated in rank, dignity, or character; never granted a noble title or made more admirable.","s":"The knight remained unennobled despite his brave deeds on the battlefield.","p":"un-en-NOH-buld","o":"Latin","y":9,"bp":29,"sy":"unen.no.bled","ps":"adjective","t":["royalty","olatin"]},{"w":"unenquiring","d":"Not inclined to ask questions or seek information; lacking intellectual curiosity or inquisitiveness.","s":"Her unenquiring attitude meant she never asked questions in science class.","p":"un-en-KWY-ring","o":"Latin","y":9,"bp":37,"sy":"un.en.quir.ing","ps":"adjective","t":["character","olatin"]},{"w":"unenrichable","d":"Incapable of being made richer, more valuable, or more rewarding in any sense; impossible to improve or enhance.","s":"The rocky soil was so unenrichable that even fertilizer couldn't help crops grow.","p":"un-en-RICH-uh-bul","o":"Latin","y":9,"bp":38,"sy":"un.en.rich.able","ps":"adjective","t":["olatin"]},{"w":"unenrichableness","d":"The state or quality of being impossible to enrich or improve; the condition of being beyond enhancement or enrichment.","s":"The farmer complained about the unenrichableness of the dry, sandy plot behind his barn.","p":"un-en-RICH-uh-bul-nes","o":"Latin","y":9,"bp":30,"sy":"un.en.rich.able.ness","ps":"noun","t":["olatin"]},{"w":"unenriched","d":"Not made richer, more nutritious, or more valuable; left without any added improvements or enhancements.","s":"The unenriched bread lacked the vitamins added to most store-bought loaves.","p":"un-en-RICHT","o":"Latin","y":8,"bp":29,"sy":"un.en.riched","ps":"adjective","t":["olatin"]},{"w":"unenriching","d":"Failing to add value, meaning, or benefit; not contributing to personal growth, knowledge, or well-being.","s":"The students found the repetitive worksheets unenriching and asked for a more creative project.","p":"un-en-RICH-ing","o":"Latin","y":9,"bp":37,"sy":"un.en.rich.ing","ps":"adjective","t":["logic","olatin"]},{"w":"unenshrined","d":"Not preserved or honored in a revered place or institution; not formally established or protected as sacred or special.","s":"The athlete's record remained unenshrined because the hall of fame had strict requirements.","p":"un-en-SHRYN D","o":"Latin","y":8,"bp":35,"sy":"un.en.shrined","ps":"adjective","t":["religion","olatin"]},{"w":"unentangle","d":"To free from a tangle, complication, or confusion; to separate and clarify something that is knotted or mixed up.","s":"She tried to unentangle the knotted necklace chains before the dance.","p":"un-en-TANG-gul","o":"Latin","y":9,"bp":30,"sy":"un.en.tan.gle","ps":"verb","t":["olatin"]},{"w":"unentertaining","d":"Failing to amuse, interest, or engage an audience; boring and unable to provide enjoyment or diversion.","s":"The movie was so unentertaining that half the audience fell asleep before the ending.","p":"un-en-ter-TAY-ning","o":"Latin","y":9,"bp":29,"sy":"un.en.ter.tain.ing","ps":"adjective","t":["olatin"]},{"w":"unentertainingly","d":"In a manner that fails to amuse or engage; boringly and without providing any pleasure or interest.","s":"The host spoke unentertainingly for an hour, and guests quietly slipped out the back door.","p":"un-en-ter-TAY-ning-lee","o":"Latin","y":9,"bp":32,"sy":"un.en.ter.tain.ing.ly","ps":"adverb","t":["olatin"]},{"w":"unenthralled","d":"Not captivated, fascinated, or spellbound by something; remaining unimpressed and indifferent.","s":"The critic left the art exhibit unenthralled, calling it the least inspiring show of the year.","p":"un-en-THRAWLD","o":"Latin","y":9,"bp":36,"sy":"un.en.thralled","ps":"adjective","t":["olatin"]},{"w":"unenthralling","d":"Failing to captivate or fascinate; unable to hold one's attention or create a sense of wonder.","s":"The documentary's unenthralling pace caused viewers to switch channels within minutes.","p":"un-en-THRAW-ling","o":"Latin","y":9,"bp":25,"sy":"un.en.thralling","ps":"adjective","t":["olatin"]},{"w":"unenthused","d":"Lacking enthusiasm or excitement; showing little or no eagerness or interest in something.","s":"Marcus was unenthused about cleaning the garage on a sunny Saturday afternoon.","p":"un-en-THYOOZD","o":"Latin","y":7,"bp":29,"sy":"un.en.thused","ps":"adjective","t":["olatin"]},{"w":"unenticed","d":"Not attracted or lured by an offer, temptation, or incentive; remaining unmoved by attempts at persuasion.","s":"Despite the flashy advertisement, the shoppers were unenticed by the overpriced gadget.","p":"un-en-TYST","o":"Latin","y":8,"bp":28,"sy":"un.en.ticed","ps":"adjective","t":["olatin"]},{"w":"unenticing","d":"Failing to attract, tempt, or appeal to someone; not appealing or inviting in any way.","s":"The cafeteria's unenticing menu of cold soup made everyone bring lunch from home.","p":"un-en-TY-sing","o":"Latin","y":8,"bp":30,"sy":"un.en.tic.ing","ps":"adjective","t":["olatin"]},{"w":"unentranced","d":"Not put into a state of wonder, delight, or hypnotic fascination; remaining unmoved or unaffected by something.","s":"The magician's tricks left the skeptical professor completely unentranced.","p":"un-en-TRANST","o":"Latin","y":8,"bp":35,"sy":"un.en.tranced","ps":"adjective","t":["emotions","olatin"]},{"w":"unentrenched","d":"Not firmly established or deeply rooted in a position, habit, or belief; still open to change or movement.","s":"The new policy was still unentrenched and could easily be changed by the next committee.","p":"un-en-TRENCHT","o":"Latin","y":9,"bp":36,"sy":"un.en.trenched","ps":"adjective","t":["logic","olatin"]},{"w":"unenumerable","d":"Impossible to count or list completely; too numerous or complex to be fully enumerated.","s":"The number of stars in the galaxy is practically unenumerable to an ordinary person.","p":"un-ih-NYOO-mer-uh-bul","o":"Latin","y":9,"bp":38,"sy":"un.enu.mer.able","ps":"adjective","t":["olatin"]},{"w":"unenumerated","d":"Not specifically listed, counted, or named; referring to rights or items not explicitly included in a formal list.","s":"Many rights are unenumerated in the constitution but are still protected by law.","p":"uh-nih-NOO-mer-ay-tih-d","o":"Latin","y":7,"bp":29,"sy":"ah.nih.nuw.mer.ey.tih.d","ps":"adjective","t":["olatin"]},{"w":"unenvied","d":"Not regarded with envy or jealousy by others; describing a position or situation that no one wishes to be in.","s":"The janitor's unenvied job of cleaning after the school festival was dirty but necessary.","p":"un-EN-veed","o":"Latin","y":8,"bp":27,"sy":"un.en.vied","ps":"adjective","t":["emotions","olatin"]},{"w":"unenvious","d":"Free from envy or jealousy; not feeling resentment toward others for their advantages or possessions.","s":"She was unenvious of her sister's trophy because she was proud of her own achievements.","p":"un-EN-vee-us","o":"Latin","y":9,"bp":29,"sy":"un.en.vi.ous","ps":"adjective","t":["emotions","olatin"]},{"w":"unenviously","d":"In a manner free from envy or jealousy; without any feelings of resentment toward others' good fortune.","s":"He unenviously congratulated his teammate on winning the spelling bee.","p":"un-EN-vee-us-lee","o":"Latin","y":9,"bp":38,"sy":"un.en.vi.ous.ly","ps":"adverb","t":["emotions","olatin"]},{"w":"unenvisaged","d":"Not imagined, pictured, or anticipated beforehand; referring to outcomes or situations that were never foreseen.","s":"The flood was a completely unenvisaged disaster that caught the whole town off guard.","p":"un-en-VIZ-ijd","o":"Latin","y":8,"bp":37,"sy":"un.en.vis.aged","ps":"adjective","t":["olatin"]},{"w":"unenvying","d":"Not feeling or showing envy toward others; content with one's own situation without coveting what others have.","s":"The unenvying coach genuinely celebrated every student's success without a hint of jealousy.","p":"un-EN-vee-ing","o":"Latin","y":8,"bp":29,"sy":"un.en.vy.ing","ps":"adjective","t":["emotions","olatin"]},{"w":"unephemeral","d":"Not short-lived or fleeting; lasting beyond a brief period of time and having lasting significance or permanence.","s":"Unlike a mayfly's life, the pyramids are unephemeral structures that have lasted thousands of years.","p":"un-ih-FEM-er-ul","o":"Latin","y":8,"bp":35,"sy":"un.ephemer.al","ps":"adjective","t":["time","olatin"]},{"w":"unepoxidised","d":"Not treated or coated with epoxy resin; describing a surface or material that has not undergone the epoxidation process.","s":"The chemist noted that the unepoxidised compound reacted differently from the treated sample.","p":"un-ih-POK-sih-dyzd","o":"Latin","y":8,"bp":38,"sy":"un.epox.i.dised","ps":"adjective","t":["olatin"]},{"w":"unequalable","d":"So outstanding or superior that nothing else can match or equal it; without a comparable rival or counterpart.","s":"Her dedication to practice was unequalable among all the students in the music program.","p":"un-EE-kwuh-luh-bul","o":"Latin","y":9,"bp":35,"sy":"un.equal.able","ps":"adjective","t":["sports","olatin"]},{"w":"unequality","d":"The state or condition of being unequal; lack of equality or uniformity between things or people.","s":"The judge pointed out the unequality in how the two students were treated for the same offense.","p":"un-ee-KWOL-ih-tee","o":"Latin","y":9,"bp":30,"sy":"un.equal.i.ty","ps":"noun","t":["olatin"]},{"w":"unequall","d":"An archaic or variant spelling of unequal, meaning not equal or not matched in size, degree, or quality.","s":"The old manuscript used the archaic spelling unequall to describe the lopsided contest.","p":"un-EE-kwul","o":"Latin","y":9,"bp":25,"sy":"un.equall","ps":"adjective","t":["wordwords","olatin"]},{"w":"unequalness","d":"The quality or state of being unequal; the condition in which things differ in size, value, or degree.","s":"The unequalness of the two teams made the championship match seem unfair from the start.","p":"un-EE-kwul-nes","o":"Latin","y":9,"bp":35,"sy":"un.equal.ness","ps":"noun","t":["olatin"]},{"w":"unequilibrated","d":"Not having reached or been brought to a state of equilibrium or balance; still in a state of imbalance or instability.","s":"The unequilibrated chemical solution was unstable and had to be carefully handled in the lab.","p":"un-ee-KWIL-ih-bray-tid","o":"Latin","y":9,"bp":29,"sy":"un.equi.li.brat.ed","ps":"adjective","t":["olatin"]},{"w":"unerected","d":"Not yet built, raised, or set upright; remaining in a flat or unassembled state.","s":"The unerected tent lay in a heap on the campground as the rain clouds rolled in.","p":"un-ih-REK-tid","o":"Latin","y":8,"bp":26,"sy":"unerect.ed","ps":"adjective","t":["olatin"]},{"w":"unergative","d":"In linguistics, describing a verb or construction that is not ergative, meaning it does not treat the subject of an intransitive verb like the object of a transitive verb.","s":"The linguist classified the verb 'fall' as unergative because it has only one argument.","p":"un-UR-guh-tiv","o":"Latin","y":9,"bp":27,"sy":"unerga.tive","ps":"adjective","t":["wordwords","olatin"]},{"w":"unergonomic","d":"Not designed with the comfort, efficiency, or safety of the human body in mind; poorly suited to the physical needs of the user.","s":"The unergonomic desk chair gave the student a backache after just one hour of homework.","p":"un-ur-guh-NOM-ik","o":"Latin","y":8,"bp":35,"sy":"uner.gonom.ic","ps":"adjective","t":["olatin"]},{"w":"uneroded","d":"Not worn away or broken down by wind, water, or other natural forces; remaining in its original, intact condition.","s":"The uneroded cliff face revealed sharp, detailed fossils that had been protected for centuries.","p":"un-ih-ROH-did","o":"Latin","y":8,"bp":25,"sy":"unerod.ed","ps":"adjective","t":["weather","physics","olatin"]},{"w":"unerudite","d":"Lacking deep learning or scholarly knowledge; not well-read or academically informed.","s":"The unerudite speaker stumbled over basic facts that any historian would have known.","p":"un-ER-yoo-dyt","o":"Latin","y":9,"bp":26,"sy":"uneru.dite","ps":"adjective","t":["logic","olatin"]},{"w":"unerupted","d":"Not yet having broken through the surface; especially describing a tooth that has not yet emerged through the gum.","s":"The unerupted volcano still posed a danger because pressure was building beneath the surface.","p":"un-ih-RUP-tid","o":"Latin","y":7,"bp":26,"sy":"unerupt.ed","ps":"adjective","t":["body","olatin"]},{"w":"unescapable","d":"Impossible to escape or avoid; inevitable and inescapable.","s":"The detective said the villain had walked into an unescapable trap of his own making.","p":"un-ih-SKAY-puh-bul","o":"Latin","y":8,"bp":34,"sy":"un.escapable","ps":"adjective","t":["olatin"]},{"w":"unescapableness","d":"The quality of being impossible to escape or avoid; the state of being entirely inescapable.","s":"The unescapableness of the math test deadline made every student study hard.","p":"un-ih-SKAY-puh-bul-nes","o":"Latin","y":9,"bp":27,"sy":"un.escapable.ness","ps":"noun","t":["olatin"]},{"w":"unescapably","d":"In a manner that cannot be escaped or avoided; inevitably.","s":"She was unescapably drawn to the mystery novel and stayed up all night reading.","p":"un-ih-SKAY-puh-blee","o":"Latin","y":8,"bp":34,"sy":"un.escapably","ps":"adverb","t":["olatin"]},{"w":"unescape","d":"To reverse or undo an escape action, such as restoring special characters that were previously escaped in a text or code string.","s":"The programmer tried to unescape the special characters in the code so it would display correctly.","p":"un-ih-SKAYP","o":"Latin","y":9,"bp":25,"sy":"un.escape","ps":"verb","t":["olatin"]},{"w":"unescrowed","d":"Not held in escrow; describing funds or property that have not been placed under a neutral third party's control pending the completion of a transaction.","s":"The unescrowed funds were finally released directly to the buyer after the deal fell through.","p":"un-ih-SKROHD","o":"Latin","y":8,"bp":29,"sy":"un.e.scrowed","ps":"adjective","t":["olatin"]},{"w":"unespied","d":"Not seen, noticed, or discovered; remaining undetected or unobserved.","s":"The small mouse moved unespied across the kitchen floor while the cat slept.","p":"un-ih-SPYD","o":"Latin","y":8,"bp":27,"sy":"un.e.spied","ps":"adjective","t":["olatin"]},{"w":"unessayed","d":"Not attempted or tried; referring to a task or effort that was never undertaken.","s":"The difficult mountain trail remained unessayed by hikers who feared the steep cliffs.","p":"un-ih-SAYD","o":"Latin","y":8,"bp":26,"sy":"unes.sayed","ps":"adjective","t":["olatin"]},{"w":"unestablish","d":"To undo or dismantle something that has been established; to remove the foundation or recognized status of something.","s":"The new law would unestablish the old committee that had existed for decades.","p":"un-ih-STAB-lish","o":"Latin","y":8,"bp":35,"sy":"un.estab.lish","ps":"verb","t":["olatin"]},{"w":"unestablished","d":"not established","s":"A reputation as yet unestablished.","p":"un-ih-STAB-lisht","o":"Latin","y":7,"bp":25,"sy":"un.estab.lished","ps":"adjective","t":["olatin"]},{"w":"unetched","d":"Not marked, engraved, or decorated by etching; having no lines or patterns scratched or chemically cut into the surface.","s":"The artist left one corner of the metal plate unetched to show the contrast with her detailed work.","p":"un-ECHT","o":"Latin","y":9,"bp":25,"sy":"un.etched","ps":"adjective","t":["chemistry","painting","olatin"]},{"w":"unetymological","d":"Not in accordance with or based on the true origin and historical development of a word; going against proper word-root analysis.","s":"Using the word 'literally' to mean 'figuratively' is an unetymological practice that confuses language purists.","p":"un-et-ih-muh-LOJ-ih-kul","o":"Latin","y":9,"bp":33,"sy":"un.e.t.y.mo.log.i.cal","ps":"adjective","t":["botany","wordwords","olatin"]},{"w":"unetymologically","d":"In a manner that does not follow or respect the true origins and root meanings of words.","s":"The word was unetymologically used in the poem, ignoring its original Latin roots.","p":"un-et-ih-muh-LOJ-ih-klee","o":"Latin","y":9,"bp":35,"sy":"un.e.t.y.mo.log.i.cal.ly","ps":"adverb","t":["botany","wordwords","olatin"]},{"w":"uneulogized","d":"Not praised or honored in a formal speech or tribute; having received no eulogy or public commendation.","s":"The quiet janitor who saved the school passed away uneulogized, though many remembered his kindness.","p":"un-YOO-luh-jyzd","o":"Latin","y":9,"bp":35,"sy":"uneu.lo.gized","ps":"adjective","t":["olatin"]},{"w":"unevaluatable","d":"Impossible to assess, measure, or assign a value to; beyond the reach of any evaluation method.","s":"The ancient scroll was so fragile and faded that its worth was considered unevaluatable.","p":"un-ih-VAL-yoo-ay-tuh-bul","o":"Latin","y":9,"bp":28,"sy":"un.eval.u.at.able","ps":"adjective","t":["numbers","olatin"]},{"w":"unevaluated","d":"Not yet assessed, judged, or assigned a value; lacking any formal review or analysis.","s":"Several unevaluated science projects sat in the corner, waiting for the judges to arrive.","p":"un-ih-VAL-yoo-ay-tid","o":"Latin","y":8,"bp":38,"sy":"un.eval.u.at.ed","ps":"adjective","t":["law","olatin"]},{"w":"unevasive","d":"Not evasive; direct and straightforward in manner, speech, or movement, without attempting to avoid or dodge.","s":"The unevasive witness answered every question directly without dodging or hesitating.","p":"un-ih-VAY-siv","o":"Latin","y":9,"bp":28,"sy":"un.eva.sive","ps":"adjective","t":["olatin"]},{"w":"uneventfulness","d":"The quality or state of having nothing significant, exciting, or noteworthy happen; the condition of being completely ordinary and without incident.","s":"The uneventfulness of the long car ride made the children fall asleep within the first hour.","p":"un-ih-VENT-ful-nes","o":"Latin","y":9,"bp":27,"sy":"un.event.ful.ness","ps":"noun","t":["olatin"]},{"w":"unevoked","d":"Not called forth, summoned, or brought to mind; remaining unstirred or unawakened in memory or feeling.","s":"The memory remained unevoked until she smelled the same perfume her grandmother used to wear.","p":"un-ih-VOHKT","o":"Latin","y":8,"bp":25,"sy":"un.evoked","ps":"adjective","t":["olatin"]},{"w":"unevolved","d":"Not having undergone evolution or development; remaining in a primitive or unchanged state.","s":"Scientists debated whether the unevolved species had simply found a perfect form millions of years ago.","p":"un-ih-VOLVD","o":"Latin","y":7,"bp":26,"sy":"un.evolved","ps":"adjective","t":["olatin"]},{"w":"unexact","d":"Not precise or accurate; lacking exactness in measurement, detail, or expression.","s":"The chef's unexact measurements resulted in a cake that tasted slightly different each time.","p":"un-ig-ZAKT","o":"Latin","y":8,"bp":20,"sy":"un.ex.act","ps":"adjective","t":["numbers","olatin"]},{"w":"unexacting","d":"not rigorous","s":"Relaxed and unexacting standards.","p":"un-ig-ZAK-ting","o":"Latin","y":8,"bp":30,"sy":"un.ex.act.ing","ps":"adjective","t":["olatin"]},{"w":"unexactness","d":"The quality of being imprecise or inaccurate; a lack of exactness or careful attention to detail.","s":"The unexactness of the map led the hikers slightly off the correct trail.","p":"un-ig-ZAKT-nes","o":"Latin","y":9,"bp":37,"sy":"un.ex.act.ness","ps":"noun","t":["olatin"]},{"w":"unexalted","d":"Not raised to a high position, rank, or status; not praised or glorified; remaining in an ordinary or humble state.","s":"Despite his talent, the humble poet remained unexalted and unknown throughout his lifetime.","p":"un-ig-ZAWL-tid","o":"Latin","y":8,"bp":29,"sy":"un.ex.alt.ed","ps":"adjective","t":["olatin"]},{"w":"unexampled","d":"having no previous example or precedent or parallel","s":"A time of unexampled prosperity.","p":"un-ig-ZAM-puld","o":"Latin","y":7,"bp":30,"sy":"un.ex.am.pled","ps":"adjective","t":["olatin"]},{"w":"unexcavated","d":"Not yet dug out or uncovered by excavation; remaining buried or untouched beneath the surface of the earth.","s":"The archaeologists suspected great treasures lay in the unexcavated sections of the ancient site.","p":"un-EK-skuh-vay-tid","o":"Latin","y":7,"bp":38,"sy":"un.ex.ca.vat.ed","ps":"adjective","t":["olatin"]},{"w":"unexcepted","d":"Not excluded or left out; included within a general rule or statement without any exception being made.","s":"Every student, unexcepted, was required to attend the school assembly on Friday morning.","p":"un-ik-SEP-tid","o":"Latin","y":8,"bp":30,"sy":"un.ex.cept.ed","ps":"adjective","t":["olatin"]},{"w":"unexceptive","d":"Not making or allowing exceptions; applying universally to all cases without exclusion.","s":"The unexceptive policy applied to everyone equally, with no special cases allowed.","p":"un-ik-SEP-tiv","o":"Latin","y":9,"bp":37,"sy":"un.ex.cep.tive","ps":"adjective","t":["olatin"]},{"w":"unexchangeable","d":"not suitable to be exchanged","s":"The rare coin was considered unexchangeable because its historical value was beyond any trade.","p":"un-iks-CHAYN-juh-bul","o":"Latin","y":9,"bp":27,"sy":"un.ex.change.able","ps":"adjective","t":["olatin"]},{"w":"unexchanged","d":"Not having been traded or swapped; still in its original state without any exchange having taken place.","s":"The gift cards sat unexchanged in the drawer long after the holiday season ended.","p":"un-eks-CHAYNZD","o":"Latin","y":9,"bp":35,"sy":"un.ex.changed","ps":"adjective","t":["olatin"]},{"w":"unexcusable","d":"Not able to be excused or justified; describing behavior or an action for which no acceptable excuse exists.","s":"Forgetting to call after the accident was simply unexcusable, no matter what the reason.","p":"un-eks-KYOO-zuh-bul","o":"Latin","y":9,"bp":37,"sy":"un.ex.cus.able","ps":"adjective","t":["olatin"]},{"w":"unexecute","d":"To reverse or undo an action that has been carried out; to cancel or nullify a previously executed command or task.","s":"The programmer found a way to unexecute the faulty command before the system crashed.","p":"un-EK-suh-kyoot","o":"Latin","y":9,"bp":29,"sy":"un.ex.e.cute","ps":"verb","t":["olatin"]},{"w":"unexecuted","d":"Not having been carried out or put into effect; describing a plan, order, or task that was never completed or performed.","s":"The architect's bold design remained unexecuted because the city ran out of funding.","p":"un-EK-suh-kyoo-tid","o":"Latin","y":7,"bp":32,"sy":"un.ex.e.cut.ed","ps":"adjective","t":["olatin"]},{"w":"unexemplary","d":"Not serving as a good example or model; failing to meet the standard of behavior or quality worth imitating.","s":"The coach warned that unexemplary behavior during the tournament would result in suspension.","p":"un-eg-ZEM-pluh-ree","o":"Latin","y":8,"bp":37,"sy":"un.ex.em.plary","ps":"adjective","t":["olatin"]},{"w":"unexemplified","d":"Not illustrated or demonstrated by a specific example; describing an idea or claim for which no concrete instance has been provided.","s":"The theory remained unexemplified because no real-world case had ever matched it perfectly.","p":"un-eg-ZEM-pluh-fyd","o":"Latin","y":9,"bp":28,"sy":"un.ex.em.pli.fied","ps":"adjective","t":["olatin"]},{"w":"unexempt","d":"Not excused or freed from a rule, duty, or obligation; subject to the same requirements as everyone else.","s":"All citizens are unexempt from paying taxes, regardless of their profession.","p":"un-eg-ZEMPT","o":"Latin","y":8,"bp":27,"sy":"un.ex.empt","ps":"adjective","t":["olatin"]},{"w":"unexempted","d":"Not having been granted an exemption or special release from a rule, tax, or obligation; treated like everyone else without special exception.","s":"Even the principal was unexempted from the school's new no-phone policy.","p":"un-eg-ZEMP-tid","o":"Latin","y":8,"bp":30,"sy":"un.ex.empt.ed","ps":"adjective","t":["economy","olatin"]},{"w":"unexercised","d":"Not having been practiced, trained, or put to use; describing a skill, muscle, or right that has been left idle and undeveloped.","s":"His unexercised muscles ached after just one afternoon of moving furniture.","p":"uh-NEH-kser-seye-zd","o":"Latin","y":7,"bp":37,"sy":"ah.neh.kser.say.zd","ps":"adjective","t":["body","olatin"]},{"w":"unexerted","d":"Not applied or put into action; describing force, effort, or influence that was never used or brought to bear on something.","s":"The team's unexerted effort in the first half nearly cost them the championship game.","p":"un-eg-ZUR-tid","o":"Latin","y":8,"bp":29,"sy":"un.ex.ert.ed","ps":"adjective","t":["animals","physics","olatin"]},{"w":"unexfoliated","d":"Not having had dead layers removed by scrubbing or peeling; describing skin or a surface that has not been exfoliated.","s":"The unexfoliated skin felt rough compared to the smooth areas she had carefully treated.","p":"un-eks-FOH-lee-ay-tid","o":"Latin","y":8,"bp":41,"sy":"un.ex.fo.li.at.ed","ps":"adjective","t":["body","olatin"]},{"w":"unexhausted","d":"Not completely used up or depleted; still possessing remaining energy, resources, or supply.","s":"The hikers were relieved to find that their water supply remained unexhausted after three days on the trail, giving them enough to safely complete the journey.","p":"un-eg-ZAWS-tid","o":"Latin","y":8,"bp":37,"sy":"un.ex.haust.ed","ps":"adjective","t":["physics","olatin"]},{"w":"unexhaustible","d":"Impossible to use up or deplete completely; having a supply or source that cannot be exhausted no matter how much is drawn from it.","s":"The storyteller seemed to have an unexhaustible imagination, never running out of new tales.","p":"un-eg-ZAWS-tuh-bul","o":"Latin","y":9,"bp":25,"sy":"un.ex.haustible","ps":"adjective","t":["olatin"]},{"w":"unexhibitable","d":"Not suitable or possible to display publicly; describing something that cannot be shown or put on exhibit.","s":"The crumbling artifact was deemed unexhibitable because it might fall apart if moved from storage.","p":"un-eg-ZIB-ih-tuh-bul","o":"Latin","y":9,"bp":25,"sy":"un.ex.hibitable","ps":"adjective","t":["olatin"]},{"w":"unexhibitionistic","d":"Not inclined to show off or seek attention from others; describing a person or behavior that avoids public display or self-promotion.","s":"The shy painter was completely unexhibitionistic, preferring to share his work only with close friends.","p":"un-eks-hib-ih-shun-IS-tik","o":"Latin","y":9,"bp":33,"sy":"un.ex.hi.bi.tion.is.tic","ps":"adjective","t":["character","olatin"]},{"w":"unexhilarated","d":"Not feeling excited, energized, or thrilled; describing someone who remains unmoved or unenthusiastic despite a potentially exciting situation.","s":"After the long, dull bus ride, the students arrived unexhilarated and ready for a nap.","p":"un-eg-ZIL-uh-ray-tid","o":"Latin","y":9,"bp":29,"sy":"un.ex.hil.a.rat.ed","ps":"adjective","t":["olatin"]},{"w":"unexhumed","d":"Not having been dug up from the ground; describing a buried body or object that remains in its underground resting place.","s":"The ancient burial site remained unexhumed out of respect for the culture that created it.","p":"un-eks-HYOOMD","o":"Latin","y":8,"bp":28,"sy":"un.ex.humed","ps":"adjective","t":["olatin"]},{"w":"unexiled","d":"Not having been banished or sent away from one's home country or community; allowed to remain in one's place of origin.","s":"The disgraced noble was surprisingly left unexiled and merely stripped of his title.","p":"un-EK-syld","o":"Latin","y":8,"bp":27,"sy":"un.ex.iled","ps":"adjective","t":["olatin"]},{"w":"unexisting","d":"Not currently in existence; describing something that does not exist or has no real presence in the world.","s":"The author described a feeling of being unexisting, as though the world moved right through her.","p":"un-eg-ZIS-ting","o":"Latin","y":8,"bp":30,"sy":"un.ex.ist.ing","ps":"adjective","t":["olatin"]},{"w":"unexorcized","d":"Not having had evil spirits or supernatural forces removed through a ritual; describing a place or person from which demons have not been expelled.","s":"The unexorcized spirit reportedly kept rattling the chains in the old mansion's basement.","p":"un-EK-sor-syzd","o":"Latin","y":8,"bp":37,"sy":"un.ex.or.cized","ps":"adjective","t":["physics","religion","olatin"]},{"w":"unexotic","d":"Not unusual, foreign, or strikingly different from the ordinary; plain and familiar rather than rare or exciting.","s":"The menu was disappointingly unexotic, offering only plain sandwiches and water.","p":"un-eg-ZOT-ik","o":"Latin","y":8,"bp":28,"sy":"un.ex.ot.ic","ps":"adjective","t":["landforms","olatin"]},{"w":"unexpectedness","d":"extraordinariness by virtue of being unexpected","s":"The unexpectedness of the warm welcome.","p":"un-eks-PEK-tid-nes","o":"Latin","y":8,"bp":29,"sy":"un.ex.pect.ed.ness","ps":"noun","t":["logic","olatin"]},{"w":"unexperience","d":"The state of lacking experience or practical knowledge; inexperience with a particular skill or situation.","s":"Years of unexperience in the kitchen showed when he burned the toast twice in a row.","p":"un-eks-PEER-ee-uns","o":"Latin","y":9,"bp":39,"sy":"un.ex.pe.ri.ence","ps":"noun","t":["logic","olatin"]},{"w":"unexperienceable","d":"Impossible to encounter, undergo, or know through personal experience; beyond what any person is able to directly experience.","s":"Some philosophers argue that true enlightenment is unexperienceable by ordinary human minds.","p":"un-eks-PEER-ee-un-suh-bul","o":"Latin","y":9,"bp":32,"sy":"un.ex.pe.ri.ence.able","ps":"adjective","t":["olatin"]},{"w":"unexpert","d":"Not having special skill, training, or expertise in a particular area; lacking the knowledge of a qualified professional.","s":"Her unexpert attempt at knitting produced a scarf that looked more like a tangled net.","p":"un-EK-spurt","o":"Latin","y":8,"bp":27,"sy":"un.ex.pert","ps":"adjective","t":["logic","olatin"]},{"w":"unexpiated","d":"Not having been atoned for or made amends for; describing a wrongdoing or guilt that has not been reconciled or forgiven through proper action.","s":"The character carried the guilt of his unexpiated sins throughout the entire novel.","p":"un-EK-spee-ay-tid","o":"Latin","y":8,"bp":32,"sy":"un.ex.pi.at.ed","ps":"adjective","t":["law","olatin"]},{"w":"unexplainably","d":"In a way that cannot be accounted for or made clear; without any logical or understandable explanation.","s":"The compass needle unexplainably spun in circles whenever they approached the old iron bridge.","p":"un-eks-PLAY-nuh-blee","o":"Latin","y":8,"bp":26,"sy":"un.ex.plain.ably","ps":"adverb","t":["logic","olatin"]},{"w":"unexplanatory","d":"Not serving to explain or clarify; failing to provide information that makes something easier to understand.","s":"The teacher's unexplanatory comments on the essay left students more confused than before.","p":"un-eks-PLAN-uh-tor-ee","o":"Latin","y":9,"bp":28,"sy":"un.ex.plana.to.ry","ps":"adjective","t":["olatin"]},{"w":"unexplicit","d":"Not clearly or directly stated; vague or implied rather than spelled out in precise detail.","s":"The directions were so unexplicit that half the class assembled the model incorrectly.","p":"un-eks-PLIS-it","o":"Latin","y":8,"bp":30,"sy":"un.ex.plic.it","ps":"adjective","t":["olatin"]},{"w":"unexploitable","d":"Not capable of being taken advantage of or used for profit; describing a resource, situation, or weakness that cannot be exploited.","s":"The remote mountain's resources were unexploitable due to the complete lack of roads.","p":"un-eks-PLOY-tuh-bul","o":"Latin","y":9,"bp":25,"sy":"un.ex.ploitable","ps":"adjective","t":["economy","olatin"]},{"w":"unexportable","d":"not suitable for export","s":"The exotic plant was unexportable because customs officials feared it could spread disease.","p":"un-eks-POR-tuh-bul","o":"Latin","y":9,"bp":36,"sy":"un.ex.portable","ps":"adjective","t":["olatin"]},{"w":"unexported","d":"Not having been sent out of a country for trade or sale abroad; describing goods or data that remain within their country or system of origin.","s":"The surplus grain sat unexported in the warehouse as trade negotiations stalled.","p":"un-eks-POR-tid","o":"Latin","y":8,"bp":30,"sy":"un.ex.port.ed","ps":"adjective","t":["economy","olatin"]},{"w":"unexpressible","d":"defying expression","s":"She felt an unexpressible joy when she finally reunited with her long-lost puppy.","p":"un-eks-PRES-uh-bul","o":"Latin","y":9,"bp":26,"sy":"un.ex.press.ible","ps":"adjective","t":["olatin"]},{"w":"unextendible","d":"Not capable of being stretched, lengthened, or expanded further; describing a deadline, material, or term that cannot be made longer.","s":"The contract was unextendible, so the team had to finish the project by Friday no matter what.","p":"un-eks-TEN-duh-bul","o":"Latin","y":9,"bp":36,"sy":"un.ex.tendible","ps":"adjective","t":["olatin"]},{"w":"unexternalized","d":"Not expressed or made visible outwardly; describing thoughts, feelings, or qualities that have been kept internal and never shown to others.","s":"Her grief remained unexternalized; she never cried in front of anyone.","p":"un-eks-TUR-nuh-lyzd","o":"Latin","y":9,"bp":29,"sy":"un.ex.ter.nal.ized","ps":"adjective","t":["olatin"]},{"w":"unextinguishable","d":"Impossible to put out or suppress; describing a fire, feeling, or idea that cannot be stopped or eliminated no matter what force is applied.","s":"The campfire seemed unextinguishable, reigniting every time they poured water on it.","p":"un-eks-TING-gwish-uh-bul","o":"Latin","y":9,"bp":30,"sy":"un.ex.tin.guish.able","ps":"adjective","t":["physics","olatin"]},{"w":"unextinguishably","d":"In a way that cannot be put out or suppressed; describing how a fire, passion, or idea burns on without any possibility of being stopped.","s":"His passion for justice burned unextinguishably throughout decades of setbacks.","p":"un-eks-TING-gwish-uh-blee","o":"Latin","y":9,"bp":30,"sy":"un.ex.tin.guish.ably","ps":"adverb","t":["olatin"]},{"w":"unextraneous","d":"Not unnecessary, irrelevant, or extra; directly related to and relevant to the matter at hand without any superfluous additions.","s":"Every detail in her report was unextraneous, making it sharp and easy to read.","p":"un-eks-TRAY-nee-us","o":"Latin","y":9,"bp":39,"sy":"un.ex.tra.ne.ous","ps":"adjective","t":["numbers","olatin"]},{"w":"unextraordinary","d":"Not remarkable, exceptional, or special in any way; completely ordinary and failing to stand out from the usual.","s":"The meal was pleasant but entirely unextraordinary — just the usual pasta and salad.","p":"un-eks-TROR-duh-nehr-ee","o":"Latin","y":9,"bp":30,"sy":"un.ex.traor.di.nary","ps":"adjective","t":["olatin"]},{"w":"unextricable","d":"Impossible to free, disentangle, or separate from a complicated situation; so deeply entangled that escape or release is not possible.","s":"The fishing line became unextricable from the tangled weeds at the bottom of the pond.","p":"un-EK-strik-uh-bul","o":"Latin","y":9,"bp":39,"sy":"un.ex.tri.ca.ble","ps":"adjective","t":["olatin"]},{"w":"uneyed","d":"Lacking an eye or eyelet; used especially to describe a needle that has no hole through which thread can be passed.","s":"The uneyed needle was useless for sewing since there was no hole for the thread.","p":"un-IDE","o":"Latin","y":8,"bp":18,"sy":"un.eyed","ps":"adjective","t":["olatin"]},{"w":"unfabricated","d":"Not manufactured, invented, or made up; genuine and not constructed from false or artificial materials.","s":"The witness insisted her account was completely unfabricated and entirely the truth.","p":"un-FAB-rih-kay-ted","o":"Latin","y":8,"bp":39,"sy":"un.fab.ri.cat.ed","ps":"adjective","t":["olatin"]},{"w":"unface","d":"To remove the facing or surface covering from something; to strip away an outer layer or decorative front.","s":"The sculptor decided to unface the statue by removing its carved features entirely.","p":"un-FAYSS","o":"Latin","y":8,"bp":18,"sy":"un.face","ps":"verb","t":["olatin"]},{"w":"unfaced","d":"Not having a finished or smooth surface applied; lacking a facing material or decorative outer layer.","s":"The unfaced wall of bricks looked rough and unfinished compared to the polished front.","p":"un-FAYST","o":"Latin","y":8,"bp":19,"sy":"un.faced","ps":"adjective","t":["olatin"]},{"w":"unfaceted","d":"Lacking facets; not cut into flat, polished surfaces as a gemstone would be.","s":"The rough, unfaceted crystal sat on the display shelf, its natural uncut surface glinting softly under the museum's warm spotlight, captivating visitors who had never seen a raw gemstone before.","p":"un-FAS-ih-ted","o":"Latin","y":8,"bp":26,"sy":"un.faceted","ps":"adjective","t":["minerals","olatin"]},{"w":"unfacilitated","d":"Not made easier or assisted by a guide, leader, or supporting resource; left without help or direction to proceed.","s":"The unfacilitated discussion quickly became chaotic without anyone to guide it.","p":"un-fah-SIL-ih-tay-ted","o":"Latin","y":9,"bp":29,"sy":"un.fa.cil.i.tat.ed","ps":"adjective","t":["olatin"]},{"w":"unfactionalized","d":"Not divided into competing factions or opposing groups; remaining unified and without internal splinter groups.","s":"The surprisingly unfactionalized club made decisions quickly because everyone agreed.","p":"un-FAK-shun-ul-ized","o":"Latin","y":9,"bp":30,"sy":"un.fac.tion.al.ized","ps":"adjective","t":["numbers","olatin"]},{"w":"unfactorisable","d":"Impossible to be broken down into smaller factors; describing a number or expression that cannot be factored using whole numbers.","s":"The math teacher showed us a prime number that is unfactorisable into smaller whole numbers.","p":"un-FAK-tor-eye-zuh-bul","o":"Latin","y":9,"bp":27,"sy":"un.fac.toris.able","ps":"adjective","t":["numbers","olatin"]},{"w":"unfactorized","d":"Not yet broken down into its component factors; describing a mathematical expression left in its original unsimplified form.","s":"The algebraic expression remained unfactorized at the top of her worksheet, stumping her for an hour.","p":"un-FAK-tor-ized","o":"Latin","y":8,"bp":38,"sy":"un.fac.tor.ized","ps":"adjective","t":["numbers","olatin"]},{"w":"unfactual","d":"Not based on or consistent with facts; containing information that is inaccurate or unsupported by evidence.","s":"The report was full of unfactual claims that the editor quickly flagged for correction.","p":"un-FAK-choo-ul","o":"Latin","y":8,"bp":29,"sy":"un.fac.tu.al","ps":"adjective","t":["olatin"]},{"w":"unfaith","d":"Lack of faith or belief; a state of disbelief, disloyalty, or absence of trust, especially in a religious context.","s":"The novel explored a character's slow descent into unfaith after years of unanswered prayers.","p":"un-FAYTH","o":"Latin","y":8,"bp":19,"sy":"un.faith","ps":"noun","t":["religion","logic","olatin"]},{"w":"unfaithfully","d":"in an unfaithful undependable unreliable manner","s":"He unfaithfully reported the results, leaving out data that contradicted his theory.","p":"un-FAYTH-ful-ee","o":"Latin","y":9,"bp":38,"sy":"un.faith.ful.ly","ps":"adverb","t":["olatin"]},{"w":"unfaithfulness","d":"the quality of being unfaithful","s":"The unfaithfulness of the ambassador shocked the entire nation when the truth was revealed.","p":"un-FAYTH-ful-nes","o":"Latin","y":8,"bp":27,"sy":"un.faith.ful.ness","ps":"noun","t":["olatin"]},{"w":"unfaked","d":"Genuine and not artificially produced or imitated; authentic and without any pretense or deception.","s":"Her unfaked tears during the movie moved everyone in the theater.","p":"un-FAYKD","o":"Latin","y":8,"bp":19,"sy":"un.faked","ps":"adjective","t":["olatin"]},{"w":"unfalcated","d":"Not curved or hooked like a sickle or falcon's beak; straight rather than having a bent or crescent shape.","s":"The biologist noted the bird's unfalcated beak, straight and unhooked unlike a hawk's.","p":"un-FAL-kay-ted","o":"Latin","y":8,"bp":30,"sy":"un.fal.cat.ed","ps":"adjective","t":["birds","olatin"]},{"w":"unfallen","d":"Not having fallen; still in an original or uncorrupted state, often used in a moral or spiritual sense to describe innocence not yet lost.","s":"The unfallen leaves still clung to the oak tree despite the howling autumn wind.","p":"un-FAW-len","o":"Latin","y":8,"bp":27,"sy":"un.fall.en","ps":"adjective","t":["religion","law","logic","olatin"]},{"w":"unfalling","d":"Not falling; remaining steady and not in a state of descent or decline.","s":"The gymnast's unfalling balance on the beam amazed the crowd.","p":"un-FAW-ling","o":"Latin","y":9,"bp":26,"sy":"un.falling","ps":"adjective","t":["olatin"]},{"w":"unfalse","d":"Not false; true, genuine, and free from deception or falsehood.","s":"The witness gave an unfalse account of what happened at the scene.","p":"un-FAWLS","o":"Latin","y":9,"bp":19,"sy":"un.false","ps":"adjective","t":["olatin"]},{"w":"unfalsified","d":"Not altered, forged, or made to appear different from the truth; remaining in its original, authentic, and genuine form.","s":"The historian was relieved to find the ancient document was unfalsified and completely authentic.","p":"un-FAWL-sih-fied","o":"Latin","y":8,"bp":37,"sy":"un.fal.si.fied","ps":"adjective","t":["logic","olatin"]},{"w":"unfamed","d":"Not famous or widely celebrated; lacking public recognition or renown.","s":"The unfamed artist worked quietly in her studio, never seeking recognition.","p":"un-FAYMD","o":"Latin","y":8,"bp":19,"sy":"un.famed","ps":"adjective","t":["olatin"]},{"w":"unfamilial","d":"Not characteristic of or relating to family bonds or relationships; lacking the warmth, closeness, or typical qualities of a family connection.","s":"His unfamilial attitude made holiday gatherings feel cold and distant.","p":"un-fah-MIL-ee-ul","o":"Latin","y":8,"bp":30,"sy":"un.fa.mil.ial","ps":"adjective","t":["kinship","olatin"]},{"w":"unfamiliarized","d":"Not made acquainted or comfortable with something; remaining a stranger to a subject, place, or skill without having been introduced to it properly.","s":"The new student was still unfamiliarized with the school's schedule after the first week.","p":"un-fah-MIL-yar-ized","o":"Latin","y":9,"bp":29,"sy":"un.fa.mil.iar.ized","ps":"adjective","t":["olatin"]},{"w":"unfancy","d":"Plain and without decoration or elaborate detail; simple and lacking any ornate or fashionable qualities.","s":"She preferred an unfancy meal of soup and bread over an elaborate dinner.","p":"un-FAN-see","o":"Latin","y":8,"bp":20,"sy":"un.fan.cy","ps":"adjective","t":["landforms","fabrics","olatin"]},{"w":"unfang","d":"To remove the fangs from; to render harmless by taking away a creature's sharp pointed teeth.","s":"The zookeeper carefully worked to unfang the model snake used for educational displays.","p":"un-FANG","o":"Latin","y":8,"bp":18,"sy":"un.fang","ps":"verb","t":["body","olatin"]},{"w":"unfarmable","d":"Not capable of being cultivated or used for agricultural purposes; describing land too rocky, poor, or otherwise unsuitable for growing crops.","s":"The rocky, steep hillside was completely unfarmable and left as wilderness.","p":"un-FARM-uh-bul","o":"Latin","y":9,"bp":27,"sy":"un.farmable","ps":"adjective","t":["farming","olatin"]},{"w":"unfashioned","d":"Not yet shaped, formed, or crafted into a finished product; remaining in a raw or unworked state without having been given a definite form.","s":"The lump of clay sat unfashioned on the table, waiting for the sculptor's hands.","p":"un-FASH-und","o":"Latin","y":8,"bp":35,"sy":"un.fash.ioned","ps":"adjective","t":["olatin"]},{"w":"unfasten","d":"cause to become undone","s":"She carefully bent down to unfasten the stubborn buckle on her little brother's backpack, tugging gently so the worn leather strap would not tear any further in the cold morning air.","p":"un-FAS-un","o":"Latin","y":6,"bp":27,"sy":"un.fas.ten","ps":"verb","t":["olatin"]},{"w":"unfastidious","d":"not fussy or hard to please; easily satisfied","s":"He was unfastidious about food and happily ate whatever was put on his plate.","p":"un-fas-TID-ee-us","o":"Latin","y":9,"bp":39,"sy":"un.fas.tid.i.ous","ps":"adjective","t":["olatin"]},{"w":"unfastidiously","d":"In a manner that is not fussy, particular, or demanding about details; acting without excessive pickiness or strict personal standards.","s":"He unfastidiously grabbed whatever clothes were nearby and got dressed in seconds.","p":"un-fas-TID-ee-us-lee","o":"Latin","y":9,"bp":30,"sy":"un.fas.tid.i.ous.ly","ps":"adverb","t":["olatin"]},{"w":"unfastidiousness","d":"The quality or state of not being fussy, overly particular, or excessively demanding; a general willingness to accept things without strict or picky standards.","s":"Her unfastidiousness in eating habits made her an easy guest to feed at any dinner.","p":"un-fas-TID-ee-us-nes","o":"Latin","y":9,"bp":32,"sy":"un.fas.tid.i.ous.ness","ps":"noun","t":["olatin"]},{"w":"unfated","d":"Not destined or predetermined by fate; free from any fixed or inevitable outcome set by destiny.","s":"He believed his future was unfated and entirely shaped by his own choices.","p":"un-FAY-ted","o":"Latin","y":8,"bp":20,"sy":"un.fat.ed","ps":"adjective","t":["olatin"]},{"w":"unfateful","d":"Not carrying great significance or decisive consequence; lacking the weight of a fateful or momentous outcome.","s":"The unfateful afternoon passed quietly, with nothing remarkable happening at all.","p":"un-FAYT-ful","o":"Latin","y":8,"bp":28,"sy":"un.fate.ful","ps":"adjective","t":["numbers","time","olatin"]},{"w":"unfathered","d":"Without a father; lacking paternal parentage or guidance, either literally or figuratively.","s":"The unfathered child grew up strong, guided by a caring community around her.","p":"un-FAH-therd","o":"Latin","y":8,"bp":29,"sy":"un.fa.thered","ps":"adjective","t":["kinship","olatin"]},{"w":"unfatherly","d":"Not behaving in the manner expected of a caring, responsible father; lacking warmth, guidance, or the qualities typical of a good paternal figure.","s":"His unfatherly indifference during his son's recital left everyone in the room uncomfortable.","p":"un-FAH-ther-lee","o":"Latin","y":8,"bp":30,"sy":"un.fa.ther.ly","ps":"adjective","t":["kinship","olatin"]},{"w":"unfathomably","d":"In a way that is impossible to understand, measure, or comprehend fully; to a degree so deep or vast that it defies all attempts at explanation.","s":"The ocean trench was unfathomably deep, stretching miles below the surface.","p":"un-FATH-um-ub-lee","o":"Latin","y":7,"bp":36,"sy":"un.fath.omably","ps":"adverb","t":["numbers","olatin"]},{"w":"unfattened","d":"(of market animals) not optimal for marketing","s":"The unfattened lambs were returned to pasture for several more weeks before market.","p":"un-FAT-end","o":"Latin","y":9,"bp":29,"sy":"un.fat.tened","ps":"adjective","t":["animals","economy","olatin"]},{"w":"unfattening","d":"Not causing weight gain or the accumulation of fat; describing food or activity that does not contribute to becoming fatter.","s":"She chose the unfattening salad over the rich pasta to stay on her diet.","p":"un-FAT-en-ing","o":"Latin","y":9,"bp":37,"sy":"un.fat.ten.ing","ps":"adjective","t":["olatin"]},{"w":"unfaultable","d":"Free from any detectable fault or error; so perfect or correct that no flaw or mistake can be found in it.","s":"The teacher called the student's essay nearly unfaultable in its logic and structure.","p":"un-FAWLT-uh-bul","o":"Latin","y":9,"bp":35,"sy":"un.fault.able","ps":"adjective","t":["olatin"]},{"w":"unfavor'd","d":"Not favored or looked upon with approval; lacking the benefit of special preference, grace, or advantage.","s":"The unfavor'd suitor was turned away at the door of the grand estate.","p":"un-FAY-verd","o":"Latin","y":8,"bp":28,"sy":"un.fa.vor'd","ps":"adjective","t":["olatin"]},{"w":"unfavorite","d":"Not preferred or liked; the opposite of a favorite, referring to something or someone that is least liked or actively disliked.","s":"Math was always his unfavorite subject, making every homework night a struggle.","p":"un-FAY-ver-it","o":"Latin","y":9,"bp":29,"sy":"un.fa.vorite","ps":"adjective","t":["olatin"]},{"w":"unfavour'd","d":"Not shown favor or approval; lacking the support, goodwill, or preference of others. This is an archaic or poetic contracted form.","s":"The unfavour'd candidate received little support despite her passionate speeches.","p":"un-FAY-verd","o":"Latin","y":9,"bp":27,"sy":"un.favour'd","ps":"adjective","t":["law","olatin"]},{"w":"unfavoured","d":"Not regarded with favor or preference; lacking approval, support, or special treatment from others.","s":"The unfavoured team surprised everyone by winning the championship game.","p":"un-FAY-verd","o":"Latin","y":8,"bp":27,"sy":"un.favoured","ps":"adjective","t":["olatin"]},{"w":"unfazed","d":"Not disturbed, bothered, or thrown off balance by a challenge, shock, or difficulty; remaining calm and composed.","s":"The experienced firefighter was unfazed by the chaos erupting around her.","p":"uh-NFAY-zd","o":"Latin","y":4,"bp":19,"sy":"ah.nfey.zd","ps":"adjective","t":["olatin"]},{"w":"unfeared","d":"Not regarded with fear or dread; not considered frightening or threatening by others.","s":"The gentle giant was unfeared by the village children who played around him daily.","p":"un-FEERD","o":"Latin","y":8,"bp":25,"sy":"un.feared","ps":"adjective","t":["emotions","olatin"]},{"w":"unfearful","d":"Free from fear; not experiencing or showing fright or apprehension in the face of danger or uncertainty.","s":"The unfearful explorer dove into the dark cave without a moment's hesitation.","p":"un-FEER-ful","o":"Latin","y":8,"bp":28,"sy":"un.fear.ful","ps":"adjective","t":["emotions","olatin"]},{"w":"unfearfully","d":"In a manner that is free from fear; boldly and without showing any sign of fright or apprehension.","s":"She unfearfully stepped onto the stage in front of hundreds of strangers.","p":"un-FEER-ful-ee","o":"Latin","y":9,"bp":37,"sy":"un.fear.ful.ly","ps":"adverb","t":["emotions","olatin"]},{"w":"unfearing","d":"Not susceptible to fear or intimidation; remaining bold and composed even in threatening or dangerous situations.","s":"The unfearing young explorer descended into the dark cave without hesitation, her torch cutting through the shadows while her teammates waited nervously at the entrance above.","p":"un-FEER-ing","o":"Latin","y":8,"bp":28,"sy":"un.fear.ing","ps":"adjective","t":["emotions","olatin"]},{"w":"unfearingly","d":"In a way that shows no fear whatsoever; acting boldly and without any trace of apprehension or dread.","s":"The child unfearingly climbed to the very top of the tall oak tree.","p":"un-FEER-ing-lee","o":"Latin","y":8,"bp":37,"sy":"un.fear.ing.ly","ps":"adverb","t":["emotions","olatin"]},{"w":"unfeasibility","d":"the quality of not being doable","s":"The engineer reported the unfeasibility of building a bridge across that raging river.","p":"un-fee-zuh-BIL-ih-tee","o":"Latin","y":9,"bp":29,"sy":"un.fea.si.bil.i.ty","ps":"noun","t":["olatin"]},{"w":"unfeather","d":"To strip or remove the feathers from a bird or feathered object; to deprive of its feathered covering.","s":"The chef had to unfeather the duck before preparing it for the feast.","p":"un-FETH-er","o":"Latin","y":8,"bp":28,"sy":"un.feath.er","ps":"verb","t":["birds","olatin"]},{"w":"unfeathered","d":"having no feathers","s":"The unfeathered chick lay helpless in the nest, its pink skin exposed to the cool morning air while its mother searched tirelessly for food among the nearby trees.","p":"un-FETH-erd","o":"Latin","y":7,"bp":35,"sy":"un.feath.ered","ps":"adjective","t":["birds","olatin"]},{"w":"unfeatured","d":"Lacking distinctive or notable features; not highlighted or showcased; without prominent facial or physical characteristics.","s":"The unfeatured background character blended into the scenery without drawing any attention.","p":"un-FEE-cherd","o":"Latin","y":8,"bp":29,"sy":"un.fea.tured","ps":"adjective","t":["olatin"]},{"w":"unfecund","d":"Not fertile or productive; incapable of producing offspring, crops, or creative output; barren or unproductive.","s":"The dry, rocky soil proved unfecund, producing almost no crops that summer.","p":"un-FEE-kund","o":"Latin","y":8,"bp":27,"sy":"un.fe.cund","ps":"adjective","t":["farming","olatin"]},{"w":"unfeelingly","d":"without compassionate feelings","s":"Unfeelingly, she required her maid to work on Christmas Day.","p":"un-FEEL-ing-lee","o":"Latin","y":8,"bp":37,"sy":"un.feel.ing.ly","ps":"adverb","t":["maps","olatin"]},{"w":"unfeelingness","d":"devoid of passion or feeling; hardheartedness","s":"Her unfeelingness toward the stray animals shocked everyone in the neighborhood.","p":"un-FEEL-ing-nes","o":"Latin","y":9,"bp":26,"sy":"un.feel.ing.ness","ps":"noun","t":["olatin"]},{"w":"unfelicitous","d":"Not well-chosen, appropriate, or pleasing; awkward, ill-suited, or unfortunate in expression or timing.","s":"His unfelicitous choice of words during the ceremony made everyone cringe.","p":"un-feh-LIS-ih-tus","o":"Latin","y":9,"bp":39,"sy":"un.fe.lic.i.tous","ps":"adjective","t":["olatin"]},{"w":"unfelicitously","d":"In a manner that is ill-suited, awkward, or inappropriate; not in a pleasingly apt or fortunate way.","s":"She unfelicitously brought up an old argument right before the party began.","p":"un-feh-LIS-ih-tus-lee","o":"Latin","y":9,"bp":30,"sy":"un.fe.lic.i.tous.ly","ps":"adverb","t":["olatin"]},{"w":"unfeminist","d":"Not aligned with or contrary to feminist principles and beliefs; opposing or inconsistent with the advocacy of equal rights for women.","s":"Some critics labeled the movie's portrayal of women as unfeminist and outdated.","p":"un-FEM-ih-nist","o":"Latin","y":8,"bp":30,"sy":"un.fem.i.nist","ps":"adjective","t":["logic","olatin"]},{"w":"unfence","d":"To remove a fence or barrier from an area; to open up an enclosed space by taking down its fencing.","s":"The farmer decided to unfence the pasture so the horses could roam freely.","p":"un-FENTS","o":"Latin","y":9,"bp":19,"sy":"un.fence","ps":"verb","t":["sports","olatin"]},{"w":"unfermentable","d":"Not capable of undergoing fermentation; describing a substance that cannot be broken down by yeast or bacteria to produce alcohol or gas.","s":"The scientist discovered that the new sugar compound was completely unfermentable.","p":"un-fer-MEN-tuh-bul","o":"Latin","y":9,"bp":25,"sy":"un.fer.mentable","ps":"adjective","t":["disease","chemistry","olatin"]},{"w":"unfervent","d":"Lacking warmth, passion, or intensity of feeling; not fervent or enthusiastic; cool and indifferent.","s":"His unfervent applause at the end of the show disappointed the performers.","p":"un-FER-vent","o":"Latin","y":8,"bp":28,"sy":"un.fer.vent","ps":"adjective","t":["olatin"]},{"w":"unfetching","d":"Not attractive, appealing, or charming; failing to draw interest or admiration from others.","s":"The dull grey walls made the room look utterly unfetching and uninviting.","p":"un-FECH-ing","o":"Latin","y":9,"bp":29,"sy":"un.fetch.ing","ps":"adjective","t":["olatin"]},{"w":"unfetter","d":"To release from chains, restraints, or restrictions; to set free from anything that confines or limits.","s":"The new law was designed to unfetter small businesses from excessive regulations.","p":"un-FET-er","o":"Latin","y":9,"bp":27,"sy":"un.fet.ter","ps":"verb","t":["olatin"]},{"w":"unfeudalize","d":"To free from or abolish the feudal system; to remove feudal structures, obligations, or hierarchies from a society or institution.","s":"The revolution sought to unfeudalize the land and distribute it among the peasants.","p":"un-FYOO-dul-yz","o":"Latin","y":9,"bp":37,"sy":"un.feu.dal.ize","ps":"verb","t":["olatin"]},{"w":"unfeverish","d":"Not having or showing signs of a fever; calm and cool in temperature or temperament, without the agitation associated with fever.","s":"After two days of illness, she finally felt calm and unfeverish.","p":"un-FEE-ver-ish","o":"Latin","y":8,"bp":29,"sy":"un.fever.ish","ps":"adjective","t":["disease","character","olatin"]},{"w":"unfictionalized","d":"Not altered or dramatized for fictional purposes; presented as real events or facts without creative embellishment or storytelling changes.","s":"The unfictionalized account of the rescue mission was more thrilling than any novel.","p":"un-FIK-shun-ul-yzd","o":"Latin","y":9,"bp":30,"sy":"un.fic.tion.al.ized","ps":"adjective","t":["stage","poetry","olatin"]},{"w":"unfiery","d":"Lacking fire, passion, or intense heat; not fiery in temperament, appearance, or effect; calm and without strong emotion.","s":"His unfiery speech failed to inspire the crowd on such an important day.","p":"un-FY-er-ee","o":"Latin","y":8,"bp":19,"sy":"un.fiery","ps":"adjective","t":["character","emotions","olatin"]},{"w":"unfightable","d":"Impossible or impractical to fight against or resist; describing an opponent or force that cannot be effectively challenged or combated.","s":"The disease felt unfightable at first, but the doctors refused to give up.","p":"un-FY-tuh-bul","o":"Latin","y":9,"bp":35,"sy":"un.fight.able","ps":"adjective","t":["physics","war","olatin"]},{"w":"unfigured","d":"Without figures, patterns, or ornamentation; plain and undecorated; also, not represented or depicted in a figure or diagram.","s":"The plain, unfigured fabric was chosen because it wouldn't clash with the patterned curtains.","p":"un-FIG-yerd","o":"Latin","y":9,"bp":28,"sy":"un.fig.ured","ps":"adjective","t":["landforms","olatin"]},{"w":"unfilial","d":"Not showing the respect, love, or duty expected of a child toward a parent; behaving in a way that is improper or disrespectful for a son or daughter.","s":"Ignoring his elderly parents' calls was considered deeply unfilial in his culture.","p":"un-FIL-ee-ul","o":"Latin","y":7,"bp":27,"sy":"un.fil.ial","ps":"adjective","t":["kinship","olatin"]},{"w":"unfilleted","d":"Not having been cut into fillets; still in whole form with bones intact, referring especially to fish or meat that has not been prepared by boning.","s":"The chef served the unfilleted fish whole, bones and all, as a traditional dish.","p":"un-FIL-ih-tid","o":"Latin","y":9,"bp":30,"sy":"un.fil.let.ed","ps":"adjective","t":["body","marine","olatin"]},{"w":"unfilmable","d":"Not suitable or possible to adapt into a film; describing a story, scene, or concept that cannot be effectively translated to the screen.","s":"Many readers argued that the complex novel was completely unfilmable.","p":"un-FIL-muh-bul","o":"Latin","y":8,"bp":27,"sy":"un.filmable","ps":"adjective","t":["poetry","wordwords","olatin"]},{"w":"unfilmed","d":"not recorded on film or tape","s":"The unfilmed sequel was described only in the author's private notes.","p":"un-FILMD","o":"Latin","y":7,"bp":25,"sy":"un.filmed","ps":"adjective","t":["olatin"]},{"w":"unfiltered","d":"Not passed through a filter; raw and unprocessed; also used figuratively to mean direct, uncensored, and without any editing or softening.","s":"She gave her unfiltered opinion on the artwork, which surprised everyone in the room.","p":"uh-NFIH-lter-d","o":"Latin","y":5,"bp":29,"sy":"ah.nfih.lter.d","ps":"adjective","t":["olatin"]},{"w":"unfinalized","d":"Not yet brought to a final or completed state; still in progress or subject to change; not officially concluded or settled.","s":"The contract remained unfinalized because both sides still disagreed on one key detail.","p":"un-FY-nuh-lyzd","o":"Latin","y":8,"bp":37,"sy":"un.fi.nal.ized","ps":"adjective","t":["olatin"]},{"w":"unfinanceable","d":"Not able to be funded or financed; describing a project or venture for which no financial backing or loans can be secured.","s":"The ambitious space project was deemed unfinanceable without international support.","p":"un-fih-NAN-suh-bul","o":"Latin","y":9,"bp":26,"sy":"un.fi.nance.able","ps":"adjective","t":["olatin"]},{"w":"unfinanced","d":"Not provided with financial support or funding; lacking the monetary backing needed to proceed or operate.","s":"The community center sat unfinanced and half-built for three years.","p":"un-fih-NANST","o":"Latin","y":8,"bp":29,"sy":"un.fi.nanced","ps":"adjective","t":["olatin"]},{"w":"unfined","d":"Not clarified or purified through a fining process; used especially of liquids such as wine or beer that have not had impurities removed.","s":"The winemaker preferred an unfined wine that retained its natural cloudiness.","p":"un-FYND","o":"Latin","y":8,"bp":19,"sy":"un.fined","ps":"adjective","t":["olatin"]},{"w":"unfingered","d":"Never touched or handled by fingers; also, in music, lacking fingering marks to guide a player's technique.","s":"The unfingered pages of the old book suggested it had never been read.","p":"un-FING-erd","o":"Latin","y":8,"bp":29,"sy":"un.fin.gered","ps":"adjective","t":["music","sports","olatin"]},{"w":"unfinicky","d":"Not overly particular or fussy, especially about food or details; easygoing and accepting of whatever is offered.","s":"Our unfinicky dog happily ate whatever food was placed in front of him.","p":"un-FIN-ih-kee","o":"Latin","y":8,"bp":26,"sy":"un.finicky","ps":"adjective","t":["olatin"]},{"w":"unfinned","d":"Lacking fins; describing a fish, rocket, or other object that has no fins attached to its body.","s":"Scientists were puzzled by the unfinned fish they discovered in the deep ocean.","p":"un-FIND","o":"Latin","y":8,"bp":25,"sy":"un.finned","ps":"adjective","t":["marine","vehicles","olatin"]},{"w":"unfishable","d":"Describing a body of water or area that cannot be fished, either because it is inaccessible, too polluted, or simply contains no catchable fish.","s":"The polluted river was declared unfishable by local environmental authorities.","p":"un-FISH-uh-bul","o":"Latin","y":9,"bp":29,"sy":"un.fish.able","ps":"adjective","t":["marine","olatin"]},{"w":"unfishlike","d":"Not resembling a fish in appearance, movement, or behavior; lacking the typical characteristics associated with fish.","s":"The odd creature moved in an unfishlike way, crawling rather than swimming.","p":"un-FISH-lyk","o":"Latin","y":9,"bp":29,"sy":"un.fish.like","ps":"adjective","t":["marine","olatin"]},{"w":"unfishy","d":"Having no fishy odor, taste, or quality; also, not suspicious or questionable in any way.","s":"The new seafood restaurant's dishes had an surprisingly unfishy, mild taste.","p":"un-FISH-ee","o":"Latin","y":8,"bp":19,"sy":"un.fishy","ps":"adjective","t":["olatin"]},{"w":"unfissured","d":"Having no cracks, splits, or fissures; completely smooth and unbroken in surface or structure.","s":"The geologist was amazed to find a completely unfissured rock formation after the earthquake.","p":"un-FISH-erd","o":"Latin","y":9,"bp":29,"sy":"un.fis.sured","ps":"adjective","t":["olatin"]},{"w":"unfixable","d":"Impossible to repair, correct, or set right; describing a problem or object that is beyond any remedy.","s":"The damage to the ancient vase was unfixable, leaving the museum heartbroken.","p":"un-FIK-suh-bul","o":"Latin","y":7,"bp":28,"sy":"un.fix.able","ps":"adjective","t":["pharmacy","olatin"]},{"w":"unfixably","d":"In a manner that cannot be repaired or corrected; to a degree that is entirely beyond fixing.","s":"The old clock was unfixably broken, so it became a decoration instead.","p":"un-FIK-suh-blee","o":"Latin","y":8,"bp":28,"sy":"un.fix.ably","ps":"adverb","t":["olatin"]},{"w":"unfixt","d":"An archaic or poetic form of 'unfixed,' meaning not fastened, settled, or determined; in a state of instability or uncertainty.","s":"In the old poem, the wandering star was described as unfixt in the endless sky.","p":"un-FIKST","o":"Latin","y":8,"bp":18,"sy":"un.fixt","ps":"adjective","t":["olatin"]},{"w":"unfizzy","d":"Lacking carbonation or bubbles; describing a beverage or substance that is flat and without effervescence.","s":"After being left open overnight, the soda became completely unfizzy and flat.","p":"un-FIZ-ee","o":"Latin","y":8,"bp":19,"sy":"un.fizzy","ps":"adjective","t":["dishes","olatin"]},{"w":"unflabby","d":"Not soft, loose, or flabby; firm and toned in body or substance, showing no excess flab.","s":"After months of training, his unflabby arms showed just how hard he had worked.","p":"un-FLAB-ee","o":"Latin","y":8,"bp":27,"sy":"un.flab.by","ps":"adjective","t":["olatin"]},{"w":"unflag","d":"To revive or restore energy and enthusiasm after a period of drooping or weakening; to lift what has flagged.","s":"The coach's inspiring words helped unflag the team's spirit before the final quarter.","p":"un-FLAG","o":"Latin","y":8,"bp":18,"sy":"un.flag","ps":"verb","t":["physics","olatin"]},{"w":"unflanged","d":"Lacking a flange, which is a projecting rim or edge used to strengthen or attach something; having a smooth, unrimmed edge.","s":"The engineer noted that the unflanged pipe would need a special connector to fit securely.","p":"un-FLANJD","o":"Latin","y":8,"bp":26,"sy":"un.flanged","ps":"adjective","t":["olatin"]},{"w":"unflappableness","d":"The quality of staying calm and composed under pressure or stress; the state of not being easily flustered or upset by difficult situations.","s":"Her unflappableness during the fire drill impressed every teacher in the building.","p":"un-FLAP-uh-bul-nes","o":"English","y":9,"bp":28,"sy":"un.flap.pable.ness","ps":"noun","t":[]},{"w":"unflashy","d":"Not showy, gaudy, or attention-grabbing; modest and understated in appearance or style.","s":"The champion's unflashy style fooled opponents who expected showboating.","p":"un-FLASH-ee","o":"Latin","y":8,"bp":25,"sy":"un.flashy","ps":"adjective","t":["olatin"]},{"w":"unflatten","d":"To restore something to its original three-dimensional or rounded shape after it has been made flat; to reverse the flattening of something.","s":"The baker tried to unflatten the dough by folding air back into it.","p":"un-FLAT-en","o":"Latin","y":9,"bp":28,"sy":"un.flat.ten","ps":"verb","t":["olatin"]},{"w":"unflattered","d":"Not praised, complimented, or made to feel special; receiving no flattery or favorable attention from others.","s":"She felt unflattered when her painting received only a polite nod from the judges.","p":"un-FLAT-erd","o":"Latin","y":9,"bp":35,"sy":"un.flat.tered","ps":"adjective","t":["olatin"]},{"w":"unflawed","d":"Without any flaws, defects, or imperfections; completely perfect in form or quality.","s":"The jeweler examined the diamond carefully and declared it absolutely unflawed, making it one of the most valuable gems he had ever seen in his long career.","p":"un-FLAWD","o":"Latin","y":7,"bp":25,"sy":"un.flawed","ps":"adjective","t":["olatin"]},{"w":"unflecked","d":"Having no flecks, spots, or small marks; describing a surface that is completely clean and uniform in color or texture.","s":"The freshly painted wall was completely unflecked, without a single spot or speck.","p":"un-FLEKT","o":"Latin","y":8,"bp":26,"sy":"un.flecked","ps":"adjective","t":["colors","olatin"]},{"w":"unflesh","d":"To strip away the flesh from; to remove bodily or physical substance, leaving only the spiritual or skeletal essence.","s":"The ancient ritual was said to unflesh the spirit, freeing it from its physical form.","p":"un-FLESH","o":"Latin","y":8,"bp":19,"sy":"un.flesh","ps":"verb","t":["religion","olatin"]},{"w":"unfleshed","d":"Stripped of flesh; reduced to bare bones or a purely spiritual state, lacking physical or bodily substance.","s":"The skeleton in the museum display was completely unfleshed, showing only bare bone.","p":"un-FLESHT","o":"Latin","y":8,"bp":26,"sy":"un.fleshed","ps":"adjective","t":["body","religion","olatin"]},{"w":"unfleshly","d":"Not of or relating to the physical body or carnal desires; spiritual, incorporeal, or transcending bodily nature.","s":"The monk devoted himself to unfleshly pursuits, meditating for hours each day.","p":"un-FLESH-lee","o":"Latin","y":8,"bp":28,"sy":"un.flesh.ly","ps":"adjective","t":["religion","olatin"]},{"w":"unflexible","d":"An older or variant form of 'inflexible,' meaning not capable of bending or being changed; rigid and unyielding in body or opinion.","s":"The old plastic ruler had become unflexible after years of sitting in the sun.","p":"un-FLEK-sih-bul","o":"Latin","y":9,"bp":30,"sy":"un.flex.i.ble","ps":"adjective","t":["olatin"]},{"w":"unflickering","d":"Not flickering or wavering; burning or shining with a perfectly steady, constant light that never wavers.","s":"The LED candle produced an unflickering glow that lit the dinner table evenly.","p":"un-FLIK-er-ing","o":"Latin","y":8,"bp":38,"sy":"un.flick.er.ing","ps":"adjective","t":["olatin"]},{"w":"unflighted","d":"Never having taken flight; describing a bird, aircraft, or projectile that has not yet flown or been launched into the air.","s":"The unflighted model rocket was displayed on the shelf but never actually launched.","p":"un-FLY-ted","o":"Latin","y":8,"bp":29,"sy":"un.flight.ed","ps":"adjective","t":["birds","vehicles","olatin"]},{"w":"unflippable","d":"Impossible to flip or turn over; so stable or heavy that it cannot be overturned, reversed, or changed.","s":"The weighted base made the trophy unflippable, no matter how hard the kids bumped the table.","p":"un-FLIP-uh-bul","o":"Latin","y":9,"bp":35,"sy":"un.flip.pable","ps":"adjective","t":["olatin"]},{"w":"unflipped","d":"Not flipped, turned over, or reversed; remaining in its original position or orientation without being overturned.","s":"The pancake sat unflipped in the pan until the edges turned golden.","p":"un-FLIPT","o":"Latin","y":8,"bp":26,"sy":"un.flipped","ps":"adjective","t":["olatin"]},{"w":"unflirtatious","d":"Not given to flirting or playful romantic teasing; serious and straightforward in social interactions without any coquettish behavior.","s":"His unflirtatious manner made it easy for everyone to feel comfortable around him.","p":"un-flir-TAY-shus","o":"Latin","y":9,"bp":26,"sy":"un.flir.ta.tious","ps":"adjective","t":["ancient","olatin"]},{"w":"unflogged","d":"Not whipped, beaten, or subjected to flogging as punishment; spared from a physical lashing.","s":"The unflogged horse trotted calmly without any sign of fear.","p":"un-FLOGD","o":"Latin","y":8,"bp":26,"sy":"un.flogged","ps":"adjective","t":["olatin"]},{"w":"unflooded","d":"Not submerged or filled with floodwater; describing land or a structure that has remained dry despite flooding conditions nearby.","s":"Remarkably, the basement remained unflooded despite the record rainfall overnight.","p":"un-FLUD-ed","o":"Latin","y":8,"bp":28,"sy":"un.flood.ed","ps":"adjective","t":["waterways","olatin"]},{"w":"unflorid","d":"Not overly ornate, flushed, or excessively elaborate in style or complexion; plain and restrained rather than flowery or ruddy.","s":"The speaker's unflorid language made the complex topic easy to understand.","p":"un-FLOR-id","o":"Latin","y":8,"bp":25,"sy":"un.florid","ps":"adjective","t":["flowers","landforms","olatin"]},{"w":"unflossed","d":"Not cleaned with dental floss; describing teeth or gums that have not had floss used between them.","s":"The dentist could tell right away that his teeth had been unflossed for months.","p":"un-FLOSST","o":"Latin","y":8,"bp":26,"sy":"un.flossed","ps":"adjective","t":["body","olatin"]},{"w":"unflowering","d":"Not producing flowers; describing a plant that has not yet bloomed or that is incapable of producing blossoms.","s":"The unflowering cactus sat in the corner, green but stubbornly bloomless all winter.","p":"un-FLOW-er-ing","o":"Latin","y":8,"bp":37,"sy":"un.flow.er.ing","ps":"adjective","t":["botany","flowers","olatin"]},{"w":"unflowery","d":"Not resembling or characteristic of flowers; lacking floral scent, color, or ornamental quality; plain and unadorned.","s":"Her unflowery writing style was direct and refreshingly free of overdone description.","p":"un-FLOW-er-ee","o":"Latin","y":8,"bp":28,"sy":"un.flow.ery","ps":"adjective","t":["flowers","landforms","colors","olatin"]},{"w":"unfluctuating","d":"not liable to fluctuate or especially to fall","p":"un-FLUK-choo-ay-ting","o":"Latin","y":9,"bp":28,"sy":"un.fluc.tu.at.ing","ps":"adjective","t":["olatin"]},{"w":"unfluent","d":"Not fluent; lacking smoothness or ease in speaking, writing, or moving; halting and struggling to express ideas clearly.","s":"The unfluent presenter stumbled over technical terms he had barely practiced.","p":"un-FLOO-ent","o":"Latin","y":8,"bp":27,"sy":"un.flu.ent","ps":"adjective","t":["olatin"]},{"w":"unfluidized","d":"Not converted into or treated as a fluid; describing a substance, especially a powder or solid, that has not been made to flow like a liquid through industrial or chemical processes.","s":"The sand remained unfluidized in the container until air was pumped through it.","p":"un-FLOO-ih-dyzd","o":"Latin","y":8,"bp":35,"sy":"un.flu.idized","ps":"adjective","t":["chemistry","olatin"]},{"w":"unflushed","d":"Not flushed; describing a toilet that has not been flushed, or a face that has not reddened, or a system that has not been cleared by a rush of water.","s":"Someone left the toilet unflushed, which caused an embarrassing scene at the party.","p":"un-FLUSHT","o":"Latin","y":7,"bp":26,"sy":"un.flushed","ps":"adjective","t":["olatin"]},{"w":"unfluted","d":"Lacking flutes, which are the rounded grooves or channels carved into columns, glassware, or other surfaces; having a plain, smooth surface without decorative ridges.","s":"The architect chose unfluted columns for a smoother, more modern appearance.","p":"un-FLOO-ted","o":"Latin","y":8,"bp":27,"sy":"un.flut.ed","ps":"adjective","t":["landforms","buildings","music","olatin"]},{"w":"unflyable","d":"Describing conditions or an aircraft that make flying impossible or unsafe; not suitable or able to be flown.","s":"High winds made conditions unflyable, so the air show was postponed until Sunday.","p":"un-FLY-uh-bul","o":"Latin","y":9,"bp":28,"sy":"un.fly.able","ps":"adjective","t":["vehicles","olatin"]},{"w":"unfocus","d":"To cause something to lose its sharp focus or clear direction; to blur or scatter attention away from a central point.","s":"He tried to unfocus his mind from the test results by taking a long walk.","p":"un-FOH-kus","o":"Latin","y":7,"bp":20,"sy":"un.fo.cus","ps":"verb","t":["olatin"]},{"w":"unfocusable","d":"Impossible to bring into focus or sharp clarity; describing something that cannot be concentrated or made distinct.","s":"The old lens was unfocusable, producing nothing but blurry photographs.","p":"un-FOH-kus-uh-bul","o":"Latin","y":9,"bp":37,"sy":"un.fo.cus.able","ps":"adjective","t":["olatin"]},{"w":"unfogged","d":"Cleared of fog or haze; describing a surface, lens, or mind that has been made free from cloudiness or obscurity.","s":"Once she wiped the mirror, the unfogged surface reflected her face clearly.","p":"un-FOGD","o":"Latin","y":8,"bp":25,"sy":"un.fogged","ps":"adjective","t":["weather","physics","olatin"]},{"w":"unfoldable","d":"Not capable of being unfolded or opened out flat; impossible to spread out from a folded state.","s":"The map was so old and brittle it seemed nearly unfoldable without tearing.","p":"un-FOHL-duh-bul","o":"Latin","y":9,"bp":29,"sy":"un.fold.able","ps":"adjective","t":["olatin"]},{"w":"unfoldment","d":"The gradual process of opening up, developing, or revealing something; the unfolding of events, ideas, or potential over time.","s":"The documentary traced the unfoldment of the young inventor's remarkable career.","p":"un-FOHLD-munt","o":"Latin","y":7,"bp":29,"sy":"un.fold.ment","ps":"noun","t":["time","olatin"]},{"w":"unfollow","d":"To stop following someone on a social media platform or online service, ending the automatic receipt of their updates or posts.","s":"She decided to unfollow the account after it posted nothing but advertisements.","p":"un-FOL-oh","o":"Latin","y":6,"bp":27,"sy":"un.fol.low","ps":"verb","t":["olatin"]},{"w":"unfond","d":"Not fond or affectionate; lacking warmth, liking, or attachment toward someone or something.","s":"He was unfond of spicy food, so he always ordered the mildest dish on the menu.","p":"un-FOND","o":"Latin","y":8,"bp":18,"sy":"un.fond","ps":"adjective","t":["emotions","olatin"]},{"w":"unfoolable","d":"Impossible to trick or deceive; describing a person so perceptive and shrewd that no deception can work on them.","s":"The experienced detective was unfoolable, spotting every trick the suspect tried.","p":"un-FOOL-uh-bul","o":"Latin","y":9,"bp":27,"sy":"un.foolable","ps":"adjective","t":["olatin"]},{"w":"unfooled","d":"Not deceived or tricked; having seen through an attempt at deception and remained unaffected by it.","s":"Even the youngest student was unfooled by the obvious April Fools' prank.","p":"un-FOOLD","o":"Latin","y":8,"bp":25,"sy":"un.fooled","ps":"adjective","t":["olatin"]},{"w":"unfootprinted","d":"Leaving no trace, mark, or record of presence; describing a person, animal, or system that has passed through without any detectable impact.","s":"The fresh snow was completely unfootprinted, a perfect white blanket across the yard.","p":"un-FOOT-prin-tid","o":"Latin","y":9,"bp":26,"sy":"un.foot.print.ed","ps":"adjective","t":["animals","olatin"]},{"w":"unforbid","d":"To remove a prohibition or ban; to permit something that was previously forbidden or restricted.","s":"The principal moved to unforbid cell phones during lunch after hearing student feedback.","p":"un-for-BID","o":"Latin","y":8,"bp":27,"sy":"un.for.bid","ps":"verb","t":["olatin"]},{"w":"unforbidden","d":"No longer prohibited or banned; allowed or permitted after previously being forbidden.","s":"Laughter was unforbidden in that classroom, making every lesson more enjoyable.","p":"un-for-BID-un","o":"Latin","y":9,"bp":37,"sy":"un.for.bid.den","ps":"adjective","t":["olatin"]},{"w":"unforceful","d":"lacking force; feeble","p":"un-FORS-ful","o":"Latin","y":8,"bp":29,"sy":"un.force.ful","ps":"adjective","t":["physics","olatin"]},{"w":"unforcefully","d":"In a manner that lacks force, strength, or assertiveness; feebly or without conviction or power.","s":"She unforcefully suggested a change, and no one paid attention.","p":"un-FORS-ful-ee","o":"Latin","y":9,"bp":38,"sy":"un.force.ful.ly","ps":"adverb","t":["physics","olatin"]},{"w":"unfordable","d":"Impossible to cross by wading; describing a body of water too deep, wide, or fast-moving to ford on foot.","s":"After the storm, the river was unfordable and the hikers had to turn back.","p":"un-FOR-duh-bul","o":"Latin","y":9,"bp":29,"sy":"un.ford.able","ps":"adjective","t":["olatin"]},{"w":"unforeknown","d":"Not known or predicted in advance; describing an event or outcome that was not foreseen before it occurred.","s":"The disaster was unforeknown, striking the village without any warning.","p":"un-for-NOHN","o":"Latin","y":8,"bp":35,"sy":"un.fore.known","ps":"adjective","t":["olatin"]},{"w":"unforeseeability","d":"The quality or state of being impossible to predict or anticipate in advance; the condition of an event being beyond reasonable foresight.","s":"The judge cited the unforeseeability of the accident as a reason to reduce the penalty.","p":"un-for-see-uh-BIL-ih-tee","o":"Latin","y":9,"bp":32,"sy":"un.fore.see.abil.i.ty","ps":"noun","t":["olatin"]},{"w":"unforeseeing","d":"Lacking the ability or tendency to predict or anticipate future events; not looking ahead to possible consequences.","s":"The unforeseeing manager was caught off guard when half his staff quit at once.","p":"un-for-SEE-ing","o":"Latin","y":9,"bp":38,"sy":"un.fore.see.ing","ps":"adjective","t":["olatin"]},{"w":"unforesighted","d":"Lacking foresight or the ability to plan for or predict future events; shortsighted with regard to future consequences.","s":"His unforesighted spending left him broke by the end of the month.","p":"un-for-SY-tid","o":"Latin","y":9,"bp":26,"sy":"un.fore.sight.ed","ps":"adjective","t":["olatin"]},{"w":"unforestallable","d":"Impossible to prevent, intercept, or stop before it happens; describing an event or action that cannot be forestalled by any means.","s":"The avalanche was unforestallable despite the team's best safety measures.","p":"un-for-STAWL-uh-bul","o":"Latin","y":9,"bp":28,"sy":"un.fore.stal.lable","ps":"adjective","t":["olatin"]},{"w":"unforetold","d":"Not predicted or prophesied in advance; describing an event that no one foretold or announced before it occurred.","s":"The scientist's amazing discovery was unforetold by any previous research.","p":"un-for-TOHLD","o":"Latin","y":8,"bp":29,"sy":"un.fore.told","ps":"adjective","t":["olatin"]},{"w":"unforged","d":"Not forged, fabricated, or falsified; genuine and authentic, or not yet shaped by a forge or manufacturing process.","s":"The historian confirmed the document was unforged and genuinely ancient.","p":"un-FORJD","o":"Latin","y":8,"bp":25,"sy":"un.forged","ps":"adjective","t":["fabrics","olatin"]},{"w":"unforgetful","d":"Not inclined to forget; having a strong or persistent memory that retains information and experiences reliably.","s":"She was unforgetful of every kindness shown to her as a child.","p":"un-for-GET-ful","o":"Latin","y":8,"bp":37,"sy":"un.for.get.ful","ps":"adjective","t":["character","olatin"]},{"w":"unforgetting","d":"Persistently retaining memories; refusing or unable to forget past events, experiences, or wrongs.","s":"His unforgetting mind stored every detail of the accident for years.","p":"un-for-GET-ing","o":"Latin","y":9,"bp":38,"sy":"un.for.get.ting","ps":"adjective","t":["olatin"]},{"w":"unforgettingly","d":"In a manner that retains all memories without letting go; persistently and without any lapse of recollection.","s":"She unforgettingly recalled the teacher's cruel remark even decades later.","p":"un-for-GET-ing-lee","o":"Latin","y":9,"bp":29,"sy":"un.for.get.ting.ly","ps":"adverb","t":["olatin"]},{"w":"unforgivingly","d":"without forgiveness; in an unforgiving manner","s":"Unforgivingly, he insisted that she pay her debt to the last penny.","p":"un-for-GIV-ing-lee","o":"Latin","y":9,"bp":28,"sy":"un.for.giv.ing.ly","ps":"adverb","t":["olatin"]},{"w":"unforgivingness","d":"The quality or state of being unforgiving; a persistent refusal to pardon offenses or show mercy toward those who have caused harm.","s":"Her unforgivingness prevented her from repairing the friendship for many years.","p":"un-for-GIV-ing-nes","o":"Latin","y":9,"bp":30,"sy":"un.for.giv.ing.ness","ps":"noun","t":["olatin"]},{"w":"unforgot","d":"Not forgotten; remaining in memory or consciousness without fading or being lost over time.","s":"The soldiers' sacrifice was unforgot by the grateful citizens of the town.","p":"un-for-GOT","o":"Latin","y":8,"bp":27,"sy":"un.for.got","ps":"adjective","t":["time","olatin"]},{"w":"unform","d":"To cause something to lose its shape, structure, or form; to break down or dissolve an established form or arrangement.","s":"The sculptor tried to unform the clay statue and start from scratch.","p":"un-FORM","o":"Latin","y":8,"bp":18,"sy":"un.form","ps":"verb","t":["olatin"]},{"w":"unformable","d":"Impossible to shape, mold, or give form to; describing a material or concept that resists being formed into any structure.","s":"The brittle material proved unformable and crumbled when pressed into a mold.","p":"un-FOR-muh-bul","o":"Latin","y":9,"bp":27,"sy":"un.formable","ps":"adjective","t":["olatin"]},{"w":"unformalizable","d":"Impossible to express in a formal, systematic, or rule-based framework; describing knowledge or processes that resist formal representation.","s":"The artist's creative process was unformalizable and could not be reduced to a set of rules.","p":"un-FOR-muh-ly-zuh-bul","o":"Latin","y":9,"bp":29,"sy":"un.for.mal.iz.able","ps":"adjective","t":["logic","olatin"]},{"w":"unformalized","d":"Not made official, structured, or subject to formal rules; remaining informal and without established procedures or documentation.","s":"Their unformalized agreement was based on a simple handshake.","p":"un-FOR-muh-lyzd","o":"Latin","y":8,"bp":38,"sy":"un.for.mal.ized","ps":"adjective","t":["olatin"]},{"w":"unformat","d":"To reverse or remove the formatting applied to a document, disk, or data set, returning it to an unstructured or original state.","s":"The technician tried to unformat the drive to recover the deleted files.","p":"un-FOR-mat","o":"Latin","y":8,"bp":27,"sy":"un.for.mat","ps":"verb","t":["olatin"]},{"w":"unformattable","d":"Impossible to apply formatting to; describing a disk, file, or document that cannot be formatted by any available method.","s":"The corrupted disk was unformattable, making data recovery impossible.","p":"un-FOR-mat-uh-bul","o":"Latin","y":9,"bp":26,"sy":"un.for.mat.table","ps":"adjective","t":["olatin"]},{"w":"unformidable","d":"Not formidable or intimidating; lacking the power, strength, or impressive qualities needed to inspire fear or respect.","s":"The opponent looked unformidable on paper, but proved tough in the match.","p":"un-FOR-mih-duh-bul","o":"Latin","y":9,"bp":35,"sy":"un.formidable","ps":"adjective","t":["emotions","olatin"]},{"w":"unformulaic","d":"Not following a standard formula or predictable pattern; original, fresh, and not bound by conventional rules or templates.","s":"The director's unformulaic storytelling surprised audiences expecting a typical adventure film.","p":"un-for-myoo-LAY-ik","o":"Latin","y":9,"bp":38,"sy":"un.for.mu.la.ic","ps":"adjective","t":["olatin"]},{"w":"unforsaken","d":"Not abandoned or deserted; still supported, remembered, or cared for rather than left behind.","s":"The stray dog, unforsaken by the family, was given a warm home.","p":"un-for-SAY-kun","o":"Latin","y":8,"bp":30,"sy":"un.for.sak.en","ps":"adjective","t":["olatin"]},{"w":"unforthcoming","d":"Not willing to share information, details, or cooperation; reserved, secretive, or reluctant to communicate openly.","s":"The witness was unforthcoming during questioning, offering only one-word answers.","p":"un-forth-KUM-ing","o":"Latin","y":8,"bp":26,"sy":"un.forth.com.ing","ps":"adjective","t":["olatin"]},{"w":"unforthcomingly","d":"In a manner that is evasive, uncooperative, or unwilling to share information openly; not in a forthcoming or transparent way.","s":"She unforthcomingly shrugged when asked about her plans for the project.","p":"un-FORTH-kum-ing-lee","o":"Latin","y":9,"bp":30,"sy":"un.forth.com.ing.ly","ps":"adverb","t":["olatin"]},{"w":"unfortified","d":"Not strengthened, reinforced, or protected; lacking defensive structures or added nutrients.","s":"The unfortified village had no walls to protect it from invasion.","p":"un-FOR-tih-fyd","o":"Latin","y":7,"bp":37,"sy":"un.for.ti.fied","ps":"adjective","t":["olatin"]},{"w":"unfossiliferous","d":"Not containing or bearing fossils; describing rock or sediment in which no fossil remains are present.","s":"Scientists were disappointed to find the rock layer unfossiliferous and bare of ancient remains.","p":"un-fos-sil-IF-er-us","o":"Latin","y":9,"bp":31,"sy":"un.fos.sil.if.er.ous","ps":"adjective","t":["minerals","maps","olatin"]},{"w":"unfostered","d":"Not cared for, encouraged, or nurtured; lacking the support needed to develop or grow.","s":"The unfostered talent of the young painter went unnoticed for years.","p":"un-FOS-terd","o":"Latin","y":8,"bp":29,"sy":"un.fos.tered","ps":"adjective","t":["olatin"]},{"w":"unfought","d":"Not contested or battled; describing a conflict, struggle, or competition that never took place.","s":"The unfought battle was avoided through careful diplomacy.","p":"un-FAWT","o":"Latin","y":9,"bp":25,"sy":"un.fought","ps":"adjective","t":["war","sports","olatin"]},{"w":"unfoxed","d":"Not deceived, tricked, or outwitted; remaining clear of cunning manipulation or clever schemes.","s":"The clever detective remained unfoxed by the criminal's elaborate tricks.","p":"un-FOKST","o":"Latin","y":8,"bp":19,"sy":"un.foxed","ps":"adjective","t":["olatin"]},{"w":"unfractured","d":"Not broken, cracked, or split; remaining intact and structurally whole without any fractures.","s":"Despite the hard fall, the bone was miraculously unfractured.","p":"un-FRAK-cherd","o":"Latin","y":8,"bp":35,"sy":"un.frac.tured","ps":"adjective","t":["olatin"]},{"w":"unfragmentable","d":"Impossible to break apart into fragments or separate pieces; incapable of being divided or shattered.","s":"The solid block of granite seemed unfragmentable without specialized equipment.","p":"un-FRAG-men-tuh-bul","o":"Latin","y":9,"bp":26,"sy":"un.frag.mentable","ps":"adjective","t":["numbers","olatin"]},{"w":"unfragmented","d":"Not broken into separate pieces or parts; remaining unified, whole, and undivided.","s":"The unfragmented manuscript had survived centuries intact.","p":"un-FRAG-men-ted","o":"Latin","y":8,"bp":38,"sy":"un.frag.ment.ed","ps":"adjective","t":["olatin"]},{"w":"unframe","d":"To remove something from its frame or border; to strip away the structure or context surrounding something.","s":"The art restorer had to carefully unframe the painting before cleaning it.","p":"un-FRAYM","o":"Latin","y":9,"bp":19,"sy":"un.frame","ps":"verb","t":["olatin"]},{"w":"unfrankable","d":"Not capable of being franked or officially stamped for free postal delivery; ineligible for a franking mark.","s":"The oversized package was unfrankable and could not be stamped for standard postage.","p":"un-FRANK-uh-bul","o":"Latin","y":9,"bp":35,"sy":"un.frank.able","ps":"adjective","t":["olatin"]},{"w":"unfraught","d":"Free from tension, anxiety, or difficulty; not loaded with stress or emotional weight.","s":"It was rare to have an unfraught conversation with him since he worried about everything.","p":"un-FRAWT","o":"Latin","y":8,"bp":26,"sy":"un.fraught","ps":"adjective","t":["emotions","olatin"]},{"w":"unfrayed","d":"Not worn, tattered, or unraveled at the edges; remaining smooth, neat, and undamaged.","s":"The flag was still unfrayed after years of flying in the wind.","p":"un-FRAYD","o":"Latin","y":8,"bp":25,"sy":"un.frayed","ps":"adjective","t":["olatin"]},{"w":"unfrazzled","d":"Not exhausted, worn out, or frazzled; calm and composed without signs of stress or strain.","s":"Even after three hours of traffic, she arrived at the meeting completely unfrazzled.","p":"un-FRAZ-uld","o":"Latin","y":9,"bp":29,"sy":"un.fraz.zled","ps":"adjective","t":["olatin"]},{"w":"unfreeable","d":"Impossible to set free or release from confinement, obligation, or restriction.","s":"The trapped butterfly seemed unfreeable from the thick spider's web.","p":"un-FREE-uh-bul","o":"Latin","y":9,"bp":29,"sy":"un.free.able","ps":"adjective","t":["olatin"]},{"w":"unfreed","d":"Not released or liberated; still held in captivity, bondage, or restriction without being set free.","s":"The prisoner remained unfreed despite the court's long deliberations.","p":"un-FREED","o":"Latin","y":8,"bp":19,"sy":"un.freed","ps":"adjective","t":["olatin"]},{"w":"unfrenzied","d":"Not in a state of wild excitement, panic, or frenzy; calm, controlled, and free from frantic energy.","s":"The crowd was surprisingly unfrenzied even as the championship trophy was lifted.","p":"un-FREN-zeed","o":"Latin","y":8,"bp":29,"sy":"un.fren.zied","ps":"adjective","t":["physics","olatin"]},{"w":"unfresh","d":"No longer fresh; stale, old, or lacking the quality of being new, clean, or recently made.","s":"The bread left on the counter overnight tasted distinctly unfresh.","p":"un-FRESH","o":"Latin","y":8,"bp":19,"sy":"un.fresh","ps":"adjective","t":["olatin"]},{"w":"unfreshness","d":"The state or quality of being no longer fresh; staleness or the absence of freshness in something.","s":"The unfreshness of the fish at the market made everyone wrinkle their noses.","p":"un-FRESH-nes","o":"Latin","y":9,"bp":35,"sy":"un.fresh.ness","ps":"noun","t":["olatin"]},{"w":"unfret","d":"To free from worry, anxiety, or irritation; to calm or soothe something that was fretful or tense.","s":"She tried to unfret herself by taking slow, deep breaths before the performance.","p":"un-FRET","o":"Latin","y":8,"bp":18,"sy":"un.fret","ps":"verb","t":["emotions","olatin"]},{"w":"unfretted","d":"without frets","s":"He played the unfretted bass with a smooth, sliding style unlike any other musician.","p":"un-FRET-ed","o":"Latin","y":9,"bp":28,"sy":"un.fret.ted","ps":"adjective","t":["olatin"]},{"w":"unfried","d":"Not cooked by frying in oil or fat; remaining in a raw or otherwise uncooked state.","s":"The chef recommended the unfried version of the chicken for a healthier meal.","p":"un-FRYD","o":"Latin","y":8,"bp":19,"sy":"un.fried","ps":"adjective","t":["culinary","olatin"]},{"w":"unfrightenable","d":"Impossible to frighten or scare; completely unaffected by threats, dangers, or alarming situations.","s":"The veteran firefighter seemed completely unfrightenable, even in the most dangerous situations.","p":"un-FRY-ten-uh-bul","o":"Latin","y":9,"bp":27,"sy":"un.fright.en.able","ps":"adjective","t":["olatin"]},{"w":"unfrightening","d":"Not causing fear, alarm, or fright; harmless and unthreatening in appearance or effect.","s":"The haunted house was so poorly decorated that it was completely unfrightening.","p":"un-FRY-ten-ing","o":"Latin","y":9,"bp":26,"sy":"un.fright.en.ing","ps":"adjective","t":["emotions","olatin"]},{"w":"unfrighteningly","d":"In a manner that does not cause fear or alarm; in a way that is harmless and completely unthreatening.","s":"The large dog barked unfrighteningly, wagging its tail the whole time.","p":"un-FRY-ten-ing-lee","o":"Latin","y":9,"bp":30,"sy":"un.fright.en.ing.ly","ps":"adverb","t":["emotions","olatin"]},{"w":"unfrilled","d":"Without frills, ruffles, or decorative edges; plain, simple, and stripped of ornamental detail.","s":"She chose an unfrilled white blouse for its clean, simple look.","p":"un-FRILD","o":"Latin","y":9,"bp":26,"sy":"un.frilled","ps":"adjective","t":["landforms","olatin"]},{"w":"unfrilly","d":"Lacking frills or decorative flourishes; straightforwardly plain and without unnecessary ornamentation.","s":"His unfrilly decorating style meant plain walls and simple furniture.","p":"un-FRIL-ee","o":"Latin","y":9,"bp":25,"sy":"un.frilly","ps":"adjective","t":["landforms","olatin"]},{"w":"unfrivolous","d":"Not frivolous or silly; serious, purposeful, and focused rather than trivial or carelessly playful.","s":"Her unfrivolous approach to studying earned her top grades every semester.","p":"un-FRIV-uh-lus","o":"Latin","y":9,"bp":34,"sy":"un.frivolous","ps":"adjective","t":["olatin"]},{"w":"unfrivolously","d":"In a serious, purposeful, and non-trivial manner; without any frivolity or unnecessary silliness.","s":"He unfrivolously handled every detail of the important science project.","p":"un-FRIV-uh-lus-lee","o":"Latin","y":9,"bp":25,"sy":"un.frivolous.ly","ps":"adverb","t":["olatin"]},{"w":"unfrogged","d":"Lacking frog fastenings; describing a garment from which the looped ornamental closures have been removed.","s":"The plain military jacket was unfrogged, lacking the decorative looped fasteners of fancier uniforms.","p":"un-FROGD","o":"Latin","y":8,"bp":26,"sy":"un.frogged","ps":"adjective","t":["animals","fabrics","olatin"]},{"w":"unfruited","d":"Not bearing or producing fruit; describing a plant or tree that has failed to develop fruit.","s":"The unfruited branches of the young apple tree showed it needed another year to mature.","p":"un-FROO-ted","o":"Latin","y":8,"bp":28,"sy":"un.fruit.ed","ps":"adjective","t":["botany","flowers","maps","spices","olatin"]},{"w":"unfrumpy","d":"Not frumpy or dowdy; stylish, neat, and well-dressed rather than old-fashioned or unattractive in appearance.","s":"Her stylish new haircut made her look completely unfrumpy for the school dance.","p":"un-FRUM-pee","o":"Latin","y":8,"bp":25,"sy":"un.frumpy","ps":"adjective","t":["fabrics","olatin"]},{"w":"unfrustrated","d":"Not experiencing frustration or irritation; remaining calm, satisfied, and undisturbed by obstacles or setbacks.","s":"Somehow, Jake remained unfrustrated after losing the board game five times in a row.","p":"un-frus-TRAY-ted","o":"Latin","y":8,"bp":38,"sy":"un.frus.trat.ed","ps":"adjective","t":["olatin"]},{"w":"unfuck","d":"To fix, correct, or undo a serious mess or badly handled situation; to restore order from chaos or disorder.","s":"The technician worked all night to unfuck the tangled server system before morning.","p":"un-FUK","o":"Latin","y":5,"bp":18,"sy":"un.fuck","ps":"verb","t":["disease","olatin"]},{"w":"unfuckable","d":"So thoroughly ruined or messed up that it cannot be fixed or corrected under any circumstances.","s":"The corrupted hard drive was declared completely unfuckable by even the best tech experts.","p":"un-FUK-uh-bul","o":"Latin","y":8,"bp":29,"sy":"un.fuck.able","ps":"adjective","t":["olatin"]},{"w":"unfucked","d":"Having been corrected or repaired after being in a disastrous or badly messed-up state.","s":"After hours of work, the jammed printer was finally unfucked and running smoothly.","p":"un-FUKT","o":"Latin","y":6,"bp":25,"sy":"un.fucked","ps":"adjective","t":["olatin"]},{"w":"unfuckupable","d":"Impossible to mess up or ruin; so well-designed or foolproof that no mistake could possibly cause failure.","s":"The step-by-step instructions were so clear they seemed completely unfuckupable.","p":"un-FUK-up-uh-bul","o":"Latin","y":9,"bp":38,"sy":"un.fuck.u.pable","ps":"adjective","t":["olatin"]},{"w":"unfudged","d":"Not altered, manipulated, or falsified; honest and accurate without any distortion or dishonest adjustment.","s":"The scientist was proud that her unfudged data stood up to every scrutiny.","p":"un-FUJD","o":"Latin","y":8,"bp":25,"sy":"un.fudged","ps":"adjective","t":["olatin"]},{"w":"unfueled","d":"not provided with fuel","s":"The rocket sat unfueled on the launchpad as engineers debated the mission's safety.","p":"un-FYOOLD","o":"Latin","y":8,"bp":27,"sy":"un.fu.eled","ps":"adjective","t":["olatin"]},{"w":"unfulfillable","d":"Impossible to fulfill, satisfy, or complete; describing a desire, promise, or requirement that can never be met.","s":"His dream of becoming both a rock star and a brain surgeon seemed completely unfulfillable.","p":"un-ful-FIL-uh-bul","o":"Latin","y":9,"bp":28,"sy":"un.ful.fil.l.able","ps":"adjective","t":["olatin"]},{"w":"unfulfillment","d":"The state of not being fulfilled or satisfied; a feeling that one's potential, desires, or goals have not been achieved.","s":"She felt a deep unfulfillment after spending years in a career she never loved.","p":"un-fool-FILL-ment","o":"Latin","y":9,"bp":26,"sy":"un.ful.fill.ment","ps":"noun","t":["olatin"]},{"w":"unfumed","d":"not exposed to or treated with fumes or smoke","s":"The unfumed greenhouse still had insects, because no one had smoked them out.","p":"un-FYOOMD","o":"Latin","y":8,"bp":19,"sy":"un.fumed","ps":"adjective","t":["olatin"]},{"w":"unfun","d":"Lacking enjoyment or amusement; not entertaining or pleasurable.","s":"Cleaning the garage on a sunny Saturday felt especially unfun to the twins.","p":"un-FUN","o":"Latin","y":6,"bp":17,"sy":"un.fun","ps":"adjective","t":["olatin"]},{"w":"unfunctional","d":"not related to or suitable for everyday needs or activities","s":"The beautiful but unfunctional chair collapsed under the slightest weight.","p":"un-FUNK-shun-ul","o":"Latin","y":8,"bp":38,"sy":"un.func.tion.al","ps":"adjective","t":["olatin"]},{"w":"unfunctionalized","d":"Not having been given a specific function or chemical functional group; lacking a designated purpose or chemical modification.","s":"The laboratory chemical remained unfunctionalized and could not yet be used in the experiment.","p":"un-FUNK-shun-ul-yzd","o":"Latin","y":9,"bp":30,"sy":"un.func.tion.al.ized","ps":"adjective","t":["chemistry","olatin"]},{"w":"unfunctionally","d":"In a manner that does not serve a practical purpose or function; without useful operation.","s":"The gadget was unfunctionally designed, with buttons placed where no thumb could reach.","p":"un-FUNK-shun-ul-ee","o":"Latin","y":9,"bp":29,"sy":"un.func.tion.al.ly","ps":"adverb","t":["olatin"]},{"w":"unfundable","d":"Not capable of receiving financial support or funding; unable to qualify for grants or monetary backing.","s":"The committee decided the vague research proposal was completely unfundable.","p":"un-FUN-duh-bul","o":"Latin","y":9,"bp":29,"sy":"un.fund.able","ps":"adjective","t":["olatin"]},{"w":"unfunky","d":"Lacking groove, style, or rhythmic energy; not having the lively, soulful quality associated with funk music or culture.","s":"The new DJ's playlist was criticized as totally unfunky and stiff.","p":"un-FUNK-ee","o":"Latin","y":8,"bp":19,"sy":"un.funky","ps":"adjective","t":["physics","music","olatin"]},{"w":"unfurnish","d":"To remove furniture or equipment from a place; to strip a room or space of its furnishings.","s":"They had to completely unfurnish the apartment before the renovations could begin.","p":"un-FUR-nish","o":"Latin","y":8,"bp":28,"sy":"un.fur.nish","ps":"verb","t":["household","olatin"]},{"w":"unfurred","d":"Not covered with fur; having the fur removed or naturally lacking a fur covering.","s":"The unfurred kitten looked surprisingly small and fragile right after birth.","p":"un-FURD","o":"Latin","y":8,"bp":25,"sy":"un.furred","ps":"adjective","t":["olatin"]},{"w":"unfurrow","d":"To smooth out or remove furrows, wrinkles, or grooves; to make a furrowed surface flat and even again.","s":"She tried to unfurrow her brow after hearing the good news about the test results.","p":"un-FUR-oh","o":"Latin","y":8,"bp":27,"sy":"un.fur.row","ps":"verb","t":["olatin"]},{"w":"unfurrowed","d":"not marked with shallow depressions or furrows","s":"The baby's soft, unfurrowed forehead was completely smooth, showing none of the stress lines that years of worry and hard work had carved so deeply into her grandmother's aged face.","p":"un-FUR-ohd","o":"Latin","y":9,"bp":29,"sy":"un.fur.rowed","ps":"adjective","t":["olatin"]},{"w":"unfused","d":"Not joined, merged, or blended together; remaining as separate, distinct parts that have not been combined.","s":"The unfused wires lay separately in the box, waiting to be connected.","p":"un-FYOOZD","o":"Latin","y":6,"bp":19,"sy":"un.fused","ps":"adjective","t":["olatin"]},{"w":"unfuturistic","d":"Not having a modern, forward-looking, or technologically advanced quality; lacking the appearance or feel of the future.","s":"The old wooden cart looked completely unfuturistic next to the sleek electric vehicles.","p":"un-fyoo-chur-IS-tik","o":"Latin","y":8,"bp":39,"sy":"un.fu.tur.is.tic","ps":"adjective","t":["olatin"]},{"w":"unfuzzy","d":"Clear, sharp, and precise; not blurry, vague, or indistinct in appearance or meaning.","s":"After cleaning the camera lens, the image became sharp and unfuzzy.","p":"un-FUZ-ee","o":"Latin","y":8,"bp":19,"sy":"un.fuzzy","ps":"adjective","t":["olatin"]},{"w":"ungabled","d":"Not having a gable; describing a building or roof that lacks the triangular section formed by two sloping roof sides.","s":"The modern flat-roofed house was completely ungabled, unlike the old farmhouses nearby.","p":"un-GAY-buld","o":"Latin","y":8,"bp":24,"ps":"adjective","t":["buildings","olatin"]},{"w":"ungag","d":"To remove a gag from someone's mouth; to restore someone's ability to speak or express themselves freely.","s":"The hero managed to ungag the hostage so she could finally call for help.","p":"un-GAG","o":"Latin","y":7,"bp":17,"sy":"un.gag","ps":"verb","t":["olatin"]},{"w":"ungainsaid","d":"Not contradicted, disputed, or denied; accepted without opposition or challenge.","s":"Her claim that the experiment was a success went ungainsaid by the entire science committee.","p":"un-gayn-SED","o":"Latin","y":9,"bp":29,"sy":"un.gain.said","ps":"adjective","t":["olatin"]},{"w":"ungainsayable","d":"Impossible to deny, contradict, or dispute; so obviously true that no argument can be made against it.","s":"The video evidence was ungainsayable proof that he had been at the scene.","p":"un-gayn-SAY-uh-bul","o":"Latin","y":9,"bp":25,"sy":"un.gain.sayable","ps":"adjective","t":["logic","olatin"]},{"w":"ungaitered","d":"Not wearing gaiters; having the protective coverings removed from the legs or ankles.","s":"The soldiers returned to camp ungaitered after removing their leg coverings at the door.","p":"un-GAY-turd","o":"Latin","y":9,"bp":27,"sy":"un.gaitered","ps":"adjective","t":["olatin"]},{"w":"ungalvanized","d":"Not coated with a protective layer of zinc through the galvanizing process; lacking the rust-resistant metal treatment.","s":"The ungalvanized iron pipes rusted quickly in the damp basement.","p":"un-GAL-vuh-nyzd","o":"Latin","y":8,"bp":38,"sy":"un.gal.va.nized","ps":"adjective","t":["chemistry","olatin"]},{"w":"ungapped","d":"Having no gaps, breaks, or spaces; continuous and uninterrupted throughout.","s":"The seamlessly ungapped fence gave the garden a clean, unbroken border.","p":"un-GAPT","o":"Latin","y":8,"bp":25,"sy":"un.gapped","ps":"adjective","t":["olatin"]},{"w":"ungarbed","d":"having removed clothing","s":"The statue stood ungarbed in the center of the fountain, carved from white marble.","p":"un-GARBD","o":"Latin","y":8,"bp":25,"sy":"un.garbed","ps":"adjective","t":["olatin"]},{"w":"ungarbled","d":"Not confused, distorted, or scrambled; clear, accurate, and transmitted or expressed without error.","s":"Finally receiving an ungarbled message, the rescue team knew exactly where to go.","p":"un-GAR-buld","o":"Latin","y":8,"bp":28,"sy":"un.gar.bled","ps":"adjective","t":["olatin"]},{"w":"ungardened","d":"Not cultivated, tended, or maintained as a garden; left wild or without horticultural care.","s":"The ungardened lot behind the school was a wild tangle of weeds and vines.","p":"un-GAR-dund","o":"Latin","y":8,"bp":29,"sy":"un.gar.dened","ps":"adjective","t":["farming","olatin"]},{"w":"ungarnered","d":"Not collected, gathered, or accumulated; left uncollected as if still waiting to be harvested.","s":"The ungarnered wheat swayed in the field long after the harvest season had ended.","p":"un-GAR-nurd","o":"Latin","y":8,"bp":29,"sy":"un.gar.nered","ps":"adjective","t":["farming","olatin"]},{"w":"ungarnished","d":"Not decorated or adorned with a garnish or embellishment; plain and without any added decoration.","s":"The chef served a plain, ungarnished bowl of soup with no herbs or decoration.","p":"un-GAR-nisht","o":"Latin","y":8,"bp":35,"sy":"un.gar.nished","ps":"adjective","t":["landforms","culinary","olatin"]},{"w":"ungartered","d":"Not held up or fastened by a garter; describing stockings or garments whose garter has been removed or is absent.","s":"He walked into the hall ungartered, his stockings slipping down his legs.","p":"un-GAR-turd","o":"Latin","y":8,"bp":27,"sy":"un.gartered","ps":"adjective","t":["fabrics","olatin"]},{"w":"ungated","d":"Not having a gate or barrier to restrict entry; open and freely accessible without any controlled entrance.","s":"The ungated community welcomed visitors without any security checkpoint at the entrance.","p":"un-GAY-tid","o":"Latin","y":6,"bp":20,"sy":"un.gat.ed","ps":"adjective","t":["olatin"]},{"w":"ungathered","d":"not brought together in one place","p":"un-GATH-urd","o":"Latin","y":8,"bp":29,"sy":"un.gath.ered","ps":"adjective","t":["olatin"]},{"w":"ungaugable","d":"Impossible to measure, assess, or evaluate; beyond the reach of any instrument or method of measurement.","s":"The depth of the ancient well seemed ungaugable, no matter how long the rope was.","p":"un-GAY-juh-bul","o":"Latin","y":9,"bp":29,"sy":"un.gau.gable","ps":"adjective","t":["music","numbers","olatin"]},{"w":"ungauged","d":"Not measured or assessed with a gauge; lacking any recorded measurement of size, pressure, or quantity.","s":"The ungauged river flooded unexpectedly because no one had been measuring its water level.","p":"un-GAYJD","o":"Latin","y":8,"bp":25,"sy":"un.gauged","ps":"adjective","t":["tools","numbers","olatin"]},{"w":"ungazing","d":"Not looking steadily or attentively at anything; having an unfocused or inattentive expression rather than a fixed gaze.","s":"She sat ungazing at the window, her mind too distracted to focus on anything outside.","p":"un-GAY-zing","o":"Latin","y":8,"bp":25,"sy":"ungaz.ing","ps":"adjective","t":["olatin"]},{"w":"ungeeky","d":"Not displaying the interests, enthusiasm, or social awkwardness associated with geeks; lacking a nerdy or obsessive quality.","s":"His ungeeky fashion sense surprised his classmates, who expected him to dress like a typical tech enthusiast.","p":"un-GEE-kee","o":"Latin","y":8,"bp":17,"ps":"adjective","t":["olatin"]},{"w":"ungelatinized","d":"Not converted into or treated with gelatin; describing a starch or substance that has not undergone the thickening process caused by heat and water.","s":"The ungelatinized starch granules remained hard and powdery because the water was never heated.","p":"un-juh-LAT-uh-nyzd","o":"Latin","y":9,"bp":26,"sy":"un.ge.la.tinized","ps":"adjective","t":["olatin"]},{"w":"ungelded","d":"describing a male horse that has not been neutered","s":"The ungelded stallion was kept in a pasture of his own at the far end of the ranch.","p":"un-GEL-did","o":"Latin","y":8,"bp":27,"sy":"un.geld.ed","ps":"adjective","t":["animals","olatin"]},{"w":"ungelled","d":"Not treated or styled with gel; lacking the stiff or fixed quality that gel gives to hair or other substances.","s":"His hair looked disheveled and ungelled compared to his usually neat appearance.","p":"un-JELD","o":"Latin","y":9,"bp":25,"sy":"un.gelled","ps":"adjective","t":["olatin"]},{"w":"ungeneralized","d":"Not made broad or general; remaining specific, detailed, and particular rather than being extended to apply widely.","s":"The scientist kept her findings ungeneralized, careful not to apply them beyond her small study group.","p":"un-JEN-ur-ul-yzd","o":"Latin","y":9,"bp":26,"sy":"un.gener.al.ized","ps":"adjective","t":["olatin"]},{"w":"ungenerosity","d":"The quality or condition of being ungenerous; a lack of willingness to give, share, or be charitable toward others.","s":"His ungenerosity at the charity auction disappointed everyone who had hoped for large donations.","p":"un-jen-er-OS-ih-tee","o":"Latin","y":8,"bp":39,"sy":"un.gen.eros.i.ty","ps":"noun","t":["olatin"]},{"w":"ungenial","d":"Not genial; lacking warmth, friendliness, or a pleasant disposition; cold and unfriendly in manner.","s":"The ungenial professor never smiled and made students feel unwelcome during office hours.","p":"un-JEE-nee-ul","o":"Latin","y":8,"bp":27,"sy":"un.ge.nial","ps":"adjective","t":["character","olatin"]},{"w":"ungenially","d":"In a manner that is not genial; without warmth or friendliness; coldly or unkindly.","s":"She responded ungenially to every compliment, dismissing kindness with a sharp word.","p":"un-JEE-nee-ul-ee","o":"Latin","y":9,"bp":30,"sy":"un.ge.nial.ly","ps":"adverb","t":["olatin"]},{"w":"ungenitured","d":"Lacking a natural disposition or temperament determined by birth; without innate characteristics associated with one's origin or nativity.","s":"The archaic poem described the spirit as ungenitured, existing without birth or origin.","p":"un-JEN-ih-cherd","o":"Latin","y":8,"bp":37,"sy":"un.gen.i.tured","ps":"adjective","t":["character","olatin"]},{"w":"ungenotyped","d":"Not having had one's genotype identified or classified through genetic testing or analysis.","s":"The rare plant specimens remained ungenotyped because the laboratory lacked the proper equipment.","p":"un-JEE-noh-typt","o":"Latin","y":9,"bp":34,"sy":"ungeno.typed","ps":"adjective","t":["olatin"]},{"w":"ungentlemanlike","d":"not befitting a gentleman","s":"Shouting insults at the referee was considered entirely ungentlemanlike behavior by the coaching staff.","p":"un-JEN-tul-man-lyk","o":"Latin","y":9,"bp":28,"sy":"un.gentle.man.like","ps":"adjective","t":["olatin"]},{"w":"ungentleness","d":"The quality or state of being not gentle; roughness, harshness, or lack of delicacy in handling people or things.","s":"The ungentleness in his voice made the younger students afraid to ask questions.","p":"un-JEN-tul-nes","o":"Latin","y":9,"bp":36,"sy":"un.gentle.ness","ps":"noun","t":["olatin"]},{"w":"ungentrified","d":"Not having undergone gentrification; describing a neighborhood or area that has not been renovated or transformed by an influx of wealthier residents.","s":"The ungentrified neighborhood still had its original diners, laundromats, and hardware stores.","p":"un-JEN-trih-fyd","o":"Latin","y":8,"bp":38,"sy":"un.gen.tri.fied","ps":"adjective","t":["economy","olatin"]},{"w":"ungeographic","d":"Not conforming to or based on actual geographic features, patterns, or boundaries; contrary to the principles of geography.","s":"The fantasy map was completely ungeographic, placing mountains in the middle of flat plains.","p":"un-jee-oh-GRAF-ik","o":"Latin","y":8,"bp":38,"sy":"un.geo.graph.ic","ps":"adjective","t":["logic","olatin"]},{"w":"ungeometric","d":"Not conforming to the principles or forms of geometry; lacking regular, precise, or measurable shapes and patterns.","s":"The sculptor's swirling, irregular forms were deliberately ungeometric and free-flowing.","p":"un-jee-oh-MET-rik","o":"Latin","y":8,"bp":38,"sy":"un.ge.o.met.ric","ps":"adjective","t":["logic","numbers","olatin"]},{"w":"ungeometrical","d":"Lacking the regularity, precision, or defined forms characteristic of geometry; not arranged according to geometric principles.","s":"The child's drawing was charmingly ungeometrical, full of wobbly lines and lopsided circles.","p":"un-jee-oh-MET-rih-kul","o":"Latin","y":9,"bp":29,"sy":"un.ge.o.met.ri.cal","ps":"adjective","t":["logic","numbers","olatin"]},{"w":"ungeometrically","d":"In a manner that does not follow geometric principles or patterns; without the regularity or precision associated with geometry.","s":"The architect had arranged the windows ungeometrically, giving the building a quirky, uneven look.","p":"un-jee-oh-MET-rih-kul-ee","o":"Latin","y":9,"bp":33,"sy":"un.ge.o.met.ri.cal.ly","ps":"adverb","t":["logic","numbers","olatin"]},{"w":"ungerminating","d":"Not germinating; failing to sprout, grow, or develop from a seed or spore into a new plant.","s":"The ungerminating seeds sat in dry soil for weeks without showing any signs of growth.","p":"un-JER-mih-nay-ting","o":"Latin","y":9,"bp":26,"sy":"unger.mi.nat.ing","ps":"adjective","t":["botany","olatin"]},{"w":"ungettable","d":"Impossible or extremely difficult to obtain, reach, or acquire; beyond one's ability to get.","s":"The autograph from the reclusive author was considered ungettable by most fans.","p":"un-GET-uh-bul","o":"Latin","y":9,"bp":27,"sy":"unget.table","ps":"adjective","t":["olatin"]},{"w":"unghostly","d":"Not resembling or characteristic of a ghost; lacking a spectral, eerie, or supernatural quality; ordinary and solidly real.","s":"The friendly old house had an unghostly warmth that put every visitor at ease.","p":"un-GOHST-lee","o":"Latin","y":8,"bp":26,"sy":"unghost.ly","ps":"adjective","t":["olatin"]},{"w":"ungilded","d":"Not covered or decorated with gold or a gold-colored finish; plain and without any gilded ornamentation.","s":"The ungilded wooden frame looked simple but elegant against the white wall.","p":"un-GIL-did","o":"Latin","y":8,"bp":25,"sy":"ungild.ed","ps":"adjective","t":["landforms","colors","olatin"]},{"w":"ungimmicky","d":"Free from gimmicks or clever tricks; straightforward, honest, and without artificial devices designed to attract attention.","s":"The chef's ungimmicky menu relied on fresh ingredients rather than flashy tricks.","p":"un-GIM-ih-kee","o":"Latin","y":9,"bp":27,"sy":"ungim.micky","ps":"adjective","t":["tools","olatin"]},{"w":"ungird","d":"To remove a belt, girdle, or band from something or someone; to release or loosen by undoing what was bound around the waist or middle.","s":"The knight would ungird his sword belt before entering the great hall for the feast.","p":"un-GERD","o":"Latin","y":8,"bp":18,"sy":"un.gird","ps":"verb","t":["olatin"]},{"w":"ungirdled","d":"Not encircled by a belt or girdle; free from any band or strap that was bound around the waist or body.","s":"The ungirdled robe flowed loosely around her as she walked through the garden.","p":"un-GER-duld","o":"Latin","y":8,"bp":28,"sy":"un.gir.dled","ps":"adjective","t":["olatin"]},{"w":"ungirlish","d":"Not characteristic of or resembling a girl in manner, appearance, or behavior; lacking qualities traditionally associated with girlhood.","s":"Her ungirlish habit of fixing car engines surprised many of her classmates.","p":"un-GER-lish","o":"Latin","y":8,"bp":28,"sy":"un.girl.ish","ps":"adjective","t":["festivals","olatin"]},{"w":"ungive","d":"To take back or retract something that was given; to reverse the act of giving.","s":"Once you truly ungive your pride, forgiving others becomes much easier.","p":"un-GIV","o":"Latin","y":8,"bp":18,"sy":"un.give","ps":"verb","t":["olatin"]},{"w":"ungiven","d":"Not given or bestowed; withheld or kept back rather than presented or awarded to someone.","s":"The prize sat ungiven on the table because the winner never showed up.","p":"un-GIV-en","o":"Latin","y":8,"bp":20,"sy":"un.giv.en","ps":"adjective","t":["olatin"]},{"w":"ungiving","d":"Not generous or willing to give; stingy, withholding, or unyielding in sharing time, attention, or resources with others.","s":"The ungiving soil refused to yield any crops despite weeks of hard work.","p":"un-GIV-ing","o":"Latin","y":8,"bp":27,"sy":"un.giv.ing","ps":"adjective","t":["time","olatin"]},{"w":"unglaciated","d":"Describing land that was never covered or shaped by glaciers; referring to terrain that has not been altered by the movement of ancient ice sheets.","s":"The unglaciated valley retained rich soil that the ice age never scraped away.","p":"un-GLAY-shee-ay-tid","o":"Latin","y":7,"bp":34,"sy":"unglaciat.ed","ps":"adjective","t":["landforms","ancient","olatin"]},{"w":"unglad","d":"Not glad; unhappy, displeased, or without a sense of joy or satisfaction about something.","s":"She was unglad to hear that the field trip had been cancelled due to rain.","p":"un-GLAD","o":"Latin","y":8,"bp":16,"ps":"adjective","t":["emotions","olatin"]},{"w":"ungladdened","d":"Not made glad or cheerful; remaining without joy or happiness; not having been cheered or brightened by any positive influence.","s":"He remained ungladdened by the good news because his own worries overshadowed it.","p":"un-GLAD-end","o":"Latin","y":9,"bp":34,"sy":"unglad.dened","ps":"adjective","t":["emotions","olatin"]},{"w":"unglamorously","d":"In a manner that lacks glamour, excitement, or appealing beauty; in a plain, dull, or ordinary way without any dazzling qualities.","s":"She unglamorously wiped grease off her hands after fixing the broken pipe.","p":"un-GLAM-er-us-lee","o":"Latin","y":9,"bp":25,"sy":"unglam.orous.ly","ps":"adverb","t":["landforms","olatin"]},{"w":"unglamorousness","d":"The state or quality of lacking glamour; the condition of being plain, dull, and without exciting or attractive qualities.","s":"The unglamorousness of the job didn't bother him because he took pride in honest work.","p":"un-GLAM-er-us-nes","o":"Latin","y":9,"bp":27,"sy":"unglam.orous.ness","ps":"noun","t":["landforms","olatin"]},{"w":"unglamourous","d":"not challenging; dull and lacking excitement","p":"un-GLAM-er-us","o":"Latin","y":9,"bp":35,"sy":"unglam.ourous","ps":"adjective","t":["olatin"]},{"w":"unglamourously","d":"In a manner that is not glamorous; without elegance, excitement, or dazzling appeal; in a plain and unremarkable way.","s":"He unglamourously tripped over the red carpet while accepting his award.","p":"un-GLAM-er-us-lee","o":"Latin","y":9,"bp":26,"sy":"unglam.ourous.ly","ps":"adverb","t":["landforms","olatin"]},{"w":"unglaze","d":"To remove the glaze or glazed surface from something, such as pottery or a window; to strip away a smooth, glossy coating.","s":"The potter decided to unglaze the pot and start the finishing process over again.","p":"un-GLAYZ","o":"Latin","y":9,"bp":17,"ps":"verb","t":["olatin"]},{"w":"unglazed","d":"not furnished with glass","s":"Windows were unglazed to admit as much light and air as possible.","p":"un-GLAZD","o":"Latin","y":5,"bp":24,"ps":"adjective","t":["olatin"]},{"w":"unglorified","d":"Not glorified or celebrated; without having been given glory, praise, or a heightened sense of grandeur or honor.","s":"The unglorified soldiers who dug trenches were just as brave as those on the front lines.","p":"un-GLOR-ih-fyd","o":"Latin","y":8,"bp":37,"sy":"un.glo.ri.fied","ps":"adjective","t":["olatin"]},{"w":"unglorify","d":"To remove or strip away glory or honor from someone or something; to diminish the celebrated or exalted status of a person or thing.","s":"The documentary aimed to unglorify war by showing its harsh realities.","p":"un-GLOR-ih-fy","o":"Latin","y":8,"bp":29,"sy":"un.glo.ri.fy","ps":"verb","t":["olatin"]},{"w":"unglossy","d":"Lacking a smooth, shiny, or polished surface finish; dull and without any glossy appearance or luster.","s":"The unglossy finish of the photograph gave it a vintage, matte appearance.","p":"un-GLOS-ee","o":"Latin","y":8,"bp":25,"sy":"un.glossy","ps":"adjective","t":["olatin"]},{"w":"unglove","d":"To remove a glove or gloves from one's hand or hands; to take off the protective or decorative covering of the hand.","s":"She had to unglove her hands quickly to answer the unexpected phone call.","p":"un-GLUV","o":"Latin","y":9,"bp":19,"sy":"un.glove","ps":"verb","t":["fabrics","olatin"]},{"w":"unglowing","d":"Not glowing; lacking warmth, brightness, radiance, or enthusiastic energy; dull and without any luminous or vibrant quality.","s":"The unglowing embers told them the campfire had died hours ago.","p":"un-GLOH-ing","o":"Latin","y":8,"bp":28,"sy":"un.glow.ing","ps":"adjective","t":["physics","colors","olatin"]},{"w":"ungnarled","d":"Not gnarled; free from knots, twists, or rough, knotty distortions; smooth and straight rather than twisted and misshapen.","s":"The ungnarled young sapling grew straight and smooth toward the sunlight.","p":"un-NARLD","o":"Latin","y":8,"bp":26,"sy":"ung.narled","ps":"adjective","t":["olatin"]},{"w":"ungnawed","d":"Not gnawed or chewed upon; remaining intact and undamaged by the biting or nibbling of an animal or person.","s":"Remarkably, the wooden fence post was ungnawed despite the beaver living nearby.","p":"un-NAWD","o":"Latin","y":8,"bp":25,"sy":"ung.nawed","ps":"adjective","t":["animals","olatin"]},{"w":"ungobbled","d":"Not gobbled up or hastily consumed; remaining uneaten or untaken after being available for someone to take or devour.","s":"A surprising amount of turkey was left ungobbled at the end of the Thanksgiving feast.","p":"un-GOB-uld","o":"Latin","y":8,"bp":28,"sy":"un.gob.bled","ps":"adjective","t":["olatin"]},{"w":"ungod","d":"To deprive of divine status or godlike qualities; to strip something or someone of the attributes associated with a god.","s":"Some philosophers argue that modern society tries to ungod the universe by explaining away mystery.","p":"un-GOD","o":"Latin","y":7,"bp":17,"sy":"un.god","ps":"verb","t":["olatin"]},{"w":"ungodlike","d":"Not resembling or befitting a god; lacking the power, majesty, or perfection typically associated with a divine being.","s":"His ungodlike patience ran out after waiting three hours for the late bus.","p":"un-GOD-lyk","o":"Latin","y":9,"bp":28,"sy":"un.god.like","ps":"adjective","t":["royalty","olatin"]},{"w":"ungood","d":"Not good; lacking goodness or positive qualities; a simple negation of what is considered good.","s":"In the dystopian novel, citizens were punished for any thoughts deemed ungood by the regime.","p":"un-GOOD","o":"Latin","y":7,"bp":18,"sy":"un.good","ps":"adjective","t":["olatin"]},{"w":"ungoodly","d":"Not goodly; lacking considerable or pleasing goodness; falling short of what is morally or physically admirable.","s":"The villain's ungoodly behavior shocked even the toughest members of the town.","p":"un-GOOD-lee","o":"Latin","y":8,"bp":27,"sy":"un.good.ly","ps":"adjective","t":["olatin"]},{"w":"unGoogleable","d":"Impossible to find through an internet search engine such as Google; describing information or a person who leaves no searchable digital trace.","s":"The mysterious hermit was so off the grid that his name was completely unGoogleable.","p":"un-GOO-gul-uh-bul","o":"Latin","y":9,"bp":35,"sy":"un.googleable","ps":"adjective","t":["botany","tools","olatin"]},{"w":"ungored","d":"Not pierced or wounded by a horn or tusk; free from the injury of being gored by an animal.","s":"Miraculously, the matador walked away ungored after the bull charged past him twice.","p":"un-GORD","o":"Latin","y":8,"bp":19,"sy":"un.gored","ps":"adjective","t":["animals","olatin"]},{"w":"ungorgeous","d":"Not gorgeous; lacking striking beauty, brilliance, or magnificence; plain or unattractive in appearance.","s":"The old gymnasium was admittedly ungorgeous, but it held a lifetime of great memories.","p":"un-GOR-jus","o":"Latin","y":9,"bp":29,"sy":"un.gor.geous","ps":"adjective","t":["landforms","colors","olatin"]},{"w":"ungot","d":"Not obtained or acquired; describing something that was never received or gained.","s":"The prize remained ungot because no contestant answered the final question correctly.","p":"un-GOT","o":"Latin","y":7,"bp":17,"sy":"un.got","ps":"adjective","t":["olatin"]},{"w":"ungothic","d":"Not Gothic in style; lacking the dark, medieval, or ornate architectural and artistic features characteristic of Gothic design.","s":"The cheerful pastel colors of the new building were decidedly ungothic in style.","p":"un-GOTH-ik","o":"Latin","y":8,"bp":27,"sy":"un.goth.ic","ps":"adjective","t":["buildings","painting","olatin"]},{"w":"ungotten","d":"Not obtained, received, or begotten; describing something that was never acquired or brought into existence.","s":"Several library books remained ungotten from the hold shelf and were eventually returned.","p":"un-GOT-un","o":"Latin","y":9,"bp":27,"sy":"un.got.ten","ps":"adjective","t":["olatin"]},{"w":"ungovernability","d":"The quality or state of being impossible to govern, control, or manage; a condition in which authority cannot be effectively exercised.","s":"The city's ungovernability became clear when three different factions all claimed leadership.","p":"un-guv-ur-nuh-BIL-ih-tee","o":"Latin","y":9,"bp":30,"sy":"un.govern.abil.i.ty","ps":"noun","t":["poetry","olatin"]},{"w":"ungovernableness","d":"The state or quality of being ungovernable; the condition of resisting all attempts at control or management.","s":"The wild horse's ungovernableness made every trainer give up after just one session.","p":"un-GUV-ur-nuh-bul-nes","o":"Latin","y":9,"bp":29,"sy":"un.govern.able.ness","ps":"noun","t":["olatin"]},{"w":"ungovernably","d":"In a manner that cannot be governed or controlled; in a way that defies all attempts at management or restraint.","s":"The toddler ran ungovernably through the store, knocking over displays as she went.","p":"un-GUV-ur-nuh-blee","o":"Latin","y":8,"bp":36,"sy":"un.govern.ably","ps":"adverb","t":["olatin"]},{"w":"ungown","d":"To remove a gown from; to strip someone of their academic or ceremonial robe.","s":"The graduating seniors had to ungown quickly after the ceremony to make room for the next group.","p":"un-GOWN","o":"Latin","y":8,"bp":18,"sy":"un.gown","ps":"verb","t":["fabrics","olatin"]},{"w":"ungowned","d":"Not wearing a gown; having been deprived of or stripped of a ceremonial or academic robe.","s":"The ungowned professor looked surprisingly casual without his academic robes.","p":"un-GOWND","o":"Latin","y":8,"bp":25,"sy":"un.gowned","ps":"adjective","t":["fabrics","olatin"]},{"w":"ungrab","d":"To release something that has been grabbed; to undo the act of seizing or grasping an object.","s":"The toddler refused to ungrab the toy even when his mother gently tried to pull it away.","p":"un-GRAB","o":"Latin","y":8,"bp":18,"sy":"un.grab","ps":"verb","t":["olatin"]},{"w":"ungraced","d":"Not graced or honored; lacking elegance, favor, or a bestowed blessing; deprived of grace.","s":"The banquet hall felt ungraced without the host's warm presence and elegant decorations.","p":"un-GRAYST","o":"Latin","y":8,"bp":25,"sy":"un.graced","ps":"adjective","t":["religion","olatin"]},{"w":"ungradated","d":"Not arranged or divided into gradual steps or grades; lacking a smooth, progressive transition from one level to another.","s":"The ungradated color wash on the wall looked flat compared to the artist's usual blended style.","p":"un-GRAY-day-tid","o":"Latin","y":8,"bp":29,"sy":"ungra.dat.ed","ps":"adjective","t":["numbers","olatin"]},{"w":"ungraduated","d":"Not marked with or divided into graduated intervals or degrees; lacking the regular markings of a scale or measure.","s":"The ungraduated cylinder made it difficult to measure exact amounts of liquid in the experiment.","p":"un-GRAJ-oo-ay-tid","o":"Latin","y":8,"bp":38,"sy":"un.grad.u.at.ed","ps":"adjective","t":["numbers","olatin"]},{"w":"ungrafted","d":"Not joined by grafting; describing a plant or branch that has not been attached to another plant through the horticultural process of grafting.","s":"The ungrafted apple seedling grew wild and produced small, bitter fruit.","p":"un-GRAFT-id","o":"Latin","y":8,"bp":28,"sy":"un.graft.ed","ps":"adjective","t":["botany","olatin"]},{"w":"ungrammared","d":"Without the application of grammatical rules; lacking the structure or organization imposed by grammar.","s":"The ancient inscription was so ungrammared that scholars struggled to decode its meaning.","p":"un-GRAM-urd","o":"Latin","y":9,"bp":35,"sy":"un.gram.mared","ps":"adjective","t":["wordwords","olatin"]},{"w":"ungrammatical","d":"not grammatical; not conforming to the rules of grammar or accepted usage","s":"The teacher circled the ungrammatical sentence on the student's paper and wrote 'fix this' in red ink.","p":"un-gruh-MAT-ih-kul","o":"Latin","y":7,"bp":28,"sy":"un.gram.mat.i.cal","ps":"adjective","t":["wordwords","olatin"]},{"w":"ungrand","d":"Not grand or impressive; lacking greatness, magnificence, or splendor; modest or plain in character.","s":"The ungrand little shack stood next to the majestic mansion, looking quite out of place.","p":"un-GRAND","o":"Latin","y":8,"bp":19,"sy":"un.grand","ps":"adjective","t":["landforms","olatin"]},{"w":"ungranulated","d":"Not formed into small grains or granules; remaining in a smooth or undivided form rather than broken into tiny particles.","s":"The ungranulated sugar dissolved unevenly in the recipe, clumping in unexpected places.","p":"un-GRAN-yoo-lay-tid","o":"Latin","y":8,"bp":39,"sy":"un.gran.u.lat.ed","ps":"adjective","t":["physics","olatin"]},{"w":"ungraspable","d":"Impossible to grasp, hold, or fully comprehend; describing something too elusive or complex to be seized physically or understood mentally.","s":"The philosopher's argument was so abstract it felt completely ungraspable to the class.","p":"un-GRASP-uh-bul","o":"Latin","y":8,"bp":35,"sy":"un.gras.pable","ps":"adjective","t":["olatin"]},{"w":"ungraspably","d":"In a manner that cannot be grasped or comprehended; in a way that eludes physical or mental understanding.","s":"The concept was ungraspably complex even for the most advanced students in the program.","p":"un-GRASP-uh-blee","o":"Latin","y":8,"bp":35,"sy":"un.gras.pably","ps":"adverb","t":["olatin"]},{"w":"ungrasped","d":"not fully apprehended","s":"The ungrasped infinite ground of all being.","p":"un-GRASPT","o":"Latin","y":8,"bp":26,"sy":"un.grasped","ps":"adjective","t":["olatin"]},{"w":"ungrated","d":"Not shredded or reduced by a grater; describing food or material that has not been processed through a grating tool.","s":"The chef used ungrated whole cheese, slicing it thinly instead of shredding it over the pasta.","p":"un-GRAYT-id","o":"Latin","y":8,"bp":27,"sy":"un.grat.ed","ps":"adjective","t":["tools","olatin"]},{"w":"ungratified","d":"not satisfied or pleased; left still wanting something","s":"She left the meeting ungratified, since none of her suggestions had been taken seriously.","p":"un-GRAT-ih-fyd","o":"Latin","y":8,"bp":37,"sy":"un.grat.i.fied","ps":"adjective","t":["olatin"]},{"w":"ungrazed","d":"Not grazed upon by animals; describing land or vegetation that has not been eaten or browsed by livestock or other grazing animals.","s":"The ungrazed meadow was thick with tall wildflowers since no animals had eaten the grass.","p":"un-GRAYZD","o":"Latin","y":7,"bp":25,"sy":"un.grazed","ps":"adjective","t":["animals","farming","olatin"]},{"w":"ungreat","d":"Not great; lacking greatness, distinction, or exceptional quality; ordinary and unremarkable.","s":"The movie was disappointingly ungreat despite its huge budget and famous cast.","p":"un-GRAYT","o":"Latin","y":8,"bp":19,"sy":"un.great","ps":"adjective","t":["olatin"]},{"w":"ungreedy","d":"Not greedy; free from excessive desire for more than one needs; generous or content with what one has.","s":"The ungreedy child split her birthday cake equally with every guest at the party.","p":"un-GREE-dee","o":"Latin","y":8,"bp":25,"sy":"un.greedy","ps":"adjective","t":["olatin"]},{"w":"ungreen","d":"Not environmentally friendly or sustainable; lacking green or living vegetation; harmful to or neglectful of the natural environment.","s":"Critics called the company's new packaging ungreen because it used layers of plastic waste.","p":"un-GREEN","o":"Latin","y":8,"bp":19,"sy":"un.green","ps":"adjective","t":["ecology","olatin"]},{"w":"ungreeted","d":"Not welcomed or acknowledged with a greeting; ignored upon arrival without any hello or recognition.","s":"The shy new student stood ungreeted at the door until the teacher noticed and welcomed her.","p":"un-GREET-id","o":"Latin","y":8,"bp":28,"sy":"un.greet.ed","ps":"adjective","t":["olatin"]},{"w":"ungregarious","d":"preferring to be alone rather than in the company of others","s":"The ungregarious cat hid upstairs whenever visitors arrived.","p":"un-grih-GAIR-ee-us","o":"Latin","y":9,"bp":39,"sy":"un.gre.gar.i.ous","ps":"adjective","t":["botany","olatin"]},{"w":"ungrieving","d":"Not experiencing or expressing grief; free from sorrow or mourning; showing no signs of sadness over a loss.","s":"The ungrieving expression on his face surprised everyone who expected tears at the sad news.","p":"un-GREEV-ing","o":"Latin","y":8,"bp":29,"sy":"un.griev.ing","ps":"adjective","t":["emotions","olatin"]},{"w":"ungrievingly","d":"In a manner that shows no grief or sorrow; without expressing or feeling mourning or sadness.","s":"She accepted the loss ungrievingly, having made peace with it long before it happened.","p":"un-GREEV-ing-lee","o":"Latin","y":8,"bp":38,"sy":"un.griev.ing.ly","ps":"adverb","t":["emotions","olatin"]},{"w":"ungrilled","d":"Not cooked on a grill; describing food that has not been exposed to the direct heat of a grilling surface or open flame.","s":"The ungrilled vegetables were served raw in the salad instead of being cooked over the flames.","p":"un-GRILD","o":"Latin","y":9,"bp":26,"sy":"un.grilled","ps":"adjective","t":["culinary","olatin"]},{"w":"ungrooved","d":"Not having grooves or channels cut into it; describing a surface that is smooth and free from any indentations or ridges.","s":"The ungrooved surface of the new vinyl record seemed strange to the collector who examined it.","p":"un-GROOVD","o":"Latin","y":8,"bp":26,"sy":"un.grooved","ps":"adjective","t":["olatin"]},{"w":"ungroundable","d":"Impossible to ground, restrict, or provide with a foundational basis; describing something or someone that cannot be confined, restricted, or given a stable foundation.","s":"The teenager argued that his behavior was ungroundable since he hadn't broken any house rules.","p":"un-GROUND-uh-bul","o":"Latin","y":9,"bp":36,"sy":"un.ground.able","ps":"adjective","t":["olatin"]},{"w":"ungrouted","d":"Describing a surface, especially tile or masonry, that has not had grout applied to fill the joints or gaps between pieces.","s":"The ungrouted tiles shifted loose because nothing was filling the gaps between them.","p":"un-GROW-tid","o":"Latin","y":9,"bp":28,"sy":"un.grout.ed","ps":"adjective","t":["buildings","olatin"]},{"w":"ungrowable","d":"Not capable of being grown or cultivated; describing a plant, crop, or organism that cannot be successfully raised in a particular environment or condition.","s":"The soil in that rocky desert patch seemed completely ungrowable, even for tough cacti.","p":"un-GROH-uh-bul","o":"Latin","y":9,"bp":29,"sy":"un.grow.able","ps":"adjective","t":["botany","ecology","farming","olatin"]},{"w":"ungrown","d":"Not yet fully grown or developed; remaining in an immature or incomplete state of growth.","s":"The ungrown seedling needed several more weeks before it would be ready to transplant outside.","p":"un-GROHN","o":"Latin","y":8,"bp":19,"sy":"un.grown","ps":"adjective","t":["olatin"]},{"w":"unguaranteeable","d":"Not able to be guaranteed or assured; describing something for which no promise or certainty of outcome can be made.","s":"The outcome of the experiment was unguaranteeable because too many variables were unknown.","p":"un-gair-un-TEE-uh-bul","o":"Latin","y":9,"bp":30,"sy":"un.guar.an.tee.able","ps":"adjective","t":["olatin"]},{"w":"unguaranteed","d":"Not backed by a guarantee or financial security; lacking any formal promise or assurance of quality, payment, or performance.","s":"The investors were nervous because the loan was completely unguaranteed, meaning there was no financial security or collateral backing it up if the company failed.","p":"un-gair-un-TEED","o":"Latin","y":8,"bp":38,"sy":"un.guar.an.teed","ps":"adjective","t":["olatin"]},{"w":"unguard","d":"To remove or withdraw a guard or protection from someone or something; to leave unprotected or exposed to danger.","s":"A chess player should never unguard the king by moving protecting pieces carelessly.","p":"un-GARD","o":"Latin","y":9,"bp":19,"sy":"un.guard","ps":"verb","t":["olatin"]},{"w":"unguardable","d":"Impossible to guard or defend against; describing a move, player, or attack that cannot be effectively stopped or blocked.","s":"The star player's speed made him virtually unguardable on the basketball court.","p":"un-GAR-duh-bul","o":"Latin","y":9,"bp":35,"sy":"un.guard.able","ps":"adjective","t":["sports","olatin"]},{"w":"unguent","d":"semisolid preparation (usually containing a medicine) applied externally as a remedy or for soothing an irritation","s":"The nurse applied a soothing unguent to the patient's dry, cracked skin.","p":"UNG-gwunt","o":"Latin","y":7,"bp":17,"ps":"noun","t":["body","pharmacy","olatin"]},{"w":"unguentary","d":"Of, relating to, or used for ointments or unguents; also used as a noun to describe a container or shop associated with ointments and salves.","s":"The ancient unguentary jar was discovered in the ruins, still faintly scented with perfumed oil.","p":"ung-GWEN-teh-ree","o":"Latin","y":9,"bp":27,"sy":"unguen.tary","ps":"adjective","t":["pharmacy","wordwords","olatin"]},{"w":"unguessable","d":"Impossible to guess or figure out; so mysterious or complex that no reasonable guess could arrive at the correct answer.","s":"The magician's trick was completely unguessable, leaving the entire audience baffled.","p":"un-GES-uh-bul","o":"Latin","y":9,"bp":34,"sy":"unguess.able","ps":"adjective","t":["olatin"]},{"w":"unguessed","d":"Not guessed or discovered by guessing; remaining unknown or unrevealed because no one has correctly identified it.","s":"The surprise ending of the novel was completely unguessed by even the most attentive readers.","p":"un-GEST","o":"Latin","y":9,"bp":25,"ps":"adjective","t":["olatin"]},{"w":"unguestlike","d":"Not behaving in the polite, considerate manner expected of a guest; failing to show the courtesy and respect appropriate when visiting someone's home.","s":"His unguestlike behavior — raiding the fridge and blasting music — annoyed his hosts.","p":"un-GEST-lyk","o":"Latin","y":9,"bp":34,"sy":"unguest.like","ps":"adjective","t":["olatin"]},{"w":"unguicular","d":"Of or relating to a nail, claw, or hoof; having or resembling a claw-like structure, especially in biology or anatomy.","s":"The biologist noted the creature's unguicular features, including its sharp, claw-like appendages.","p":"un-GWIK-yuh-ler","o":"Latin","y":9,"bp":30,"sy":"un.guic.u.lar","ps":"adjective","t":["body","olatin"]},{"w":"unguilt","d":"The absence or removal of guilt; a state of being free from blame, wrongdoing, or a sense of culpability.","s":"She walked away from the verdict with a sense of unguilt that finally let her sleep at night.","p":"un-GILT","o":"Latin","y":9,"bp":19,"sy":"un.guilt","ps":"noun","t":["law","olatin"]},{"w":"unguiltness","d":"The quality or state of being without guilt; complete freedom from blame or moral wrongdoing.","s":"His unguiltness was evident in the calm, steady way he answered every question.","p":"un-GILT-nes","o":"Latin","y":9,"bp":35,"sy":"un.guilt.ness","ps":"noun","t":["law","logic","olatin"]},{"w":"unguilty","d":"Not guilty; free from blame, wrongdoing, or moral fault.","s":"The jury declared the defendant unguilty after reviewing the new evidence.","p":"un-GIL-tee","o":"Latin","y":9,"bp":25,"sy":"un.guilty","ps":"adjective","t":["law","logic","olatin"]},{"w":"unguinous","d":"Having the quality or consistency of an ointment or grease; oily, fatty, or resembling an unguent in texture.","s":"The mechanic's unguinous hands left greasy prints on every surface he touched.","p":"UNG-gwih-nus","o":"Latin","y":9,"bp":26,"sy":"un.guinous","ps":"adjective","t":["pharmacy","olatin"]},{"w":"ungulate","d":"any of a number of mammals with hooves that are superficially similar but not necessarily closely related taxonomically","p":"UNG-gyuh-lit","o":"Latin","y":8,"bp":27,"sy":"un.gu.late","ps":"noun","t":["animals","numbers","olatin"]},{"w":"unhabitual","d":"Not habitual or customary; describing behavior or actions that are not part of a regular routine or established pattern.","s":"Taking a cold shower every morning was unhabitual for her, so it still shocked her each time.","p":"un-huh-BIH-choo-ul","o":"Latin","y":8,"bp":32,"sy":"un.hab.it.u.al","ps":"adjective","t":["olatin"]},{"w":"unhackable","d":"Impossible to hack or break into using digital or physical means; describing a system, device, or network that is completely secure against unauthorized access.","s":"The company claimed its new encryption system was completely unhackable.","p":"un-HAK-uh-bul","o":"Latin","y":8,"bp":29,"sy":"un.hack.able","ps":"adjective","t":["tools","olatin"]},{"w":"unhackneyed","d":"Not overused or worn out by repetition; fresh, original, and not made dull through excessive familiarity or cliché.","s":"The poet's unhackneyed metaphors felt refreshingly original in a sea of clichés.","p":"un-HAK-need","o":"Latin","y":8,"bp":35,"sy":"un.hack.neyed","ps":"adjective","t":["olatin"]},{"w":"unhair","d":"To remove hair from a surface, hide, or skin, often as part of a tanning or preparation process; to make hairless.","s":"Leather tanners must unhair the hide before beginning the curing process.","p":"un-HAIR","o":"Latin","y":8,"bp":18,"sy":"un.hair","ps":"verb","t":["body","olatin"]},{"w":"unhairing","d":"The process of removing hair from animal hides or skins, typically as a step in leatherworking or taxidermy.","s":"The unhairing of the animal skins was the messiest step in making traditional leather.","p":"un-HAIR-ing","o":"Latin","y":9,"bp":28,"sy":"un.hair.ing","ps":"noun","t":["animals","vehicles","olatin"]},{"w":"unhallow","d":"remove the consecration from a person or an object","s":"The ancient ritual was performed to unhallow the temple after it had been desecrated.","p":"un-HAL-oh","o":"Latin","y":9,"bp":27,"sy":"un.hal.low","ps":"verb","t":["olatin"]},{"w":"unhallowed","d":"remove the consecration from a person or an object","s":"The soldiers were buried in unhallowed ground far from the village cemetery.","p":"un-HAL-ohd","o":"Latin","y":8,"bp":29,"sy":"un.hal.lowed","ps":"verb","t":["olatin"]},{"w":"unhammered","d":"Not shaped, struck, or worked with a hammer; describing metal or material that has not undergone the hammering process.","s":"The unhammered metal was still smooth and flat, waiting for the blacksmith to shape it.","p":"un-HAM-erd","o":"Latin","y":9,"bp":29,"sy":"un.ham.mered","ps":"adjective","t":["tools","olatin"]},{"w":"unhandcuff","d":"To remove handcuffs from a person; to release someone from the restraint of handcuffs.","s":"The officer moved to unhandcuff the suspect after the judge ordered his release.","p":"un-HAND-kuf","o":"Latin","y":9,"bp":29,"sy":"un.hand.cuff","ps":"verb","t":["olatin"]},{"w":"unhandicapped","d":"Not having a handicap or disadvantage; describing a person or situation that is free from any physical, mental, or competitive limitation.","s":"On an equal playing field, the unhandicapped runners finished the race in record time.","p":"un-HAN-dee-kapt","o":"Latin","y":9,"bp":26,"sy":"un.hand.i.capped","ps":"adjective","t":["olatin"]},{"w":"unhandsome","d":"Not attractive or good-looking; lacking physical beauty or appeal; also used to describe behavior that is ungracious or ungenerous.","s":"The old building's crumbling facade looked unhandsome next to the gleaming new tower.","p":"un-HAN-sum","o":"Latin","y":9,"bp":29,"sy":"un.hand.some","ps":"adjective","t":["olatin"]},{"w":"unhandsomely","d":"In a manner that is unattractive, ungracious, or ungenerous; without physical appeal or generous behavior.","s":"He behaved unhandsomely by taking credit for his partner's work.","p":"un-HAN-sum-lee","o":"Latin","y":8,"bp":38,"sy":"un.hand.some.ly","ps":"adverb","t":["olatin"]},{"w":"unhang","d":"To take down or remove something that has been hung; to detach an object from the position in which it was hanging.","s":"She decided to unhang the old portrait and replace it with a family photograph.","p":"un-HANG","o":"Latin","y":8,"bp":18,"sy":"un.hang","ps":"verb","t":["olatin"]},{"w":"unhanged","d":"not hung up or suspended; taken down, or never put into a hanging position","s":"The new painting stayed unhanged for a month, leaning against the wall of the hallway.","p":"un-HANGD","o":"Latin","y":8,"bp":25,"sy":"un.hanged","ps":"adjective","t":["olatin"]},{"w":"unhappen","d":"To cause something that has occurred to be reversed or undone; to make an event seem as though it never took place, typically used in a hypothetical or wishful sense.","s":"No matter how much she wished it, she could not unhappen the argument that ended their friendship.","p":"un-HAP-un","o":"Latin","y":8,"bp":27,"sy":"un.hap.pen","ps":"verb","t":["olatin"]},{"w":"unharassed","d":"Not subjected to harassment, intimidation, or persistent annoyance; free from unwanted pressure or troubling interference.","s":"For the first time in months, she walked down the street feeling unharassed and free.","p":"un-huh-RAST","o":"Latin","y":9,"bp":29,"sy":"un.ha.rassed","ps":"adjective","t":["olatin"]},{"w":"unharbour","d":"To drive out or expel from a place of shelter or refuge; to force someone or something out of a harbor or protected place.","s":"The storm forced the captain to unharbour and sail into open water immediately.","p":"un-HAR-ber","o":"Latin","y":9,"bp":28,"sy":"un.har.bour","ps":"verb","t":["physics","waterways","seafaring","olatin"]},{"w":"unhardenable","d":"Not capable of being hardened; describing a material or substance that cannot be made harder through any physical or chemical process.","s":"The soft clay proved unhardenable even after hours in the kiln.","p":"un-HAR-dun-uh-bul","o":"Latin","y":9,"bp":38,"sy":"un.hard.en.able","ps":"adjective","t":["chemistry","olatin"]},{"w":"unhardiness","d":"The quality or state of being not hardy; a lack of toughness, resilience, or ability to withstand difficult conditions.","s":"The plant's unhardiness made it impossible to grow in cold northern climates.","p":"un-HAR-dee-nes","o":"Latin","y":9,"bp":37,"sy":"un.har.di.ness","ps":"noun","t":["olatin"]},{"w":"unhardy","d":"Not hardy or robust; lacking the toughness, strength, or resilience needed to endure harsh or difficult conditions.","s":"The unhardy seedlings wilted during the unexpected late frost.","p":"un-HAR-dee","o":"Latin","y":8,"bp":19,"sy":"un.hardy","ps":"adjective","t":["olatin"]},{"w":"unharmful","d":"Not causing harm or injury; completely safe and posing no danger or damage to people, animals, or the environment.","s":"The scientist confirmed the substance was completely unharmful to humans.","p":"un-HARM-ful","o":"Latin","y":8,"bp":28,"sy":"un.harm.ful","ps":"adjective","t":["animals","ecology","olatin"]},{"w":"unharming","d":"Not causing harm or injury to anyone or anything; completely harmless in action or effect.","s":"The unharming nature of the gentle breeze made the afternoon walk along the cliffs feel peaceful and completely safe for everyone in the group.","p":"un-HAR-ming","o":"Latin","y":8,"bp":28,"sy":"un.harm.ing","ps":"adjective","t":["olatin"]},{"w":"unharmonic","d":"Lacking harmony or musical agreement; producing sounds or combinations that are discordant and unpleasant to the ear.","s":"The unharmonic screeching of the poorly tuned instruments during rehearsal made the conductor wince and immediately call for a ten-minute break.","p":"un-har-MON-ik","o":"Latin","y":8,"bp":30,"sy":"un.har.mon.ic","ps":"adjective","t":["music","olatin"]},{"w":"unharmonized","d":"Not brought into harmony or agreement; left without coordination or blending so that each part remains separate and inconsistent with the others.","s":"The unharmonized vocal parts in the choir's first practice clashed so badly that the director asked everyone to stop and start from the beginning.","p":"un-HAR-muh-nyzd","o":"Latin","y":8,"bp":38,"sy":"un.har.mo.nized","ps":"adjective","t":["music","olatin"]},{"w":"unharried","d":"Not harassed, rushed, or stressed; free from pressure or disturbance and able to proceed at a calm, unhurried pace.","s":"The unharried scientist took her time examining each specimen carefully, knowing that rushing would only lead to mistakes in her important research.","p":"un-HAIR-eed","o":"Latin","y":8,"bp":28,"sy":"un.har.ried","ps":"adjective","t":["olatin"]},{"w":"unharvestable","d":"Not capable of being gathered or collected; describing a crop or resource that cannot be successfully harvested due to damage, inaccessibility, or other conditions.","s":"After the severe flooding destroyed the fields, the soggy and rotting wheat became completely unharvestable, leaving the farmers facing a devastating financial loss for the season.","p":"un-HAR-veh-stuh-bul","o":"Latin","y":9,"bp":25,"sy":"un.har.vestable","ps":"adjective","t":["farming","olatin"]},{"w":"unhashable","d":"Not able to be processed by a hash function; describing data or an object that cannot be converted into a fixed hash value, often because it is mutable or otherwise incompatible.","s":"The programmer quickly discovered that the list she had used as a dictionary key was unhashable, causing her program to crash with a frustrating type error.","p":"un-HASH-uh-bul","o":"Latin","y":9,"bp":29,"sy":"un.hash.able","ps":"adjective","t":["olatin"]},{"w":"unhashed","d":"Not subjected to a hash function; remaining in its original, unencrypted, or unscrambled state without being converted into a coded value.","s":"The security expert was alarmed to find that all the passwords in the old database were stored as unhashed plain text, making them easy targets for hackers.","p":"un-HASHT","o":"Latin","y":8,"bp":25,"sy":"un.hashed","ps":"adjective","t":["olatin"]},{"w":"unhasp","d":"To unfasten or open a hasp; to release a hinged clasp or fastening that holds a door, gate, or lid closed.","s":"She carefully reached over the old wooden fence to unhasp the rusty latch, pulling the gate open just wide enough for her to slip through into the garden.","p":"un-HASP","o":"Latin","y":8,"bp":18,"sy":"un.hasp","ps":"verb","t":["olatin"]},{"w":"unhasting","d":"Not hurrying or rushing; moving or acting in a deliberate, slow, and measured manner without any sense of urgency.","s":"The unhasting elder moved through the crowded market with quiet confidence, stopping to examine each item at his own pace without feeling pressured by the busy crowd around him.","p":"un-HAYST-ing","o":"Latin","y":8,"bp":28,"sy":"un.hast.ing","ps":"adjective","t":["numbers","olatin"]},{"w":"unhat","d":"To remove a hat from someone's head, either as a gesture of respect or simply to take it off.","s":"The old-fashioned gentleman would unhat himself every time he entered the building, placing his bowler carefully on the hook beside the door before greeting his hosts.","p":"un-HAT","o":"Latin","y":7,"bp":17,"sy":"un.hat","ps":"verb","t":["fabrics","olatin"]},{"w":"unhatchable","d":"Not capable of hatching; describing an egg or plan that cannot successfully develop or come to fruition under any circumstances.","s":"The biologist sadly confirmed that the penguin egg was unhatchable after examining it, meaning the colony would not see a new chick born that season.","p":"un-HACH-uh-bul","o":"Latin","y":9,"bp":35,"sy":"un.hatch.able","ps":"adjective","t":["spices","olatin"]},{"w":"unhated","d":"Not hated or regarded with dislike; free from the animosity or ill will of others.","s":"Despite being strict in the classroom, Ms. Rivera was largely unhated by her students, who appreciated her fairness and genuine interest in their success.","p":"un-HAYT-ed","o":"Latin","y":8,"bp":20,"sy":"un.hat.ed","ps":"adjective","t":["olatin"]},{"w":"unhateful","d":"Free from hatred or strong dislike; not characterized by ill will, hostility, or resentment toward others.","s":"Even after years of difficult conflicts, she managed to remain unhateful toward those who had wronged her, choosing to focus on forgiveness and moving forward with her life.","p":"un-HAYT-ful","o":"Latin","y":8,"bp":28,"sy":"un.hate.ful","ps":"adjective","t":["character","olatin"]},{"w":"unhatted","d":"Not wearing a hat; having the head uncovered or bare, without any form of headwear.","s":"The unhatted boy stood in the cold rain at the bus stop, wishing he had listened to his mother's advice and grabbed his cap before running out the door.","p":"un-HAT-ed","o":"Latin","y":9,"bp":27,"sy":"un.hat.ted","ps":"adjective","t":["fabrics","olatin"]},{"w":"unhaunted","d":"Not visited or disturbed by ghosts, spirits, or persistent troubling memories; free from any supernatural or psychological hauntings.","s":"After the old farmhouse had been renovated and filled with cheerful light, neighbors agreed it felt completely unhaunted and welcoming, nothing like the eerie place it had once been.","p":"un-HAWN-ted","o":"Latin","y":8,"bp":28,"sy":"un.haunt.ed","ps":"adjective","t":["olatin"]},{"w":"unhaveable","d":"Not capable of being possessed, obtained, or owned; describing something that is impossible for anyone to have or acquire.","s":"True peace of mind sometimes feels unhaveable during exam season, when worries about grades and deadlines seem to crowd out every moment of calm and rest.","p":"un-HAV-uh-bul","o":"Latin","y":9,"bp":29,"sy":"un.have.able","ps":"adjective","t":["olatin"]},{"w":"unhazarded","d":"Not risked or exposed to danger; kept safe without being subjected to any hazard or perilous chance.","s":"The museum's most valuable painting remained unhazarded in its climate-controlled vault during the renovation, protected from dust, moisture, and any accidental damage by the construction workers nearby.","p":"un-HAZ-erd-ed","o":"Latin","y":8,"bp":30,"sy":"un.haz.ard.ed","ps":"adjective","t":["olatin"]},{"w":"unhazardous","d":"thought to be devoid of risk","s":"The science teacher assured students that the experiment was completely unhazardous if they followed directions.","p":"un-HAZ-er-dus","o":"Latin","y":9,"bp":35,"sy":"un.haz.ardous","ps":"adjective","t":["olatin"]},{"w":"unhazed","d":"Not subjected to hazing, harassment, or intimidation; also, not surrounded by haze or mental confusion; clear and untouched.","s":"The new members of the drama club were relieved to find they were completely unhazed, welcomed warmly with rehearsal schedules and friendly introductions rather than embarrassing initiation challenges.","p":"un-HAYZD","o":"Latin","y":8,"bp":19,"sy":"un.hazed","ps":"adjective","t":["olatin"]},{"w":"unhealable","d":"Not capable of being healed, cured, or restored to health; describing a wound, illness, or damage that cannot be remedied by any means.","s":"The doctors feared that the deep emotional wound left by the tragic accident might prove unhealable without years of dedicated therapy and strong support from family and friends.","p":"un-HEEL-uh-bul","o":"Latin","y":9,"bp":29,"sy":"un.heal.able","ps":"adjective","t":["disease","olatin"]},{"w":"unhealing","d":"Not healing or promoting recovery; failing to mend, repair, or restore health in a wound, injury, or troubled situation.","s":"The unhealing sore on his foot continued to worry the doctor, who referred him to a specialist to find out why the tissue simply refused to recover.","p":"un-HEEL-ing","o":"Latin","y":8,"bp":28,"sy":"un.heal.ing","ps":"adjective","t":["olatin"]},{"w":"unhealthfully","d":"In a manner that is harmful to health or well-being; in a way that promotes poor physical or mental condition.","s":"The teenagers were eating unhealthfully all week during finals, surviving on energy drinks and vending machine snacks instead of balanced meals and enough sleep to keep their brains sharp.","p":"un-HELTH-ful-ee","o":"Latin","y":9,"bp":26,"sy":"un.health.ful.ly","ps":"adverb","t":["olatin"]},{"w":"unhealthfulness","d":"the quality of promoting poor health","s":"The unhealthfulness of the cafeteria menu prompted parents to demand more nutritious options.","p":"un-HELTH-ful-nes","o":"Latin","y":9,"bp":28,"sy":"un.health.ful.ness","ps":"noun","t":["olatin"]},{"w":"unheart","d":"To discourage or dishearten someone; to remove the courage, spirit, or emotional core from a person, leaving them deflated and without motivation.","s":"The harsh criticism from the judges seemed to unheart the young dancer completely, and she sat quietly in the corner for a long time before her coach could lift her spirits again.","p":"un-HART","o":"Latin","y":8,"bp":19,"sy":"un.heart","ps":"verb","t":["emotions","olatin"]},{"w":"unheatable","d":"Not capable of being heated or warmed; describing a substance or object that resists any increase in temperature regardless of the heat applied.","s":"The strange new compound was essentially unheatable under normal laboratory conditions, which made it a potentially valuable material for use in high-temperature industrial environments and spacecraft shielding.","p":"un-HEET-uh-bul","o":"Latin","y":9,"bp":29,"sy":"un.heat.able","ps":"adjective","t":["olatin"]},{"w":"unheavenly","d":"Not resembling or befitting heaven; lacking the beautiful, peaceful, or divine qualities associated with paradise; earthly or unpleasant.","s":"The noise and chaos of the overcrowded bus terminal felt deeply unheavenly to the traveler, who had been imagining a serene and quiet journey through the peaceful countryside.","p":"un-HEV-en-lee","o":"Latin","y":8,"bp":30,"sy":"un.heav.en.ly","ps":"adjective","t":["olatin"]},{"w":"unhedged","d":"Not protected by a financial hedge or qualifying statement; fully exposed to risk or stated without reservation or caution.","s":"His unhedged opinion about the controversy got him into serious trouble with his colleagues.","p":"uh-NHEH-jd","o":"Latin","y":7,"bp":19,"sy":"ah.nhheh.jhd","ps":"adjective","t":["olatin"]},{"w":"unhedonistic","d":"Not focused on or devoted to the pursuit of pleasure or self-gratification; characterized by a disregard for personal enjoyment as a primary goal.","s":"The monk's unhedonistic lifestyle, centered on meditation and service to others, stood in sharp contrast to the pleasure-seeking habits of many people living in the busy city nearby.","p":"un-hee-duh-NIS-tik","o":"Latin","y":8,"bp":39,"sy":"un.he.do.nis.tic","ps":"adjective","t":["character","sports","olatin"]},{"w":"unheedful","d":"Not paying attention or taking notice; careless and inattentive, especially when caution or awareness is needed.","s":"The unheedful driver sped through the school zone without slowing down, apparently unaware of the flashing warning lights and the crossing guard waving frantically from the curb.","p":"un-HEED-ful","o":"Latin","y":8,"bp":28,"sy":"un.heed.ful","ps":"adjective","t":["olatin"]},{"w":"unheediness","d":"The quality or state of being inattentive, careless, or neglectful of warnings, cautions, or important information.","s":"The teacher's repeated warnings about the test went ignored, and the class's unheediness became obvious when nearly everyone failed to study the one chapter she had specifically highlighted for review.","p":"un-HEE-dee-nes","o":"Latin","y":9,"bp":37,"sy":"un.heed.i.ness","ps":"noun","t":["olatin"]},{"w":"unheeding","d":"marked by or paying little heed or attention","p":"un-HEED-ing","o":"Latin","y":8,"bp":28,"sy":"un.heed.ing","ps":"adjective","t":["olatin"]},{"w":"unheedingly","d":"In a manner that shows a lack of attention or care; acting without noticing or responding to warnings, signs, or important information.","s":"She unheedingly walked past the wet floor sign and slipped, proving that her tendency to ignore posted warnings could sometimes lead to very real and painful consequences.","p":"un-HEED-ing-lee","o":"Latin","y":8,"bp":37,"sy":"un.heed.ing.ly","ps":"adverb","t":["olatin"]},{"w":"unheedy","d":"Lacking heed or caution; careless and inattentive, prone to ignoring important warnings or proceeding without due care.","s":"The unheedy puppy bounded straight toward the busy street, and its owner had to sprint to catch it before it reached the dangerous traffic just around the corner.","p":"un-HEE-dee","o":"Latin","y":8,"bp":19,"sy":"un.heedy","ps":"adjective","t":["olatin"]},{"w":"unheired","d":"Having no heir or successor; describing a title, estate, or position that has been left without anyone to inherit or carry it forward.","s":"The ancient earldom passed into the hands of a distant cousin after it was discovered that the estate had been unheired for over two decades following the last lord's death.","p":"un-AIRD","o":"Latin","y":8,"bp":25,"sy":"un.heired","ps":"adjective","t":["kinship","olatin"]},{"w":"unhelm","d":"To remove a helmet from someone's head; to strip away the protective headgear, leaving the head exposed.","s":"After the jousting tournament ended, the victor reached over to unhelm his defeated opponent as a traditional sign of respect and acknowledgment of a well-fought contest.","p":"un-HELM","o":"Latin","y":8,"bp":18,"sy":"un.helm","ps":"verb","t":["olatin"]},{"w":"unhelmet","d":"To take a helmet off someone or oneself; to remove protective headgear, exposing the head beneath.","s":"The coach asked the players to unhelmet and gather around her on the field so she could address them face-to-face before the second half of the championship game began.","p":"un-HEL-met","o":"Latin","y":8,"bp":27,"sy":"un.hel.met","ps":"verb","t":["olatin"]},{"w":"unhelmeted","d":"Not wearing a helmet; having an uncovered or unprotected head, without any form of protective headgear.","s":"The unhelmeted cyclist weaved through traffic confidently, seemingly unaware of how much more vulnerable he was compared to the riders around him who were properly protected.","p":"un-HEL-meh-ted","o":"Latin","y":8,"bp":30,"sy":"un.hel.met.ed","ps":"adjective","t":["olatin"]},{"w":"unhelpable","d":"Not capable of being helped or assisted; describing a situation or person that cannot be improved or aided by any available means.","s":"The social worker felt that no case was truly unhelpable, and she threw all her energy into finding creative solutions even for the most difficult situations she encountered.","p":"un-HEL-puh-bul","o":"Latin","y":9,"bp":30,"sy":"un.hel.pa.ble","ps":"adjective","t":["olatin"]},{"w":"unhelped","d":"Not given assistance or support; left without aid or help when it was needed or expected.","s":"The injured bird sat unhelped in the corner of the yard for an hour before a kind neighbor finally spotted it and carefully brought it inside to call a wildlife rescue center.","p":"un-HELPT","o":"Latin","y":8,"bp":25,"sy":"un.helped","ps":"adjective","t":["olatin"]},{"w":"unhelpfully","d":"in an unhelpful manner","s":"He stood by unhelpfully while the house burned down.","p":"un-HELP-fuh-lee","o":"Latin","y":8,"bp":37,"sy":"un.help.ful.ly","ps":"adverb","t":["olatin"]},{"w":"unhelpfulness","d":"an inability to be helpful","s":"The customer service representative's unhelpfulness left the frustrated shopper with no solution.","p":"un-HELP-fuh-ness","o":"Latin","y":9,"bp":26,"sy":"un.help.ful.ness","ps":"noun","t":["olatin"]},{"w":"unherded","d":"Not gathered, driven, or managed as a herd; left to roam or exist without being guided or grouped together.","s":"The unherded sheep wandered freely across the wide green meadow all morning.","p":"un-HUR-ded","o":"Latin","y":8,"bp":27,"sy":"un.herd.ed","ps":"adjective","t":["olatin"]},{"w":"unhesitative","d":"Showing no hesitation or uncertainty; acting with complete confidence and without pause.","s":"Her unhesitative response to the emergency showed how well she had been trained.","p":"un-HEZ-ih-tay-tiv","o":"Latin","y":9,"bp":38,"sy":"un.hesi.ta.tive","ps":"adjective","t":["olatin"]},{"w":"unhesitatively","d":"In a manner that shows no hesitation or wavering; acting with immediate and confident decisiveness.","s":"He unhesitatively jumped into the lake to rescue the drowning puppy.","p":"un-HEZ-ih-tay-tiv-lee","o":"Latin","y":9,"bp":29,"sy":"un.hesi.ta.tive.ly","ps":"adverb","t":["olatin"]},{"w":"unhide","d":"To make visible or reveal something that was previously hidden or concealed.","s":"She clicked the button to unhide the secret folder on her computer.","p":"un-HYD","o":"Latin","y":7,"bp":18,"sy":"un.hide","ps":"verb","t":["olatin"]},{"w":"unhilarious","d":"Not funny or amusing; failing to provoke laughter or humor in any way.","s":"The comedian's last joke was completely unhilarious, and the audience sat in awkward silence.","p":"un-hih-LAIR-ee-us","o":"Latin","y":9,"bp":38,"sy":"un.hi.lar.i.ous","ps":"adjective","t":["olatin"]},{"w":"unhill","d":"To flatten or remove a hill or mound; to level raised ground so it is no longer elevated.","s":"The gardener used a rake to unhill the soil she had mounded around the plants.","p":"un-HIL","o":"Latin","y":9,"bp":18,"sy":"un.hill","ps":"verb","t":["landforms","olatin"]},{"w":"unhinderedly","d":"In a manner free from any obstacle, interference, or restriction; moving or acting without being blocked.","s":"The river flowed unhinderedly through the valley after the old dam was removed.","p":"un-HIN-durd-lee","o":"Latin","y":8,"bp":38,"sy":"un.hin.dered.ly","ps":"adverb","t":["olatin"]},{"w":"unhinted","d":"Not suggested, implied, or indicated by any hint; left entirely without a clue or subtle signal.","s":"Her surprise birthday party remained completely unhinted at until the moment she walked through the door.","p":"un-HIN-ted","o":"Latin","y":8,"bp":27,"sy":"un.hint.ed","ps":"adjective","t":["olatin"]},{"w":"unhippocratic","d":"Contrary to or not in keeping with the ethical principles of the Hippocratic oath taken by medical professionals.","s":"The doctor's decision to withhold treatment was considered unhippocratic by his horrified colleagues.","p":"un-hip-oh-KRAT-ik","o":"Latin","y":9,"bp":28,"sy":"un.hip.po.crat.ic","ps":"adjective","t":["body","logic","olatin"]},{"w":"unhirable","d":"Not suitable or qualified to be hired for a job; impossible to employ due to disqualifying characteristics.","s":"After the scandal, the executive became virtually unhirable throughout the entire industry.","p":"un-HY-ruh-bul","o":"Latin","y":9,"bp":26,"sy":"un.hirable","ps":"adjective","t":["olatin"]},{"w":"unhired","d":"Not having been selected or employed for a position; still without a job after applying or being considered.","s":"The talented artist remained unhired for months despite sending out dozens of applications.","p":"un-HYRD","o":"Latin","y":8,"bp":19,"sy":"un.hired","ps":"adjective","t":["olatin"]},{"w":"unhirsute","d":"Lacking hair or having little to no body hair; not hairy or covered with coarse, bristly hair.","s":"The unhirsute cat looked strange without its usual fluffy coat after the groomer shaved it.","p":"un-hur-SOOT","o":"Latin","y":9,"bp":28,"sy":"un.hir.sute","ps":"adjective","t":["olatin"]},{"w":"unhistoried","d":"Having no recorded history or notable past events; lacking a documented or storied heritage.","s":"The unhistoried village had no written records or famous events to its name.","p":"un-HIS-tuh-reed","o":"Latin","y":8,"bp":37,"sy":"un.his.to.ried","ps":"adjective","t":["olatin"]},{"w":"unhistrionic","d":"Free from dramatic exaggeration or theatrical behavior; calm, restrained, and not given to overly emotional display.","s":"Her unhistrionic response to winning the award impressed everyone who expected dramatic tears.","p":"un-his-tree-ON-ik","o":"Latin","y":8,"bp":38,"sy":"un.histri.on.ic","ps":"adjective","t":["stage","emotions","olatin"]},{"w":"unhit","d":"Not struck, reached, or contacted by a blow, projectile, or attack; having avoided being hit.","s":"The unhit target at the far end of the range made the archer determined to try again.","p":"un-HIT","o":"Latin","y":7,"bp":17,"sy":"un.hit","ps":"adjective","t":["olatin"]},{"w":"unhittable","d":"Impossible or extremely difficult to hit, strike, or make contact with; beyond the reach of any blow or attack.","s":"The pitcher's curveball was so sharp it seemed completely unhittable to every batter.","p":"un-HIT-uh-bul","o":"Latin","y":9,"bp":29,"sy":"un.hit.table","ps":"adjective","t":["olatin"]},{"w":"unhive","d":"To remove bees from a hive; to disperse or release a colony from its hive structure.","s":"The beekeeper decided to unhive the colony and relocate the bees to a larger box.","p":"un-HYV","o":"Latin","y":8,"bp":18,"sy":"un.hive","ps":"verb","t":["insects","olatin"]},{"w":"unhoard","d":"To release or distribute what has been hoarded; to bring a stockpile out of storage and make it available.","s":"After years of collecting, she finally decided to unhoard her vast collection of vintage toys.","p":"un-HORD","o":"Latin","y":8,"bp":19,"sy":"un.hoard","ps":"verb","t":["olatin"]},{"w":"unhold","d":"To release from a grip or hold; to let go of something that was being held or restrained.","s":"The toddler refused to unhold his mother's hand even when they reached the playground.","p":"un-HOHLD","o":"Latin","y":8,"bp":18,"sy":"un.hold","ps":"verb","t":["olatin"]},{"w":"unholdable","d":"Impossible to hold, grasp, or contain; too slippery, abstract, or fleeting to be kept in one's grip.","s":"The wriggling puppy was practically unholdable as it squirmed out of every embrace.","p":"un-HOHL-duh-bul","o":"Latin","y":9,"bp":29,"sy":"un.hold.able","ps":"adjective","t":["time","olatin"]},{"w":"unholed","d":"Having no hole or perforation; intact and without any opening, puncture, or hollow space.","s":"She bought an unholed piece of wood to replace the damaged panel in the fence.","p":"un-HOHLD","o":"Latin","y":8,"bp":19,"sy":"un.holed","ps":"adjective","t":["olatin"]},{"w":"unholster","d":"To draw or remove a weapon, especially a gun, from its holster; to take something out of its protective casing.","s":"The officer was trained never to unholster his weapon unless absolutely necessary.","p":"un-HOHL-stur","o":"Latin","y":8,"bp":28,"sy":"un.hol.ster","ps":"verb","t":["war","olatin"]},{"w":"unholstered","d":"Having been drawn out of a holster; describing a weapon or object that has been removed from its carrying case.","s":"The guard stood at attention with his unholstered firearm ready in his hand.","p":"un-HOHL-sturd","o":"Latin","y":7,"bp":35,"sy":"un.hol.stered","ps":"adjective","t":["war","olatin"]},{"w":"unhomelike","d":"Not resembling or feeling like a home; lacking the warmth, comfort, and familiarity associated with a welcoming home.","s":"The cold, bare hospital room felt unhomelike and made recovery feel even harder.","p":"un-HOHM-lyk","o":"Latin","y":9,"bp":29,"sy":"un.home.like","ps":"adjective","t":["olatin"]},{"w":"unhomelikeness","d":"The quality or state of not feeling like a home; the absence of the warmth, coziness, and comfort that define a home.","s":"The unhomelikeness of the empty apartment struck her the moment she walked through the door.","p":"un-HOHM-lyk-nes","o":"Latin","y":9,"bp":27,"sy":"un.home.like.ness","ps":"noun","t":["olatin"]},{"w":"unhomeliness","d":"The state or quality of lacking the comfortable, cozy qualities of a home; the feeling that a place is cold or unwelcoming.","s":"The unhomeliness of the stark waiting room made patients feel anxious and uncomfortable.","p":"un-HOHM-lee-nes","o":"Latin","y":9,"bp":38,"sy":"un.home.li.ness","ps":"noun","t":["olatin"]},{"w":"unhomely","d":"Not having the cozy, comfortable, or welcoming qualities of a home; feeling cold, strange, or unfamiliar.","s":"The sleek, modern furniture gave the cottage an unhomely feeling that guests found off-putting.","p":"un-HOHM-lee","o":"Latin","y":8,"bp":27,"sy":"un.home.ly","ps":"adjective","t":["olatin"]},{"w":"unhomogenized","d":"not having undergone homogenization","s":"The unhomogenized milk from the farm had a thick layer of cream floating on top.","p":"un-hoh-MOJ-uh-nyzd","o":"Latin","y":9,"bp":28,"sy":"un.ho.mog.e.nized","ps":"adjective","t":["olatin"]},{"w":"unhoned","d":"Not sharpened or refined; lacking the keen edge or polished skill that comes from careful practice and preparation.","s":"The unhoned blade was too dull to cut through the thick rope efficiently.","p":"un-HOHND","o":"Latin","y":8,"bp":19,"sy":"un.honed","ps":"adjective","t":["olatin"]},{"w":"unhoneyed","d":"Not sweetened with honey or flattery; lacking a sweet, smooth, or soothing quality in taste or tone.","s":"The unhoneyed herbal tea tasted bitter without any sweetener to soften its sharp flavor.","p":"un-HUN-eed","o":"Latin","y":8,"bp":26,"sy":"un.honeyed","ps":"adjective","t":["olatin"]},{"w":"unhonor'd","d":"Not honored or celebrated; lacking the recognition, respect, or tribute that was deserved, used especially in poetry.","s":"The brave soldier died unhonor'd, his deeds forgotten by the kingdom he served.","p":"un-ON-urd","o":"Latin","y":8,"bp":26,"sy":"un.honor'd","ps":"adjective","t":["poetry","olatin"]},{"w":"unhonorable","d":"Not worthy of honor or respect; lacking integrity or the qualities that earn admiration and esteem from others.","s":"His unhonorable conduct during the tournament led to his immediate disqualification.","p":"un-ON-ur-uh-bul","o":"Latin","y":9,"bp":35,"sy":"un.honor.able","ps":"adjective","t":["olatin"]},{"w":"unhonored","d":"Not given honor, recognition, or tribute; overlooked or neglected without receiving the respect or praise that is deserved.","s":"Many teachers go unhonored despite dedicating their entire lives to their students.","p":"un-ON-urd","o":"Latin","y":8,"bp":26,"sy":"un.honored","ps":"adjective","t":["olatin"]},{"w":"unhonour'd","d":"British spelling variant meaning not honored or celebrated; left without tribute or recognition, especially in verse.","s":"The poet wrote of warriors who died unhonour'd on forgotten battlefields.","p":"un-ON-urd","o":"Latin","y":9,"bp":27,"sy":"un.honour'd","ps":"adjective","t":["poetry","wordwords","olatin"]},{"w":"unhonourable","d":"British spelling of unhonorable; not deserving of honor or respect; acting in a way that violates standards of integrity.","s":"The committee declared his actions unhonourable and stripped him of his title.","p":"un-ON-ur-uh-bul","o":"Latin","y":9,"bp":35,"sy":"un.honourable","ps":"adjective","t":["wordwords","olatin"]},{"w":"unhood","d":"To remove a hood from someone or something; to uncover or expose the head or top by pulling away a covering.","s":"She reached out to unhood the falcon before releasing it into the open sky.","p":"un-HUD","o":"Latin","y":8,"bp":18,"sy":"un.hood","ps":"verb","t":["olatin"]},{"w":"unhoofed","d":"Lacking hooves; not having the hard, protective foot covering characteristic of horses, cattle, and similar animals.","s":"The sculptor created an unhoofed mythical creature with smooth, rounded feet instead of hooves.","p":"un-HOOFD","o":"Latin","y":8,"bp":25,"sy":"un.hoofed","ps":"adjective","t":["animals","olatin"]},{"w":"unhookable","d":"Impossible or very difficult to unhook or detach; so tangled or fixed that it cannot be freed from a hook or fastening.","s":"The clasp was so bent and rusted that the necklace became completely unhookable.","p":"un-HUK-uh-bul","o":"Latin","y":9,"bp":29,"sy":"un.hook.able","ps":"adjective","t":["olatin"]},{"w":"unhoop","d":"To remove or release from a hoop; to take apart something held together by a circular band or ring.","s":"The cooper had to unhoop the barrel carefully to replace the rotting wooden staves.","p":"un-HOOP","o":"Latin","y":8,"bp":18,"sy":"un.hoop","ps":"verb","t":["olatin"]},{"w":"unhoped","d":"so unexpected as to have not been imagined","s":"An unhoped-for piece of luck.","p":"un-HOPD","o":"Latin","y":8,"bp":19,"sy":"un.hoped","ps":"adjective","t":["olatin"]},{"w":"unhopeful","d":"showing utter resignation or hopelessness","s":"After weeks of failed attempts to rescue the stranded hikers, the exhausted rescue team grew unhopeful that they would find survivors before the storm arrived.","p":"un-HOHP-ful","o":"Latin","y":8,"bp":28,"sy":"un.hope.ful","ps":"adjective","t":["olatin"]},{"w":"unhorrified","d":"Not shocked, frightened, or horrified; remaining calm or unaffected when confronted with something that would normally cause horror or alarm.","s":"The seasoned nurse was unhorrified by the gory scene because she had seen far worse.","p":"un-HOR-ih-fyd","o":"Latin","y":9,"bp":37,"sy":"un.hor.ri.fied","ps":"adjective","t":["olatin"]},{"w":"unhorselike","d":"Not resembling or characteristic of a horse; behaving or appearing in a way that is unusual or atypical for a horse.","s":"The tiny, spotted creature moved in an unhorselike way that confused the stable hands.","p":"un-HORS-lyk","o":"Latin","y":9,"bp":35,"sy":"un.horse.like","ps":"adjective","t":["animals","olatin"]},{"w":"unhosed","d":"Not sprayed or cleaned with a hose; also informally, not cheated or treated unfairly.","s":"The dusty car sat unhosed in the driveway while its owner was away on vacation.","p":"un-HOHZD","o":"Latin","y":8,"bp":19,"sy":"un.hosed","ps":"adjective","t":["olatin"]},{"w":"unhospitable","d":"Not welcoming or friendly to guests; failing to provide comfort or shelter to visitors.","s":"The rocky, windswept island was unhospitable to settlers who tried to build homes there.","p":"un-HOS-pih-tuh-bul","o":"Latin","y":9,"bp":36,"sy":"un.hos.pitable","ps":"adjective","t":["olatin"]},{"w":"unhot","d":"Not hot; lacking heat or warmth; cool or cold in temperature.","s":"She poured herself a cup of unhot coffee and decided she preferred it cold anyway.","p":"un-HOT","o":"Latin","y":7,"bp":17,"sy":"un.hot","ps":"adjective","t":["olatin"]},{"w":"unhouse","d":"To remove from a house or dwelling; to deprive someone of shelter or a place to live.","s":"The flood threatened to unhouse hundreds of families who had lived there for generations.","p":"un-HOWS","o":"Latin","y":9,"bp":19,"sy":"un.house","ps":"verb","t":["olatin"]},{"w":"unhousebroken","d":"Not trained to follow the indoor rules of a household, especially regarding a pet's bathroom habits; not domesticated to live indoors properly.","s":"The unhousebroken puppy left a trail of puddles across the new kitchen floor.","p":"un-HOWS-broh-kun","o":"Latin","y":9,"bp":26,"sy":"un.house.bro.ken","ps":"adjective","t":["household","olatin"]},{"w":"unhoused","d":"Deprived of a house or shelter; left without a home or place of residence.","s":"The storm left dozens of families unhoused and seeking shelter at the community center.","p":"un-HOWZD","o":"Latin","y":7,"bp":25,"sy":"un.housed","ps":"adjective","t":["olatin"]},{"w":"unhousedness","d":"The state or condition of being without a home or permanent shelter; homelessness.","s":"The charity worked tirelessly to address the unhousedness crisis affecting the city's poorest residents.","p":"un-HOWZD-nes","o":"Latin","y":9,"bp":36,"sy":"un.housed.ness","ps":"noun","t":["olatin"]},{"w":"unhued","d":"Lacking color or hue; colorless or without any distinguishable tint or shade.","s":"The artist left one corner of the canvas unhued, letting the bare white speak for itself.","p":"un-HYOOD","o":"Latin","y":8,"bp":18,"sy":"un.hued","ps":"adjective","t":["colors","olatin"]},{"w":"unhug","d":"To release from a hug; to undo or reverse the act of embracing someone.","s":"After their argument, she wanted to unhug him and pretend the awkward moment never happened.","p":"un-HUG","o":"Latin","y":7,"bp":17,"sy":"un.hug","ps":"verb","t":["olatin"]},{"w":"unhugged","d":"Not having been embraced or hugged; deprived of the warmth and comfort of a hug.","s":"The lonely puppy sat unhugged in the corner of the shelter, waiting for someone to notice him.","p":"un-HUGD","o":"Latin","y":8,"bp":25,"sy":"un.hugged","ps":"adjective","t":["olatin"]},{"w":"unhumanitarian","d":"Lacking concern for human welfare; not showing the compassion or generosity characteristic of a humanitarian.","s":"The general's unhumanitarian treatment of prisoners shocked the international community.","p":"un-hyoo-man-ih-TAIR-ee-un","o":"Latin","y":9,"bp":32,"sy":"un.hu.man.i.tar.i.an","ps":"adjective","t":["maps","olatin"]},{"w":"unhumanize","d":"To strip away human qualities or characteristics from a person or group; to make less humane or human in nature.","s":"Harsh prison conditions can unhumanize both the prisoners and the guards who work there.","p":"un-HYOO-muh-nyz","o":"Latin","y":9,"bp":30,"sy":"un.hu.man.ize","ps":"verb","t":["olatin"]},{"w":"unhumorous","d":"lacking humor","p":"un-HYOO-mor-us","o":"Latin","y":9,"bp":30,"sy":"un.hu.mor.ous","ps":"adjective","t":["olatin"]},{"w":"unhumorously","d":"In a manner that is completely without humor or wit; in a dull, flat, or humorless way.","s":"She unhumorously corrected every joke her classmates told during the talent show.","p":"un-HYOO-mor-us-lee","o":"Latin","y":9,"bp":39,"sy":"un.hu.mor.ous.ly","ps":"adverb","t":["olatin"]},{"w":"unhumourous","d":"British spelling variant of unhumorous; lacking humor or wit; not funny or amusing in any way.","s":"The British critic called the comedian's routine completely unhumourous and painfully dull.","p":"un-HYOO-mor-us","o":"Latin","y":9,"bp":35,"sy":"un.hu.mourous","ps":"adjective","t":["wordwords","olatin"]},{"w":"unhumourously","d":"British spelling variant of unhumorously; in a manner completely lacking humor or amusement.","s":"He unhumourously explained why he found nothing funny about the situation.","p":"un-HYOO-mor-us-lee","o":"Latin","y":9,"bp":26,"sy":"un.hu.mourous.ly","ps":"adverb","t":["wordwords","olatin"]},{"w":"unhungover","d":"Not experiencing the unpleasant aftereffects of excessive alcohol consumption; feeling well and clear-headed.","s":"Surprisingly unhungover after the party, she was ready to hike at sunrise.","p":"un-HUNG-oh-ver","o":"Latin","y":8,"bp":29,"sy":"un.hun.gover","ps":"adjective","t":["olatin"]},{"w":"unhunted","d":"Not pursued, tracked, or sought by hunters; left undisturbed in the wild without being made prey.","s":"The unhunted deer grazed peacefully in the protected nature reserve.","p":"un-HUN-tid","o":"Latin","y":8,"bp":27,"sy":"un.hunt.ed","ps":"adjective","t":["ecology","olatin"]},{"w":"unhurrying","d":"Not rushing or moving hastily; proceeding in a calm, leisurely, and unhurried manner.","s":"With an unhurrying pace, the old tortoise made its way across the sunny path.","p":"un-HUR-ee-ing","o":"Latin","y":9,"bp":30,"sy":"un.hur.ry.ing","ps":"adjective","t":["olatin"]},{"w":"unhurtable","d":"Incapable of being hurt, injured, or harmed; immune to physical or emotional damage.","s":"The superhero believed she was unhurtable until the villain found her weakness.","p":"un-HUR-tuh-bul","o":"Latin","y":9,"bp":27,"sy":"un.hurtable","ps":"adjective","t":["emotions","olatin"]},{"w":"unhushed","d":"Not silenced or quieted; still making noise or continuing to speak despite efforts to quiet it.","s":"The unhushed crowd kept talking loudly even after the movie began.","p":"un-HUSHT","o":"Latin","y":8,"bp":25,"sy":"un.hushed","ps":"adjective","t":["olatin"]},{"w":"unhusk","d":"To remove the outer husk or shell from a grain, seed, or similar plant product; to strip away the outer covering.","s":"She had to unhusk dozens of ears of corn before dinner could be prepared.","p":"un-HUSK","o":"Latin","y":8,"bp":18,"sy":"un.husk","ps":"verb","t":["botany","olatin"]},{"w":"unhybridized","d":"Not crossed or mixed with another variety or species; remaining in a pure, unmixed genetic state without hybridization.","s":"The scientist searched for an unhybridized strain of the wild plant for her research.","p":"un-HY-brih-dyzd","o":"Latin","y":8,"bp":36,"sy":"un.hy.bridized","ps":"adjective","t":["olatin"]},{"w":"unhyphenate","d":"To remove the hyphen from a compound word or phrase, joining the parts together or separating them as standalone words.","s":"The editor decided to unhyphenate 'e-mail' and simply write it as 'email.'.","p":"un-HY-fuh-nayt","o":"Latin","y":9,"bp":37,"sy":"un.hy.phen.ate","ps":"verb","t":["chemistry","wordwords","olatin"]},{"w":"unhypnotised","d":"British spelling of unhypnotized; not having been placed in a hypnotic trance; remaining fully conscious and unaffected by hypnosis.","s":"The volunteer remained unhypnotised despite the magician's best efforts on stage.","p":"un-HIP-nuh-tyzd","o":"Latin","y":8,"bp":38,"sy":"un.hyp.no.tised","ps":"adjective","t":["wordwords","olatin"]},{"w":"unhypnotizable","d":"Incapable of being hypnotized; resistant to entering a hypnotic trance regardless of the technique used.","s":"Some people are considered unhypnotizable because their minds resist suggestion.","p":"un-hip-NOH-tuh-zy-uh-bul","o":"Latin","y":9,"bp":30,"sy":"un.hyp.no.ti.z.able","ps":"adjective","t":["olatin"]},{"w":"unhypnotized","d":"Not having been placed under hypnosis; fully alert and aware, without being in a hypnotic state.","s":"The unhypnotized audience members watched curiously as others fell into a trance.","p":"un-HIP-nuh-tyzd","o":"Latin","y":8,"bp":38,"sy":"un.hyp.no.tized","ps":"adjective","t":["olatin"]},{"w":"unhypocritical","d":"Free from hypocrisy; genuinely sincere and consistent between one's stated beliefs and actual behavior.","s":"Her unhypocritical lifestyle meant she practiced exactly what she preached every day.","p":"un-hip-uh-KRIT-ih-kul","o":"Latin","y":9,"bp":30,"sy":"un.hyp.o.crit.i.cal","ps":"adjective","t":["logic","olatin"]},{"w":"unhypocritically","d":"In a manner free from hypocrisy; with complete sincerity and consistency between words and actions.","s":"He unhypocritically admitted his own mistakes before criticizing others.","p":"un-hip-uh-KRIT-ih-kuh-lee","o":"Latin","y":9,"bp":33,"sy":"un.hyp.o.crit.i.cal.ly","ps":"adverb","t":["wordwords","olatin"]},{"w":"unhypothesised","d":"British spelling of unhypothesized; not yet proposed as a hypothesis; not having been theorized or formally conjectured.","s":"The strange phenomenon remained unhypothesised until a young researcher proposed an explanation.","p":"un-hy-POTH-uh-syzd","o":"Latin","y":9,"bp":29,"sy":"un.hy.poth.e.sised","ps":"adjective","t":["logic","wordwords","olatin"]},{"w":"unibranchiate","d":"Having only one gill or gill-like respiratory organ, as certain aquatic animals do.","s":"The rare unibranchiate organism fascinated students because it had only one gill structure.","p":"yoo-nih-BRANK-ee-it","o":"Latin","y":9,"bp":25,"sy":"uni.branchi.ate","ps":"adjective","t":["animals","marine","music","olatin"]},{"w":"unicapsular","d":"Having or consisting of only a single capsule, as certain plant seed pods or anatomical structures do.","s":"The botanist noted that the unicapsular seed pod contained all its seeds in a single chamber.","p":"yoo-nih-KAP-syuh-ler","o":"Latin","y":8,"bp":38,"sy":"un.i.cap.su.lar","ps":"adjective","t":["body","botany","olatin"]},{"w":"unicarinated","d":"Having a single keel-like ridge or carina; possessing only one raised longitudinal ridge along a surface.","s":"The shell was described as unicarinated because it had a single prominent ridge along its length.","p":"yoo-nih-KAR-ih-nay-tid","o":"Latin","y":8,"bp":39,"sy":"uni.car.i.nat.ed","ps":"adjective","t":["olatin"]},{"w":"uniced","d":"Not covered or decorated with icing; not chilled or treated with ice.","s":"The uniced birthday cake sat on the counter waiting for its layer of frosting.","p":"un-YSD","o":"Latin","y":8,"bp":16,"ps":"adjective","t":["olatin"]},{"w":"unicentral","d":"Having or relating to a single center of control or organization, where all authority or activity originates from one central point.","s":"The unicentral organization made all decisions from one headquarters with no regional offices.","p":"yoo-nih-SEN-trul","o":"Latin","y":8,"bp":29,"sy":"uni.cen.tral","ps":"adjective","t":["poetry","olatin"]},{"w":"unichromosomal","d":"Relating to or involving only a single chromosome, describing organisms, cells, or genetic conditions associated with one chromosome.","s":"The biologist studied a unichromosomal organism that carried all its genetic information on one chromosome.","p":"yoo-nih-kroh-moh-SOH-mul","o":"Latin","y":9,"bp":27,"sy":"unichro.mo.so.mal","ps":"adjective","t":["olatin"]},{"w":"unicity","d":"The state or quality of being unique or one of a kind; the condition of existing as a single, unified entity.","s":"The philosopher argued for the unicity of truth, believing there could only be one ultimate reality.","p":"yoo-NIS-ih-tee","o":"Latin","y":6,"bp":20,"sy":"unic.i.ty","ps":"noun","t":["olatin"]},{"w":"unicolonial","d":"Describing a social insect population, such as ants, that behaves as a single large colony without boundaries between separate nests.","s":"Invasive unicolonial ants are especially destructive because their massive colonies have no internal boundaries.","p":"yoo-nih-kuh-LOH-nee-ul","o":"Latin","y":8,"bp":35,"sy":"uni.colo.nial","ps":"adjective","t":["insects","olatin"]},{"w":"unicoloniality","d":"The condition in which a population of social insects functions as one boundless, interconnected supercolony rather than as separate, competing colonies.","s":"Researchers studied unicoloniality in fire ants to understand how their massive networks function.","p":"yoo-nih-kuh-loh-nee-AL-ih-tee","o":"Latin","y":9,"bp":29,"sy":"uni.colo.nial.i.ty","ps":"noun","t":["insects","olatin"]},{"w":"unicolored","d":"Having only a single, uniform color throughout, with no patterns, markings, or variations in hue.","s":"The seamstress chose a unicolored fabric so the pattern would show up clearly.","p":"YOO-nih-kul-urd","o":"Latin","y":8,"bp":29,"sy":"uni.col.ored","ps":"adjective","t":["colors","olatin"]},{"w":"uniconic","d":"Representing or characterized by a single iconic image or symbol that stands alone as the primary visual identifier.","s":"The designer created a uniconic logo that stood as a single, powerful symbol for the brand.","p":"yoo-nih-KON-ik","o":"Latin","y":8,"bp":27,"sy":"uni.con.ic","ps":"adjective","t":["character","olatin"]},{"w":"unicore","d":"Having or using only a single processing core, as in a computer processor that performs all computations through one core unit.","s":"The older unicore processor could only handle one task at a time, unlike modern chips.","p":"YOO-nih-kor","o":"Latin","y":9,"bp":19,"sy":"uni.core","ps":"adjective","t":["olatin"]},{"w":"unicornuate","d":"Having only one horn or horn-shaped projection, often used in anatomy to describe a uterus or other structure with a single horn-like extension.","s":"The veterinarian explained that a unicornuate uterus has only one horn instead of the usual two.","p":"yoo-nih-KOR-nyoo-it","o":"Latin","y":9,"bp":37,"sy":"uni.cor.nu.ate","ps":"adjective","t":["body","olatin"]},{"w":"unicostate","d":"Having a single rib or midrib, used in botany to describe a leaf with only one prominent central vein running its length.","s":"The leaf was described as unicostate because it had a single central rib running its length.","p":"yoo-nih-KOS-tayt","o":"Latin","y":9,"bp":27,"sy":"uni.costate","ps":"adjective","t":["body","botany","olatin"]},{"w":"unicuspid","d":"Having a single cusp or point, as in a tooth or valve with only one pointed projection.","s":"The dentist explained that a unicuspid tooth has only one pointed tip, making it very different from the multi-cusped molars at the back of your mouth.","p":"yoo-nih-KUS-pid","o":"Latin","y":8,"bp":28,"sy":"uni.cus.pid","ps":"adjective","t":["body","olatin"]},{"w":"unicyclic","d":"Having or involving a single cycle or ring, used in chemistry to describe a molecule containing one ring structure, or in mathematics to describe a graph with exactly one cycle.","s":"The chemist described the unicyclic molecule as having exactly one ring in its structure.","p":"yoo-nih-SY-klik","o":"Latin","y":9,"bp":26,"sy":"uni.cyclic","ps":"adjective","t":["chemistry","numbers","olatin"]},{"w":"unicyclist","d":"a person who rides a unicycle","s":"The talented unicyclist balanced perfectly on one wheel while juggling three balls at the circus.","p":"yoo-nih-SY-klist","o":"Latin","y":8,"bp":29,"sy":"uni.cy.clist","ps":"noun","t":["olatin"]},{"w":"unideaed","d":"Lacking ideas or original thought; having no concepts or creative notions to offer.","s":"The exhausted writer stared at a blank page, completely unideaed after weeks of nonstop work.","p":"un-eye-DEE-ud","o":"Latin","y":9,"bp":24,"ps":"adjective","t":["olatin"]},{"w":"unidealized","d":"Not presented in an idealized or glorified way; shown as realistic and imperfect rather than as a perfect or romanticized version.","s":"The documentary gave an unidealized portrait of the hero, showing his flaws alongside his courage.","p":"un-eye-DEE-uh-lyzd","o":"Latin","y":8,"bp":35,"sy":"unide.al.ized","ps":"adjective","t":["ancient","olatin"]},{"w":"unidentical","d":"Not identical; describing things that differ from each other and cannot be considered exactly the same.","s":"The two samples looked similar under normal light but were clearly unidentical when examined under the microscope.","p":"un-eye-DEN-tih-kul","o":"Latin","y":8,"bp":35,"sy":"uniden.ti.cal","ps":"adjective","t":["olatin"]},{"w":"unidentifiable","d":"impossible to identify","s":"The charred remains of the painting were so damaged that they were completely unidentifiable.","p":"un-eye-den-tih-FY-uh-bul","o":"Latin","y":7,"bp":27,"sy":"uniden.ti.fi.able","ps":"adjective","t":["olatin"]},{"w":"unidentifiably","d":"In a manner that cannot be identified or recognized; to a degree that makes identification completely impossible.","s":"The creature moved unidentifiably through the shadows, leaving the scientists baffled.","p":"un-eye-den-tih-FY-uh-blee","o":"Latin","y":9,"bp":27,"sy":"uniden.ti.fi.ably","ps":"adverb","t":["olatin"]},{"w":"unidiomaticity","d":"The quality or state of being unidiomatic; the characteristic of language use that does not follow the natural expressions or phrases typical of a given language.","s":"The language teacher pointed out the unidiomaticity of the phrase 'make the homework' instead of 'do the homework.'.","p":"un-id-ee-oh-muh-TIS-ih-tee","o":"Latin","y":9,"bp":29,"sy":"uni.d.iomatic.i.ty","ps":"noun","t":["wordwords","olatin"]},{"w":"unidiosyncratic","d":"Not having or showing idiosyncrasies; lacking the distinctive personal quirks or unusual habits that make someone or something unique.","s":"His writing style was surprisingly unidiosyncratic, blending in with hundreds of other authors of his era.","p":"un-id-ee-oh-sin-KRAT-ik","o":"Latin","y":9,"bp":30,"sy":"uni.d.iosyn.crat.ic","ps":"adjective","t":["olatin"]},{"w":"unidyllic","d":"Not idyllic; lacking the peaceful, charming, or perfectly pleasant qualities associated with an ideal or tranquil scene.","s":"The cramped, noisy apartment was decidedly unidyllic, nothing like the peaceful countryside she had dreamed of.","p":"un-ih-DIL-ik","o":"Latin","y":9,"bp":26,"sy":"unidyl.lic","ps":"adjective","t":["olatin"]},{"w":"uniface","d":"Having markings, design, or working on only one face or side, as in an archaeological stone tool flaked on a single surface, or a coin stamped on one side only.","s":"The archaeologist found a uniface tool, worked carefully on only one side by ancient hands.","p":"YOO-nih-fays","o":"Latin","y":8,"bp":19,"sy":"uni.face","ps":"adjective","t":["minerals","economy","ancient","tools","olatin"]},{"w":"unifactorial","d":"Involving or determined by a single factor, especially in genetics where a trait is controlled by only one gene or factor.","s":"The scientist proposed a unifactorial explanation, arguing that a single gene caused the entire disorder.","p":"yoo-nih-fak-TOR-ee-ul","o":"Latin","y":8,"bp":39,"sy":"uni.fac.to.ri.al","ps":"adjective","t":["olatin"]},{"w":"unifamilial","d":"Designed for or relating to a single family, as in a residential building or housing unit intended to house one family only.","s":"The zoning law restricted the area to unifamilial housing, meaning only single-family homes could be built.","p":"yoo-nih-fuh-MIL-ee-ul","o":"Latin","y":8,"bp":37,"sy":"uni.fa.mil.ial","ps":"adjective","t":["buildings","kinship","olatin"]},{"w":"uniflagellate","d":"Having only a single flagellum, the whip-like tail used for movement, as seen in certain microorganisms and cells.","s":"The biology textbook explained that a uniflagellate organism moves through water using a single whip-like tail.","p":"yoo-nih-FLAJ-uh-lit","o":"Latin","y":9,"bp":26,"sy":"uni.flag.el.late","ps":"adjective","t":["olatin"]},{"w":"uniflow","d":"Describing a system in which fluid, gas, or steam moves in one direction only, without reversing or circulating back through the same path.","s":"The engineer designed a uniflow engine to ensure steam moved in only one direction through the cylinder.","p":"YOO-nih-floh","o":"Latin","y":7,"bp":19,"sy":"uni.flow","ps":"adjective","t":["olatin"]},{"w":"unifoliolate","d":"Describing a compound leaf that has been reduced to a single leaflet, appearing simple but actually derived from a compound leaf structure.","s":"The botanist noted that the plant was unifoliolate, bearing only a single leaflet on each leaf stalk.","p":"yoo-nih-FOH-lee-uh-lit","o":"Latin","y":9,"bp":39,"sy":"uni.fo.li.o.late","ps":"adjective","t":["botany","chemistry","olatin"]},{"w":"unigeneric","d":"Belonging to or comprising only one genus; describing a family or group that contains just a single genus of organisms.","s":"The classification was unigeneric, meaning all species in the family belonged to just one genus.","p":"yoo-nih-jeh-NER-ik","o":"Latin","y":8,"bp":29,"sy":"uni.gener.ic","ps":"adjective","t":["kinship","olatin"]},{"w":"uniglandular","d":"Having or involving only a single gland, describing biological structures or organisms with just one glandular organ or secreting body.","s":"The tissue sample was described as uniglandular because it contained only a single glandular structure.","p":"yoo-nih-GLAN-dyoo-lur","o":"Latin","y":8,"bp":36,"sy":"uniglan.du.lar","ps":"adjective","t":["body","music","olatin"]},{"w":"unignitable","d":"Incapable of being set on fire or ignited; not able to be made to burn or combust under normal conditions.","s":"The special foam coating made the material unignitable, perfect for fireproof protective suits.","p":"un-ig-NY-tuh-bul","o":"Latin","y":9,"bp":34,"sy":"unig.nitable","ps":"adjective","t":["chemistry","olatin"]},{"w":"unilabiate","d":"Having only one lip or lip-like structure, used in botany to describe a flower whose corolla has developed only a single lip-shaped lobe.","s":"The unusual flower was unilabiate, having only one lip-shaped petal instead of the typical two.","p":"yoo-nih-LAY-bee-it","o":"Latin","y":9,"bp":30,"sy":"uni.l.abi.ate","ps":"adjective","t":["botany","flowers","olatin"]},{"w":"unilineal","d":"Tracing descent or kinship through only one line — either the mother's side or the father's side — but not both simultaneously.","s":"In a unilineal descent system, a child traces family membership through only one parent's line.","p":"yoo-nih-LIN-ee-ul","o":"Latin","y":8,"bp":28,"sy":"uni.lin.eal","ps":"adjective","t":["kinship","olatin"]},{"w":"unilinear","d":"Developing or progressing in a single straight line or sequence, without branching or diverging into multiple paths or directions.","s":"The philosopher rejected unilinear theories of progress, arguing that societies develop along many different paths.","p":"yoo-nih-LIN-ee-ur","o":"Latin","y":8,"bp":28,"sy":"uni.lin.ear","ps":"adjective","t":["olatin"]},{"w":"unilingual","d":"Using, knowing, or expressed in only one language; describing a person or community that operates in a single language.","s":"Growing up in a small rural town, she remained unilingual until she studied Spanish in high school.","p":"yoo-nih-LING-gwul","o":"Latin","y":8,"bp":27,"sy":"unilin.gual","ps":"adjective","t":["wordwords","olatin"]},{"w":"unilingually","d":"In a manner involving or using only one language; describing communication or activity that takes place exclusively in a single language.","s":"The conference proceeded unilingually in English, frustrating the delegates who spoke only French.","p":"yoo-nih-LING-gwuh-lee","o":"Latin","y":9,"bp":36,"sy":"unilin.gual.ly","ps":"adverb","t":["wordwords","olatin"]},{"w":"unillumed","d":"Not illuminated or lit up; remaining in darkness without any source of light shining upon it.","s":"The old cellar was unillumed and damp, making the children hesitate at the top of the stairs.","p":"un-ih-LOOMD","o":"Latin","y":9,"bp":26,"sy":"unil.lumed","ps":"adjective","t":["olatin"]},{"w":"unillumined","d":"Not illuminated or enlightened, either literally lacking light or figuratively lacking understanding, knowledge, or clarity.","s":"The narrow alley remained unillumined long after the rest of the town had installed streetlights.","p":"un-ih-LOO-mind","o":"Latin","y":9,"bp":35,"sy":"unil.lu.mined","ps":"adjective","t":["logic","olatin"]},{"w":"unillusioned","d":"Free from illusions or false beliefs; having a clear, realistic view of the world without comforting but untrue ideas.","s":"After years of travel, she returned home unillusioned, seeing her hometown clearly without rose-tinted glasses.","p":"un-ih-LOO-zhund","o":"Latin","y":9,"bp":36,"sy":"unil.lu.sioned","ps":"adjective","t":["logic","olatin"]},{"w":"unillustrious","d":"Not illustrious; lacking fame, distinction, or an impressive reputation; obscure and not celebrated or widely recognized.","s":"The general's unillustrious career was filled with minor posts and no memorable victories.","p":"un-ih-LUS-tree-us","o":"Latin","y":9,"bp":26,"sy":"unil.lus.tri.ous","ps":"adjective","t":["olatin"]},{"w":"unilobar","d":"Having or consisting of only one lobe, as in an organ or structure divided into a single rounded section.","s":"The scan revealed that the patient had a unilobar liver condition affecting only one lobe.","p":"yoo-nih-LOH-bar","o":"Latin","y":8,"bp":25,"sy":"unilo.bar","ps":"adjective","t":["music","numbers","olatin"]},{"w":"unimaged","d":"Not yet captured or represented by an image; never photographed, scanned, or otherwise depicted visually.","s":"The vast depths of the trench remained unimaged, never captured by any camera or sonar device.","p":"un-IH-mijd","o":"Latin","y":8,"bp":25,"sy":"unim.aged","ps":"adjective","t":["olatin"]},{"w":"unimitable","d":"Impossible to imitate or copy; so unique that no one can successfully reproduce or duplicate it.","s":"Her unique comedic timing was truly unimitable; every actor who tried to copy her fell flat.","p":"un-IH-mih-tuh-bul","o":"Latin","y":9,"bp":27,"sy":"unim.itable","ps":"adjective","t":["olatin"]},{"w":"unimitated","d":"Not copied or reproduced by anyone; standing as an original that has never been replicated or mimicked.","s":"The sculptor's radical technique remained unimitated for decades, too bold for others to attempt.","p":"un-IH-mih-tay-tid","o":"Latin","y":8,"bp":30,"sy":"unim.i.tat.ed","ps":"adjective","t":["olatin"]},{"w":"unimmunized","d":"Not having received immunization or vaccination; lacking protection against disease through prior medical treatment.","s":"The health workers worried that the unimmunized children were at risk during the measles outbreak.","p":"un-IH-myoo-nyzd","o":"Latin","y":8,"bp":35,"sy":"unim.mu.nized","ps":"adjective","t":["body","disease","olatin"]},{"w":"unimodal","d":"having a single mode","s":"The histogram showed a unimodal distribution, with one clear peak representing the most common test score.","p":"yoo-nih-MOH-dul","o":"Latin","y":6,"bp":25,"sy":"uni.modal","ps":"adjective","t":["olatin"]},{"w":"unimodally","d":"In a manner characterized by a single mode or peak; describing data or distributions that have only one dominant value or highest point.","s":"The data was distributed unimodally, clustering around a single central value with no secondary peaks.","p":"yoo-nih-MOH-duh-lee","o":"Latin","y":9,"bp":29,"sy":"uni.modal.ly","ps":"adverb","t":["character","olatin"]},{"w":"unimodular","d":"Having a determinant equal to one, or characterized by a single unit of measure; used especially in mathematics and physics to describe certain matrices or transformations.","s":"The mathematician proved that the matrix was unimodular because its determinant equaled exactly one.","p":"yoo-nih-MOJ-oo-lar","o":"Latin","y":7,"bp":30,"sy":"uni.mod.u.lar","ps":"adjective","t":["physics","character","numbers","olatin"]},{"w":"unimodularity","d":"The property or state of being unimodular; the condition in which a mathematical matrix or system has a determinant of exactly one.","s":"The professor lectured on unimodularity, explaining its importance in simplifying complex matrix calculations.","p":"yoo-nih-moj-oo-LAIR-ih-tee","o":"Latin","y":9,"bp":29,"sy":"uni.mod.u.lar.i.ty","ps":"noun","t":["numbers","olatin"]},{"w":"unimpacted","d":"Not affected, influenced, or struck by an external force or event; remaining unchanged by whatever occurred nearby.","s":"Surprisingly, the remote village remained unimpacted by the floods that devastated nearby towns.","p":"un-im-PAK-tid","o":"Latin","y":8,"bp":29,"sy":"unim.pact.ed","ps":"adjective","t":["physics","olatin"]},{"w":"unimpairable","d":"Incapable of being damaged, weakened, or made less effective; too strong or well-protected to suffer any impairment.","s":"The device was built with unimpairable circuits that could withstand extreme temperature and pressure.","p":"un-im-PAIR-uh-bul","o":"Latin","y":9,"bp":35,"sy":"unim.pairable","ps":"adjective","t":["olatin"]},{"w":"unimpale","d":"To remove something or someone from a piercing spike or pointed object; to reverse the act of impaling.","s":"The rescue team worked carefully to unimpale the injured bird from the broken fence post.","p":"un-im-PAYL","o":"Latin","y":9,"bp":25,"sy":"unim.pale","ps":"verb","t":["olatin"]},{"w":"unimpaled","d":"Not pierced or skewered on a spike or sharp point; freed from or never subjected to the act of impaling.","s":"Miraculously, the knight emerged from the battle unimpaled, without a single lance wound to his body.","p":"un-im-PAYLD","o":"Latin","y":8,"bp":26,"sy":"unim.paled","ps":"adjective","t":["olatin"]},{"w":"unimparted","d":"Not shared, communicated, or passed on to others; kept to oneself rather than being given or disclosed.","s":"The secret recipe remained unimparted, locked away in the chef's memory forever.","p":"un-im-PAR-tid","o":"Latin","y":8,"bp":29,"sy":"unim.part.ed","ps":"adjective","t":["olatin"]},{"w":"unimpeached","d":"Not called into question, challenged, or formally accused of wrongdoing; having one's integrity or credibility left fully intact.","s":"The judge's record remained unimpeached throughout her long career on the bench.","p":"un-im-PEECHT","o":"Latin","y":9,"bp":34,"sy":"unim.peached","ps":"adjective","t":["law","olatin"]},{"w":"unimperiled","d":"Not placed in danger or at risk; safe from harm or threatening circumstances.","s":"The hikers felt relieved that the trail was unimperiled by the recent storm.","p":"un-im-PAIR-uld","o":"Latin","y":8,"bp":35,"sy":"unim.per.iled","ps":"adjective","t":["olatin"]},{"w":"unimplicated","d":"Not connected to or involved in a wrongdoing or crime; free from any suggestion of guilt or participation.","s":"Three suspects were charged, but the fourth student remained completely unimplicated in the prank.","p":"un-IM-plih-kay-tid","o":"Latin","y":8,"bp":38,"sy":"unim.pli.cat.ed","ps":"adjective","t":["law","olatin"]},{"w":"unimplied","d":"Not suggested, hinted at, or indirectly expressed; conveying nothing beyond what is explicitly stated.","s":"The contract was straightforward, with no hidden meanings left unimplied.","p":"un-im-PLYD","o":"Latin","y":8,"bp":26,"sy":"unim.plied","ps":"adjective","t":["olatin"]},{"w":"unimportantly","d":"In a manner that carries little or no significance; in a way that has minimal impact or relevance to the matter at hand.","s":"She mentioned, almost unimportantly, that she had already solved the puzzle hours ago.","p":"un-im-POR-tunt-lee","o":"Latin","y":9,"bp":26,"sy":"unim.por.tant.ly","ps":"adverb","t":["olatin"]},{"w":"unimported","d":"Not brought in from another country or region; produced or obtained domestically rather than through foreign trade.","s":"All the vegetables used in the dish were locally grown and unimported.","p":"un-im-POR-tid","o":"Latin","y":8,"bp":29,"sy":"unim.port.ed","ps":"adjective","t":["economy","olatin"]},{"w":"unimposable","d":"Incapable of being forced upon or applied to someone or something; impossible to impose as a rule, burden, or requirement.","s":"The teacher realized the rule was unimposable once half the class pushed back against it.","p":"un-im-POH-zuh-bul","o":"Latin","y":9,"bp":35,"sy":"unim.pos.able","ps":"adjective","t":["olatin"]},{"w":"unimposed","d":"Not forced upon or applied by authority; left voluntary rather than being required or mandated by an outside power.","s":"For once, the curfew was unimposed, and the campers stayed up watching the meteor shower.","p":"un-im-POZD","o":"Latin","y":8,"bp":26,"sy":"unim.posed","ps":"adjective","t":["poetry","olatin"]},{"w":"unimpregnable","d":"Not resistant to capture, penetration, or attack; lacking the quality of being impossible to overcome or break into.","s":"Without its reinforced walls, the old fort was entirely unimpregnable against modern weapons.","p":"un-im-PREG-nuh-bul","o":"Latin","y":9,"bp":25,"sy":"unim.preg.nable","ps":"adjective","t":["olatin"]},{"w":"unimpressionable","d":"not sensitive or susceptible to impression","p":"un-im-PRESH-uh-nuh-bul","o":"Latin","y":9,"bp":29,"sy":"unim.pres.sion.able","ps":"adjective","t":["olatin"]},{"w":"unimprovable","d":"Not capable of being made better or enhanced in any way; already at its best or fundamentally unable to be improved.","s":"The coach declared the athlete's form practically unimprovable after years of perfect training.","p":"un-im-PROOV-uh-bul","o":"Latin","y":8,"bp":36,"sy":"unim.prov.able","ps":"adjective","t":["olatin"]},{"w":"unimuscular","d":"Having or consisting of only a single muscle; used in biology to describe organisms or structures with just one muscular unit.","s":"The tiny sea creature had a simple, unimuscular body with just one muscle controlling movement.","p":"yoo-nih-MUS-kyoo-lar","o":"Latin","y":8,"bp":35,"sy":"unimus.cu.lar","ps":"adjective","t":["body","olatin"]},{"w":"unincensed","d":"Not angered or enraged; remaining calm and composed without feeling provoked or furious about a situation.","s":"Surprisingly, the coach was unincensed by the team's loss and calmly discussed improvements.","p":"un-in-SENST","o":"Latin","y":8,"bp":29,"sy":"un.in.censed","ps":"adjective","t":["emotions","olatin"]},{"w":"unincentivized","d":"Not motivated by rewards or incentives; lacking any offered benefit or encouragement that would inspire action or effort.","s":"Workers who are unincentivized often struggle to find motivation to exceed expectations.","p":"un-in-SEN-tih-vyzd","o":"Latin","y":9,"bp":27,"sy":"un.in.cen.tivized","ps":"adjective","t":["olatin"]},{"w":"unincinerated","d":"Not destroyed or reduced to ash by burning; remaining unconsumed by fire or a high-temperature incineration process.","s":"The documents were found unincinerated in the corner of the warehouse after the fire.","p":"un-in-SIN-uh-ray-tid","o":"Latin","y":9,"bp":28,"sy":"un.incin.er.at.ed","ps":"adjective","t":["olatin"]},{"w":"uninclined","d":"Not feeling a desire or tendency to do something; lacking enthusiasm or willingness to engage in a particular action.","s":"Marcus was uninclined to spend his Saturday cleaning when the sun was shining outside.","p":"un-in-KLYND","o":"Latin","y":8,"bp":29,"sy":"un.in.clined","ps":"adjective","t":["olatin"]},{"w":"unincluded","d":"Not contained within or made part of a group, set, or collection; left out or excluded from consideration.","s":"The dessert was unincluded in the meal price, which surprised many diners.","p":"un-in-KLOOD-id","o":"Latin","y":8,"bp":30,"sy":"un.in.clud.ed","ps":"adjective","t":["olatin"]},{"w":"unincreasing","d":"Not growing larger or greater over time; remaining flat or stable without any upward movement in value or quantity.","s":"The scientist noted that the temperature remained unincreasing for three hours during the experiment.","p":"un-in-KREES-ing","o":"Latin","y":8,"bp":38,"sy":"un.in.creas.ing","ps":"adjective","t":["time","olatin"]},{"w":"unincremented","d":"Not increased by a small step or unit; remaining at its original value without any addition or upward adjustment.","s":"The counter stayed unincremented because the programmer forgot to add the update command.","p":"un-IN-kruh-ment-id","o":"Latin","y":9,"bp":28,"sy":"un.in.cre.ment.ed","ps":"adjective","t":["numbers","olatin"]},{"w":"unincubated","d":"Not kept in a warm, controlled environment to promote growth or development; lacking the incubation process needed to hatch eggs or cultivate cells.","s":"The unincubated eggs were too cold to hatch without the warmth of the mother hen.","p":"un-IN-kyoo-bay-tid","o":"Latin","y":8,"bp":38,"sy":"un.in.cu.bat.ed","ps":"adjective","t":["ecology","farming","olatin"]},{"w":"unindent","d":"To remove or reverse an indentation in text or code, moving a line or block back to the left margin or a lesser level of indentation.","s":"The editor told the student to unindent the first line so it matched the rest of the paragraph.","p":"un-IN-dent","o":"Latin","y":8,"bp":25,"sy":"unin.dent","ps":"verb","t":["olatin"]},{"w":"unindentured","d":"Not bound by an indenture or formal contract of service; free from any legal obligation requiring one to work for another for a set period.","s":"After finishing his apprenticeship, the young craftsman was finally unindentured and free to work anywhere.","p":"un-in-DEN-churd","o":"Latin","y":8,"bp":36,"sy":"unin.den.tured","ps":"adjective","t":["law","olatin"]},{"w":"unindexable","d":"Not capable of being organized into or listed within an index; impossible to categorize or retrieve through standard indexing methods.","s":"The encrypted files were unindexable by the search engine, making them impossible to find online.","p":"un-IN-dek-suh-bul","o":"Latin","y":9,"bp":35,"sy":"unin.dex.able","ps":"adjective","t":["olatin"]},{"w":"unindicative","d":"Not serving as a sign or indicator of something; failing to point toward or suggest any particular meaning, quality, or conclusion.","s":"The student's first quiz score was unindicative of her true ability to master the subject.","p":"un-in-DIK-uh-tiv","o":"Latin","y":9,"bp":35,"sy":"unindica.tive","ps":"adjective","t":["logic","olatin"]},{"w":"unindicted","d":"Not formally charged with a crime by a grand jury or legal authority; free from any official accusation of criminal wrongdoing.","s":"Despite the investigation, the business partner remained unindicted and continued working at the firm.","p":"uh-nih-NDEYE-tih-d","o":"Latin","y":6,"bp":36,"sy":"ah.nih.nday.tih.d","ps":"adjective","t":["poetry","law","olatin"]},{"w":"unindividualized","d":"Not treated or adapted to suit a particular person's individual needs, characteristics, or circumstances; handled in a generic, one-size-fits-all manner.","s":"The lesson plan felt unindividualized, as if it were written for a single type of learner.","p":"un-in-dih-VIJ-oo-uh-lyzd","o":"Latin","y":9,"bp":32,"sy":"unin.di.vid.u.al.ized","ps":"adjective","t":["olatin"]},{"w":"unindoctrinated","d":"Not taught or trained to accept a particular set of beliefs, ideas, or principles uncritically; free from ideological conditioning.","s":"Children who remain unindoctrinated are often better at questioning ideas and thinking critically.","p":"un-in-DOK-trih-nay-tid","o":"Latin","y":9,"bp":30,"sy":"unin.doc.tri.nat.ed","ps":"adjective","t":["logic","olatin"]},{"w":"uninducible","d":"Not capable of being brought about, stimulated, or persuaded to occur; impossible to induce or trigger.","s":"The bacteria were uninducible, refusing to produce the enzyme no matter what chemicals the scientist added.","p":"un-in-DOO-sih-bul","o":"Latin","y":9,"bp":34,"sy":"unin.ducible","ps":"adjective","t":["olatin"]},{"w":"unindulgent","d":"Not lenient, permissive, or willing to gratify desires or whims; strict and unwilling to give in to indulgence.","s":"The unindulgent trainer refused to let players skip practice just because they were tired.","p":"un-in-DUL-junt","o":"Latin","y":8,"bp":35,"sy":"unin.dul.gent","ps":"adjective","t":["olatin"]},{"w":"unindustrious","d":"Lacking in diligence, hard work, or productivity; not showing effort or a strong work ethic.","s":"The unindustrious student rarely finished assignments and often wasted class time daydreaming.","p":"un-in-DUS-tree-us","o":"Latin","y":9,"bp":26,"sy":"unin.dus.tri.ous","ps":"adjective","t":["logic","olatin"]},{"w":"uninfectious","d":"Not capable of spreading infection or disease from one person or organism to another; not contagious or transmissible.","s":"The doctor confirmed the rash was uninfectious, so the student could return to school safely.","p":"un-in-FEK-shus","o":"Latin","y":9,"bp":38,"sy":"un.in.fec.tious","ps":"adjective","t":["disease","olatin"]},{"w":"uninflamed","d":"Not affected by inflammation, irritation, or redness; calm and free from swelling or heightened emotion.","s":"After applying ice, the sprained ankle looked uninflamed and much less swollen by morning.","p":"un-in-FLAMD","o":"Latin","y":8,"bp":29,"sy":"un.in.flamed","ps":"adjective","t":["disease","emotions","olatin"]},{"w":"uninflatable","d":"Not able to be filled with air or gas; incapable of being inflated or expanded by blowing in air.","s":"The damaged pool toy was uninflatable because the valve had cracked beyond repair.","p":"un-in-FLAY-tuh-bul","o":"Latin","y":9,"bp":38,"sy":"un.in.flat.able","ps":"adjective","t":["olatin"]},{"w":"uninflated","d":"Not filled with air or gas; remaining flat or at its original, unexpanded size and shape.","s":"The uninflated balloons lay limp on the table, waiting for someone to bring the helium tank.","p":"un-in-FLAY-tid","o":"Latin","y":7,"bp":30,"sy":"un.in.flat.ed","ps":"adjective","t":["olatin"]},{"w":"uninflectable","d":"Not capable of being changed in form through grammatical inflection; unable to be bent, altered, or modified in ending or shape.","s":"Some borrowed words are uninflectable in English and don't change form even in plural.","p":"un-in-FLEK-tuh-bul","o":"Latin","y":9,"bp":25,"sy":"un.in.flectable","ps":"adjective","t":["wordwords","olatin"]},{"w":"uninforming","d":"Not providing useful information, knowledge, or enlightenment; failing to educate or clarify.","s":"The vague presentation was uninforming and left the audience with more questions than answers.","p":"un-in-FOR-ming","o":"Latin","y":8,"bp":37,"sy":"un.in.form.ing","ps":"adjective","t":["logic","olatin"]},{"w":"uninfringed","d":"Not violated, trespassed upon, or encroached on; kept whole and intact without any intrusion or breach.","s":"The citizens celebrated that their right to free speech remained uninfringed after the new law passed.","p":"un-in-FRINJD","o":"Latin","y":8,"bp":35,"sy":"un.in.fringed","ps":"adjective","t":["olatin"]},{"w":"uninfringible","d":"Impossible to violate, trespass upon, or break; so protected or absolute that no infringement can occur.","s":"The lawyers argued that the ancient treaty created an uninfringible right to use the land.","p":"un-in-FRIN-jih-bul","o":"Latin","y":9,"bp":26,"sy":"un.in.fringi.ble","ps":"adjective","t":["olatin"]},{"w":"uningenious","d":"Not clever, inventive, or resourceful; lacking the skill or creativity to devise original solutions or ideas.","s":"The uningenious solution to the puzzle frustrated the teacher, who expected more creativity from her students.","p":"un-in-JEEN-yus","o":"Latin","y":9,"bp":35,"sy":"unin.ge.nious","ps":"adjective","t":["olatin"]},{"w":"uningested","d":"Not swallowed, consumed, or taken into the body; remaining outside the digestive system.","s":"The uningested medicine sat untouched on the table because the patient refused to swallow it.","p":"un-in-JES-tid","o":"Latin","y":8,"bp":27,"sy":"uningest.ed","ps":"adjective","t":["olatin"]},{"w":"uningratiating","d":"Not charming, pleasing, or likely to win favor with others; failing to make a positive or agreeable impression on people.","s":"His uningratiating manner at the party made it hard for anyone to warm up to him.","p":"un-in-GRAY-shee-ay-ting","o":"Latin","y":9,"bp":29,"sy":"un.ingra.ti.at.ing","ps":"adjective","t":["olatin"]},{"w":"uninhabitedness","d":"The state or quality of having no people or living things residing in a place; the condition of being completely empty of inhabitants.","s":"The uninhabitedness of the old mansion gave the neighborhood children the perfect place to dare each other to explore.","p":"un-in-HAB-ih-tid-nes","o":"Latin","y":9,"bp":31,"sy":"un.in.hab.it.ed.ness","ps":"noun","t":["olatin"]},{"w":"uninheritable","d":"Not able to be passed down or received from a parent or ancestor as an inheritance; incapable of being legally or genetically inherited.","s":"The lawyer explained that the property was uninheritable because of a legal dispute that had never been resolved.","p":"un-in-HAIR-ih-tuh-bul","o":"Latin","y":9,"bp":29,"sy":"un.in.her.i.ta.ble","ps":"adjective","t":["law","kinship","olatin"]},{"w":"uninherited","d":"Not received or passed down through inheritance from a parent or ancestor; not obtained by legal succession or genetic transmission.","s":"The uninherited fortune sat in a bank account for decades while the court tried to find living relatives.","p":"un-in-HAIR-ih-tid","o":"Latin","y":8,"bp":38,"sy":"un.in.her.it.ed","ps":"adjective","t":["law","kinship","olatin"]},{"w":"uninhibitable","d":"Not capable of being restrained, suppressed, or held back; impossible to inhibit or prevent from occurring.","s":"Her uninhibitable enthusiasm for science made it impossible for anyone to dampen her excitement.","p":"un-in-HIB-ih-tuh-bul","o":"Latin","y":9,"bp":25,"sy":"un.in.hibitable","ps":"adjective","t":["olatin"]},{"w":"uninhibitedness","d":"The quality or state of being free from restraint, self-consciousness, or suppression; the condition of acting openly and without holding back.","s":"The actor's uninhibitedness on stage made every performance feel completely genuine and alive.","p":"un-in-HIB-ih-tid-nes","o":"Latin","y":9,"bp":31,"sy":"un.in.hib.it.ed.ness","ps":"noun","t":["olatin"]},{"w":"uninitializable","d":"Not capable of being set up, started, or given an initial state; unable to be initialized or prepared for operation.","s":"The programmer groaned when the error message said the variable was uninitializable and the whole program crashed.","p":"un-ih-NISH-uh-lyz-uh-bul","o":"Latin","y":9,"bp":28,"sy":"unini.tial.iz.able","ps":"adjective","t":["olatin"]},{"w":"uninjurable","d":"Not capable of being harmed, wounded, or damaged; immune to injury of any kind.","s":"The superhero seemed uninjurable, bouncing back from every attack without a scratch.","p":"un-IN-jur-uh-bul","o":"Latin","y":9,"bp":35,"sy":"un.in.jurable","ps":"adjective","t":["olatin"]},{"w":"uninked","d":"Not marked, printed on, or covered with ink; having no ink applied to its surface.","s":"The uninked stamp left a blank impression on the paper, ruining the entire batch of invitations.","p":"un-INGKT","o":"Latin","y":8,"bp":17,"ps":"adjective","t":["olatin"]},{"w":"uninoculated","d":"Not having received an inoculation or vaccine; not treated with a biological substance to produce immunity against a disease.","s":"The uninoculated plants quickly fell sick when the disease spread through the greenhouse.","p":"un-ih-NOK-yoo-lay-tid","o":"Latin","y":8,"bp":38,"sy":"uninoc.u.lat.ed","ps":"adjective","t":["disease","pharmacy","olatin"]},{"w":"uninquiring","d":"not inquiring","s":"The uninquiring student sat quietly, never once raising her hand to ask about anything that confused her.","p":"un-in-KWYR-ing","o":"Latin","y":9,"bp":37,"sy":"un.in.quir.ing","ps":"adjective","t":["olatin"]},{"w":"uninquisitive","d":"not inquiring","s":"An uninquisitive scientist would never make great discoveries because curiosity is the heart of research.","p":"un-in-KWIZ-ih-tiv","o":"Latin","y":9,"bp":28,"sy":"un.in.quis.i.tive","ps":"adjective","t":["olatin"]},{"w":"uninscribed","d":"Not written on, engraved, or marked with an inscription; bearing no text, letters, or symbols on its surface.","s":"The uninscribed stone marker stood in the cemetery with no name or date to tell whose grave it marked.","p":"un-in-SKRYBD","o":"Latin","y":8,"bp":34,"sy":"unin.scribed","ps":"adjective","t":["maps","painting","olatin"]},{"w":"uninsightful","d":"Not showing or providing deep understanding, perception, or awareness; lacking the ability to see beneath the surface of situations or ideas.","s":"The uninsightful review simply said the book was 'okay' without explaining anything meaningful about it.","p":"un-in-SYT-ful","o":"Latin","y":8,"bp":36,"sy":"unin.sight.ful","ps":"adjective","t":["olatin"]},{"w":"uninsightfully","d":"In a manner that lacks deep understanding or keen perception; without demonstrating any meaningful awareness or thoughtful analysis.","s":"He uninsightfully dismissed the poem as boring without considering what the author was trying to express.","p":"un-in-SYT-ful-ee","o":"Latin","y":9,"bp":27,"sy":"unin.sight.ful.ly","ps":"adverb","t":["olatin"]},{"w":"uninsistent","d":"Not forceful, demanding, or firm in pressing a point or position; willing to let a matter drop without pushing hard.","s":"The uninsistent coach suggested plays but never pressured the team to follow them exactly.","p":"un-in-SIS-tunt","o":"Latin","y":8,"bp":35,"sy":"unin.sis.tent","ps":"adjective","t":["olatin"]},{"w":"uninsistently","d":"In a manner that is not forceful or persistent; without pressing a point firmly or repeatedly.","s":"She uninsistently offered her opinion once and then quietly let the group decide for themselves.","p":"un-in-SIS-tunt-lee","o":"Latin","y":9,"bp":26,"sy":"unin.sis.tent.ly","ps":"adverb","t":["olatin"]},{"w":"uninspectable","d":"Not able to be examined, checked, or reviewed; impossible to subject to inspection or scrutiny.","s":"The sealed vault was deemed uninspectable by the investigators because they lacked the proper authorization.","p":"un-in-SPEK-tuh-bul","o":"Latin","y":9,"bp":23,"sy":"unin.spectable","ps":"adjective","t":["olatin"]},{"w":"uninspected","d":"Not having been examined, checked, or reviewed by an inspector or authority; passed over without official scrutiny.","s":"The uninspected luggage slipped through security during the chaotic rush of the holiday travel season.","p":"un-in-SPEK-tid","o":"Latin","y":7,"bp":35,"sy":"unin.spect.ed","ps":"adjective","t":["poetry","olatin"]},{"w":"uninspirable","d":"Not capable of being moved, stirred, or filled with creative energy or enthusiasm; impossible to inspire.","s":"The critics called the dull landscape uninspirable, saying it could not stir creativity in even the most talented artist.","p":"un-in-SPY-ruh-bul","o":"Latin","y":9,"bp":35,"sy":"unin.spirable","ps":"adjective","t":["physics","olatin"]},{"w":"uninspirational","d":"Not motivating, uplifting, or capable of sparking enthusiasm or creativity in others; failing to provide any sense of inspiration.","s":"The uninspirational speech left the audience yawning instead of cheering as the principal had hoped.","p":"un-in-spih-RAY-shun-ul","o":"Latin","y":9,"bp":28,"sy":"unin.spi.ra.tional","ps":"adjective","t":["olatin"]},{"w":"uninspiringly","d":"In a manner that fails to spark enthusiasm, creativity, or motivation; in a dull, flat, or lifeless way that leaves others unmoved.","s":"The teacher uninspiringly read from the textbook in a flat voice while students struggled to stay awake.","p":"un-in-SPY-ring-lee","o":"Latin","y":9,"bp":26,"sy":"unin.spir.ing.ly","ps":"adverb","t":["botany","olatin"]},{"w":"uninstall","d":"To remove a software program or application from a computer or device, erasing all its associated files and settings.","s":"She decided to uninstall the app after it crashed her phone three times in one day.","p":"AH2 N IH0 N S T AO1 L","o":"Latin","y":6,"bp":28,"sy":"unin.stall","ps":"verb","t":["tools","olatin"]},{"w":"uninstallation","d":"The process of removing a software program, application, or system from a computer or device, including the deletion of all associated files.","s":"The uninstallation of the old software took longer than expected because of dozens of hidden files.","p":"un-in-stuh-LAY-shun","o":"Latin","y":9,"bp":27,"sy":"unin.stal.la.tion","ps":"noun","t":["tools","olatin"]},{"w":"uninstaller","d":"A program or tool that removes previously installed software from a computer system, deleting all associated files and settings.","s":"He downloaded a special uninstaller to completely remove the program that kept leaving files behind.","p":"un-in-STAWL-er","o":"Latin","y":8,"bp":34,"sy":"unin.staller","ps":"noun","t":["tools","olatin"]},{"w":"uninstantiated","d":"Not instantiated; not created as a specific instance or example, especially in programming where a class or object has not been given a concrete form.","s":"The uninstantiated object in the code caused an error because the programmer forgot to assign it a value.","p":"un-in-STAN-shee-ay-tid","o":"Latin","y":9,"bp":29,"sy":"unin.stan.ti.at.ed","ps":"adjective","t":["olatin"]},{"w":"uninstigated","d":"Not provoked or stirred up by any external cause; occurring or done without being prompted or urged by another person or force.","s":"The fight seemed completely uninstigated — no one could figure out what had started it.","p":"un-IN-stih-gay-tid","o":"Latin","y":8,"bp":38,"sy":"unin.sti.gat.ed","ps":"adjective","t":["physics","olatin"]},{"w":"uninstructive","d":"failing to instruct","s":"The uninstructive manual left us completely confused about how to assemble the bookshelf.","p":"un-in-STRUK-tiv","o":"Latin","y":9,"bp":25,"sy":"unin.struc.tive","ps":"adjective","t":["olatin"]},{"w":"uninstructively","d":"in an uninformative manner","p":"un-in-STRUK-tiv-lee","o":"Latin","y":9,"bp":28,"sy":"unin.struc.tive.ly","ps":"adverb","t":["olatin"]},{"w":"uninstructiveness","d":"The quality or state of failing to teach, inform, or provide useful guidance; the condition of being without educational value.","s":"The uninstructiveness of the presentation frustrated every student who was trying to learn the concept.","p":"un-in-STRUK-tiv-nes","o":"Latin","y":9,"bp":29,"sy":"unin.struc.tive.ness","ps":"noun","t":["olatin"]},{"w":"uninsulated","d":"Not covered or protected by insulating material; lacking a barrier that prevents the passage of heat, electricity, or sound.","s":"The uninsulated pipes in the old house froze solid during the first night of the winter storm.","p":"un-IN-syoo-lay-tid","o":"Latin","y":7,"bp":37,"sy":"unin.su.lat.ed","ps":"adjective","t":["physics","olatin"]},{"w":"uninsurance","d":"The condition of lacking insurance coverage; the state of having no financial protection against loss, illness, or other risks.","s":"The family's uninsurance meant they faced enormous medical bills after the accident.","p":"un-in-SHOOR-ens","o":"Latin","y":9,"bp":35,"sy":"unin.sur.ance","ps":"noun","t":["disease","olatin"]},{"w":"unintegral","d":"Not forming an essential or necessary part of a whole; lacking the quality of being complete or indispensable to the overall structure.","s":"The missing chapter felt unintegral to the story, as if someone had carelessly tossed it in without purpose.","p":"un-IN-teh-grul","o":"Latin","y":8,"bp":30,"sy":"un.in.te.gral","ps":"adjective","t":["olatin"]},{"w":"unintegrated","d":"not integrated; not taken into or made a part of a whole","p":"un-IN-teh-gray-tid","o":"Latin","y":8,"bp":39,"sy":"un.in.te.grat.ed","ps":"adjective","t":["olatin"]},{"w":"unintellectual","d":"Not characterized by or requiring deep thought or mental effort; lacking intellectual curiosity, rigor, or engagement with ideas.","s":"The talk show host kept things unintellectual on purpose so that every viewer could easily follow along.","p":"un-in-tel-EK-choo-ul","o":"Latin","y":9,"bp":30,"sy":"un.in.tel.lec.tu.al","ps":"adjective","t":["character","olatin"]},{"w":"unintellectually","d":"In a manner that shows little or no intellectual depth or thoughtful reasoning; without engaging the mind seriously.","s":"He unintellectually argued his point by repeating himself louder instead of offering better reasons.","p":"un-in-tel-EK-choo-ul-ee","o":"Latin","y":9,"bp":33,"sy":"un.in.tel.lec.tu.al.ly","ps":"adverb","t":["logic","olatin"]},{"w":"unintelligent","d":"lacking intelligence","s":"A dull job with lazy and unintelligent co-workers.","p":"un-in-TEL-ih-jent","o":"Latin","y":7,"bp":28,"sy":"un.in.tel.li.gent","ps":"adjective","t":["olatin"]},{"w":"unintelligently","d":"in an unintelligent manner","s":"He acted rather unintelligently in this crisis.","p":"un-in-TEL-ih-jent-lee","o":"Latin","y":9,"bp":31,"sy":"un.in.tel.li.gent.ly","ps":"adverb","t":["olatin"]},{"w":"unintelligentsia","d":"A group of people regarded as actively anti-intellectual or as the opposite of the intelligentsia; those who reject or dismiss learning, culture, and serious thought.","s":"The comedian joked that the unintelligentsia were the ones who never read the instructions.","p":"un-in-tel-ih-GENT-see-uh","o":"Latin","y":9,"bp":30,"sy":"un.in.tel.li.gentsia","ps":"noun","t":["olatin"]},{"w":"unintelligibleness","d":"The quality or state of being impossible to understand or make sense of; the condition of being too unclear, garbled, or confused to comprehend.","s":"The unintelligibleness of his scrawled notes made studying nearly impossible.","p":"un-in-TEL-ih-jih-bul-nes","o":"Latin","y":9,"bp":33,"sy":"un.in.tel.li.gi.ble.ness","ps":"noun","t":["kinship","olatin"]},{"w":"unintelligibly","d":"in an unintelligible manner","s":"The foreigners spoke unintelligibly.","p":"un-in-TEL-ih-jih-blee","o":"Latin","y":8,"bp":30,"sy":"un.in.tel.li.gi.bly","ps":"adverb","t":["olatin"]},{"w":"unintensified","d":"Not made stronger, more extreme, or more concentrated; remaining at its original level without any increase in force or degree.","s":"The unintensified flavor of the soup disappointed guests who expected something bold.","p":"un-in-TEN-sih-fyd","o":"Latin","y":9,"bp":28,"sy":"un.in.ten.si.fied","ps":"adjective","t":["physics","olatin"]},{"w":"unintercalated","d":"Not having an extra day, month, or section inserted into a sequence; lacking any interpolated addition within a regular series or calendar.","s":"The unintercalated calendar skipped the extra day, causing scheduling confusion.","p":"un-in-TUR-kuh-lay-tid","o":"Latin","y":9,"bp":30,"sy":"un.in.ter.ca.lat.ed","ps":"adjective","t":["numbers","time","olatin"]},{"w":"uninterchangeable","d":"Not able to be used in place of one another; describing things so distinct that they cannot be swapped or substituted without a meaningful difference.","s":"The two engine parts looked alike but were actually uninterchangeable.","p":"un-in-tur-CHAYN-juh-bul","o":"Latin","y":9,"bp":30,"sy":"un.in.ter.change.able","ps":"adjective","t":["olatin"]},{"w":"uninterest","d":"A lack of interest or concern; the state of being indifferent or not curious about something.","s":"Her uninterest in the topic was obvious from the blank look on her face.","p":"un-IN-trest","o":"Latin","y":8,"bp":30,"sy":"un.in.ter.est","ps":"noun","t":["character","olatin"]},{"w":"unintermitted","d":"Not stopped or interrupted; continuing without any pause or break.","s":"The unintermitted roar of the waterfall filled the canyon day and night.","p":"un-in-tur-MIT-id","o":"Latin","y":9,"bp":28,"sy":"un.in.ter.mit.ted","ps":"adjective","t":["olatin"]},{"w":"unintermittedly","d":"In a continuous, unbroken manner; without any pauses, stops, or interruptions occurring along the way.","s":"Rain fell unintermittedly for three days, flooding the low-lying streets.","p":"un-in-tur-MIT-id-lee","o":"Latin","y":9,"bp":31,"sy":"un.in.ter.mit.ted.ly","ps":"adverb","t":["olatin"]},{"w":"unintermitting","d":"Never pausing or stopping; continuing without any interruption or break in activity or flow.","s":"The unintermitting buzz of the broken alarm drove everyone in the office crazy.","p":"un-in-tur-MIT-ing","o":"Latin","y":9,"bp":29,"sy":"un.in.ter.mit.ting","ps":"adjective","t":["olatin"]},{"w":"uninternalized","d":"Not fully absorbed into one's own thinking, values, or behavior; describing a belief or rule that has been heard but not truly made one's own.","s":"The lesson remained uninternalized because he never truly reflected on its meaning.","p":"un-in-TUR-nuh-lyzd","o":"Latin","y":9,"bp":29,"sy":"un.in.ter.nal.ized","ps":"adjective","t":["logic","olatin"]},{"w":"uninterpolated","d":"Not having extra material, data points, or text inserted between existing elements; free from additions placed within an original sequence.","s":"The uninterpolated manuscript was valuable because it contained no later additions.","p":"un-in-TUR-puh-lay-tid","o":"Latin","y":9,"bp":30,"sy":"un.in.ter.po.lat.ed","ps":"adjective","t":["numbers","olatin"]},{"w":"uninterpreted","d":"Not explained, translated, or given meaning; left without any analysis or clarification of what it signifies.","s":"The ancient symbols remained uninterpreted for centuries until a scholar cracked the code.","p":"un-in-TUR-prih-tid","o":"Latin","y":9,"bp":28,"sy":"un.in.ter.pret.ed","ps":"adjective","t":["wordwords","olatin"]},{"w":"uninterred","d":"Not buried in the earth or given a formal burial; describing a body or remains that have been left above ground without interment.","s":"The uninterred remains were discovered in an old field, shocking the whole town.","p":"un-in-TURD","o":"Latin","y":9,"bp":29,"sy":"un.in.terred","ps":"adjective","t":["olatin"]},{"w":"uninterruptedly","d":"without interruption","s":"This pleasant state of affairs had continued peacefully and uninterruptedly for many years.","p":"un-in-tuh-RUP-tid-lee","o":"Latin","y":8,"bp":31,"sy":"un.in.ter.rupt.ed.ly","ps":"adverb","t":["olatin"]},{"w":"uninterruptedness","d":"The quality or state of proceeding without any breaks or interruptions; the condition of being completely continuous and unbroken.","s":"The uninterruptedness of the concert made it feel like one seamless musical journey.","p":"un-in-tuh-RUP-tid-nes","o":"Latin","y":9,"bp":32,"sy":"un.in.ter.rupt.ed.ness","ps":"noun","t":["olatin"]},{"w":"unintimidatable","d":"Incapable of being frightened, threatened, or made to feel timid; describing a person who cannot be bullied or pressured into submission.","s":"The unintimidatable captain walked calmly into the argument and settled it immediately.","p":"un-in-TIM-ih-day-tuh-bul","o":"Latin","y":9,"bp":31,"sy":"un.in.tim.i.dat.able","ps":"adjective","t":["olatin"]},{"w":"unintimidating","d":"Not causing fear, nervousness, or a sense of being threatened; describing something or someone that feels approachable and non-threatening.","s":"The new teacher had an unintimidating smile that made students feel safe asking questions.","p":"un-in-TIM-ih-day-ting","o":"Latin","y":8,"bp":30,"sy":"un.in.tim.i.dat.ing","ps":"adjective","t":["emotions","olatin"]},{"w":"unintoxicated","d":"not inebriated","s":"The unintoxicated driver was the obvious choice to take everyone home safely.","p":"un-in-TOK-sih-kay-tid","o":"Latin","y":9,"bp":29,"sy":"un.in.tox.i.cat.ed","ps":"adjective","t":["olatin"]},{"w":"unintrigued","d":"Not feeling curious, fascinated, or drawn in by something; remaining indifferent or unmoved by what might otherwise spark interest.","s":"Surprisingly, she was completely unintrigued by the mysterious locked door in the hallway.","p":"un-in-TREEGD","o":"Latin","y":9,"bp":35,"sy":"un.in.trigued","ps":"adjective","t":["olatin"]},{"w":"unintriguing","d":"Not interesting, mysterious, or fascinating; failing to spark curiosity or a desire to learn more about it.","s":"The movie's unintriguing plot made half the audience fall asleep before the ending.","p":"un-in-TREE-ging","o":"Latin","y":9,"bp":38,"sy":"un.in.trigu.ing","ps":"adjective","t":["olatin"]},{"w":"unintroduced","d":"Not having been formally presented or made known to others; describing a person who has not been introduced in a social or official setting.","s":"The unintroduced guest stood awkwardly by the door, hoping someone would say hello.","p":"un-in-truh-DOOST","o":"Latin","y":8,"bp":38,"sy":"un.in.tro.duced","ps":"adjective","t":["olatin"]},{"w":"uninuclear","d":"Having only one nucleus; relating to or consisting of a single nucleus within a cell or structure.","s":"The biologist noted the uninuclear cell under the microscope had just one distinct nucleus.","p":"yoo-nih-NOO-klee-ur","o":"Latin","y":8,"bp":32,"sy":"un.in.u.cle.ar","ps":"adjective","t":["olatin"]},{"w":"uninucleate","d":"having one nucleus","s":"Most red blood cells are not uninucleate — they actually have no nucleus at all.","p":"yoo-nih-NOO-klee-it","o":"Latin","y":9,"bp":38,"sy":"un.in.u.cle.ate","ps":"adjective","t":["olatin"]},{"w":"uninucleated","d":"Having or containing only a single nucleus within a cell; describing a cell characterized by the presence of one nucleus.","s":"The lab report confirmed the organism was uninucleated, containing only a single nucleus.","p":"yoo-nih-NOO-klee-ay-tid","o":"Latin","y":8,"bp":41,"sy":"un.in.u.cle.at.ed","ps":"adjective","t":["character","olatin"]},{"w":"uninundated","d":"Not flooded or overwhelmed by a large quantity of water or anything else; remaining free from an inundating deluge of liquid or information.","s":"The higher farmland remained uninundated even after the heavy rains flooded the valley.","p":"un-ih-NUN-day-tid","o":"Latin","y":8,"bp":40,"sy":"un.i.n.un.dat.ed","ps":"adjective","t":["waterways","olatin"]},{"w":"uninvaded","d":"Not having been entered, attacked, or taken over by an outside force; remaining free from intrusion or conquest.","s":"The small island remained uninvaded throughout the long war due to its remote location.","p":"un-in-VAY-did","o":"Latin","y":8,"bp":29,"sy":"un.in.vad.ed","ps":"adjective","t":["physics","olatin"]},{"w":"uninvent","d":"To reverse or undo the creation of an invention; to conceptually eliminate something that has been invented.","s":"Once you know how a magic trick works, you can't uninvent that knowledge.","p":"un-in-VENT","o":"Latin","y":8,"bp":27,"sy":"un.in.vent","ps":"verb","t":["olatin"]},{"w":"uninvestigable","d":"Impossible to investigate or examine; not capable of being looked into or researched.","s":"The case was declared uninvestigable because all the evidence had been destroyed.","p":"un-in-VES-tih-guh-bul","o":"Latin","y":9,"bp":30,"sy":"un.in.ves.ti.ga.ble","ps":"adjective","t":["economy","olatin"]},{"w":"uninvite","d":"To withdraw or cancel an invitation that was previously given to someone.","s":"She had to uninvite her cousin after the venue reduced the guest limit.","p":"un-in-VYT","o":"Latin","y":7,"bp":27,"sy":"un.in.vite","ps":"verb","t":["olatin"]},{"w":"uninvitedly","d":"without invitation","s":"The women arrived uninvitedly.","p":"un-in-VY-tid-lee","o":"Latin","y":8,"bp":38,"sy":"un.in.vit.ed.ly","ps":"adverb","t":["olatin"]},{"w":"uninvitingly","d":"In a manner that is not welcoming, appealing, or attractive; in a way that discourages people from coming closer.","s":"The dark, dusty hallway stretched uninvitingly before the nervous explorers.","p":"un-in-VY-ting-lee","o":"Latin","y":8,"bp":38,"sy":"un.invit.ing.ly","ps":"adverb","t":["olatin"]},{"w":"uninvitingness","d":"The quality or state of being unwelcoming, unappealing, or off-putting; the condition of not drawing people in.","s":"The uninvitingness of the abandoned cabin made the hikers choose to camp outside instead.","p":"un-in-VY-ting-nes","o":"Latin","y":9,"bp":27,"sy":"un.invit.ing.ness","ps":"noun","t":["painting","olatin"]},{"w":"uninvoked","d":"Not called upon, summoned, or cited; never having been appealed to or brought into use.","s":"The rarely uninvoked rule was finally used to settle the long-standing dispute.","p":"un-in-VOKT","o":"Latin","y":8,"bp":28,"sy":"un.in.voked","ps":"adjective","t":["olatin"]},{"w":"uninvolving","d":"Failing to engage interest or participation; not drawing someone in emotionally or mentally.","s":"The uninvolving documentary barely held anyone's attention past the first ten minutes.","p":"un-in-VOL-ving","o":"Latin","y":7,"bp":37,"sy":"un.in.volv.ing","ps":"adjective","t":["painting","emotions","olatin"]},{"w":"uninym","d":"A single unique name that identifies one specific person, place, or thing with no other referent sharing that name.","s":"The brand chose a uninym so it could be identified by a single, unique name worldwide.","p":"YOO-nih-nim","o":"Latin","y":9,"bp":16,"ps":"noun","t":["olatin"]},{"w":"uniocular","d":"Relating to or involving only one eye; having or using a single eye.","s":"The uniocular microscope had only one eyepiece, unlike the newer binocular models.","p":"yoo-nee-OK-yuh-ler","o":"Latin","y":8,"bp":28,"sy":"unioc.u.lar","ps":"adjective","t":["olatin"]},{"w":"uniovulate","d":"having a single ovule","s":"The botanist identified the flower as uniovulate because its ovary contained only one ovule.","p":"yoo-nee-OV-yuh-lit","o":"Latin","y":9,"bp":27,"sy":"uniovu.late","ps":"adjective","t":["olatin"]},{"w":"unipartite","d":"Consisting of or divided into only one part; not separated into multiple sections or divisions.","s":"The document had a unipartite structure, meaning it was divided into just one single section.","p":"yoo-nih-PAR-tyt","o":"Latin","y":9,"bp":29,"sy":"uni.par.tite","ps":"adjective","t":["numbers","olatin"]},{"w":"unipedicular","d":"Having or relating to a single pedicle, especially describing a surgical approach that enters through only one pedicle of a vertebra.","s":"The surgeon used a unipedicular approach to treat the fractured vertebra with minimal disruption.","p":"yoo-nih-peh-DIK-yuh-ler","o":"Latin","y":8,"bp":38,"sy":"uni.pedic.u.lar","ps":"adjective","t":["body","olatin"]},{"w":"unipennate","d":"Describing a muscle in which the muscle fibers are arranged on only one side of a central tendon, resembling one side of a feather.","s":"The unipennate muscle runs fibers diagonally on just one side of its tendon, like a single feather half.","p":"yoo-nih-PEN-ayt","o":"Latin","y":9,"bp":27,"sy":"unipen.nate","ps":"adjective","t":["body","birds","olatin"]},{"w":"unipersonal","d":"Relating to or involving only one person; in grammar, describing a verb that is used only in the third person singular.","s":"The unipersonal verb in Spanish appears only in third-person singular form and cannot be used otherwise.","p":"yoo-nih-PUR-suh-nul","o":"Latin","y":8,"bp":35,"sy":"uniper.son.al","ps":"adjective","t":["wordwords","olatin"]},{"w":"uniplanar","d":"Existing or occurring within a single geometric plane; confined to one flat, two-dimensional surface.","s":"The uniplanar motion of the robot arm was restricted to a single flat surface for precision cutting.","p":"yoo-nih-PLAY-ner","o":"Latin","y":8,"bp":28,"sy":"uni.pla.nar","ps":"adjective","t":["olatin"]},{"w":"uniplicate","d":"Having a single fold; characterized by being folded or pleated exactly one time.","s":"The geologist noted the uniplicate fold in the rock layer, which had just a single crisp crease.","p":"yoo-nih-PLY-kit","o":"Latin","y":9,"bp":29,"sy":"uni.pli.cate","ps":"adjective","t":["character","time","olatin"]},{"w":"unipolar","d":"having a single pole","s":"The unipolar neuron sends signals in one direction from a single pole on the cell body.","p":"yoo-nih-POH-ler","o":"Latin","y":5,"bp":25,"sy":"unipo.lar","ps":"adjective","t":["olatin"]},{"w":"uniprocessor","d":"A computer system that contains only one central processing unit, handling all computational tasks with a single processor.","s":"Older computers used a uniprocessor design, relying on a single chip to handle all tasks.","p":"yoo-nih-PROH-ses-er","o":"Latin","y":8,"bp":36,"sy":"unipro.ces.sor","ps":"noun","t":["olatin"]},{"w":"unipupilled","d":"Having only one pupil in the eye; characterized by the presence of a single pupil.","s":"The rare unipupilled condition in certain animals means they have a single undivided pupil in the eye.","p":"yoo-nih-PYOO-pild","o":"Latin","y":9,"bp":32,"ps":"adjective","t":["character","olatin"]},{"w":"uniradiated","d":"Exposed to or emitting only a single ray or beam of radiation; having just one radiating element.","s":"The uniradiated sample showed no exposure to any radiation source during the experiment.","p":"yoo-nih-RAY-dee-ay-tid","o":"Latin","y":8,"bp":38,"sy":"uni.ra.di.at.ed","ps":"adjective","t":["chemistry","physics","olatin"]},{"w":"unironed","d":"(of linens or clothes) not ironed","s":"A pile of unironed laundry.","p":"un-EYE-ernd","o":"Latin","y":8,"bp":24,"ps":"adjective","t":["fabrics","olatin"]},{"w":"unironic","d":"Completely sincere and straightforward; containing no irony, sarcasm, or hidden double meaning.","s":"His unironic love for cheesy pop songs surprised everyone who thought he had sophisticated taste.","p":"un-eye-RON-ik","o":"Latin","y":6,"bp":25,"sy":"uniron.ic","ps":"adjective","t":["olatin"]},{"w":"unironical","d":"Lacking any sense of irony or sarcasm; entirely genuine and meant exactly as stated without hidden contradiction.","s":"Her unironical enthusiasm for collecting rubber ducks was completely genuine and heartfelt.","p":"un-eye-RON-ih-kul","o":"Latin","y":8,"bp":29,"sy":"uniron.i.cal","ps":"adjective","t":["olatin"]},{"w":"unironically","d":"In a completely sincere and straightforward way, without any irony, sarcasm, or intentional contradiction of meaning.","s":"He unironically wore a cape to school because he genuinely believed it made him look heroic.","p":"un-eye-RON-ih-klee","o":"Latin","y":7,"bp":38,"sy":"uniron.i.cal.ly","ps":"adverb","t":["olatin"]},{"w":"unirradiated","d":"Not exposed to radiation; describing material or food that has not been treated with ionizing radiation.","s":"The unirradiated control group of seeds was kept in a dark room away from all radiation sources.","p":"un-ih-RAY-dee-ay-tid","o":"Latin","y":8,"bp":39,"sy":"unir.ra.di.at.ed","ps":"adjective","t":["physics","olatin"]},{"w":"unisectarian","d":"Not belonging to or favoring any particular religious sect; open to all denominations or belief groups equally.","s":"The unisectarian community center welcomed people of all religious backgrounds without preference.","p":"yoo-nih-sek-TAIR-ee-un","o":"Latin","y":8,"bp":39,"sy":"uni.sec.tar.i.an","ps":"adjective","t":["religion","logic","olatin"]},{"w":"uniseptate","d":"Having only one septum or internal dividing wall; describing a structure partitioned by a single wall.","s":"The biologist observed that the fungal spore was uniseptate, meaning it had a single internal dividing wall.","p":"yoo-nih-SEP-tayt","o":"Latin","y":9,"bp":27,"sy":"unisep.tate","ps":"adjective","t":["olatin"]},{"w":"uniserial","d":"Arranged in a single row or series; consisting of one line of units placed one after another.","s":"The uniserial arrangement of cells in the specimen formed a single straight line under the microscope.","p":"yoo-nih-SEER-ee-ul","o":"Latin","y":8,"bp":29,"sy":"unis.e.ri.al","ps":"adjective","t":["olatin"]},{"w":"uniseriate","d":"Arranged in or consisting of a single row or layer of cells; organized in one continuous series.","s":"The botanist noted the uniseriate structure of the plant tissue, with cells lined up in a single row.","p":"yoo-nih-SEER-ee-it","o":"Latin","y":9,"bp":30,"sy":"unis.e.ri.ate","ps":"adjective","t":["olatin"]},{"w":"unisilicate","d":"A type of silicate mineral in which each silicon atom is bonded to four oxygen atoms forming a single, isolated silicate unit.","s":"Olivine is a classic unisilicate mineral built from isolated silicate tetrahedra linked only by metal ions.","p":"yoo-nih-SIL-ih-kit","o":"Latin","y":9,"bp":35,"sy":"unisil.i.cate","ps":"noun","t":["chemistry","minerals","olatin"]},{"w":"unislamic","d":"Contrary to or inconsistent with the teachings and principles of Islam; not in accordance with Islamic law or values.","s":"Scholars debated whether the new custom was unislamic or simply a misunderstood cultural tradition.","p":"un-iz-LAM-ik","o":"Latin","y":6,"bp":28,"sy":"unis.lam.ic","ps":"adjective","t":["law","logic","olatin"]},{"w":"unisonant","d":"Producing or characterized by a single unified sound; sounding together in perfect unison without variation in pitch.","s":"The choir sang in a perfectly unisonant tone that filled the cathedral with one powerful, unified sound.","p":"yoo-NIH-suh-nunt","o":"Latin","y":8,"bp":26,"sy":"uniso.nant","ps":"adjective","t":["character","olatin"]},{"w":"unissuable","d":"Not capable of being issued, published, or officially put forth; impossible to distribute or release through proper channels.","s":"The judge ruled the warrant unissuable because there was insufficient evidence to justify its approval.","p":"un-ISH-oo-uh-bul","o":"Latin","y":9,"bp":27,"sy":"unis.suable","ps":"adjective","t":["olatin"]},{"w":"unisulcate","d":"Having a single groove or furrow; describing a surface or structure marked by only one sulcus or channel.","s":"The pollen grain was identified as unisulcate because it had just one furrow along its surface.","p":"yoo-nih-SUL-kayt","o":"Latin","y":9,"bp":27,"sy":"unisul.cate","ps":"adjective","t":["olatin"]},{"w":"unitable","d":"Capable of being united or joined together; able to be combined or merged with something else.","s":"The two rival factions proved unitable after years of negotiation finally brought them to common ground.","p":"yoo-NY-tuh-bul","o":"Latin","y":9,"bp":24,"ps":"adjective","t":["olatin"]},{"w":"unitasking","d":"The practice of focusing on and completing one task at a time rather than attempting to do multiple things simultaneously.","s":"She practiced unitasking by focusing entirely on her homework before allowing herself to check her phone.","p":"yoo-nih-TASK-ing","o":"Latin","y":8,"bp":29,"sy":"uni.task.ing","ps":"noun","t":["time","olatin"]},{"w":"unitegmic","d":"Describing a plant ovule that is enclosed by only one protective covering or integument layer instead of two.","s":"The unitegmic ovule in that plant species is covered by only one protective layer rather than two.","p":"yoo-nih-TEG-mik","o":"Latin","y":8,"bp":25,"ps":"adjective","t":["botany","olatin"]},{"w":"uniterable","d":"Not capable of being iterated or repeated; describing a process or sequence that can only be performed or executed once.","s":"The teacher warned that the exam was uniterable, meaning students could not repeat or retake any section.","p":"un-IT-er-uh-bul","o":"Latin","y":9,"bp":29,"sy":"unit.er.able","ps":"adjective","t":["olatin"]},{"w":"unition","d":"The act or process of uniting two or more things into one; the state of being joined or combined together.","s":"The philosopher wrote about the unition of mind and body as the foundation of human experience.","p":"yoo-NIH-shun","o":"Latin","y":8,"bp":19,"sy":"uni.tion","ps":"noun","t":["olatin"]},{"w":"unititular","d":"Having no title or official designation; not holding or bearing any formal title or name.","s":"The unititular document lacked any heading or title, making it difficult to file or reference.","p":"un-ih-TIT-yoo-ler","o":"Latin","y":8,"bp":32,"sy":"uni.ti.t.u.lar","ps":"adjective","t":["maps","olatin"]},{"w":"univalence","d":"The quality or state of having only one valence or combining power; the condition of being univalent in chemistry or biology.","s":"The chemist explained that univalence in an element means it can only form one bond with another atom.","p":"yoo-nih-VAY-lents","o":"Latin","y":9,"bp":29,"sy":"uni.va.lence","ps":"noun","t":["chemistry","olatin"]},{"w":"univalent","d":"used of a chromosome that is not paired or united with its homologous chromosome during synapsis","p":"yoo-nih-VAY-lent","o":"Latin","y":6,"bp":28,"sy":"uni.va.lent","ps":"adjective","t":["olatin"]},{"w":"univalved","d":"Having only a single valve or shell, as certain mollusks such as snails, rather than two hinged shells.","s":"The univalved shell of the snail was a single spiral piece, unlike the two-part shells of clams.","p":"yoo-nih-VALVD","o":"Latin","y":8,"bp":26,"sy":"uni.valved","ps":"adjective","t":["marine","olatin"]},{"w":"univalvular","d":"Relating to or having only one valve; consisting of or characterized by a single valve or shell portion.","s":"The univalvular heart defect involved only one faulty valve that required surgical repair.","p":"yoo-nih-VAL-vyoo-ler","o":"Latin","y":8,"bp":35,"sy":"uni.valvu.lar","ps":"adjective","t":["character","olatin"]},{"w":"univariable","d":"Involving or containing only one variable; relating to statistical or mathematical analysis that examines a single factor at a time.","s":"The scientist ran a univariable analysis to study how a single factor affected the outcome.","p":"yoo-nih-VAIR-ee-uh-bul","o":"Latin","y":9,"bp":35,"sy":"uni.vari.able","ps":"adjective","t":["numbers","time","olatin"]},{"w":"univentricular","d":"Having or relating to only one ventricle, especially describing a heart condition in which only a single functional ventricle is present.","s":"Babies born with a univentricular heart have only one functioning pumping chamber instead of two.","p":"yoo-nih-ven-TRIK-yoo-ler","o":"Latin","y":9,"bp":29,"sy":"uni.ven.tric.u.lar","ps":"adjective","t":["body","olatin"]},{"w":"univerbation","d":"The linguistic process by which two or more separate words merge or fuse into a single new word over time.","s":"The term 'cannot' is a classic example of univerbation, where two separate words fused into one over time.","p":"yoo-nih-ver-BAY-shun","o":"Latin","y":8,"bp":38,"sy":"uni.ver.ba.tion","ps":"noun","t":["wordwords","time","olatin"]},{"w":"Universalian","d":"A person who believes in or advocates universalism, particularly the theological doctrine that all souls will ultimately be saved or united with God.","s":"As a Universalian, she believed that salvation was available to every person regardless of their background.","p":"yoo-nih-ver-SAY-lee-un","o":"Latin","y":8,"bp":36,"sy":"uni.ver.salian","ps":"noun","t":["logic","olatin"]},{"w":"universalist","d":"of or relating to or tending toward universalism","s":"The universalist philosopher argued that basic human rights should apply to every person on Earth.","p":"yoo-nih-VER-suh-list","o":"Latin","y":5,"bp":38,"sy":"uni.ver.sal.ist","ps":"adjective","t":["character","olatin"]},{"w":"universalize","d":"make universal","s":"This author's stories universalize old themes.","p":"yoo-nih-VER-suh-lyz","o":"Latin","y":8,"bp":38,"sy":"uni.ver.sal.ize","ps":"verb","t":["olatin"]},{"w":"universalness","d":"The quality or state of being universal; the characteristic of applying to or encompassing all cases, people, or things without exception.","s":"The universalness of laughter across all cultures suggests it is a fundamental part of human nature.","p":"yoo-nih-VER-sul-nes","o":"Latin","y":9,"bp":26,"sy":"uni.ver.sal.ness","ps":"noun","t":["olatin"]},{"w":"univied","d":"Not covered or adorned with ivy; lacking the growth of ivy that often decorates old buildings or walls.","s":"The old brick wall looked bare and univied after the gardeners stripped off all the climbing plants.","p":"un-IH-veed","o":"Latin","y":8,"bp":19,"sy":"uni.vied","ps":"adjective","t":["buildings","olatin"]},{"w":"unjacketed","d":"Not wearing or covered by a jacket; lacking a protective outer covering or casing.","s":"The unjacketed book sat on the shelf looking plain without its colorful cover.","p":"un-JAK-ih-ted","o":"Latin","y":8,"bp":30,"sy":"un.jack.et.ed","ps":"adjective","t":["fabrics","olatin"]},{"w":"unjaded","d":"Not worn out, dulled, or made cynical by experience; remaining fresh, enthusiastic, and open to new things.","s":"The unjaded tourist gasped with delight at every new sight on the trip.","p":"un-JAY-did","o":"Latin","y":8,"bp":20,"sy":"un.jad.ed","ps":"adjective","t":["olatin"]},{"w":"unjailed","d":"Not confined to jail; free from imprisonment or incarceration.","s":"After the charges were dropped, the suspect was unjailed and walked out a free person.","p":"un-JAYLD","o":"Latin","y":9,"bp":25,"sy":"un.jailed","ps":"adjective","t":["law","olatin"]},{"w":"unjammable","d":"Impossible to jam, block, or interfere with; describing a signal, mechanism, or device that cannot be disrupted or stopped.","s":"The military radio was unjammable, so the soldiers could always communicate clearly.","p":"un-JAM-uh-bul","o":"Latin","y":9,"bp":27,"sy":"un.jammable","ps":"adjective","t":["tools","olatin"]},{"w":"unjarred","d":"Not shaken, jolted, or disturbed; remaining undisturbed and free from any rattling or jarring impact.","s":"She was completely unjarred by the loud noise, calmly continuing to read her book.","p":"un-JARD","o":"Latin","y":8,"bp":25,"sy":"un.jarred","ps":"adjective","t":["olatin"]},{"w":"unjarring","d":"Not jarring, grating, or causing a harsh discordant sensation; smooth and free from any unpleasant jolt or clash.","s":"The soft, unjarring melody helped the baby fall peacefully to sleep.","p":"un-JAR-ing","o":"Latin","y":8,"bp":28,"sy":"un.jar.ring","ps":"adjective","t":["olatin"]},{"w":"unjaundiced","d":"Not affected by jaundice; free from prejudice or bias, seeing things clearly and without a distorted or yellowed perspective.","s":"With an unjaundiced eye, she evaluated both candidates fairly and without bias.","p":"un-JAWN-dist","o":"Latin","y":8,"bp":35,"sy":"un.jaun.diced","ps":"adjective","t":["olatin"]},{"w":"unjealous","d":"Free from jealousy or envy; not feeling or showing resentment toward others because of their advantages or possessions.","s":"Her unjealous nature made her genuinely happy when her friend won the award.","p":"un-JEL-us","o":"Latin","y":9,"bp":28,"sy":"un.jeal.ous","ps":"adjective","t":["emotions","olatin"]},{"w":"unjewelled","d":"Not decorated or adorned with jewels; lacking precious stones or gems as ornamentation.","s":"She wore a simple, unjewelled gown that relied on its elegant cut rather than gems.","p":"un-JOO-uld","o":"Latin","y":9,"bp":29,"sy":"un.jew.elled","ps":"adjective","t":["minerals","olatin"]},{"w":"unjewish","d":"Not characteristic of or associated with Jewish culture, religion, or tradition; lacking qualities considered typically Jewish.","s":"The historian noted that some of the traditions at the ceremony were unjewish in origin.","p":"un-JOO-ish","o":"Latin","y":8,"bp":27,"sy":"un.jew.ish","ps":"adjective","t":["religion","festivals","olatin"]},{"w":"unjinx","d":"To remove a jinx or curse from someone or something; to reverse bad luck or break a spell of misfortune.","s":"She knocked on wood three times to unjinx herself after breaking the mirror.","p":"un-JINGKS","o":"Latin","y":8,"bp":18,"sy":"un.jinx","ps":"verb","t":["olatin"]},{"w":"unjocular","d":"Lacking humor or playfulness; not given to joking or making light of situations; serious and solemn in manner.","s":"The principal's unjocular tone made it clear that the situation was no laughing matter.","p":"un-JOK-yoo-ler","o":"Latin","y":8,"bp":29,"sy":"un.joc.u.lar","ps":"adjective","t":["olatin"]},{"w":"unjoint","d":"To separate at the joints; to take apart or disjoint something by disconnecting its joined parts.","s":"The chef began to unjoint the chicken before marinating the separate pieces.","p":"un-JOYNT","o":"Latin","y":8,"bp":19,"sy":"un.joint","ps":"verb","t":["olatin"]},{"w":"unjolly","d":"Not cheerful, merry, or good-humored; lacking the lively high spirits associated with jolliness.","s":"The unjolly librarian frowned whenever students laughed too loudly near the shelves.","p":"un-JOL-ee","o":"Latin","y":9,"bp":20,"sy":"un.jol.ly","ps":"adjective","t":["olatin"]},{"w":"unjostled","d":"Not pushed, bumped, or crowded against; moving or resting without being shaken or shoved by others.","s":"She carried the tray of glasses through the crowded room, arriving unjostled at the table.","p":"un-JOS-uld","o":"Latin","y":8,"bp":28,"sy":"un.jos.tled","ps":"adjective","t":["olatin"]},{"w":"unjudging","d":"Not forming harsh judgments or critical opinions about others; accepting people without evaluating or condemning them.","s":"Her unjudging attitude made everyone feel comfortable sharing their secrets with her.","p":"un-JUJ-ing","o":"Latin","y":8,"bp":28,"sy":"un.judg.ing","ps":"adjective","t":["olatin"]},{"w":"unjudgmental","d":"Not tending to make harsh moral judgments about others; accepting and open-minded rather than critical or condemnatory.","s":"A good therapist is unjudgmental, listening without criticizing whatever the patient shares.","p":"un-juj-MEN-tul","o":"Latin","y":8,"bp":38,"sy":"un.judg.men.tal","ps":"adjective","t":["character","logic","olatin"]},{"w":"unjudgmentally","d":"In a manner free from harsh moral judgment; behaving with acceptance and open-mindedness rather than criticism or condemnation.","s":"She listened unjudgmentally as her friend described the mistake she had made.","p":"un-juj-MEN-tul-ee","o":"Latin","y":9,"bp":29,"sy":"un.judg.men.tal.ly","ps":"adverb","t":["logic","olatin"]},{"w":"unjudicial","d":"Not befitting or characteristic of a judge or court of law; lacking the impartiality, formality, or procedure associated with judicial process.","s":"The council's hasty decision was criticized as unjudicial because no proper evidence was reviewed.","p":"un-joo-DISH-ul","o":"Latin","y":8,"bp":30,"sy":"un.ju.di.cial","ps":"adjective","t":["law","olatin"]},{"w":"unjudicious","d":"Lacking good judgment or wisdom; showing poor discernment or unwise decision-making in a given situation.","s":"It was unjudicious to spend all his savings on one risky investment.","p":"un-joo-DISH-us","o":"Latin","y":9,"bp":37,"sy":"un.ju.di.cious","ps":"adjective","t":["logic","olatin"]},{"w":"unjudiciously","d":"In a manner that lacks good judgment or wisdom; acting without careful thought or sound discernment.","s":"She unjudiciously blurted out the surprise before the birthday girl arrived.","p":"un-joo-DISH-us-lee","o":"Latin","y":9,"bp":28,"sy":"un.ju.di.cious.ly","ps":"adverb","t":["logic","olatin"]},{"w":"unjuicy","d":"Lacking juiciness, moisture, or interesting content; dry, dull, or uninteresting in either physical texture or engaging quality.","s":"The overcooked steak was tough and unjuicy, disappointing everyone at the barbecue.","p":"un-JOO-see","o":"Latin","y":8,"bp":19,"sy":"un.juicy","ps":"adjective","t":["olatin"]},{"w":"unjumpable","d":"Impossible to jump over; describing an obstacle or barrier so high or formidable that it cannot be cleared by jumping.","s":"The towering fence was unjumpable, so the athletes had to find another way around.","p":"un-JUM-puh-bul","o":"Latin","y":9,"bp":27,"sy":"un.jumpable","ps":"adjective","t":["olatin"]},{"w":"unjuried","d":"Not selected or evaluated by a jury of judges; describing an art show, competition, or exhibition that accepts entries without a judging panel.","s":"The unjuried art show allowed any local artist to display their work without being evaluated.","p":"un-JOOR-eed","o":"Latin","y":8,"bp":25,"sy":"un.juried","ps":"adjective","t":["law","sports","olatin"]},{"w":"unjustice","d":"The absence of justice; a condition or act characterized by unfairness, wrongdoing, or the violation of what is morally right.","s":"The protesters marched against what they called unjustice in the legal system.","p":"un-JUS-tis","o":"Latin","y":9,"bp":28,"sy":"un.jus.tice","ps":"noun","t":["character","olatin"]},{"w":"unjustifiedly","d":"In a manner that lacks adequate reason, proof, or justification; done or said without a sound basis or valid excuse.","s":"He was unjustifiedly punished for a rule he never knew existed.","p":"un-JUS-tih-fyd-lee","o":"Latin","y":9,"bp":28,"sy":"un.jus.ti.fied.ly","ps":"adverb","t":["logic","olatin"]},{"w":"unkeepable","d":"Impossible to keep or maintain; describing a promise, rule, or object that cannot be upheld or preserved under any circumstances.","s":"The promise she made was unkeepable given how much her schedule had changed.","p":"un-KEEP-uh-bul","o":"Latin","y":9,"bp":29,"sy":"un.keep.able","ps":"adjective","t":["olatin"]},{"w":"unkemptitude","d":"The state or quality of being unkempt; a condition of untidiness, dishevelment, or general lack of grooming and order.","s":"His unkemptitude was legendary — his hair wild and his clothes always wrinkled.","p":"un-KEMP-tih-tood","o":"Latin","y":9,"bp":38,"sy":"un.kemp.ti.tude","ps":"noun","t":["kinship","olatin"]},{"w":"unkenned","d":"Unknown or unrecognized; beyond the range of one's knowledge or perception, especially in Scottish and archaic English usage.","s":"The creature lurked in unkenned shadows of the forest, unknown to anyone in the village.","p":"un-KEND","o":"Latin","y":8,"bp":25,"sy":"un.kenned","ps":"adjective","t":["logic","olatin"]},{"w":"unkennel","d":"To release or drive out from a kennel; to bring into the open something that has been confined or hidden, as a fox from its den.","s":"At dawn, the farmer would unkennel the hounds to begin the morning hunt.","p":"un-KEN-ul","o":"Latin","y":8,"bp":27,"sy":"un.ken.nel","ps":"verb","t":["animals","olatin"]},{"w":"unkerned","d":"In typography, describing text or type that has not had its letter-spacing adjusted; having no kerning applied between characters.","s":"The graphic designer noticed the unkerned text looked awkwardly spaced across the headline.","p":"un-KERND","o":"Latin","y":8,"bp":25,"sy":"un.kerned","ps":"adjective","t":["olatin"]},{"w":"unkeyed","d":"characterized by avoidance of traditional western tonality","s":"The avant-garde composer wrote an unkeyed piece that drifted freely between tones.","p":"un-KEED","o":"Latin","y":8,"bp":19,"sy":"un.keyed","ps":"adjective","t":["festivals","character","olatin"]},{"w":"unkidnapped","d":"Not having been kidnapped; describing a person who has been safely freed from an abduction or was never taken captive in the first place.","s":"The relieved family embraced their unkidnapped child after the false alarm was cleared up.","p":"un-KID-napt","o":"Latin","y":9,"bp":35,"sy":"un.kid.napped","ps":"adjective","t":["olatin"]},{"w":"unkill","d":"To reverse or undo the act of killing; to restore life to something or someone that has been slain, typically used in fantasy or figurative contexts.","s":"In the video game, a special power-up allowed players to unkill their fallen teammates.","p":"un-KIL","o":"Latin","y":9,"bp":18,"sy":"un.kill","ps":"verb","t":["olatin"]},{"w":"unkilled","d":"Not killed or slain; still living despite having been in a dangerous or lethal situation.","s":"Miraculously, the explorer emerged from the dangerous jungle unkilled and unharmed.","p":"un-KILD","o":"Latin","y":8,"bp":25,"sy":"un.killed","ps":"adjective","t":["olatin"]},{"w":"unkilted","d":"Not wearing a kilt; describing a person, especially a Scotsman, who is without the traditional pleated tartan skirt.","s":"The Scottish dancer appeared unkilted at rehearsal, wearing ordinary trousers instead.","p":"un-KIL-tid","o":"Latin","y":8,"bp":27,"sy":"un.kilt.ed","ps":"adjective","t":["fabrics","festivals","olatin"]},{"w":"unkindled","d":"not set afire","s":"The unkindled fireplace left the room cold and dark on the winter evening.","p":"un-KIN-duld","o":"Latin","y":8,"bp":28,"sy":"un.kin.dled","ps":"adjective","t":["olatin"]},{"w":"unkindly","d":"lacking in sympathy and kindness","s":"The teacher's unkindly remark about the student's artwork left the young girl feeling hurt, embarrassed, and completely unwilling to share her creative work ever again.","p":"un-KYND-lee","o":"Latin","y":5,"bp":27,"sy":"un.kind.ly","ps":"adjective","t":["emotions","olatin"]},{"w":"unkindred","d":"Not related by blood or family; having no kinship or common bond with another person or group.","s":"Among the unkindred strangers at the party, she searched for a familiar face.","p":"un-KIN-drid","o":"Latin","y":8,"bp":28,"sy":"un.kin.dred","ps":"adjective","t":["body","kinship","olatin"]},{"w":"unkinglike","d":"Not befitting or resembling a king; lacking the dignity, authority, or noble conduct expected of a monarch.","s":"His selfish decisions were completely unkinglike, making his subjects lose faith in his leadership.","p":"un-KING-lyk","o":"Latin","y":9,"bp":30,"sy":"un.k.ing.like","ps":"adjective","t":["poetry","politics","royalty","olatin"]},{"w":"unkingly","d":"Not characteristic of or suitable for a king; behaving or appearing in a manner unworthy of royal status or dignity.","s":"The prince behaved unkingly when he threw a tantrum in front of the royal court.","p":"un-KING-lee","o":"Latin","y":8,"bp":28,"sy":"un.k.ing.ly","ps":"adjective","t":["royalty","olatin"]},{"w":"unkingship","d":"The condition or state of lacking kingship; the absence or removal of royal power, authority, or the qualities associated with being a king.","s":"The council debated whether the ruler's cruel actions had led to his own unkingship.","p":"un-KING-ship","o":"Latin","y":8,"bp":30,"sy":"un.k.ing.ship","ps":"noun","t":["poetry","royalty","olatin"]},{"w":"unkink","d":"To straighten out a kink or twist; to remove a curl, tangle, or bend from something such as a rope, hose, or muscle.","s":"She carefully tried to unkink the garden hose so the water would flow freely.","p":"un-KINK","o":"Latin","y":8,"bp":18,"sy":"un.kink","ps":"verb","t":["body","olatin"]},{"w":"unkinky","d":"Free from kinks, twists, or curls; describing something that is straight, smooth, or uncomplicated.","s":"After brushing her hair thoroughly, it became smooth and unkinky.","p":"un-KIN-kee","o":"Latin","y":8,"bp":19,"sy":"un.kinky","ps":"adjective","t":["olatin"]},{"w":"unkist","d":"An archaic or dialectal form of unkissed; not having been kissed or touched with a kiss.","s":"The old poem lamented that the hero died unkist, never having found love.","p":"un-KIST","o":"Latin","y":8,"bp":18,"sy":"un.kist","ps":"adjective","t":["wordwords","olatin"]},{"w":"unknight","d":"To deprive of the rank, title, or honor of knighthood; to strip a knight of the status and privileges associated with that honor.","s":"The king threatened to unknight the disloyal soldier and strip him of his honor.","p":"un-NYT","o":"Latin","y":8,"bp":25,"sy":"un.knight","ps":"verb","t":["royalty","olatin"]},{"w":"unknighted","d":"Deprived of or never granted the rank of knighthood; describing a person who has had the honor of being a knight taken away or withheld.","s":"The shamed warrior was publicly unknighted before the entire kingdom.","p":"un-NY-tid","o":"Latin","y":8,"bp":29,"sy":"un.knight.ed","ps":"adjective","t":["royalty","olatin"]},{"w":"unknightlike","d":"Not resembling or befitting a knight; lacking the courage, honor, chivalry, or noble conduct expected of a knight.","s":"Bullying younger students was considered completely unknightlike behavior at the academy.","p":"un-NYT-lyk","o":"Latin","y":9,"bp":36,"sy":"un.knight.like","ps":"adjective","t":["royalty","olatin"]},{"w":"unknightly","d":"Contrary to or unworthy of a knight; behaving or appearing in a way that goes against the chivalric code and ideals of knighthood.","s":"The soldier acted unknightly by abandoning his companions on the battlefield.","p":"un-NYT-lee","o":"Latin","y":8,"bp":29,"sy":"un.knight.ly","ps":"adjective","t":["royalty","olatin"]},{"w":"unknit","d":"To undo or unravel something that has been knitted; to separate or loosen something that was tightly joined or woven together.","s":"The seamstress had to unknit several rows after spotting an error in the pattern.","p":"un-NIT","o":"Latin","y":8,"bp":18,"sy":"un.knit","ps":"verb","t":["fabrics","olatin"]},{"w":"unknittable","d":"Impossible to knit or weave together; describing a material or situation that cannot be joined, united, or formed by knitting.","s":"The tangled mess of yarn was so tight it seemed completely unknittable.","p":"un-NIT-uh-bul","o":"Latin","y":9,"bp":35,"sy":"un.knit.table","ps":"adjective","t":["fabrics","olatin"]},{"w":"unknottable","d":"Impossible to tie into a knot; describing a material, situation, or problem that cannot be knotted or fastened by tying.","s":"The magician claimed the rope was unknottable, yet somehow tied it in seconds.","p":"un-NOT-uh-bul","o":"Latin","y":9,"bp":35,"sy":"un.knot.table","ps":"adjective","t":["olatin"]},{"w":"unknottedness","d":"The state or quality of being without knots; the condition of being free from tangles, ties, or knots.","s":"The sailor admired the perfect unknottedness of the freshly untangled rope.","p":"un-NOT-id-nis","o":"Latin","y":9,"bp":26,"sy":"un.knot.ted.ness","ps":"noun","t":["olatin"]},{"w":"unknow","d":"To cease to know something; to erase or reverse knowledge of something once known, often used in archaic or philosophical contexts.","s":"Once you learn a painful truth, you cannot simply unknow it.","p":"un-NOH","o":"Latin","y":5,"bp":18,"sy":"un.know","ps":"verb","t":["logic","olatin"]},{"w":"unknowableness","d":"The quality or state of being impossible to know or comprehend; the condition of being beyond the reach of human understanding or perception.","s":"Philosophers debated the unknowableness of what exists beyond the universe.","p":"un-NOH-uh-bul-nis","o":"Latin","y":9,"bp":27,"sy":"un.know.able.ness","ps":"noun","t":["olatin"]},{"w":"unknowingness","d":"ignorance (especially of orthodox beliefs)","s":"His unknowingness about basic history made the teacher pause and reconsider her lesson plan.","p":"un-NOH-ing-nis","o":"Latin","y":9,"bp":26,"sy":"un.know.ing.ness","ps":"noun","t":["logic","olatin"]},{"w":"unknowledge","d":"The absence or lack of knowledge; ignorance or a state in which understanding, learning, or awareness is entirely absent.","s":"The philosopher argued that unknowledge can sometimes be more dangerous than outright ignorance.","p":"un-NOL-ij","o":"Latin","y":9,"bp":35,"sy":"un.knowl.edge","ps":"noun","t":["logic","olatin"]},{"w":"unknowledged","d":"Not acknowledged or recognized; lacking the recognition of known facts, skills, or information that ought to be known.","s":"The student's hard work went unknowledged by the distracted teacher.","p":"un-NOL-ijd","o":"Latin","y":8,"bp":36,"sy":"un.knowl.edged","ps":"adjective","t":["olatin"]},{"w":"unlachrymose","d":"Not inclined to weep or be tearful; describing a person or disposition that is free from excessive sadness, sentimentality, or crying.","s":"Surprisingly unlachrymose at the sad movie, Jake sat dry-eyed while everyone else wept.","p":"un-LAK-rih-mohs","o":"Latin","y":9,"bp":36,"sy":"un.lachry.mose","ps":"adjective","t":["character","emotions","olatin"]},{"w":"unlacquered","d":"Not coated with lacquer or any shiny protective finish; describing a surface, especially wood or metal, left in its natural, unvarnished state.","s":"The unlacquered wood felt rough under her fingers compared to the polished table nearby.","p":"un-LAK-erd","o":"Latin","y":9,"bp":35,"sy":"un.lac.quered","ps":"adjective","t":["olatin"]},{"w":"unlaicized","d":"Not converted to or made secular; remaining in a clerical or religious state rather than being transferred to lay or non-religious status.","s":"The monk remained unlaicized despite leaving the monastery for several years.","p":"un-LAY-ih-syzd","o":"Latin","y":9,"bp":29,"sy":"un.lai.cized","ps":"adjective","t":["religion","olatin"]},{"w":"unlaminated","d":"Not covered or reinforced with laminate; describing a material or surface that has not been layered with a protective plastic or other bonded coating.","s":"The unlaminated paper tore easily when it got wet in the rain.","p":"un-LAM-ih-nay-tid","o":"Latin","y":8,"bp":38,"sy":"un.lam.i.nat.ed","ps":"adjective","t":["olatin"]},{"w":"unlanced","d":"Not pierced or opened with a lance or surgical instrument; describing a wound, boil, or abscess that has not been cut open to drain.","s":"The unlanced wound became infected because the doctor had not treated it in time.","p":"un-LANST","o":"Latin","y":8,"bp":25,"sy":"un.lanced","ps":"adjective","t":["body","disease","culinary","music","war","olatin"]},{"w":"unlap","d":"To unfold or separate something that overlaps; to open out or spread apart layers or folds that were previously lying one over another.","s":"She carefully began to unlap the layers of cloth wrapped around the fragile statue.","p":"un-LAP","o":"Latin","y":7,"bp":17,"sy":"un.lap","ps":"verb","t":["olatin"]},{"w":"unlapsed","d":"Not lapsed or expired; describing a subscription, membership, license, or agreement that remains valid and has not run out or been discontinued.","s":"The unlapsed insurance policy meant she was still covered after the accident.","p":"un-LAPST","o":"Latin","y":8,"bp":25,"sy":"un.lapsed","ps":"adjective","t":["olatin"]},{"w":"unlasered","d":"Not treated or processed with a laser; lacking any modification, engraving, or cutting that would have been done by a laser beam.","s":"The unlasered document still had visible scratches that a laser treatment would have removed.","p":"un-LAY-zerd","o":"Latin","y":8,"bp":26,"sy":"un.lasered","ps":"adjective","t":["painting","olatin"]},{"w":"unlathed","d":"Not shaped or smoothed on a lathe; describing material that has not been turned or finished by a lathe machine.","s":"The unlathed walls of the old cabin were rough and unfinished.","p":"un-LAYTHD","o":"Latin","y":8,"bp":25,"sy":"un.lathed","ps":"adjective","t":["tools","olatin"]},{"w":"unlatinized","d":"Not converted into Latin form or style; describing a language, word, or culture that has not been adapted to or influenced by Latin conventions.","s":"The unlatinized text retained its original Greek forms throughout the ancient manuscript.","p":"un-LAT-ih-nyzd","o":"Latin","y":8,"bp":35,"sy":"un.la.tinized","ps":"adjective","t":["wordwords","olatin"]},{"w":"unlaudable","d":"Not worthy of praise or admiration; describing an action or quality that deserves no applause or commendation.","s":"His reckless behavior was entirely unlaudable, earning him only criticism from the judges.","p":"un-LAW-duh-bul","o":"Latin","y":9,"bp":29,"sy":"un.laud.able","ps":"adjective","t":["olatin"]},{"w":"unlauded","d":"Not praised or celebrated; describing someone or something that has received no recognition or public acclaim.","s":"Many great scientists died unlauded, only receiving recognition long after their deaths.","p":"un-LAW-did","o":"Latin","y":8,"bp":27,"sy":"un.laud.ed","ps":"adjective","t":["olatin"]},{"w":"unlaugh","d":"To retract or reverse a laugh; to take back the expression of amusement as if it had never occurred.","s":"He wished he could unlaugh at the joke once he realized it was hurtful.","p":"un-LAF","o":"Latin","y":8,"bp":19,"sy":"un.laugh","ps":"verb","t":["olatin"]},{"w":"unlaughable","d":"Not capable of being laughed at or found amusing; so serious or grim that laughter is entirely impossible or inappropriate.","s":"The tragedy was so serious it felt completely unlaughable, even to the class comedian.","p":"un-LAF-uh-bul","o":"Latin","y":9,"bp":35,"sy":"un.laugh.able","ps":"adjective","t":["olatin"]},{"w":"unlaughing","d":"Not laughing; maintaining a serious or solemn expression entirely free from any trace of amusement or mirth.","s":"She sat unlaughing at the comedy show, clearly too upset to find anything amusing.","p":"un-LAF-ing","o":"Latin","y":8,"bp":29,"sy":"un.laugh.ing","ps":"adjective","t":["olatin"]},{"w":"unlaughingly","d":"In a manner that involves no laughter or amusement; with complete seriousness and without any hint of a smile or chuckle.","s":"He unlaughingly corrected the student's joke, making the whole class feel awkward.","p":"un-LAF-ing-lee","o":"Latin","y":8,"bp":38,"sy":"un.laugh.ing.ly","ps":"adverb","t":["olatin"]},{"w":"unlaundered","d":"Not washed or cleaned through a laundering process; describing clothes or fabric that remain dirty and unprocessed.","s":"The unlaundered jersey smelled terrible after three days of soccer practice.","p":"un-LAWN-derd","o":"Latin","y":8,"bp":35,"sy":"un.laun.dered","ps":"adjective","t":["fabrics","olatin"]},{"w":"unlaureled","d":"not crowned with laurel; having no acclaim or reward","s":"The unlaureled heroism of endurance.","p":"un-LOR-uld","o":"Latin","y":8,"bp":29,"sy":"un.lau.reled","ps":"adjective","t":["royalty","olatin"]},{"w":"unlawfulness","d":"the quality of failing to conform to law","s":"The judge emphasized the unlawfulness of the company's actions during the trial.","p":"un-LAW-ful-nis","o":"Latin","y":7,"bp":38,"sy":"un.law.ful.ness","ps":"noun","t":["law","olatin"]},{"w":"unlawlike","d":"Not resembling or consistent with the nature of a law; lacking the formal, binding, or authoritative character that a proper law should have.","s":"The vigilante's wild methods were considered unlawlike by the police department.","p":"un-LAW-lyk","o":"Latin","y":9,"bp":28,"sy":"un.law.like","ps":"adjective","t":["poetry","law","olatin"]},{"w":"unlazy","d":"Not lazy; characterized by energy, diligence, and a willingness to work hard rather than rest or avoid effort.","s":"The unlazy students stayed after school to finish their science projects with extra care.","p":"un-LAY-zee","o":"Latin","y":8,"bp":18,"sy":"un.lazy","ps":"adjective","t":["physics","character","olatin"]},{"w":"unleafy","d":"Lacking leaves; describing a tree, branch, or plant that has few or no leaves attached to it.","s":"The unleafy branches of the oak tree in January looked like dark scratches against the gray sky.","p":"un-LEE-fee","o":"Latin","y":8,"bp":19,"sy":"un.leafy","ps":"adjective","t":["botany","flowers","olatin"]},{"w":"unlearn","d":"try to forget; put out of one's memory or knowledge","s":"After years of bad habits, the athlete had to unlearn her incorrect throwing technique before improving.","p":"un-LURN","o":"Latin","y":5,"bp":19,"sy":"un.learn","ps":"verb","t":["logic","olatin"]},{"w":"unleashable","d":"Incapable of being held back or restrained by a leash or any other means of control; impossible to keep contained or restricted.","s":"The unleashable energy of the crowd at the concert was impossible to contain.","p":"un-LEESH-uh-bul","o":"Latin","y":9,"bp":35,"sy":"un.leash.able","ps":"adjective","t":["olatin"]},{"w":"unleavened","d":"made without leavening","s":"Unleavened bread is often simply flour mixed with water.","p":"un-LEV-und","o":"Latin","y":6,"bp":29,"sy":"un.leav.ened","ps":"adjective","t":["olatin"]},{"w":"unled","d":"Not guided, directed, or led by a leader; lacking any form of leadership or direction from another person or authority.","s":"The unled group of hikers wandered the trail without direction until someone volunteered to guide them.","p":"un-LED","o":"Latin","y":7,"bp":17,"sy":"un.led","ps":"adjective","t":["poetry","olatin"]},{"w":"unlegalistic","d":"Not characterized by strict adherence to legal rules or technicalities; free from an overly rigid or literal interpretation of the law.","s":"The teacher took an unlegalistic approach to classroom rules, focusing on kindness rather than strict regulations.","p":"un-lee-guh-LIS-tik","o":"Latin","y":8,"bp":39,"sy":"un.le.gal.is.tic","ps":"adjective","t":["law","character","olatin"]},{"w":"unlegalized","d":"Not made legal through official authorization or legislation; remaining outside the bounds of legal recognition or formal approval.","s":"The sale of that substance remained unlegalized despite ongoing debates in the state legislature.","p":"un-LEE-guh-lyzd","o":"Latin","y":8,"bp":37,"sy":"un.le.gal.ized","ps":"adjective","t":["poetry","law","politics","olatin"]},{"w":"unlegislated","d":"Not established or regulated by a legislative body; describing a matter or activity for which no formal law has been written or enacted.","s":"Many environmental protections in that region remained unlegislated, leaving wildlife vulnerable.","p":"un-LEJ-is-lay-tid","o":"Latin","y":8,"bp":39,"sy":"un.leg.is.lat.ed","ps":"adjective","t":["law","politics","olatin"]},{"w":"unlemmatized","d":"Not reduced to its base or dictionary form; describing a word that has not been processed to identify its root lemma, especially in linguistic or computational analysis.","s":"The computer struggled to analyze the text because the words were unlemmatized and appeared in all their varied forms.","p":"un-LEM-uh-tyzd","o":"Latin","y":9,"bp":38,"sy":"un.lem.ma.tized","ps":"adjective","t":["botany","wordwords","olatin"]},{"w":"unlengthened","d":"Not made longer or extended; remaining at its original length without any addition or stretching.","s":"The unlengthened rope was too short to reach the bottom of the well.","p":"un-LENGK-thund","o":"Latin","y":8,"bp":36,"sy":"un.length.ened","ps":"adjective","t":["numbers","olatin"]},{"w":"unlet","d":"Not rented out to a tenant; describing a property, room, or dwelling that is currently vacant and has not been leased to anyone.","s":"The unlet apartment sat empty for months before the landlord finally found a tenant.","p":"un-LET","o":"Latin","y":7,"bp":17,"sy":"un.let","ps":"adjective","t":["olatin"]},{"w":"unlettered","d":"having little acquaintance with writing","s":"Special tutorials to assist the unlettered sector of society.","p":"un-LET-erd","o":"Latin","y":8,"bp":29,"sy":"un.let.tered","ps":"adjective","t":["olatin"]},{"w":"unlevel","d":"Not flat, even, or horizontal; having an uneven or tilted surface that varies in height from one point to another.","s":"The carpenter noticed the floor was unlevel and shimmed the boards until everything was even.","p":"un-LEV-ul","o":"Latin","y":6,"bp":20,"sy":"un.lev.el","ps":"adjective","t":["olatin"]},{"w":"unleveraged","d":"Not making use of borrowed capital or financial leverage; describing an investment or business position that relies entirely on its own equity without debt.","s":"The small business was unleveraged, meaning it operated entirely on its own savings without any loans.","p":"uh-NLEH-vrih-jd","o":"Latin","y":8,"bp":35,"sy":"ah.nleh.vrih.jhd","ps":"adjective","t":["economy","tools","olatin"]},{"w":"unliberal","d":"Not open-minded, generous, or tolerant; characterized by narrow thinking, stinginess, or a refusal to accept new or progressive ideas.","s":"The unliberal policies restricted what citizens could read or discuss in public.","p":"un-LIB-er-ul","o":"Latin","y":8,"bp":29,"sy":"un.lib.er.al","ps":"adjective","t":["character","olatin"]},{"w":"unliberated","d":"Not freed from oppression, restriction, or confinement; still subject to control, restraint, or the limitations of an unjust system.","s":"The unliberated prisoners waited anxiously for rescue as the conflict continued.","p":"un-LIB-er-ay-tid","o":"Latin","y":8,"bp":38,"sy":"un.lib.er.at.ed","ps":"adjective","t":["olatin"]},{"w":"unlicentious","d":"Not excessively indulgent, immoral, or unrestrained in behavior; characterized by self-discipline and adherence to moral boundaries.","s":"The unlicentious novel surprised readers who expected something scandalous but found only wholesome adventure.","p":"un-ly-SEN-shus","o":"Latin","y":9,"bp":38,"sy":"un.li.cen.tious","ps":"adjective","t":["character","logic","olatin"]},{"w":"unlicked","d":"Not licked or touched by a tongue; also used figuratively to describe something rough, unpolished, or not yet shaped into a finished form.","s":"The unlicked envelope slid open easily because the glue had never been activated.","p":"un-LIKT","o":"Latin","y":8,"bp":25,"sy":"un.licked","ps":"adjective","t":["olatin"]},{"w":"unlidded","d":"Having the lid removed or absent; open at the top because no cover or lid is present.","s":"The unlidded pot boiled over, sending steam swirling across the kitchen ceiling.","p":"un-LID-id","o":"Latin","y":8,"bp":27,"sy":"un.lid.ded","ps":"adjective","t":["olatin"]},{"w":"unlife","d":"A state of existence that is the opposite of living; a condition resembling life but lacking its essential vital qualities, often associated with supernatural or zombie-like existence.","s":"In the fantasy novel, vampires existed in a state of unlife, neither truly alive nor fully dead.","p":"UN-lyf","o":"Latin","y":7,"bp":18,"sy":"un.life","ps":"noun","t":["olatin"]},{"w":"unlifelike","d":"not resembling a real, living creature or person","p":"un-LYF-lyk","o":"Latin","y":9,"bp":29,"sy":"un.life.like","ps":"adjective","t":["olatin"]},{"w":"unliftable","d":"Impossible to lift or raise; so heavy, fixed, or immovable that no amount of effort can elevate it from its current position.","s":"The ancient stone was unliftable — even five strong students working together couldn't budge it.","p":"un-LIF-tuh-bul","o":"Latin","y":9,"bp":27,"sy":"un.liftable","ps":"adjective","t":["olatin"]},{"w":"unligated","d":"Not tied, bound, or sealed with a ligature; describing a vessel, tissue, or structure that has not been surgically or physically tied off.","s":"The surgeon noted that the blood vessel was unligated and needed to be tied off immediately.","p":"un-LY-gay-tid","o":"Latin","y":8,"bp":29,"sy":"un.li.gat.ed","ps":"adjective","t":["body","seafaring","olatin"]},{"w":"unlightened","d":"Not made brighter or lighter in weight, color, or mood; remaining in a state of darkness, heaviness, or gloom without any relief.","s":"The unlightened hallway was so dark that students bumped into each other trying to find the door.","p":"un-LY-tund","o":"Latin","y":8,"bp":35,"sy":"un.light.ened","ps":"adjective","t":["emotions","colors","olatin"]},{"w":"unlignified","d":"Not converted into wood or woody tissue; describing plant cells that have not undergone the process of becoming hardened with lignin.","s":"The unlignified plant cells were soft and flexible because they had not yet developed woody walls.","p":"un-LIG-nih-fyd","o":"Latin","y":8,"bp":37,"sy":"un.lig.ni.fied","ps":"adjective","t":["body","botany","olatin"]},{"w":"unlikability","d":"The quality or state of being unpleasant, unappealing, or difficult to like; the characteristic that causes others to feel dislike or aversion toward a person or thing.","s":"The villain's unlikability made him the most memorable character in the entire series.","p":"un-ly-kuh-BIL-ih-tee","o":"Latin","y":8,"bp":41,"sy":"un.lik.a.bil.i.ty","ps":"noun","t":["olatin"]},{"w":"unlikable","d":"(of characters in literature or drama) tending to evoke antipathetic feelings","p":"un-LIK-uh-bul","o":"Latin","y":7,"bp":28,"sy":"un.lik.able","ps":"adjective","t":["stage","poetry","character","olatin"]},{"w":"unliked","d":"Not liked or regarded with favor; failing to win affection or approval from others.","s":"The unliked post sat with zero reactions while every other photo on the page gathered hundreds.","p":"un-LYKT","o":"Latin","y":6,"bp":19,"sy":"un.liked","ps":"adjective","t":["emotions","olatin"]},{"w":"unliken","d":"To make unlike or dissimilar; to remove a comparison or likeness previously drawn between two things.","s":"The critic tried to unliken the two novels, arguing that their shared themes were purely coincidental and not worth comparing.","p":"un-LY-kun","o":"Latin","y":8,"bp":19,"sy":"un.liken","ps":"verb","t":["olatin"]},{"w":"unlikeness","d":"dissimilarity evidenced by an absence of likeness","s":"The unlikeness between the twins surprised everyone who assumed they would look and act identical.","p":"un-LYK-nus","o":"Latin","y":9,"bp":29,"sy":"un.like.ness","ps":"noun","t":["olatin"]},{"w":"unlimed","d":"Not treated or covered with lime; describing soil or surfaces that have not had lime applied to them.","s":"The unlimed soil in the garden was too acidic for the roses to thrive, so the gardener planned to add lime in the spring.","p":"un-LYMD","o":"Latin","y":8,"bp":19,"sy":"un.limed","ps":"adjective","t":["olatin"]},{"w":"unlimitable","d":"Incapable of being limited or restricted; boundless and impossible to confine within any set boundary.","s":"The philosopher argued that human curiosity is unlimitable, always pushing beyond every frontier of knowledge we think we have reached.","p":"un-LIM-ih-tuh-bul","o":"Latin","y":9,"bp":35,"sy":"un.lim.itable","ps":"adjective","t":["maps","olatin"]},{"w":"unlineal","d":"Not proceeding in a direct line of descent or succession; not following a hereditary or ancestral lineage.","s":"The king feared that his unlineal heir would have no rightful claim to the throne and that civil war would surely follow.","p":"un-LIN-ee-ul","o":"Latin","y":8,"bp":27,"sy":"un.lin.eal","ps":"adjective","t":["olatin"]},{"w":"unlink","d":"To separate or disconnect things that were joined or linked together; to break a chain or connection between items.","s":"The technician had to carefully unlink the two server systems before performing maintenance so that neither machine would crash during the process.","p":"un-LINK","o":"Latin","y":5,"bp":18,"sy":"un.link","ps":"verb","t":["olatin"]},{"w":"unlipsticked","d":"Not wearing or having had lipstick applied; describing lips that are bare and free of lipstick.","s":"She appeared at the morning meeting with unlipsticked lips and her hair still damp, looking as though she had barely had time to dress.","p":"un-LIP-stikt","o":"Latin","y":8,"bp":36,"sy":"un.lip.sticked","ps":"adjective","t":["olatin"]},{"w":"unliquored","d":"Not mixed with or containing liquor; free from the addition of any alcoholic spirits.","s":"The punch bowl at the school dance remained unliquored all evening, filled only with sparkling cider and fresh fruit slices.","p":"un-LIK-urd","o":"Latin","y":9,"bp":26,"ps":"adjective","t":["numbers","olatin"]},{"w":"unlistable","d":"Impossible to compile into a list; too numerous, vague, or complex to be enumerated or catalogued.","s":"The sheer number of variables in the experiment was unlistable, and the researchers eventually gave up trying to document every single one.","p":"un-LIS-tuh-bul","o":"Latin","y":9,"bp":27,"sy":"un.listable","ps":"adjective","t":["olatin"]},{"w":"unlistenable","d":"So unpleasant or irritating in sound that one cannot bear to listen to it; impossible to hear without discomfort.","s":"The feedback from the broken microphone was so loud and shrill that it made the entire performance completely unlistenable for the audience in the front rows.","p":"un-LIS-un-uh-bul","o":"Latin","y":8,"bp":38,"sy":"un.lis.ten.able","ps":"adjective","t":["animals","olatin"]},{"w":"unlistened","d":"Not listened to; describing words, sounds, or advice that were ignored or went unheard by those who should have paid attention.","s":"Her repeated warnings about the storm went unlistened, and the hikers were caught completely off guard when the rain began to pour.","p":"un-LIS-und","o":"Latin","y":8,"bp":29,"sy":"un.lis.tened","ps":"adjective","t":["wordwords","olatin"]},{"w":"unlistening","d":"Not paying attention or giving ear to what is being said; failing or refusing to listen.","s":"The unlistening crowd continued to chatter among themselves while the speaker stood at the podium, waiting patiently for a moment of silence.","p":"un-LIS-un-ing","o":"Latin","y":8,"bp":37,"sy":"un.lis.ten.ing","ps":"adjective","t":["olatin"]},{"w":"unlitigated","d":"Not brought before a court or settled through legal proceedings; not resolved by litigation.","s":"The dispute over the property boundary remained unlitigated for decades because both neighbors preferred to avoid the expense and stress of a courtroom battle.","p":"un-LIT-ih-gay-tid","o":"Latin","y":8,"bp":40,"sy":"un.l.it.i.gat.ed","ps":"adjective","t":["law","olatin"]},{"w":"unliveable","d":"Describing a place or condition that is so poor or uncomfortable that it is unfit for anyone to live there.","p":"un-LIV-uh-bul","o":"Latin","y":8,"bp":29,"sy":"un.live.able","ps":"adjective","t":["olatin"]},{"w":"unliveried","d":"not wearing livery","p":"un-LIV-uh-reed","o":"Latin","y":8,"bp":30,"sy":"un.liv.er.ied","ps":"adjective","t":["body","olatin"]},{"w":"unliving","d":"live so as to annul some previous behavior","p":"un-LIV-ing","o":"Latin","y":7,"bp":27,"sy":"un.liv.ing","ps":"verb","t":["olatin"]},{"w":"unloadable","d":"Not capable of being unloaded or removed from a container, vehicle, or system.","s":"The cargo was wedged so tightly into the hold of the ship that it was practically unloadable without special equipment and extra crew members.","p":"un-LOH-duh-bul","o":"Latin","y":9,"bp":29,"sy":"un.load.able","ps":"adjective","t":["vehicles","olatin"]},{"w":"unloathed","d":"Not hated or despised; regarded without feelings of loathing or disgust.","s":"Surprisingly, the stern teacher was largely unloathed by her students, who respected her high standards even when they found her assignments challenging.","p":"un-LOHTHD","o":"Latin","y":8,"bp":26,"sy":"un.loathed","ps":"adjective","t":["olatin"]},{"w":"unloathsome","d":"Not disgusting or repulsive; free from any quality that would cause hatred or strong revulsion.","s":"The usually unloathsome task of weeding the garden became almost meditative on a cool morning with birdsong filling the quiet air.","p":"un-LOHTH-sum","o":"Latin","y":9,"bp":35,"sy":"un.loath.some","ps":"adjective","t":["olatin"]},{"w":"unlobed","d":"without lobes","s":"The scientist noted that the unlobed leaf was unusual for that species of plant.","p":"un-LOHBD","o":"Latin","y":8,"bp":19,"sy":"un.lobed","ps":"adjective","t":["olatin"]},{"w":"unlocalizable","d":"Impossible to assign to a specific location or place; incapable of being pinpointed or confined to a particular area.","s":"The source of the strange humming noise was completely unlocalizable, seeming to come from everywhere in the building at once with no clear origin.","p":"un-LOH-kuh-ly-zuh-bul","o":"Latin","y":9,"bp":28,"sy":"un.lo.cal.iz.able","ps":"adjective","t":["olatin"]},{"w":"unlocalized","d":"Not confined or restricted to a specific location; spread broadly rather than centered in one particular place.","s":"The patient described a dull, unlocalized pain that spread across her entire back rather than concentrating in any single spot the doctor could examine.","p":"un-LOH-kuh-lyzd","o":"Latin","y":8,"bp":37,"sy":"un.lo.cal.ized","ps":"adjective","t":["olatin"]},{"w":"unlocatable","d":"Impossible to find or determine the location of; not able to be tracked down or discovered.","s":"The missing hiker was unlocatable for three days despite the search team's best efforts and the use of drones over the dense forest.","p":"un-LOH-kay-tuh-bul","o":"Latin","y":9,"bp":37,"sy":"un.lo.cat.able","ps":"adjective","t":["olatin"]},{"w":"unlocated","d":"lacking a particular location","s":"The buried treasure remained unlocated for centuries despite many treasure hunters searching the island.","p":"un-LOH-kay-tid","o":"Latin","y":7,"bp":29,"sy":"un.lo.cat.ed","ps":"adjective","t":["olatin"]},{"w":"unlodge","d":"To dislodge or remove something from a position where it has become fixed, stuck, or settled.","s":"The mechanic struggled to unlodge the rusted bolt that had been stuck in the engine block for years without budging even slightly.","p":"un-LOJ","o":"Latin","y":9,"bp":19,"sy":"un.lodge","ps":"verb","t":["olatin"]},{"w":"unlofty","d":"Not high, elevated, or grand in character; lacking loftiness in manner, ambition, or physical height.","s":"His unlofty goals surprised his ambitious parents, who had always imagined he would aim for a prestigious career rather than a quiet life on a farm.","p":"un-LAWF-tee","o":"Latin","y":8,"bp":17,"ps":"adjective","t":["olatin"]},{"w":"unlogged","d":"Not recorded in a log or registry; also, not cleared of logs or timber.","s":"The vast stretch of unlogged forest stood untouched at the edge of the valley, its ancient trees rising far above the younger growth nearby.","p":"un-LOGD","o":"Latin","y":7,"bp":25,"sy":"un.logged","ps":"adjective","t":["olatin"]},{"w":"unlonely","d":"Not feeling or characterized by loneliness; free from the feeling of being alone or isolated.","s":"Surrounded by her closest friends on a warm summer evening, she felt wonderfully unlonely for the first time in what seemed like months.","p":"un-LOH-nlee","o":"Latin","y":8,"bp":27,"sy":"un.lone.ly","ps":"adjective","t":["character","emotions","olatin"]},{"w":"unlooking","d":"Not actively looking or paying visual attention; having one's eyes open but not directing focused attention at anything.","s":"He sat by the window in an unlooking daze, his eyes open and pointed at the street below but his mind clearly somewhere far away.","p":"un-LUK-ing","o":"Latin","y":8,"bp":28,"sy":"un.look.ing","ps":"adjective","t":["olatin"]},{"w":"unlooted","d":"Not plundered or robbed; describing a place or thing that has not been stripped of its valuables by thieves or invaders.","s":"Remarkably, the ancient tomb was discovered unlooted, its treasures still perfectly arranged exactly as they had been placed thousands of years ago.","p":"un-LOO-tid","o":"Latin","y":8,"bp":27,"sy":"un.loot.ed","ps":"adjective","t":["olatin"]},{"w":"unlopped","d":"Not cut or trimmed; describing branches, trees, or other growths that have not been pruned or chopped back.","s":"The unlopped hedges along the old estate's driveway had grown wild and towering over many years of neglect, nearly blocking out the afternoon sunlight.","p":"un-LOPT","o":"Latin","y":8,"bp":25,"sy":"un.lopped","ps":"adjective","t":["flowers","olatin"]},{"w":"unlord","d":"To deprive of the rank, title, or authority of a lord; to strip someone of lordly status or power.","s":"The rebel council voted to unlord the baron, stripping him of every title and estate he had held since inheriting them from his father.","p":"un-LORD","o":"Latin","y":8,"bp":18,"sy":"un.lord","ps":"verb","t":["poetry","olatin"]},{"w":"unlovable","d":"incapable of inspiring love or affection","s":"She was in some mysterious way...unlovable.","p":"un-LUV-uh-bul","o":"Latin","y":7,"bp":26,"sy":"unlov.able","ps":"adjective","t":["emotions","olatin"]},{"w":"unlovably","d":"In a manner that makes it impossible to inspire love or affection; in a way that repels rather than attracts warm feelings.","s":"The villain was written so unlovably that every reader cheered when he finally received the consequences of his cold and selfish actions.","p":"un-LUV-uh-blee","o":"Latin","y":8,"bp":26,"sy":"unlov.ably","ps":"adverb","t":["emotions","olatin"]},{"w":"unlove","d":"To cease to love; to undo or reverse the feeling of love one once had for a person or thing.","s":"She realized with sadness that she could not simply unlove him the way one deletes a contact, because feelings do not vanish on command.","p":"un-LUV","o":"Latin","y":7,"bp":16,"ps":"verb","t":["emotions","olatin"]},{"w":"unlovedness","d":"The state or condition of not being loved; the quality of existing without receiving love or affection from others.","s":"The novel's central theme is the quiet ache of unlovedness, the way a person can feel invisible even in a room full of people who know their name.","p":"un-LUVD-nus","o":"Latin","y":9,"bp":34,"sy":"unloved.ness","ps":"noun","t":["emotions","olatin"]},{"w":"unloveliness","d":"The quality or state of lacking beauty, charm, or loveliness; the condition of being unattractive or without grace.","s":"The gray concrete walls and flickering fluorescent lights gave the waiting room an air of unloveliness that made every minute spent there feel twice as long.","p":"un-LUV-lee-nus","o":"Latin","y":9,"bp":36,"sy":"unlove.li.ness","ps":"noun","t":["olatin"]},{"w":"unlovely","d":"without beauty or charm","s":"The unlovely building stood out among the charming old houses lining the street.","p":"un-LUV-lee","o":"Latin","y":6,"bp":25,"sy":"unlove.ly","ps":"adjective","t":["olatin"]},{"w":"unloverlike","d":"Not resembling or befitting a lover; lacking the tenderness, affection, or romantic behavior expected of someone in love.","s":"His unloverlike behavior — forgetting her birthday twice — made her question his feelings.","p":"un-LUV-er-lyk","o":"Latin","y":9,"bp":34,"sy":"unlover.like","ps":"adjective","t":["emotions","ancient","olatin"]},{"w":"unlubed","d":"Not lubricated; lacking any applied oil, grease, or other substance to reduce friction between surfaces.","s":"The unlubed bicycle chain screeched horribly with every turn of the pedal.","p":"un-LOOBD","o":"Latin","y":8,"bp":19,"sy":"un.lubed","ps":"adjective","t":["physics","olatin"]},{"w":"unlubricated","d":"not lubricated","s":"The unlubricated gears in the old clock ground against each other until the mechanism seized up.","p":"un-LOO-bri-kay-tid","o":"Latin","y":7,"bp":39,"sy":"un.lu.bri.cat.ed","ps":"adjective","t":["olatin"]},{"w":"unluck","d":"The absence of good fortune; bad luck or misfortune that seems to follow a person or situation persistently.","s":"He joked that he had a lifetime supply of unluck after losing his keys three days in a row.","p":"un-LUK","o":"Latin","y":7,"bp":18,"sy":"un.luck","ps":"noun","t":["olatin"]},{"w":"unlustrous","d":"Lacking luster, shine, or brilliance; dull and without any gleam or gloss on the surface.","s":"The unlustrous finish of the old silver trophy showed years of neglect.","p":"un-LUS-trus","o":"Latin","y":9,"bp":29,"sy":"un.lus.trous","ps":"adjective","t":["colors","olatin"]},{"w":"unlying","d":"Not given to lying; truthful and honest in speech and conduct, free from deception or falsehood.","s":"Known for being unlying, she always told the truth even when it was uncomfortable.","p":"un-LY-ing","o":"Latin","y":8,"bp":20,"sy":"un.ly.ing","ps":"adjective","t":["olatin"]},{"w":"unlyrical","d":"Lacking lyrical quality; not melodious, poetic, or expressive in the manner of song or verse.","s":"Critics called his speech unlyrical and flat, wishing it had more poetic flair.","p":"un-LEER-ih-kul","o":"Latin","y":9,"bp":28,"sy":"un.lyri.cal","ps":"adjective","t":["music","poetry","olatin"]},{"w":"unlyrically","d":"In a manner that lacks lyrical quality or poetic expressiveness; without the musicality or beauty of verse.","s":"She spoke unlyrically about the sunset, describing it simply as orange and round.","p":"un-LEER-ih-kul-ee","o":"Latin","y":9,"bp":37,"sy":"un.lyri.cal.ly","ps":"adverb","t":["music","poetry","olatin"]},{"w":"unlysed","d":"Not lysed; describing cells or organisms that have not been broken down or dissolved through the process of lysis.","s":"The unlysed cells remained intact under the microscope, their membranes perfectly preserved.","p":"un-LYZD","o":"Latin","y":9,"bp":19,"sy":"unl.ysed","ps":"adjective","t":["olatin"]},{"w":"undeck","d":"To remove decorations or ornaments from something; to strip away the decorative coverings that had previously been applied to a surface or space.","s":"After the holidays, it took us two hours to undeck the halls and pack away all the decorations.","p":"un-DEK","o":"Dutch","y":8,"bp":14,"sy":"un.deck","ps":"verb","t":["odutch"]},{"w":"underdeck","d":"The space or area located beneath the main deck of a ship or vessel, used for storage, crew quarters, or housing cargo.","s":"The sailors stored extra supplies in the underdeck compartment to keep them safe from the waves.","p":"UN-der-dek","o":"Dutch","y":8,"bp":24,"sy":"un.der.deck","ps":"noun","t":["seafaring","odutch"]},{"w":"undecent","d":"Not decent; lacking propriety, modesty, or acceptable standards of behavior or appearance; improper or indecorous.","s":"The school board deemed the language in the play undecent and voted to require revisions before allowing any student performance of the script.","p":"un-DEE-sunt","o":"French","y":8,"bp":21,"sy":"un.de.cent","ps":"adjective","t":["ofrench"]},{"w":"undecently","d":"In a manner that is not decent or proper; behaving or acting in a way that lacks modesty, propriety, or acceptable social standards.","s":"The crowd was shocked when the contestant undecently interrupted the host mid-sentence and grabbed the microphone during the live televised competition.","p":"un-DEE-sunt-lee","o":"French","y":8,"bp":30,"sy":"un.de.cent.ly","ps":"adverb","t":["ofrench"]},{"w":"undersensitive","d":"Having less sensitivity than is normal or appropriate; failing to respond adequately to stimuli, emotions, or circumstances that would typically produce a reaction.","s":"The undersensitive smoke detector failed to sound its alarm until the kitchen was already filled with thick, billowing clouds of dark smoke.","p":"UN-der-SEN-sih-tiv","o":"French","y":9,"bp":29,"sy":"un.der.sen.si.tive","ps":"adjective","t":["emotions","ofrench"]},{"w":"unelegant","d":"Lacking elegance, grace, or refinement; clumsy, awkward, or lacking in tasteful style or sophistication.","s":"His unelegant entrance into the formal dining hall, tripping over a chair and knocking over two glasses, drew startled looks from every guest.","p":"un-EL-ih-gunt","o":"French","y":8,"bp":29,"sy":"un.el.e.gant","ps":"adjective","t":["ofrench"]},{"w":"uneligible","d":"Not eligible; failing to meet the required qualifications or conditions necessary to be chosen, accepted, or allowed to participate.","s":"Because she had turned eighteen before the competition deadline, she was ruled uneligible for the youth category and could not enter the contest.","p":"un-EL-ih-jih-bul","o":"French","y":9,"bp":32,"sy":"un.el.i.gi.ble","ps":"adjective","t":["ofrench"]},{"w":"unline","d":"To remove the lining from something; to strip away the inner layer or material that lines a garment, container, or surface.","s":"The tailor decided to unline the old coat so that a fresh, more durable fabric could be sewn carefully into the interior before winter.","p":"un-LYN","o":"French","y":8,"bp":18,"sy":"un.line","ps":"verb","t":["fabrics","ofrench"]},{"w":"unlute","d":"To remove a lute or clay seal from a vessel; to open something that has been sealed shut with a clay or similar adhesive substance.","s":"The alchemist used a thin metal tool to carefully unlute the ceramic flask, breaking the hardened clay seal that protected the rare compound inside.","p":"un-LOOT","o":"French","y":8,"bp":18,"sy":"un.lute","ps":"verb","t":["marine","seafaring","ofrench"]},{"w":"underact","d":"act (a role) with great restraint","s":"The director told the student not to underact the emotional scene, but to show more feeling.","p":"un-der-AKT","o":"French","y":8,"bp":21,"sy":"un.der.act","ps":"verb","t":["ofrench"]},{"w":"underaction","d":"Performance or execution that falls below the required or expected level of energy and effort; the act of doing less than what a situation demands.","s":"The film critic noted that the lead character's underaction made the climax feel flat and unconvincing.","p":"un-der-AK-shun","o":"French","y":8,"bp":37,"sy":"un.der.ac.tion","ps":"noun","t":["physics","ofrench"]},{"w":"underaid","d":"To give less help, support, or assistance than is needed or deserved; the state of receiving insufficient aid.","s":"The relief organization warned that underaid during the disaster would leave thousands without food.","p":"UN-der-ayd","o":"French","y":9,"bp":21,"sy":"un.der.aid","ps":"verb","t":["ofrench"]},{"w":"underattendance","d":"A situation in which fewer people show up to an event or gathering than expected or required.","s":"The principal was worried about the underattendance at the school play after the heavy rain.","p":"UN-der-uh-TEN-dunts","o":"French","y":9,"bp":30,"sy":"un.der.at.ten.dance","ps":"noun","t":["ofrench"]},{"w":"underbar","d":"A horizontal bar or line positioned beneath another element, often used in typography or as a structural support below a main bar.","s":"The gymnast slipped on the underbar during practice and had to restart her routine.","p":"UN-der-bar","o":"French","y":8,"bp":21,"sy":"un.der.bar","ps":"noun","t":["chemistry","ofrench"]},{"w":"underboil","d":"To boil something for less time or at a lower temperature than is necessary, leaving it insufficiently cooked.","s":"If you underboil the pasta, it will be chewy and hard to eat.","p":"UN-der-boyl","o":"French","y":9,"bp":28,"sy":"un.der.boil","ps":"verb","t":["culinary","time","ofrench"]},{"w":"underbrace","d":"A brace or support structure placed underneath something to hold it up from below.","s":"The engineer added an underbrace to the bridge to keep it from sagging in the middle.","p":"UN-der-brays","o":"French","y":9,"bp":29,"sy":"un.der.brace","ps":"noun","t":["ofrench"]},{"w":"underbranch","d":"A branch that grows beneath the main or upper branches of a tree, closer to the ground.","s":"The bird built its nest on an underbranch where it was sheltered from the wind.","p":"UN-der-branch","o":"French","y":9,"bp":35,"sy":"un.der.branch","ps":"noun","t":["flowers","ofrench"]},{"w":"undercard","d":"The series of preliminary or lesser-featured contests or performances that take place before the main event, especially in boxing.","s":"The young boxer was excited to fight on the undercard before the championship match.","p":"UN-der-kard","o":"French","y":5,"bp":28,"sy":"un.der.card","ps":"noun","t":["sports","ofrench"]},{"w":"undercharge","d":"a price that is too low","s":"The cashier accidentally gave an undercharge, charging only two dollars for a five-dollar item.","p":"UN-der-charj","o":"French","y":9,"bp":35,"sy":"un.der.charge","ps":"noun","t":["ofrench"]},{"w":"undercollar","d":"An inner or hidden collar worn or sewn beneath the outer visible collar of a garment.","s":"The tailor sewed a soft undercollar inside the jacket to make it comfortable against the neck.","p":"UN-der-KOL-er","o":"French","y":9,"bp":37,"sy":"un.der.col.lar","ps":"noun","t":["fabrics","ofrench"]},{"w":"underconstable","d":"A law-enforcement officer who ranks below and serves under a chief constable or head officer.","s":"The underconstable assisted the head officer in keeping order during the town festival.","p":"UN-der-KON-stuh-bul","o":"French","y":9,"bp":29,"sy":"un.der.con.sta.ble","ps":"noun","t":["law","ofrench"]},{"w":"underenforce","d":"To enforce a law, rule, or policy less strictly or thoroughly than required, allowing violations to go unchecked.","s":"Critics argued that the school tends to underenforce the dress code rules on Fridays.","p":"UN-der-en-FORS","o":"French","y":9,"bp":38,"sy":"un.der.en.force","ps":"verb","t":["law","politics","ofrench"]},{"w":"underexplain","d":"To explain something with less detail or clarity than the subject requires, leaving the listener confused or uninformed.","s":"The teacher warned students not to underexplain their answers on the essay test.","p":"UN-der-ek-SPLAYN","o":"French","y":9,"bp":38,"sy":"un.der.ex.plain","ps":"verb","t":["ofrench"]},{"w":"underhonest","d":"Being less than completely honest; falling short of full truthfulness or transparency.","s":"An underhonest salesperson might leave out important details that could change your decision.","p":"UN-der-ON-est","o":"French","y":8,"bp":37,"sy":"un.der.hon.est","ps":"adjective","t":["ofrench"]},{"w":"undermanage","d":"To manage a situation, organization, or group with less oversight, effort, or skill than is needed for it to function well.","s":"If you undermanage a team project, everyone ends up confused about their responsibilities.","p":"UN-der-MAN-ij","o":"French","y":9,"bp":37,"sy":"un.der.man.age","ps":"verb","t":["ofrench"]},{"w":"undermatch","d":"To pair or compete someone against an opponent or challenge that is below their level; to make an unequal match in the wrong direction.","s":"The coach did not want to undermatch his star wrestler against opponents who were too weak.","p":"UN-der-mach","o":"French","y":9,"bp":29,"sy":"un.der.match","ps":"verb","t":["sports","ofrench"]},{"w":"underminister","d":"A minister or official who holds a rank subordinate to the chief or head minister in a government or organization.","s":"The underminister handled routine paperwork while the head official attended the summit.","p":"UN-der-MIN-ih-ster","o":"French","y":9,"bp":40,"sy":"un.der.min.is.ter","ps":"noun","t":["politics","ofrench"]},{"w":"underorder","d":"To order or request a smaller quantity of something than is actually needed, resulting in a shortage.","s":"The cafeteria manager made sure not to underorder supplies before the busy lunch rush.","p":"UN-der-OR-der","o":"French","y":8,"bp":29,"sy":"un.der.order","ps":"verb","t":["ofrench"]},{"w":"underpair","d":"a pair that ranks below another pair, especially in a card game","s":"In the card game her underpair lost to his higher pair of kings.","p":"UN-der-pair","o":"French","y":9,"bp":28,"sy":"un.der.pair","ps":"noun","t":["ofrench"]},{"w":"underperceive","d":"To perceive or notice less of something than is actually present; to take in less sensory or mental information than the full situation provides.","s":"Scientists found that tired drivers often underperceive the speed of oncoming vehicles.","p":"UN-der-per-SEEV","o":"French","y":9,"bp":38,"sy":"un.der.per.ceive","ps":"verb","t":["ofrench"]},{"w":"underpower","d":"To supply with less power, energy, or strength than is necessary for a task or device to function properly.","s":"The tiny engine would underpower the heavy truck when it tried to climb the steep hill.","p":"uh-nder-POW-er","o":"French","y":8,"bp":30,"sy":"ah.nder.paw.er","ps":"verb","t":["physics","tools","ofrench"]},{"w":"underpraise","d":"To give less praise, recognition, or credit than a person's effort or achievement truly deserves.","s":"It would be a shame to underpraise the student who worked so hard on her science project.","p":"UN-der-prayz","o":"French","y":9,"bp":35,"sy":"un.der.praise","ps":"verb","t":["ofrench"]},{"w":"underprint","d":"To print fewer copies of something than are needed, or to print with insufficient ink or detail.","s":"The publisher had to rush more copies after deciding to underprint the bestselling novel.","p":"UN-der-print","o":"French","y":8,"bp":29,"sy":"un.der.print","ps":"verb","t":["ofrench"]},{"w":"underprize","d":"To value or esteem something at less than its true worth; to underestimate the importance or value of something.","s":"Collectors sometimes underprize rare coins simply because they don't recognize their age.","p":"UN-der-pryz","o":"French","y":9,"bp":29,"sy":"un.der.prize","ps":"verb","t":["ofrench"]},{"w":"underprocess","d":"To process something through fewer steps or with less thoroughness than the procedure requires, resulting in an incomplete or inferior result.","s":"Food safety experts warn that to underprocess canned vegetables can lead to harmful bacteria.","p":"UN-der-PROS-es","o":"French","y":9,"bp":38,"sy":"un.der.pro.cess","ps":"verb","t":["ofrench"]},{"w":"underpromise","d":"To promise less than you are actually capable of delivering, often as a strategy so that the final result exceeds expectations.","s":"Wise managers underpromise on deadlines so they can pleasantly surprise clients by finishing early.","p":"UN-der-PROM-is","o":"French","y":9,"bp":36,"sy":"un.der.promise","ps":"verb","t":["ofrench"]},{"w":"underproof","d":"Describing a substance, especially bread dough or a liquid, that has not risen, fermented, or developed to the required level or strength.","s":"The baker let the dough underproof, so the bread came out dense and flat.","p":"UN-der-proof","o":"French","y":8,"bp":29,"sy":"un.der.proof","ps":"adjective","t":["chemistry","culinary","dishes","ofrench"]},{"w":"underprovision","d":"To supply or allocate fewer resources, funds, or necessities than a situation or group requires.","s":"The camp suffered from underprovision of clean water during the long, dry summer.","p":"UN-der-pruh-VIH-zhun","o":"French","y":9,"bp":29,"sy":"un.der.pro.vi.sion","ps":"verb","t":["ofrench"]},{"w":"underput","d":"To place or add less of something than the correct or required amount.","s":"The chef accidentally underput the seasoning, making the soup taste bland and watery.","p":"UN-der-put","o":"French","y":8,"bp":21,"sy":"un.der.put","ps":"verb","t":["ofrench"]},{"w":"underreaction","d":"A response to an event or situation that is less intense, forceful, or adequate than the circumstances actually demand.","s":"The team's underreaction to the early warning signs let the small problem grow into a big crisis.","p":"UN-der-ree-AK-shun","o":"French","y":9,"bp":40,"sy":"un.der.re.ac.tion","ps":"noun","t":["ofrench"]},{"w":"underservant","d":"A servant who holds a lower rank and works under a more senior or head servant in a household or organization.","s":"The underservant was responsible for cleaning the lower floors of the grand estate.","p":"UN-der-SER-vunt","o":"French","y":8,"bp":38,"sy":"un.der.ser.vant","ps":"noun","t":["household","ofrench"]},{"w":"underserviced","d":"Receiving less service, maintenance, or care than is needed or expected; inadequately served by available resources.","s":"Many rural communities remain underserviced when it comes to reliable internet access.","p":"UN-der-SER-vist","o":"French","y":9,"bp":38,"sy":"un.der.ser.viced","ps":"adjective","t":["ofrench"]},{"w":"undersize","d":"smaller than normal for its kind","s":"The inspector rejected the undersize bolts because they would not hold the structure safely.","p":"UN-der-syz","o":"French","y":7,"bp":28,"sy":"un.der.size","ps":"adjective","t":["ofrench"]},{"w":"undersphere","d":"A sphere or rounded region that lies beneath or inside another larger sphere, especially in a geometric or theoretical context.","s":"The scientist described the undersphere as the layer of atmosphere found just below the main one.","p":"UN-der-sfeer","o":"French","y":9,"bp":35,"sy":"un.der.sphere","ps":"noun","t":["ofrench"]},{"w":"understage","d":"The area beneath or below a theatrical stage, used by stagehands, for storage, or for mechanical equipment.","s":"The prop crew stored extra scenery in the understage area beneath the main platform.","p":"UN-der-stayj","o":"French","y":9,"bp":29,"sy":"un.der.stage","ps":"noun","t":["stage","ofrench"]},{"w":"undersuit","d":"A close-fitting garment worn beneath another suit or outer layer, such as a thermal layer worn under a spacesuit or wetsuit.","s":"The astronaut pulled on the thermal undersuit before putting on the bulky outer spacesuit.","p":"UN-der-soot","o":"French","y":8,"bp":28,"sy":"un.der.suit","ps":"noun","t":["fabrics","ofrench"]},{"w":"undersupply","d":"A condition in which the available quantity of a good, resource, or commodity is less than what is needed or demanded.","s":"The undersupply of clean water in the drought-stricken region caused serious health problems.","p":"UN-der-suh-PLY","o":"French","y":7,"bp":37,"sy":"un.der.sup.ply","ps":"noun","t":["ofrench"]},{"w":"undersupport","d":"To provide less support, backing, or assistance than a person, project, or structure requires to succeed or remain stable.","s":"The bridge collapsed partly because of the undersupport of its aging foundation.","p":"UN-der-suh-PORT","o":"French","y":9,"bp":38,"sy":"un.der.sup.port","ps":"verb","t":["ofrench"]},{"w":"underuse","d":"the failure to use something as much or as fully as it could be used","s":"The underuse of the library's science section surprised the new librarian.","p":"uh-nder-YOO-z","o":"French","y":7,"bp":21,"sy":"ah.nder.yuw.z","ps":"noun","t":["ofrench"]},{"w":"undeserve","d":"To fail to earn or merit something; to be unworthy of a reward, punishment, or treatment that one receives.","s":"She felt she would undeserve the award if she hadn't truly worked for it.","p":"un-dih-ZERV","o":"French","y":9,"bp":28,"sy":"un.de.serve","ps":"verb","t":["ofrench"]},{"w":"undesirous","d":"having or feeling no desire","s":"A very private man, totally undesirous of public office.","p":"un-dih-ZY-rus","o":"French","y":9,"bp":29,"sy":"un.de.sirous","ps":"adjective","t":["ofrench"]},{"w":"undiscreet","d":"Lacking discretion or tact; tending to share information or act in ways that are careless and reveal things that should be kept private.","s":"Her undiscreet comment about the surprise party ruined the whole secret.","p":"un-dih-SKREET","o":"French","y":8,"bp":27,"sy":"undis.creet","ps":"adjective","t":["character","ofrench"]},{"w":"unduke","d":"To strip someone of the rank, title, or privileges of a duke; to remove a person's ducal status.","s":"The king decided to unduke the nobleman after he betrayed the crown.","p":"un-DYOOK","o":"French","y":8,"bp":18,"sy":"un.duke","ps":"verb","t":["royalty","ofrench"]},{"w":"unexistence","d":"The state or condition of not existing; total absence of being or presence in the world.","s":"The philosopher argued about the unexistence of things we can imagine but never touch.","p":"un-eg-ZIS-tense","o":"French","y":9,"bp":37,"sy":"un.ex.is.tence","ps":"noun","t":["ofrench"]},{"w":"unfix","d":"To loosen, detach, or release something that was previously fixed, fastened, or firmly set in place.","s":"The mechanic had to unfix the bolt he had tightened too soon before adjusting the part.","p":"un-FIKS","o":"French","y":6,"bp":17,"sy":"un.fix","ps":"verb","t":["ofrench"]},{"w":"unfrenetic","d":"Not frantic or wildly energetic; calm, composed, and free from frenzied or hectic activity.","s":"The yoga class had an unfrenetic pace that helped everyone relax after a busy week.","p":"un-freh-NET-ik","o":"French","y":8,"bp":30,"sy":"un.fre.net.ic","ps":"adjective","t":["ofrench"]},{"w":"unfrequent","d":"Not occurring often; rare or infrequent; happening only occasionally or at widely spaced intervals.","s":"Her visits to the library became unfrequent once her workload increased.","p":"un-FREE-kwent","o":"French","y":9,"bp":29,"sy":"un.fre.quent","ps":"adjective","t":["ofrench"]},{"w":"ungallant","d":"Offensively discourteous; failing to show the polite, respectful, and chivalrous behavior expected, especially toward others.","s":"It was ungallant of him to walk through the door without holding it open for anyone behind him.","p":"un-GAL-unt","o":"French","y":8,"bp":28,"sy":"un.gal.lant","ps":"adjective","t":["ofrench"]},{"w":"unglue","d":"To separate or detach things that have been glued together; to loosen a bond created by an adhesive.","s":"She carefully used warm water to unglue the old stamp from the envelope.","p":"uh-NGLOO","o":"French","y":7,"bp":18,"sy":"ah.ngluw","ps":"verb","t":["ofrench"]},{"w":"ungratefulness","d":"A lack of gratitude or appreciation for kindness, help, or gifts received from others.","s":"His ungratefulness after receiving so many gifts shocked everyone at the party.","p":"un-GRAYT-ful-nes","o":"French","y":8,"bp":27,"sy":"un.grate.ful.ness","ps":"noun","t":["ofrench"]},{"w":"unhasty","d":"Not hurried or rushed; acting or moving in a slow, deliberate, and unhurried manner without urgency.","s":"The surgeon's unhasty movements during the operation showed true skill and patience.","p":"un-HAY-stee","o":"French","y":8,"bp":19,"sy":"un.hasty","ps":"adjective","t":["ofrench"]},{"w":"unhonest","d":"Lacking honesty or integrity; not truthful, sincere, or straightforward in one's words or actions.","s":"The unhonest merchant was eventually caught selling counterfeit goods at the market.","p":"un-ON-est","o":"French","y":8,"bp":21,"sy":"un.hon.est","ps":"adjective","t":["wordwords","ofrench"]},{"w":"uniformize","d":"To make uniform or consistent; to bring different things into the same standard form or appearance.","s":"The data have been uniformized.","p":"YOO-nih-form-ize","o":"French","y":9,"bp":27,"sy":"uni.formize","ps":"verb","t":["ofrench"]},{"w":"uniliteral","d":"Consisting of or relating to only one letter; describing a word, root, or element made up of a single letter.","s":"The linguist studied uniliteral symbols that each represented a single letter sound.","p":"yoo-nih-LIT-er-ul","o":"French","y":8,"bp":29,"sy":"unilit.er.al","ps":"adjective","t":["botany","chemistry","wordwords","ofrench"]},{"w":"unimaginableness","d":"The quality or state of being impossible to imagine or conceive; the condition of being so extreme or unusual that the mind cannot picture it.","s":"The unimaginableness of outer space makes it hard for scientists to explain to students.","p":"un-ih-MAJ-ih-nuh-bul-nes","o":"French","y":9,"bp":29,"sy":"unimag.in.able.ness","ps":"noun","t":["ofrench"]},{"w":"unimaginably","d":"To an unimaginable extent; in a way or to a degree that is impossible to picture or comprehend mentally.","s":"The mountain peak was unimaginably cold, even for experienced climbers.","p":"un-ih-MAJ-ih-nuh-blee","o":"French","y":6,"bp":36,"sy":"unimag.in.ably","ps":"adverb","t":["ofrench"]},{"w":"unimagine","d":"To attempt to undo or reverse the act of imagining something; to try to erase a mental image or concept from one's mind.","s":"Once she saw the surprise ending, she could not unimagine it no matter how hard she tried.","p":"un-ih-MAJ-in","o":"French","y":9,"bp":26,"sy":"unimag.ine","ps":"verb","t":["ofrench"]},{"w":"unimanual","d":"Describing a task or activity that is performed using only one hand rather than requiring the use of both hands simultaneously.","s":"The pianist practiced unimanual exercises to strengthen her weaker left hand.","p":"yoo-nih-MAN-yoo-ul","o":"French","y":8,"bp":29,"sy":"uni.man.u.al","ps":"adjective","t":["ofrench"]},{"w":"uninspire","d":"To fail to inspire or motivate; to cause a loss of enthusiasm, creativity, or excitement in someone.","s":"A dull presentation can uninspire even the most enthusiastic students.","p":"un-in-SPIRE","o":"French","y":9,"bp":26,"sy":"unin.spire","ps":"verb","t":["ofrench"]},{"w":"unintelligence","d":"The absence or lack of intelligence; the state of being unable to learn, reason, or understand things effectively.","s":"His unintelligence in choosing to argue with the referee got him ejected from the game.","p":"un-in-TEL-ih-jence","o":"French","y":9,"bp":29,"sy":"un.in.tel.li.gence","ps":"noun","t":["logic","ofrench"]},{"w":"unionbuster","d":"A person, organization, or strategy that works to break up, weaken, or destroy a labor union and prevent workers from organizing.","s":"The factory owner hired a unionbuster to convince workers to give up their organization.","p":"YOON-yun-bus-ter","o":"French","y":8,"bp":34,"sy":"union.buster","ps":"noun","t":["ofrench"]},{"w":"unionless","d":"Without a labor union; describing workers, industries, or workplaces that have no union representation or organization.","s":"The small café was unionless, so workers had no formal group to represent their rights.","p":"YOON-yun-les","o":"French","y":8,"bp":26,"sy":"union.less","ps":"adjective","t":["ofrench"]},{"w":"unionwide","d":"Extending across or applying to an entire union, whether a labor union or a political union of states or regions.","s":"The unionwide vote on the new contract included members from every city in the state.","p":"YOON-yun-wide","o":"French","y":9,"bp":26,"sy":"union.wide","ps":"adjective","t":["politics","ofrench"]},{"w":"unispecific","d":"Relating to or targeting only one particular species or one specific thing; narrowly focused on a single subject or organism.","s":"The unispecific antibody was designed to target only one particular type of cell.","p":"yoo-nih-speh-SIF-ik","o":"French","y":8,"bp":37,"sy":"unis.pe.cif.ic","ps":"adjective","t":["ofrench"]},{"w":"unitarianize","d":"To convert or adapt something to Unitarian principles; to make a belief, organization, or system reflect a unified or single-authority structure.","s":"The reformers wanted to unitarianize the scattered religious groups into one unified belief system.","p":"yoo-nih-TAIR-ee-un-ize","o":"French","y":9,"bp":39,"sy":"uni.tar.i.an.ize","ps":"verb","t":["poetry","logic","ofrench"]},{"w":"universology","d":"The systematic study or science of the universe as a whole, examining its laws, structures, and underlying principles as one unified subject.","s":"The professor's class on universology explored theories about the structure of the entire universe.","p":"yoo-nih-ver-SOL-oh-jee","o":"French","y":8,"bp":39,"sy":"uni.ver.sol.o.gy","ps":"noun","t":["astronomy","law","logic","ofrench"]},{"w":"unjoin","d":"To separate, disconnect, or detach things or people that were previously joined or connected together.","s":"She had to unjoin the two metal links by prying them apart with pliers.","p":"un-JOIN","o":"French","y":8,"bp":18,"sy":"un.join","ps":"verb","t":["ofrench"]},{"w":"unjoyous","d":"Lacking joy or happiness; cheerless, sad, or devoid of the positive feelings associated with delight and celebration.","s":"The unjoyous atmosphere at the cancelled festival made everyone feel deflated.","p":"un-JOY-us","o":"French","y":9,"bp":21,"sy":"un.joy.ous","ps":"adjective","t":["festivals","emotions","ofrench"]},{"w":"unliteral","d":"Not literal; going beyond the exact, word-for-word meaning of language; figurative or metaphorical in interpretation.","s":"The poem's unliteral language used dragons to represent fear rather than real beasts.","p":"un-LIT-er-ul","o":"French","y":8,"bp":29,"sy":"un.lit.er.al","ps":"adjective","t":["poetry","wordwords","ofrench"]},{"w":"unliterally","d":"In a non-literal way; not according to the strict or exact meaning of words; figuratively or metaphorically.","s":"She unliterally described the sunset as 'a fire swallowing the sea,' painting a vivid picture.","p":"un-LIT-er-ul-ee","o":"French","y":9,"bp":38,"sy":"un.lit.er.al.ly","ps":"adverb","t":["poetry","wordwords","ofrench"]},{"w":"unloyal","d":"Not loyal or faithful; failing to show steadfast allegiance or devotion to a person, group, or cause.","s":"The unloyal soldier secretly shared battle plans with the enemy.","p":"un-LOY-ul","o":"French","y":7,"bp":20,"sy":"un.loy.al","ps":"adjective","t":["ofrench"]},{"w":"underbark","d":"The layer of tissue or material found just beneath the outer bark of a tree, often including the cambium and inner bark.","s":"The woodpecker drilled through the underbark layer searching for insects hiding beneath the outer surface.","p":"UN-der-bark","o":"Norse","y":8,"bp":24,"sy":"un.der.bark","ps":"noun","t":["body","flowers","onordic"]},{"w":"underfellow","d":"A person of lower rank or status within a group; someone who is subordinate or considered inferior to others.","s":"In the old guild system, an underfellow was an apprentice ranked below even the junior craftsmen.","p":"UN-der-fel-oh","o":"Norse","y":9,"bp":33,"sy":"un.der.fel.low","ps":"noun","t":["character","onordic"]},{"w":"undersay","d":"To express something in weaker or fewer words than the situation calls for; to deliberately say less than the full truth.","s":"The cautious diplomat chose to undersay his concerns rather than cause an international incident.","p":"UN-der-say","o":"Norse","y":8,"bp":17,"sy":"un.der.say","ps":"verb","t":["logic","wordwords","onordic"]},{"w":"underskin","d":"The tissue or layer that lies directly beneath the surface of the skin; the subcutaneous layer.","s":"The doctor used an ultrasound to examine the underskin layers where the infection had spread.","p":"UN-der-skin","o":"Norse","y":8,"bp":24,"sy":"un.der.skin","ps":"noun","t":["body","onordic"]},{"w":"underthrust","d":"A geological fault movement in which one section of rock is pushed beneath another; also, a forceful push directed underneath something.","s":"The geologist explained that an underthrust occurs when one tectonic plate slides beneath another during a collision.","p":"UN-der-thrust","o":"Norse","y":8,"bp":31,"sy":"un.der.thrust","ps":"noun","t":["minerals","onordic"]},{"w":"unfellow","d":"To deprive someone of fellowship or companionship; to exclude a person from a group or community.","s":"To unfellow someone in the old order meant to strip them of their membership and standing in the guild.","p":"un-FEL-oh","o":"Norse","y":9,"bp":17,"sy":"un.fel.low","ps":"verb","t":["nations","onordic"]},{"w":"ungear","d":"To remove or disengage gears from a mechanism; to strip or disable the working parts of a machine.","s":"The mechanic had to ungear the transmission carefully before replacing the worn-out clutch plate.","p":"un-GEER","o":"Norse","y":8,"bp":12,"ps":"verb","t":["tools","onordic"]},{"w":"ungeld","d":"To free from a tax or tribute payment; in historical usage, to release someone from the obligation of paying a geld or levy.","s":"The king decided to ungeld the village, releasing the struggling peasants from their heavy tax obligation.","p":"un-GELD","o":"Norse","y":8,"bp":14,"sy":"un.geld","ps":"verb","t":["economy","onordic"]},{"w":"undertilde","d":"A diacritical mark consisting of a tilde placed beneath a letter, used in some linguistic or phonetic notation systems.","s":"The linguist added an undertilde beneath the letter to indicate a special pronunciation.","p":"un-der-TIL-deh","o":"Spanish","y":9,"bp":25,"sy":"un.der.tilde","ps":"noun","t":["wordwords","oiberian"]},{"w":"unkosher","d":"Not conforming to Jewish dietary laws; also used figuratively to describe something improper, suspicious, or ethically questionable.","s":"Mixing meat and dairy in that dish made the whole meal unkosher.","p":"un-KOH-sher","o":"Yiddish","y":8,"bp":15,"sy":"un.kosher","ps":"adjective","t":["law","logic","onordic"]}]`,h:`[{"w":"unidirectionality","d":"The quality of moving or operating in only one single path or way.","s":"The unidirectionality of the rushing river meant the little toy boat could only drift south.","p":"yoo-ni-di-rek-shuh-NAL-i-tee","o":"Latin","y":9,"bp":45,"nt":"Open","ps":"noun","t":["championship","movement","physics","olatin"],"m":"unidirectionallity","sy":"u.ni.di.rec.tion.al.i.ty"},{"w":"undercooling","d":"The process of lowering the temperature of a liquid below its normal freezing point without it turning solid right away.","s":"During the science experiment, the rapid undercooling of the liquid caused it to suddenly freeze into a weird crystal shape.","p":"un-der-KOO-ling","o":"Old English","y":8,"bp":45,"nt":"Open","ps":"noun","t":["championship","metallurgy","physics","ooldeng"],"m":"undercoolling","sy":"un.der.cool.ing"},{"w":"unguligrade","d":"Walking on the very tips of the toes, upon hooves.","s":"Horses are unguligrade, running on a single enlarged toe.","p":"ung-GYOO-lih-grayd","o":"Latin","y":9,"bp":65,"nt":"Open","ps":"adjective","t":["championship","palaeontology","olatin"],"m":"ungulagrade","sy":"un.gu.li.grade"},{"w":"univocity","d":"The quality of carrying exactly one meaning in every use.","s":"The logician insisted on the univocity of every term in the proof.","p":"yoo-nih-VOSS-ih-tee","o":"Latin","y":8,"bp":62,"nt":"Open","ps":"noun","t":["championship","logic","olatin"],"m":"univocety","sy":"u.ni.voc.i.ty"},{"w":"unflappability","d":"A calmness that nothing at all can disturb.","s":"The pilot's unflappability reassured every passenger aboard.","p":"un-flap-uh-BIL-ih-tee","o":"English","y":9,"bp":58,"nt":"Open","ps":"noun","t":["championship","character"],"m":"unflapability","sy":"un.flap.pa.bil.i.ty"}]`};
